-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('d6e470e2-1633-5311-8d80-9dee7f4df8f5'::uuid, 'francais', '2de', 'Repères : de la poésie médiévale aux Lumières', 'Au Moyen Âge, les troubadours chantent au sud. Comment appelle-t-on les poètes du nord ?', 'mcq', '["Les jongleurs","Les ménestrels","Les trouvères","Les rhétoriqueurs"]'::jsonb, 2, 'Troubadours en langue d’oc au sud, trouvères en langue d’oïl au nord : tous deux chantent l’amour courtois.', 1),
    ('c559ca34-2d05-5b10-82fc-e275507935cb'::uuid, 'francais', '2de', 'Repères : de la poésie médiévale aux Lumières', 'Quel texte de Du Bellay (1549) sert de manifeste à la Pléiade ?', 'mcq', '["Les Regrets","Défense et illustration de la langue française","Les Antiquités de Rome","L’Art poétique"]'::jsonb, 1, 'Ce manifeste veut faire du français une vraie langue de poésie, capable de rivaliser avec le latin et l’italien.', 2),
    ('7a24fc2e-c829-5576-a5d6-7a5975f05220'::uuid, 'francais', '2de', 'Repères : de la poésie médiévale aux Lumières', 'Quels thèmes nés à la Renaissance traverseront les siècles ?', 'mcq', '["La guerre et la conquête","La nature sauvage et la montagne","La ville et l’industrie","La fuite du temps, la beauté qui passe, l’exil"]'::jsonb, 3, 'Ronsard chante la beauté qui fane, Du Bellay l’exil : ces thèmes reviendront chez les romantiques et bien au-delà.', 3),
    ('c89a0c3f-0091-59af-b5ce-9f06a323bccc'::uuid, 'francais', '2de', 'Repères : de la poésie médiévale aux Lumières', 'Qu’impose la poésie du XVIIe siècle ?', 'mcq', '["Des mètres fixes, des rimes riches et le respect des genres","Le vers libre","Le mélange des genres","L’abandon de la rime"]'::jsonb, 0, 'Le XVIIe siècle est celui de la règle : chaque genre a ses codes, et le poète les respecte.', 4),
    ('bb56a539-5165-5da2-b192-900d02a40652'::uuid, 'francais', '2de', 'Le vocabulaire poétique', 'Combien de syllabes compte un décasyllabe ?', 'mcq', '["8","10","12","6"]'::jsonb, 1, 'Octosyllabe : 8 ; décasyllabe : 10 ; alexandrin : 12, coupé en deux hémistiches de 6.', 1),
    ('4bba61b4-727c-5c25-9c95-da726cb45621'::uuid, 'francais', '2de', 'Le vocabulaire poétique', 'Dans quel cas le e muet compte-t-il pour une syllabe ?', 'mcq', '["En fin de vers","Devant une voyelle","Jamais","Devant une consonne, à l’intérieur du vers"]'::jsonb, 3, 'Devant une voyelle, il s’élide ; en fin de vers, il ne se compte pas ; devant une consonne, il se prononce et compte.', 2),
    ('d7630db2-4c4a-572a-85b4-f641da356a76'::uuid, 'francais', '2de', 'Le vocabulaire poétique', 'Combien de sons communs faut-il pour qu’une rime soit riche ?', 'mcq', '["Un seul","Deux","Trois ou plus","Aucun"]'::jsonb, 2, 'Rime pauvre : un son commun ; suffisante : deux ; riche : trois ou plus.', 3),
    ('245956f6-3b17-51d7-b839-eead43f3a8db'::uuid, 'francais', '2de', 'Le vocabulaire poétique', 'Qu’est-ce qu’un contre-rejet ?', 'mcq', '["Un court fragment placé à la fin d’un vers, qui appartient à la phrase du vers suivant","Un fragment mis en valeur au début du vers suivant","Une rime qui revient deux fois","Une strophe de trois vers"]'::jsonb, 0, 'Le rejet déborde au début du vers suivant ; le contre-rejet, lui, commence en fin de vers la phrase qui continue ensuite.', 4),
    ('b84cc50c-89e3-5da8-bb91-7aa9b4816be2'::uuid, 'francais', '2de', 'Les animaux au service du rire et de la dénonciation : le Roman de Renart', 'Entre quelles dates les branches du Roman de Renart ont-elles été composées ?', 'mcq', '["Vers 900-1000","Entre 1170 et 1250 environ","Au XVe siècle","Au XVIIe siècle"]'::jsonb, 1, 'Ce sont des récits en vers écrits par plusieurs auteurs sur près d’un siècle : ce n’est pas l’œuvre d’un seul homme.', 1),
    ('8f660d8d-2ee7-5076-b1c3-9368db5953e1'::uuid, 'francais', '2de', 'Les animaux au service du rire et de la dénonciation : le Roman de Renart', 'Qu’est-ce qu’une parodie ?', 'mcq', '["Un récit en vers","Une histoire vraie","Un texte religieux","L’imitation comique d’un modèle sérieux"]'::jsonb, 3, 'Renart remplace les combats héroïques de la chanson de geste par des ruses de goupil : c’est une parodie.', 2),
    ('9e4adf57-f1c9-551c-a7e5-f32438f59499'::uuid, 'francais', '2de', 'Les animaux au service du rire et de la dénonciation : le Roman de Renart', 'Quel rôle tient Chantecler le coq ?', 'mcq', '["Le roi","Le grand baron brutal","Un naïf plein de vanité","Le juge du procès"]'::jsonb, 2, 'Chantecler se laisse flatter par Renart : sa vanité le rend vulnérable à la ruse.', 3),
    ('0fbccb27-3a8c-5fe0-ad6a-4f21dda798fd'::uuid, 'francais', '2de', 'Les animaux au service du rire et de la dénonciation : le Roman de Renart', 'Sur quoi repose le comique de situation du Roman de Renart ?', 'mcq', '["Les ruses, les déguisements et les coups reçus","Les jeux de mots savants","Les débats philosophiques","Les descriptions de paysages"]'::jsonb, 0, 'Ce comique très physique est proche de la farce ; il s’ajoute au comique de mots, fait de jeux de mots et de serments détournés.', 4),
    ('0308429a-3116-5ed8-aeda-d7f45472f809'::uuid, 'francais', '2de', 'Sonnets : structure et animalité (Du Bellay et Ronsard)', 'Quel schéma de rimes les quatrains d’un sonnet suivent-ils le plus souvent ?', 'mcq', '["AABB AABB","ABAB CDCD","ABBA ABBA","AAAA BBBB"]'::jsonb, 2, 'Les deux quatrains reprennent les mêmes rimes embrassées ; les tercets varient, souvent en CCD EED en France.', 1),
    ('99f40d62-ffce-5645-af4f-3cdc5c54c137'::uuid, 'francais', '2de', 'Sonnets : structure et animalité (Du Bellay et Ronsard)', 'En quelle année paraissent Les Regrets de Du Bellay ?', 'mcq', '["1549","1558","1600","1532"]'::jsonb, 1, 'Les Regrets (1558) sont écrits pendant son séjour à Rome ; 1549 est l’année de sa Défense et illustration de la langue française.', 2),
    ('20192b85-7dd7-57c3-a4f0-4dc537ab12a0'::uuid, 'francais', '2de', 'Sonnets : structure et animalité (Du Bellay et Ronsard)', 'De quel poète latin Ronsard hérite-t-il le thème du carpe diem ?', 'mcq', '["Virgile","Ovide","Cicéron","Horace"]'::jsonb, 3, 'La formule vient d’Horace : puisque la beauté passe, il faut en jouir au présent.', 3),
    ('521ea509-44f2-52f9-8b57-e188b11c011d'::uuid, 'francais', '2de', 'Sonnets : structure et animalité (Du Bellay et Ronsard)', 'Que dit l’image du poète en cerf blessé ?', 'mcq', '["La douleur du désir","La joie de la chasse","La fuite du temps","La force du poète"]'::jsonb, 0, 'L’animal n’est pas une bête réelle : c’est un véhicule de la métaphore, hérité de Pétrarque.', 4),
    ('21fbc8f6-e247-5868-8b07-24a127a416a0'::uuid, 'francais', '2de', 'Universalité et pluralité de l’image du lion', 'Quel épisode biblique fait du lion une menace ?', 'mcq', '["Le déluge","La tour de Babel","La fosse aux lions","Le veau d’or"]'::jsonb, 2, 'Dans la Bible, le lion est à la fois menace — la fosse aux lions — et force au service du juste, avec Samson ou Daniel.', 1),
    ('3ef563f8-6c21-59ab-849a-9cd213dc433d'::uuid, 'francais', '2de', 'Universalité et pluralité de l’image du lion', 'De quel fabuliste antique vient l’expression « la part du lion » ?', 'mcq', '["Phèdre","Ésope","Homère","Virgile"]'::jsonb, 1, 'Chez Ésope, le puissant prend sa part d’avance : l’expression est restée dans la langue.', 2),
    ('eb08d9f2-64ad-5377-94c9-15d1683103b1'::uuid, 'francais', '2de', 'Universalité et pluralité de l’image du lion', 'Selon le bestiaire médiéval, quel trait du lion en fait un symbole du Christ ?', 'mcq', '["Il chasse la nuit","Il vit en troupeau","Il rugit plus fort que tous","Il ranime ses petits au troisième jour"]'::jsonb, 3, 'Les petits ranimés au troisième jour rappellent la résurrection ; le lion efface aussi ses traces et dort les yeux ouverts.', 3),
    ('4c984145-59a1-5524-832b-566ccc6a4885'::uuid, 'francais', '2de', 'Universalité et pluralité de l’image du lion', 'Quel portrait le Roman de Renart fait-il du lion Noble ?', 'mcq', '["Un roi faible et partial","Un compagnon fidèle","Un héros invincible","Un saint"]'::jsonb, 0, 'Chez Chrétien de Troyes, le lion est le fidèle compagnon d’Yvain ; dans Renart, c’est un roi médiocre : le même animal change de sens.', 4),
    ('05788ba0-f683-543f-ae77-d306319c5968'::uuid, 'francais', '2de', 'La fable comme écho et reflet des combats des Lumières', 'Quand les Fables de La Fontaine sont-elles publiées ?', 'mcq', '["De 1580 à 1595","De 1750 à 1770","De 1668 à 1694","En 1789"]'::jsonb, 2, 'Un siècle avant les Lumières, elles critiquent déjà la cour, l’arbitraire du pouvoir et la justice inégale.', 1),
    ('41d54446-d2bb-537e-a145-3616b1f90fb4'::uuid, 'francais', '2de', 'La fable comme écho et reflet des combats des Lumières', 'Qui est l’auteur des Lettres persanes ?', 'mcq', '["Voltaire","Montesquieu","Diderot","Rousseau"]'::jsonb, 1, 'Montesquieu y fait voir la France par les yeux de voyageurs persans : un regard étranger pour dénoncer les travers de chez soi.', 2),
    ('6f8d0af7-52eb-517a-b764-cdbd79c1fcb2'::uuid, 'francais', '2de', 'La fable comme écho et reflet des combats des Lumières', 'En quoi consiste l’ironie ?', 'mcq', '["Répéter un mot en début de vers","Exagérer pour émouvoir","Raconter une histoire vraie","Dire le contraire de ce qu’on pense pour le rendre insoutenable"]'::jsonb, 3, 'Le lecteur qui décode l’ironie devient complice : il se convainc lui-même.', 3),
    ('109ee3ef-c6b0-5f36-97da-6e855f5b4c70'::uuid, 'francais', '2de', 'La fable comme écho et reflet des combats des Lumières', 'Quelle stratégie les formes des Lumières partagent-elles avec la fable ?', 'mcq', '["Détourner le regard vers un ailleurs — un animal, un naïf, un étranger","Écrire uniquement en vers","Supprimer toute morale","S’adresser seulement aux savants"]'::jsonb, 0, 'Un animal, un naïf comme Candide, un étranger comme les Persans de Montesquieu : l’ailleurs fait voir le scandale de chez soi.', 4),
    ('eedaa62f-76d7-5d21-b42d-1840da95fc71'::uuid, 'francais', '2de', 'Repères : littérature d’idées et presse, du XIXe au XXIe siècle', 'Que signifie délibérer ?', 'mcq', '["Toucher les émotions du lecteur","Donner des preuves","Peser plusieurs thèses avant de trancher","Raconter une anecdote"]'::jsonb, 2, 'Convaincre vise la raison, persuader les émotions, délibérer le jugement : un texte efficace combine souvent les trois.', 1),
    ('875b4b2d-98e8-5974-bf49-471717859e9f'::uuid, 'francais', '2de', 'Repères : littérature d’idées et presse, du XIXe au XXIe siècle', 'Quand paraît « J’accuse… ! » de Zola ?', 'mcq', '["Le 29 juillet 1881","Le 13 janvier 1898","Le 4 août 1789","Le 2 décembre 1851"]'::jsonb, 1, 'Publié en une de L’Aurore le 13 janvier 1898, il est le sommet de la littérature d’idées dans la presse.', 2),
    ('4ee3459b-0b1f-5cd1-978f-5a074847239b'::uuid, 'francais', '2de', 'Repères : littérature d’idées et presse, du XIXe au XXIe siècle', 'À quoi servent les connecteurs logiques dans un texte argumentatif ?', 'mcq', '["À illustrer la thèse","À émouvoir le lecteur","À citer des sources","À organiser le raisonnement"]'::jsonb, 3, 'Mais, donc, car, pourtant : ils articulent les arguments entre eux et guident le lecteur.', 3),
    ('e9e77bd7-5d9c-5188-9b12-3a3c38dc907f'::uuid, 'francais', '2de', 'Repères : littérature d’idées et presse, du XIXe au XXIe siècle', 'Au XXIe siècle, chaque lecteur peut devenir diffuseur. Quelle question cela pose-t-il ?', 'mcq', '["Comment vérifier l’information","Comment imprimer plus vite","Comment écrire en vers","Comment supprimer les journaux"]'::jsonb, 0, 'Quand tout le monde peut diffuser, la vérification devient l’enjeu central, tout comme la question de savoir qui finance.', 4),
    ('b3e3fa7b-bdba-5ea8-8030-f6eff627edd1'::uuid, 'francais', '2de', 'Les fondamentaux du journalisme', 'Dans quel genre journalistique le journaliste raconte-t-il ce qu’il a vu sur place ?', 'mcq', '["La brève","Le reportage","L’éditorial","La tribune"]'::jsonb, 1, 'Le reportage relève de l’information : il rapporte des faits observés, sans défendre une position.', 1),
    ('e25a7072-2e22-549e-ab49-135be5e5d860'::uuid, 'francais', '2de', 'Les fondamentaux du journalisme', 'Qu’est-ce qu’une tribune ?', 'mcq', '["La position officielle du journal","Un résumé placé sous le titre","Une brève de quelques lignes","Un texte d’opinion signé par quelqu’un d’extérieur au journal"]'::jsonb, 3, 'L’éditorial exprime la position du journal ; la tribune donne la parole à une personne extérieure.', 2),
    ('ddead8ff-96e0-5b3c-81d9-371de957f1f3'::uuid, 'francais', '2de', 'Les fondamentaux du journalisme', 'Comment appelle-t-on la première phrase d’un article ?', 'mcq', '["La chute","Le chapô","L’attaque","L’intertitre"]'::jsonb, 2, 'L’attaque ouvre l’article, la chute le termine ; le chapô, lui, est le court résumé placé sous le titre.', 3),
    ('fe3e1342-57f1-5ac1-9944-b212cd3d4a5d'::uuid, 'francais', '2de', 'Les fondamentaux du journalisme', 'Selon la Charte de Munich, avec quoi le journaliste ne doit-il pas confondre son métier ?', 'mcq', '["La publicité","L’enquête","La photographie","L’écriture"]'::jsonb, 0, 'Parmi ses devoirs : vérifier, ne pas dénaturer, rectifier ses erreurs, protéger ses sources et ne pas mélanger information et publicité.', 4),
    ('4af1101f-d331-5ac6-b218-e113640bdeff'::uuid, 'francais', '2de', 'La presse au XIXe siècle, essor journalistique et littéraire', 'Quel journal Girardin vend-il à moitié prix en 1836 ?', 'mcq', '["L’Aurore","Le Charivari","La Presse","Le Temps"]'::jsonb, 2, 'Financée par la publicité, La Presse devient accessible à un public beaucoup plus large.', 1),
    ('e5a63b8b-cd86-51e7-b2a7-60ed5332e1c8'::uuid, 'francais', '2de', 'La presse au XIXe siècle, essor journalistique et littéraire', 'Lequel de ces romans d’Alexandre Dumas a paru en feuilleton ?', 'mcq', '["Les Misérables","Les Trois Mousquetaires","Madame Bovary","Germinal"]'::jsonb, 1, 'Dumas publie en feuilleton Les Trois Mousquetaires et Le Comte de Monte-Cristo, comme Eugène Sue Les Mystères de Paris.', 2),
    ('7c205072-1d65-5b46-88cb-4cc9c68140b1'::uuid, 'francais', '2de', 'La presse au XIXe siècle, essor journalistique et littéraire', 'Quel effet la parution en épisodes a-t-elle sur l’écriture du roman ?', 'mcq', '["Des chapitres très longs","L’absence de personnages","Des romans en vers","Des chapitres courts qui finissent sur du suspense"]'::jsonb, 3, 'Il faut donner envie d’acheter le numéro suivant : suspense en fin d’épisode, rebondissements fréquents, personnages typés.', 3),
    ('1608efc9-1174-54ab-bb73-da82bbb65829'::uuid, 'francais', '2de', 'La presse au XIXe siècle, essor journalistique et littéraire', 'Dans quel journal satirique Daumier publie-t-il ses caricatures ?', 'mcq', '["Le Charivari","L’Aurore","La Presse","Le Figaro"]'::jsonb, 0, 'La caricature de presse fait rire des puissants, au prix de la censure et des procès.', 4),
    ('362eb321-bbc9-5081-b667-88aa76c9a2b6'::uuid, 'francais', '2de', 'Victor Hugo, « Exil » : l’absence et le manque (XIXe siècle)', 'Où Hugo séjourne-t-il avant de s’installer à Guernesey ?', 'mcq', '["À Londres puis à Genève","À Bruxelles puis à Jersey","En Corse","À Rome"]'::jsonb, 1, 'Bruxelles, puis Jersey de 1852 à 1855, enfin Guernesey de 1855 à 1870.', 1),
    ('4ed32844-d362-5d70-8684-ab551665fd2b'::uuid, 'francais', '2de', 'Victor Hugo, « Exil » : l’absence et le manque (XIXe siècle)', 'Quand Hugo rentre-t-il en France ?', 'mcq', '["En 1859, avec l’amnistie","En 1852","En 1885","En 1870, après dix-neuf ans d’exil"]'::jsonb, 3, 'Il ne rentre qu’à la chute du Second Empire, en 1870 : il avait promis de revenir avec la liberté.', 2),
    ('e099f27f-9e7c-5724-be6c-844296f3daf8'::uuid, 'francais', '2de', 'Victor Hugo, « Exil » : l’absence et le manque (XIXe siècle)', 'Quel grand roman Hugo écrit-il à Guernesey ?', 'mcq', '["Notre-Dame de Paris","Le Rouge et le Noir","Les Misérables","Germinal"]'::jsonb, 2, 'L’exil n’est pas un silence : Hugo publie, se fait photographier sur son rocher et achève Les Misérables.', 3),
    ('22505c7f-ecf1-5d67-9cf7-4ef1e400f825'::uuid, 'francais', '2de', 'Victor Hugo, « Exil » : l’absence et le manque (XIXe siècle)', 'Autour de quelles deux parties Les Contemplations s’organisent-elles ?', 'mcq', '["« Autrefois » et « Aujourd’hui »","« Le jour » et « La nuit »","« Paris » et « Guernesey »","« Colère » et « Pardon »"]'::jsonb, 0, 'La mort de Léopoldine, en 1843, sépare ces deux parties comme un gouffre.', 4),
    ('abfab354-c1a9-5804-93a9-70292a62e64f'::uuid, 'francais', '2de', 'Exil en poésie, poésie en exil (XXe siècle)', 'En quelle année paraît le Cahier d’un retour au pays natal d’Aimé Césaire ?', 'mcq', '["1918","1962","1939","1981"]'::jsonb, 2, 'Dans ce texte de 1939, Césaire forge le mot « négritude » et transforme une insulte en fierté.', 1),
    ('a224d253-8b21-58b1-89fd-7990817fcc94'::uuid, 'francais', '2de', 'Exil en poésie, poésie en exil (XXe siècle)', 'Quel poète écrit l’Afrique depuis Paris ?', 'mcq', '["Mahmoud Darwich","Léopold Sédar Senghor","Paul Celan","Nâzim Hikmet"]'::jsonb, 1, 'Senghor, comme Césaire, fait de la distance avec le pays un moteur de son écriture.', 2),
    ('a33d8be3-ae91-58f2-abe7-b8bcbeb0dd9a'::uuid, 'francais', '2de', 'Exil en poésie, poésie en exil (XXe siècle)', 'Qui est Nâzim Hikmet ?', 'mcq', '["Un poète palestinien","Un poète martiniquais","Un chanteur français","Un poète turc qui écrit depuis la prison puis l’exil"]'::jsonb, 3, 'Emprisonné puis exilé, Hikmet fait de l’enfermement et de l’éloignement la matière de sa poésie.', 3),
    ('36a0f9b4-e84f-51e8-8776-d8e52a350911'::uuid, 'francais', '2de', 'Exil en poésie, poésie en exil (XXe siècle)', 'Que porte l’image de la clé d’une maison qui n’existe plus ?', 'mcq', '["La perte irréversible","L’espoir d’un retour proche","La richesse perdue","Le départ en vacances"]'::jsonb, 0, 'La valise dit le départ, la frontière le passage ; la clé d’une maison disparue dit ce qu’on ne retrouvera jamais.', 4),
    ('34d00570-2dc3-589b-8c16-263659f85f4f'::uuid, 'francais', '2de', 'Mise en scène de destins en souffrance : Migrants, Sonia Ristic (XXIe siècle)', 'En quelle année Sonia Ristić est-elle née ?', 'mcq', '["1945","1972","1990","1958"]'::jsonb, 1, 'Née à Belgrade en 1972, elle a elle-même connu l’exil au moment des guerres de Yougoslavie.', 1),
    ('88b1c795-a494-53ac-a4db-93f605bd8fa5'::uuid, 'francais', '2de', 'Mise en scène de destins en souffrance : Migrants, Sonia Ristic (XXIe siècle)', 'Quelle est la matière première du théâtre documentaire ?', 'mcq', '["Des mythes antiques","Des contes de fées","Des témoignages, des rapports et des articles","Des poèmes en alexandrins"]'::jsonb, 2, 'Le théâtre du réel part de documents qu’il met en forme dramatique.', 2),
    ('47e3b485-1b4d-5d18-8c5d-c43cf70cf87e'::uuid, 'francais', '2de', 'Mise en scène de destins en souffrance : Migrants, Sonia Ristic (XXIe siècle)', 'Que produit le choix de personnages parfois non nommés ?', 'mcq', '["Un héros unique très développé","Une intrigue amoureuse","Un effet comique","Le destin individuel cède la place à une situation collective"]'::jsonb, 3, 'Personnes déplacées, passeurs, fonctionnaires, témoins : l’écriture chorale fait entendre une situation plutôt qu’un héros.', 3),
    ('93a83969-ba96-5f0a-b9f0-1ecd357d318d'::uuid, 'francais', '2de', 'Mise en scène de destins en souffrance : Migrants, Sonia Ristic (XXIe siècle)', 'De quoi la pièce parle-t-elle surtout ?', 'mcq', '["De ce que l’attente, la frontière et l’administration font aux personnes","De la migration comme problème politique à résoudre","D’une histoire d’amour","De la vie d’un passeur célèbre"]'::jsonb, 0, 'Dignité, peur, espoir, mémoire du pays quitté : la pièce regarde des personnes, pas un dossier.', 4),
    ('7320b31f-6094-50f8-bfd4-b2cd31d237a0'::uuid, 'francais', '2de', 'Repères : le roman et le récit, du XVIIIe au XXIe siècle', 'Comment appelle-t-on le moment du récit où l’on décrit, le temps de l’histoire s’arrêtant ?', 'mcq', '["Le sommaire","L’ellipse","La pause","La scène"]'::jsonb, 2, 'Sommaire : on résume ; scène : on raconte au rythme réel ; ellipse : on saute ; pause : on décrit.', 1),
    ('3a2cf88a-16ec-5700-b62f-aa2719367d83'::uuid, 'francais', '2de', 'Repères : le roman et le récit, du XVIIIe au XXIe siècle', 'Quel écrivain explore la mémoire au XXe siècle ?', 'mcq', '["Balzac","Proust","Laclos","Zola"]'::jsonb, 1, 'Proust explore la mémoire, Céline casse la langue écrite, Camus écrit une voix blanche : le récit doute de lui-même.', 2),
    ('a4143fe0-747a-5668-946b-a19377b59d54'::uuid, 'francais', '2de', 'Repères : le roman et le récit, du XVIIIe au XXIe siècle', 'Qu’est-ce que la focalisation externe ?', 'mcq', '["Le narrateur sait tout","On connaît les pensées d’un personnage","Un personnage raconte à la première personne","On ne voit que les comportements, sans accès aux pensées"]'::jsonb, 3, 'Le lecteur observe de l’extérieur, comme une caméra : il doit deviner ce que pensent les personnages.', 3),
    ('8fcbda91-afe4-5b58-ba86-1c41f52593b3'::uuid, 'francais', '2de', 'Repères : le roman et le récit, du XVIIIe au XXIe siècle', 'Qui est l’auteur de Manon Lescaut ?', 'mcq', '["L’abbé Prévost","Laclos","Voltaire","Rousseau"]'::jsonb, 0, 'Au XVIIIe siècle, le roman conquiert sa légitimité en se déguisant : mémoires fictifs chez Prévost, lettres chez Laclos, conte chez Voltaire.', 4),
    ('6cf6e5de-5b61-57dc-b294-e5dc0a42a98a'::uuid, 'francais', '2de', 'Récit réaliste et critique sociale : Maupassant et le XIXe siècle', 'Combien de nouvelles Maupassant a-t-il écrites environ ?', 'mcq', '["Une trentaine","Une centaine","Environ trois cents","Plus de mille"]'::jsonb, 2, 'Environ trois cents nouvelles, souvent courtes et resserrées autour d’une situation, avec une chute qui retourne le sens.', 1),
    ('8b2b3f23-dd4f-540e-b1ee-4de009e7969c'::uuid, 'francais', '2de', 'Récit réaliste et critique sociale : Maupassant et le XIXe siècle', 'Que met en accusation « La Parure » ?', 'mcq', '["La guerre de 1870","La vanité et le culte de l’apparence","La corruption des juges","La misère ouvrière"]'::jsonb, 1, 'Dix ans de misère pour rembourser un bijou qui était faux : la chute ne surprend pas seulement, elle accuse.', 2),
    ('d49a8f6a-4a6d-5716-871a-bf67684cd07e'::uuid, 'francais', '2de', 'Récit réaliste et critique sociale : Maupassant et le XIXe siècle', 'Quel est le rôle du « détail vrai » dans le récit réaliste ?', 'mcq', '["Il ralentit l’action","Il remplace les dialogues","Il annonce la fin","Il fait croire au reste du récit"]'::jsonb, 3, 'Un détail exact et concret rend le monde du récit crédible, et le lecteur accepte le reste.', 3),
    ('7d8525a3-6ea1-5516-a84f-ec5e45f36c3b'::uuid, 'francais', '2de', 'Récit réaliste et critique sociale : Maupassant et le XIXe siècle', 'Pourquoi Maupassant reste-t-il plus proche du réalisme que du naturalisme ?', 'mcq', '["Il accuse la société sans se réclamer d’une science","Il refuse de décrire les milieux populaires","Il écrit des romans en vers","Il invente des mondes merveilleux"]'::jsonb, 0, 'Le naturalisme de Zola se veut scientifique (hérédité, milieu) ; Maupassant montre sans théorie.', 4),
    ('3fe58c69-96c2-5373-99ca-93e534ad1eed'::uuid, 'francais', '2de', 'L’Étranger de Camus : une œuvre « à part »', 'Dans quelle ville Meursault est-il employé ?', 'mcq', '["Oran","Paris","Alger","Marseille"]'::jsonb, 2, 'Le roman raconte quelques mois de la vie de Meursault, employé à Alger, à la première personne.', 1),
    ('e7744cf9-93ed-56c8-b54e-506ac8e5c2a4'::uuid, 'francais', '2de', 'L’Étranger de Camus : une œuvre « à part »', 'Par quel événement le roman s’ouvre-t-il ?', 'mcq', '["La mort de la mère de Meursault","Le meurtre sur la plage","Le procès","La rencontre avec Marie"]'::jsonb, 0, 'Le roman s’ouvre sur la mort de sa mère et l’enterrement, où son absence de larmes lui sera reprochée au procès.', 2),
    ('141b0bd0-6d73-57c6-b7a4-d61816b1892f'::uuid, 'francais', '2de', 'L’Étranger de Camus : une œuvre « à part »', 'Quelle œuvre du cycle de l’absurde est un essai ?', 'mcq', '["L’Étranger","Caligula","La Peste","Le Mythe de Sisyphe"]'::jsonb, 3, 'Le cycle de l’absurde réunit un roman, L’Étranger, une pièce, Caligula, et un essai, Le Mythe de Sisyphe.', 3),
    ('fca846a5-8bc4-52c7-9555-cdac2314adbd'::uuid, 'francais', '2de', 'L’Étranger de Camus : une œuvre « à part »', 'En quoi consiste la révolte, chez Camus ?', 'mcq', '["Fuir le monde","Vivre lucidement, sans se raconter d’histoires","Obéir aux rituels sociaux","Chercher un sens caché dans chaque événement"]'::jsonb, 1, 'Face au silence du monde, la révolte n’invente pas de consolation : elle regarde l’absurde en face.', 4),
    ('a0e7205c-0a73-5e14-b47b-507bed288306'::uuid, 'francais', '2de', 'L’autobiographie : pourquoi s’écrire ? Comment s’écrire ?', 'Qui a formulé la notion de pacte autobiographique ?', 'mcq', '["Jean-Jacques Rousseau","Annie Ernaux","Philippe Lejeune","Montaigne"]'::jsonb, 2, 'Le critique Philippe Lejeune a défini ce pacte : l’auteur, le narrateur et le personnage sont une même personne.', 1),
    ('878891bd-2e32-5632-83b1-97b748a083cc'::uuid, 'francais', '2de', 'L’autobiographie : pourquoi s’écrire ? Comment s’écrire ?', 'Qu’est-ce qui distingue les Mémoires de l’autobiographie ?', 'mcq', '["Ils sont écrits au jour le jour","Ils racontent une époque à travers un témoin","Ils sont entièrement inventés","Ils sont écrits à la deuxième personne"]'::jsonb, 1, 'L’autobiographie met l’accent sur la vie individuelle ; les Mémoires, sur les événements dont l’auteur a été témoin.', 2),
    ('79cbc776-9f6c-598e-9b8c-e7f399176c36'::uuid, 'francais', '2de', 'L’autobiographie : pourquoi s’écrire ? Comment s’écrire ?', 'Qu’est-ce qu’un roman autobiographique ?', 'mcq', '["Un journal intime publié","Une biographie écrite par un historien","Un récit sans aucun lien avec la vie de l’auteur","Un récit où la fiction sert de paravent à la vie de l’auteur"]'::jsonb, 3, 'L’auteur change les noms et invente : la fiction lui permet de raconter sa vie sans s’engager au pacte autobiographique.', 3),
    ('38ff344f-dcd2-50b2-ba1f-c34afe3dee89'::uuid, 'francais', '2de', 'L’autobiographie : pourquoi s’écrire ? Comment s’écrire ?', 'Quel problème la mémoire pose-t-elle à l’autobiographe ?', 'mcq', '["Elle trie, déforme et invente sans le vouloir","Elle garde tout avec exactitude","Elle interdit d’écrire à la première personne","Elle oblige à tout inventer"]'::jsonb, 0, 'Même sincère, l’autobiographe reconstruit : la sincérité n’est pas la vérité.', 4),
    ('b9f3dc9e-b8cf-509a-b769-8a79a78511ff'::uuid, 'francais', '2de', 'Parcours du héros et engagement social : Qu’Allah bénisse la France, Abd Al Malik', 'Quel est le nom de naissance d’Abd Al Malik ?', 'mcq', '["Mohamed Diallo","Régis Fayette-Mikano","Karim Benali","Paul Mbemba"]'::jsonb, 1, 'Né Régis Fayette-Mikano en 1975, il prend le nom d’Abd Al Malik après sa conversion.', 1),
    ('8b83eb01-f05b-5da1-a0fa-872d36d0ddfd'::uuid, 'francais', '2de', 'Parcours du héros et engagement social : Qu’Allah bénisse la France, Abd Al Malik', 'De quelle origine est sa famille ?', 'mcq', '["Sénégalaise","Marocaine","Haïtienne","Congolaise"]'::jsonb, 3, 'Le récit part d’une famille congolaise installée à Strasbourg, dans la précarité.', 2),
    ('6b50cfff-c52f-53cc-af21-96843cfc559e'::uuid, 'francais', '2de', 'Parcours du héros et engagement social : Qu’Allah bénisse la France, Abd Al Malik', 'Quel islam l’auteur choisit-il après sa conversion ?', 'mcq', '["Un islam politique","Aucun, il y renonce","Un islam soufi de paix","Un islam rigoriste"]'::jsonb, 2, 'Le soufisme lui apporte une discipline intérieure, un travail sur soi que le livre présente comme une issue.', 3),
    ('4f991288-b95d-51dc-a56f-4d8bf7fecf55'::uuid, 'francais', '2de', 'Parcours du héros et engagement social : Qu’Allah bénisse la France, Abd Al Malik', 'Que réalise Abd Al Malik à partir de son livre en 2014 ?', 'mcq', '["Un film","Une pièce de théâtre","Une bande dessinée","Un opéra"]'::jsonb, 0, 'Il en tire d’abord un album, puis réalise en 2014 un film qui porte le même titre.', 4),
    ('fe5c0396-9bd3-5df2-aa6c-7ce03a161247'::uuid, 'francais', '2de', 'Écritures urbaines et représentations sociales', 'Quels lieux de Paris Hugo met-il en scène dans Les Misérables ?', 'mcq', '["Les Halles et le grand magasin","La pension Vauquer","Les égouts et les barricades","Les banlieues et les grands ensembles"]'::jsonb, 2, 'Chez Hugo, Balzac et Zola, la ville du XIXe siècle devient un outil d’analyse sociale.', 1),
    ('c987c9d7-a278-5099-a6a1-64cdfe275804'::uuid, 'francais', '2de', 'Écritures urbaines et représentations sociales', 'À quel quartier aristocratique Balzac oppose-t-il la pension Vauquer ?', 'mcq', '["Le quartier Latin","Le faubourg Saint-Germain","Montmartre","Le Marais"]'::jsonb, 1, 'La modeste pension et le faubourg aristocratique marquent les deux extrémités de l’échelle sociale parisienne.', 2),
    ('a11d5899-d7b9-5082-a8c6-8262a2d352b9'::uuid, 'francais', '2de', 'Écritures urbaines et représentations sociales', 'Que révèle l’opposition centre / périphérie dans un récit ?', 'mcq', '["Un simple changement de décor","Une erreur de géographie","Le goût de l’auteur pour la nature","Une hiérarchie spatiale et sociale"]'::jsonb, 3, 'Dire où quelqu’un habite, c’est déjà dire ce qu’il peut espérer : la ville classe les personnages.', 3),
    ('062f1885-7e52-5e5c-b0ba-260265e17129'::uuid, 'francais', '2de', 'Écritures urbaines et représentations sociales', 'Quelles écritures entrent dans le champ du roman au XXe siècle ?', 'mcq', '["La littérature ouvrière, puis les écritures issues de l’immigration","Les chansons de geste","Les romans de chevalerie","Les fables animalières"]'::jsonb, 0, 'Le roman s’ouvre aux marges — la cité, la zone, l’usine — et à ceux qui les habitent.', 4),
    ('909dabd3-7a74-5589-b89a-7ba5ff2cb9ad'::uuid, 'francais', '2de', 'Le vocabulaire du théâtre', 'Qu’est-ce qu’une stichomythie ?', 'mcq', '["Une longue réplique","Une parole seule en scène","Un échange de répliques très courtes","Une indication de décor"]'::jsonb, 2, 'La stichomythie accélère le rythme, souvent dans un affrontement : chaque personnage répond du tac au tac.', 1),
    ('8d124969-5612-5910-bb5e-43d6ae4b30a1'::uuid, 'francais', '2de', 'Le vocabulaire du théâtre', 'Comment appelle-t-on une longue réplique ?', 'mcq', '["Un aparté","Une tirade","Une didascalie","Une stichomythie"]'::jsonb, 1, 'La tirade est une longue réplique adressée à d’autres personnages ; le monologue est une parole seule en scène.', 2),
    ('4bddfd4a-96d3-53e7-8f66-d5a51e7bdb0d'::uuid, 'francais', '2de', 'Le vocabulaire du théâtre', 'Quel est le rôle de l’exposition ?', 'mcq', '["Résoudre le conflit","Relancer l’action","Renverser brutalement la situation","Informer le spectateur de la situation"]'::jsonb, 3, 'L’exposition informe ; le nœud installe le conflit, les péripéties le relancent, le dénouement le résout.', 3),
    ('15d4fc3d-8356-5007-a49f-9daaead1de56'::uuid, 'francais', '2de', 'Le vocabulaire du théâtre', 'Qu’est-ce qu’un coup de théâtre ?', 'mcq', '["Un renversement brutal de la situation","Le lever de rideau","Une scène comique","Une réplique adressée au public"]'::jsonb, 0, 'Il bouleverse soudain l’action et relance l’intérêt du spectateur.', 4),
    ('edace3f3-0c1a-5b56-8cf6-b814a844dd89'::uuid, 'francais', '2de', 'L’impossible amour : Roméo et Juliette, Shakespeare', 'Vers quelle année Roméo et Juliette est-elle écrite ?', 'mcq', '["Vers 1450","Vers 1660","Vers 1595","Vers 1830"]'::jsonb, 2, 'Shakespeare l’écrit vers 1595, bien avant les règles classiques françaises.', 1),
    ('2067d205-4ff3-5d95-a7ca-67f6bc874bdc'::uuid, 'francais', '2de', 'L’impossible amour : Roméo et Juliette, Shakespeare', 'À qui les parents de Juliette la destinent-ils ?', 'mcq', '["À Mercutio","À Pâris","À Tybalt","Au prince"]'::jsonb, 1, 'Juliette est promise à Pâris sans qu’on lui demande son avis : l’ordre patriarcal est l’un des obstacles de la pièce.', 2),
    ('526bd00c-8f58-5f00-bdf3-b22ac4d7874c'::uuid, 'francais', '2de', 'L’impossible amour : Roméo et Juliette, Shakespeare', 'Quels personnages apportent le registre comique ?', 'mcq', '["Roméo et Juliette","Le prince et Pâris","Les chefs des deux familles","La nourrice et Mercutio"]'::jsonb, 3, 'Shakespeare mêle comique et tragique, ce que les classiques français condamneront et que les romantiques admireront.', 3),
    ('3183c6b5-b3cd-5fab-ae90-3bc11fba08fa'::uuid, 'francais', '2de', 'L’impossible amour : Roméo et Juliette, Shakespeare', 'Qui dit le prologue de la pièce ?', 'mcq', '["Un chœur","Roméo","La nourrice","Le prince de Vérone"]'::jsonb, 0, 'Dès l’ouverture, le chœur annonce la mort des amants : le spectateur ne se demande plus ce qui va arriver, mais comment.', 4),
    ('09ab9ee5-3f26-5f4b-b7ea-1ef8ccc29e81'::uuid, 'francais', '2de', 'Drame romantique et triangle amoureux : Les Caprices de Marianne, Musset', 'Dans quel recueil Musset publie-t-il son théâtre, d’abord écrit pour être lu ?', 'mcq', '["Les Nuits","La Confession d’un enfant du siècle","Un spectacle dans un fauteuil","Premières poésies"]'::jsonb, 2, 'Après l’échec de sa première pièce, Musset écrit un théâtre destiné à la lecture.', 1),
    ('4d40239b-d2f4-5480-87f0-85cac8def68b'::uuid, 'francais', '2de', 'Drame romantique et triangle amoureux : Les Caprices de Marianne, Musset', 'Quel rapport à l’amour Octave incarne-t-il ?', 'mcq', '["L’idéaliste qui préfère le rêve","Le libertin cynique qui se découvre incapable d’aimer","Le mari jaloux","Le père autoritaire"]'::jsonb, 1, 'Face à Cœlio l’idéaliste, Octave le libertin : les deux amis sont « deux moitiés d’un même homme ».', 2),
    ('d0102f0e-4530-5e72-bc7e-d328eb7d4269'::uuid, 'francais', '2de', 'Drame romantique et triangle amoureux : Les Caprices de Marianne, Musset', 'Comment Cœlio meurt-il ?', 'mcq', '["Il se suicide","Il meurt en duel contre Octave","Il est tué à la guerre","Il est tué par les hommes de Claudio lors d’un rendez-vous piégé"]'::jsonb, 3, 'Un malentendu l’envoie à un rendez-vous où l’attendent les hommes du mari : le hasard remplace la nécessité tragique.', 3),
    ('099da36c-9949-5f5b-a484-3b7d06c2df01'::uuid, 'francais', '2de', 'Drame romantique et triangle amoureux : Les Caprices de Marianne, Musset', 'Dans quel livre Musset analyse-t-il le mal du siècle ?', 'mcq', '["La Confession d’un enfant du siècle","Lorenzaccio","Hernani","Les Contemplations"]'::jsonb, 0, 'Il y décrit une génération née après Napoléon, sans guerre à faire ni foi solide, entre rêve et cynisme.', 4),
    ('2cec3b86-bb16-55b8-83fb-20b285f490d5'::uuid, 'francais', '2de', 'Héros tragique et destin meurtrier : Roberto Zucco, Koltès', 'En quelle année Roberto Zucco est-elle créée ?', 'mcq', '["1968","1975","1990","2005"]'::jsonb, 2, 'Koltès l’écrit peu avant sa mort, survenue en 1989 ; la pièce est créée l’année suivante.', 1),
    ('64fa104d-1c1b-50bb-b337-f42d88adfdd8'::uuid, 'francais', '2de', 'Héros tragique et destin meurtrier : Roberto Zucco, Koltès', 'Que rappelle la progression de la pièce par tableaux ?', 'mcq', '["La comédie de boulevard","La tragédie antique et le chemin de croix","Le roman-feuilleton","La farce médiévale"]'::jsonb, 1, 'Quinze stations, des lieux traversés : un chemin plutôt qu’une intrigue.', 2),
    ('d141838c-2488-5048-80ff-b9b2edc0a7b8'::uuid, 'francais', '2de', 'Héros tragique et destin meurtrier : Roberto Zucco, Koltès', 'Comment Koltès répond-il à ceux qui l’accusent de glorifier un criminel ?', 'mcq', '["Il retire la pièce","Il ajoute une morale finale","Il explique l’enfance du criminel","Zucco n’est pas un portrait mais une figure, comme Œdipe ou Médée"]'::jsonb, 3, 'Le personnage n’est pas la copie du criminel réel : c’est une figure mythique, que Koltès demande seulement de regarder.', 3),
    ('92abcc4f-53bf-52d1-922a-fedd17d1d3ca'::uuid, 'francais', '2de', 'Héros tragique et destin meurtrier : Roberto Zucco, Koltès', 'Que vise la pièce, selon Koltès ?', 'mcq', '["La violence d’une société entière","La folie d’un seul homme","Le fonctionnement de la police","La vie en prison"]'::jsonb, 0, 'Plutôt que d’expliquer un individu, la pièce montre la violence du monde qu’il traverse.', 4),
    ('5f74c15a-2a51-5f8e-8548-4d44dff0811a'::uuid, 'francais', '2de', 'Les représentations de la mort dans le théâtre', 'Quel théâtre français revendique de montrer la mort sur scène au nom de la vérité ?', 'mcq', '["La tragédie classique","La comédie de mœurs","Le drame romantique","Le théâtre de l’absurde"]'::jsonb, 2, 'Contre la bienséance classique, le drame romantique réclame la liberté de tout montrer.', 1),
    ('34126e3a-9d53-5129-90a2-2a7aa294b7b3'::uuid, 'francais', '2de', 'Les représentations de la mort dans le théâtre', 'Que fait Beckett de la mort ?', 'mcq', '["Un spectacle montré en détail","Une attente : on n’en finit pas de mourir","Une fête","Un récit de messager"]'::jsonb, 1, 'Chez Beckett, l’attente est le sujet : la mort n’arrive pas, elle s’étire.', 2),
    ('509bfa0b-4668-508e-8346-e9760b879a9d'::uuid, 'francais', '2de', 'Les représentations de la mort dans le théâtre', 'Quel est le rôle du chœur dans la représentation de la mort ?', 'mcq', '["Il remplace le décor","Il cache la mort","Il fait rire","Il commente et amplifie"]'::jsonb, 3, 'Le chœur donne à la mort une portée collective, en la commentant plutôt qu’en la montrant.', 3),
    ('40212352-8fcf-5c31-a741-c3bdd7347c68'::uuid, 'francais', '2de', 'Les représentations de la mort dans le théâtre', 'Quelle différence y a-t-il entre montrer une mort et la faire raconter ?', 'mcq', '["Montrée, c’est un fait ; racontée, c’est un événement de langage","Aucune différence","Racontée, elle est toujours comique","Montrée, elle est interdite partout"]'::jsonb, 0, 'Faire entrer un cadavre ou faire un récit ne raconte pas la même histoire : le hors-scène confie à la parole le soin de faire voir.', 4),
    ('82336921-01e6-5ef6-bdf1-b2d5d67f7842'::uuid, 'francais', '2de', 'Repères : le théâtre, du XVIIe au XXIe siècle', 'Quel conflit est au cœur du théâtre de Corneille ?', 'mcq', '["La fatalité amoureuse","La critique des mœurs","Le conflit du devoir et de la passion","L’absurdité de l’existence"]'::jsonb, 2, 'Corneille oppose le devoir et la passion ; Racine peint la fatalité amoureuse ; Molière, les caractères et les mœurs.', 1),
    ('319cd71a-bff6-592a-aead-7d657d20b7d5'::uuid, 'francais', '2de', 'Repères : le théâtre, du XVIIe au XXIe siècle', 'Qu’apporte Marivaux au théâtre du XVIIIe siècle ?', 'mcq', '["Les trois unités","Le langage du sentiment et le brouillage des rangs sociaux","Le théâtre de l’absurde","La distanciation"]'::jsonb, 1, 'Chez Marivaux, maîtres et valets échangent parfois leurs rôles, et l’amour se découvre à travers le langage.', 2),
    ('58228d67-a7bf-525f-83bd-cec3ced20c4b'::uuid, 'francais', '2de', 'Repères : le théâtre, du XVIIe au XXIe siècle', 'Que met en scène le drame bourgeois ?', 'mcq', '["Des rois et des dieux","Des animaux qui parlent","Des scènes sans dialogue","Des héros ordinaires et des sujets sérieux"]'::jsonb, 3, 'Au XVIIIe siècle, le drame bourgeois donne un sujet grave à des personnages qui ne sont ni rois ni héros.', 3),
    ('73bf4024-b5d7-51dd-8e8f-dee2939133be'::uuid, 'francais', '2de', 'Repères : le théâtre, du XVIIe au XXIe siècle', 'Qu’est le théâtre au XVIIe siècle ?', 'mcq', '["Un art de cour, soumis à la censure et au goût du roi","Un art libre de toute règle","Un spectacle réservé aux paysans","Un art interdit par l’Église"]'::jsonb, 0, 'Le public, la salle et ce qu’on autorise à montrer façonnent le théâtre : au XVIIe siècle, c’est le roi qui donne le ton.', 4),
    ('c5261514-ccb0-5b28-941f-b1b02bac1b80'::uuid, 'histoire-geo', '2de', 'Les grandes périodes de l’histoire', 'Vers quelle date l’invention de l’écriture met-elle fin à la Préhistoire ?', 'mcq', '["Vers 10 000 av. J.-C.","Vers 753 av. J.-C.","Vers 3300 av. J.-C.","Vers 476 apr. J.-C."]'::jsonb, 2, 'L’écriture apparaît vers 3300 av. J.-C. en Mésopotamie : elle ouvre l’Antiquité.', 1),
    ('a696d525-a198-5f86-99e2-c723322c8a70'::uuid, 'histoire-geo', '2de', 'Les grandes périodes de l’histoire', 'Quel événement ouvre traditionnellement l’époque moderne ?', 'mcq', '["L’arrivée de Colomb en Amérique en 1492","La Révolution française en 1789","La chute de Rome en 476","La fin de la Première Guerre mondiale"]'::jsonb, 0, 'L’époque moderne va de 1492, l’arrivée de Colomb en Amérique, à 1789, la Révolution française.', 2),
    ('3bed0da5-e764-5a21-9cb8-db4a9956fa8e'::uuid, 'histoire-geo', '2de', 'Les grandes périodes de l’histoire', 'Le récit d’un ancien combattant recueilli par un historien est une source…', 'mcq', '["Matérielle","Iconographique","Écrite","Orale"]'::jsonb, 3, 'Un témoignage est une source orale ; comme les autres, l’historien doit la critiquer avant de la croire.', 3),
    ('757f06ab-95ea-5b45-90da-bbc8db1a062c'::uuid, 'histoire-geo', '2de', 'Les grandes périodes de l’histoire', 'Quand et où est né le découpage en cinq grandes périodes ?', 'mcq', '["En Chine, au Moyen Âge","En Europe, au XIXe siècle","À Rome, dans l’Antiquité","À l’ONU, après 1945"]'::jsonb, 1, 'Né en Europe au XIXe siècle, ce découpage éclaire mal l’histoire propre de la Chine, de l’Afrique ou des Amériques.', 4),
    ('e3c0efef-83b1-5e6e-8ec2-00149051a8b9'::uuid, 'histoire-geo', '2de', 'Athènes : la mise en place d’un contexte favorable à la naissance de la démocratie', 'Comment s’appelle la place publique d’une cité grecque ?', 'mcq', '["L’acropole","L’agora","La chôra","La Pnyx"]'::jsonb, 1, 'L’agora est la place publique ; l’acropole est la ville haute des dieux, la chôra la campagne alentour.', 1),
    ('2bca6cde-aa00-59d7-b580-9fd48c09f323'::uuid, 'histoire-geo', '2de', 'Athènes : la mise en place d’un contexte favorable à la naissance de la démocratie', 'Selon quel critère Solon classe-t-il les citoyens en 594 av. J.-C. ?', 'mcq', '["Leur naissance","Leur âge","Leur richesse","Leur métier"]'::jsonb, 2, 'En classant les citoyens selon leur richesse et non leur naissance, Solon retire du pouvoir à l’aristocratie.', 2),
    ('fb207277-6fbd-55d9-9c42-483b4e0486c1'::uuid, 'histoire-geo', '2de', 'Athènes : la mise en place d’un contexte favorable à la naissance de la démocratie', 'Que fixe la loi de Périclès de 451 av. J.-C. ?', 'mcq', '["Le tirage au sort de la Boulè","L’abolition de l’esclavage pour dettes","L’ostracisme","Il faut être né de parents athéniens pour être citoyen"]'::jsonb, 3, 'Depuis 451, seul un homme adulte né de père et de mère athéniens est citoyen : le corps civique se ferme.', 3),
    ('e86c38de-3c7b-5a7a-9ce8-4d3ecf7f92ef'::uuid, 'histoire-geo', '2de', 'Athènes : la mise en place d’un contexte favorable à la naissance de la démocratie', 'Dans l’Athènes démocratique, les citoyens forment la grande majorité de la population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Femmes, métèques et esclaves sont exclus de la citoyenneté : ensemble, ils forment la grande majorité des habitants.', 4),
    ('f6ec30e9-b4f8-5f71-83f9-2ed89ad9e6fc'::uuid, 'histoire-geo', '2de', 'Ve siècle av. J.-C. : Athènes, une démocratie au centre d’un empire maritime', 'Quelle bataille de 490 av. J.-C. est la première victoire terrestre sur les Perses ?', 'mcq', '["Salamine","Platées","Marathon","Les Thermopyles"]'::jsonb, 2, 'Marathon (490) est la première victoire terrestre ; Salamine (480) est la victoire navale décisive, Platées (479) met fin à l’invasion.', 1),
    ('e6abe6f3-578d-5550-b5df-8306f16b4443'::uuid, 'histoire-geo', '2de', 'Ve siècle av. J.-C. : Athènes, une démocratie au centre d’un empire maritime', 'Pourquoi la victoire de Salamine renforce-t-elle le poids des thètes ?', 'mcq', '["Ce sont les riches qui ont payé la flotte","Ces citoyens pauvres étaient les rameurs de la flotte","Ce sont des hoplites lourdement armés","Ce sont des mercenaires étrangers"]'::jsonb, 1, 'Les thètes, citoyens pauvres, ramaient sur les trières : devenus indispensables, ils sont écoutés à l’assemblée.', 2),
    ('7cd515ac-c0af-5830-ba94-ff94e3969e7b'::uuid, 'histoire-geo', '2de', 'Ve siècle av. J.-C. : Athènes, une démocratie au centre d’un empire maritime', 'Que désigne l’isonomie ?', 'mcq', '["L’égalité des citoyens devant la loi","L’égal partage des terres","Le droit de vote des femmes","L’élection des magistrats"]'::jsonb, 0, 'L’isonomie est l’égalité devant la loi ; l’isègoria, l’égal droit de parole à l’assemblée.', 3),
    ('ef0e8bdf-3429-5e90-a4ad-8aa1d829e42c'::uuid, 'histoire-geo', '2de', 'Ve siècle av. J.-C. : Athènes, une démocratie au centre d’un empire maritime', 'Quel est le rôle de l’Héliée ?', 'mcq', '["Préparer les séances de l’assemblée","Commander l’armée","Percevoir le tribut des alliés","Juger, avec des jurés tirés au sort"]'::jsonb, 3, 'L’Héliée est le tribunal populaire : ses jurés sont tirés au sort parmi les citoyens.', 4),
    ('b9674faa-9129-5da8-8384-382fba180e94'::uuid, 'histoire-geo', '2de', 'De la constitution de l’Empire romain à son apogée', 'Comment appelle-t-on le régime mis en place par Auguste ?', 'mcq', '["Le Principat","La République","La tétrarchie","La dictature perpétuelle"]'::jsonb, 0, 'Auguste concentre les pouvoirs tout en gardant les apparences républicaines : c’est le Principat.', 1),
    ('3df822bd-5348-5162-be56-542f955754b4'::uuid, 'histoire-geo', '2de', 'De la constitution de l’Empire romain à son apogée', 'Combien d’habitants compte environ l’Empire romain à son apogée ?', 'mcq', '["6 millions","60 millions","600 millions","1 milliard"]'::jsonb, 1, 'Environ 60 millions d’habitants vivent dans un Empire qui s’étend, sous Trajan, de la Bretagne à l’Euphrate.', 2),
    ('04ed50f6-35aa-5c7c-b914-847cb7dd76a8'::uuid, 'histoire-geo', '2de', 'De la constitution de l’Empire romain à son apogée', 'En quelle année Jules César est-il assassiné ?', 'mcq', '["27 av. J.-C.","509 av. J.-C.","44 av. J.-C.","14 apr. J.-C."]'::jsonb, 2, 'César, devenu dictateur au terme des guerres civiles, est assassiné en 44 av. J.-C. ; Octave devient Auguste en 27.', 3),
    ('c27385dc-d4a5-5588-963f-2ec652b3217f'::uuid, 'histoire-geo', '2de', 'De la constitution de l’Empire romain à son apogée', 'Qu’est-ce qui ébranle l’Empire au IIIe siècle ?', 'mcq', '["L’édit de Caracalla","La conversion au christianisme","La fondation de Constantinople","Les invasions, les usurpations et la crise monétaire"]'::jsonb, 3, 'Au IIIe siècle, invasions, usurpations et crise monétaire ébranlent un système fondé sur l’esclavage, l’armée et une lourde fiscalité.', 4),
    ('f8ba928e-aed8-53cd-b1a1-414f70a2a2c6'::uuid, 'histoire-geo', '2de', 'Constantin : la reconstruction d’un empire méditerranéen sur des bases chrétiennes au IVe siècle', 'Quel empereur met en place la tétrarchie ?', 'mcq', '["Constantin","Théodose","Trajan","Dioclétien"]'::jsonb, 3, 'Dioclétien (284-305) partage le pouvoir entre quatre empereurs et renforce l’administration.', 1),
    ('7f3c06b7-ee36-53cf-a15d-4ff7f0414e24'::uuid, 'histoire-geo', '2de', 'Constantin : la reconstruction d’un empire méditerranéen sur des bases chrétiennes au IVe siècle', 'Sur le site de quelle cité Constantinople est-elle fondée en 330 ?', 'mcq', '["Byzance","Nicée","Antioche","Alexandrie"]'::jsonb, 0, 'Constantinople est bâtie sur le site de l’ancienne Byzance, qui contrôle les détroits entre Europe et Asie.', 2),
    ('a9734d64-89e4-56fa-962e-7e2cc8599263'::uuid, 'histoire-geo', '2de', 'Constantin : la reconstruction d’un empire méditerranéen sur des bases chrétiennes au IVe siècle', 'À partir de quelle année Constantin règne-t-il seul ?', 'mcq', '["312","313","324","330"]'::jsonb, 2, 'Vainqueur au pont Milvius en 312, Constantin ne règne seul qu’à partir de 324 : la tétrarchie n’a pas survécu à Dioclétien.', 3),
    ('ee2f9af8-ac80-5ecd-9fd7-7fab2f2f2da1'::uuid, 'histoire-geo', '2de', 'Constantin : la reconstruction d’un empire méditerranéen sur des bases chrétiennes au IVe siècle', 'Comment Constantin soutient-il l’Église ?', 'mcq', '["Il interdit tous les cultes païens","Il finance les églises et exempte le clergé","Il nomme lui-même le pape","Il fait du christianisme la religion officielle"]'::jsonb, 1, 'Constantin finance les églises, exempte le clergé et arbitre les querelles ; c’est Théodose qui fera du christianisme la religion officielle.', 4),
    ('6bb8a235-2fda-518e-ba05-1a1a7241a4dc'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace de rencontres et de conflits au Moyen Âge', 'Dans quelle ville Urbain II lance-t-il l’appel à la croisade en 1095 ?', 'mcq', '["Rome","Clermont","Paris","Venise"]'::jsonb, 1, 'C’est à Clermont, en 1095, que le pape Urbain II appelle à délivrer Jérusalem.', 1),
    ('94bd7d5e-1ae7-5b56-b201-c938976e66eb'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace de rencontres et de conflits au Moyen Âge', 'Quelles villes sont les grands centres du monde musulman médiéval ?', 'mcq', '["Rome, Tolède et Palerme","Constantinople, Nicée et Antioche","Bagdad, Le Caire et Cordoue","Acre, Tripoli et Édesse"]'::jsonb, 2, 'Bagdad, Le Caire et Cordoue sont les centres d’un Islam riche, urbain et savant.', 2),
    ('7febdebf-2ed5-5028-b584-ee8fcfaf396e'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace de rencontres et de conflits au Moyen Âge', 'Quelle ville espagnole les chrétiens reprennent-ils en 1085 ?', 'mcq', '["Tolède","Grenade","Cordoue","Séville"]'::jsonb, 0, 'La prise de Tolède en 1085 est une étape de la Reconquista, avant Las Navas de Tolosa (1212) et Grenade (1492).', 3),
    ('9135624b-f4d8-5a4b-827d-3f42cd733eda'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace de rencontres et de conflits au Moyen Âge', 'Qui prend le pouvoir en Sicile, île jusque-là arabe ?', 'mcq', '["Les Byzantins","Les Vénitiens","Les Castillans","Les Normands"]'::jsonb, 3, 'Dans la Sicile normande, chrétiens, musulmans et juifs cohabitent, commercent et se traduisent.', 4),
    ('4a734f29-7aec-5623-97be-190498bd9c55'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace d’échanges entre les civilisations', 'Qu’est-ce que la commende ?', 'mcq', '["Une taxe sur les épices","Un contrat qui associe un bailleur de fonds et un marchand voyageur","Un ordre religieux","Un navire de guerre vénitien"]'::jsonb, 1, 'La commende associe celui qui avance l’argent et celui qui part en mer : ils se partagent le profit.', 1),
    ('162eaa61-ccf9-5b0c-8d63-9a561642dc95'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace d’échanges entre les civilisations', 'Dans quel domaine al-Khwarizmi a-t-il marqué les savoirs ?', 'mcq', '["La médecine","La philosophie d’Aristote","L’algèbre","La géographie"]'::jsonb, 2, 'Al-Khwarizmi est associé à l’algèbre ; son nom a d’ailleurs donné le mot « algorithme ».', 2),
    ('0d5e4695-8c64-5c5b-ad80-27b1cefb20da'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace d’échanges entre les civilisations', 'Que vendent surtout les marchands italiens dans les ports d’Orient ?', 'mcq', '["Des draps, des métaux, du bois et des armes","Des épices et de la soie","Du sucre et de l’alun","Du coton et des agrumes"]'::jsonb, 0, 'Les Italiens vendent draps, métaux, bois et armes, et achètent épices, soie, alun et sucre.', 3),
    ('9b2d9848-aec4-532e-baa9-a3a4bd8b0fd6'::uuid, 'histoire-geo', '2de', 'La Méditerranée, un espace d’échanges entre les civilisations', 'À quoi sert l’assurance maritime ?', 'mcq', '["À payer sans transporter d’or","À tenir des comptes exacts","À traduire les contrats","À répartir le risque du naufrage"]'::jsonb, 3, 'L’assurance répartit le risque d’un naufrage entre plusieurs personnes ; la lettre de change, elle, évite de transporter de l’or.', 4),
    ('935c074b-3640-5980-af65-da4f5054b151'::uuid, 'histoire-geo', '2de', 'L’élargissement du monde au XVe siècle', 'Qu’est-ce qu’un portulan ?', 'mcq', '["Un navire à voile latine","Une carte des côtes et des caps","Un instrument pour mesurer la latitude","Un traité de partage"]'::jsonb, 1, 'Le portulan représente les côtes, les caps et les ports ; l’astrolabe donne la latitude.', 1),
    ('aed4827f-08cb-5de7-9dcb-9facf4001e90'::uuid, 'histoire-geo', '2de', 'L’élargissement du monde au XVe siècle', 'Pour quel royaume Christophe Colomb navigue-t-il en 1492 ?', 'mcq', '["Le Portugal","L’Angleterre","La France","La Castille"]'::jsonb, 3, 'Colomb, marin génois, navigue pour la Castille, rivale du Portugal dans la course vers l’Asie.', 2),
    ('0ddfb215-d4f9-5966-9658-a56145a62b1f'::uuid, 'histoire-geo', '2de', 'L’élargissement du monde au XVe siècle', 'Pourquoi le Brésil devient-il portugais ?', 'mcq', '["Il se trouve à l’est de la ligne fixée par le traité de Tordesillas","Colomb l’a offert au roi du Portugal","Magellan l’a conquis en 1520","Il a été acheté à la Castille"]'::jsonb, 0, 'Le traité de Tordesillas (1494) donne l’ouest de la ligne à la Castille et l’est au Portugal : le Brésil tombe du côté portugais.', 3),
    ('48a5300b-5ca9-520a-a2ac-a25984abde59'::uuid, 'histoire-geo', '2de', 'L’élargissement du monde au XVe siècle', 'Quel est le principal atout de la caravelle ?', 'mcq', '["Elle peut porter cent canons","Elle est propulsée par des rameurs","Légère, elle peut remonter au vent","Elle navigue sans boussole"]'::jsonb, 2, 'Légère et maniable, la caravelle peut remonter au vent : elle permet de revenir des côtes africaines.', 4),
    ('b7a41818-d378-56fe-8b7f-9f67a2d449fd'::uuid, 'histoire-geo', '2de', 'La traite atlantique du XVIe au XIXe siècle : le cœur d’un nouveau circuit économique mondial', 'Qu’appelle-t-on le marronnage ?', 'mcq', '["La fuite des esclaves et les communautés d’évadés","Le commerce des captifs","Le travail dans les plantations de café","Le rachat de sa liberté"]'::jsonb, 0, 'Le marronnage est la fuite des esclaves, qui forment parfois des communautés d’évadés ; c’est une forme de résistance.', 1),
    ('5d93367d-33f4-5cb3-a076-9f78823fcdb5'::uuid, 'histoire-geo', '2de', 'La traite atlantique du XVIe au XIXe siècle : le cœur d’un nouveau circuit économique mondial', 'Quel statut le Code noir de 1685 donne-t-il à l’esclave ?', 'mcq', '["Celui de sujet du roi","Celui d’un bien meuble","Celui d’un serviteur libre","Celui d’un affranchi"]'::jsonb, 1, 'Le Code noir fait de l’esclave un bien meuble, autorise les châtiments et encadre l’affranchissement.', 2),
    ('53e1aa00-d98e-5c6e-99da-53b8d43726a1'::uuid, 'histoire-geo', '2de', 'La traite atlantique du XVIe au XIXe siècle : le cœur d’un nouveau circuit économique mondial', 'Qui rétablit l’esclavage dans les colonies françaises en 1802 ?', 'mcq', '["Louis XVI","Robespierre","Bonaparte","Victor Schœlcher"]'::jsonb, 2, 'Aboli en 1794, l’esclavage est rétabli par Bonaparte en 1802, puis aboli définitivement en 1848.', 3),
    ('90797f87-f832-5123-b747-8c26918055c6'::uuid, 'histoire-geo', '2de', 'La traite atlantique du XVIe au XIXe siècle : le cœur d’un nouveau circuit économique mondial', 'Quels sont les principaux transporteurs de la traite atlantique ?', 'mcq', '["Les Français","Les Britanniques","Les Néerlandais","Les Portugais et les Brésiliens"]'::jsonb, 3, 'Les Portugais et les Brésiliens ont transporté le plus de captifs, devant les Britanniques et les Français.', 4),
    ('270671dd-b475-5b38-8b92-7a217d3190af'::uuid, 'histoire-geo', '2de', 'Les conséquences des grandes découvertes', 'De combien la population indigène d’Amérique chute-t-elle en un siècle, selon les estimations ?', 'mcq', '["De 10 à 20 %","De 30 à 40 %","De 50 %","De 80 à 90 %"]'::jsonb, 3, 'Surtout à cause des maladies venues d’Europe, la population indigène chute de 80 à 90 % en un siècle.', 1),
    ('a3ab09c5-cf8a-5e35-bf7f-90396cff4073'::uuid, 'histoire-geo', '2de', 'Les conséquences des grandes découvertes', 'Lequel de ces produits a voyagé d’Europe vers l’Amérique ?', 'mcq', '["La canne à sucre","Le maïs","La tomate","Le cacao"]'::jsonb, 0, 'Blé, canne à sucre, bœufs et chevaux gagnent l’Amérique ; maïs, tomate et cacao font le trajet inverse.', 2),
    ('849735be-ef27-5077-9219-b88f6a07a8c5'::uuid, 'histoire-geo', '2de', 'Les conséquences des grandes découvertes', 'Qui la révolution des prix du XVIe siècle appauvrit-elle ?', 'mcq', '["Les marchands","Les rentiers","Les banquiers","Les propriétaires de mines"]'::jsonb, 1, 'La hausse des prix ronge les revenus fixes des rentiers, alors qu’elle favorise les marchands.', 3),
    ('084004dc-d349-5fb7-aceb-cec705f5e5b9'::uuid, 'histoire-geo', '2de', 'Les conséquences des grandes découvertes', 'Quel facteur est décisif militairement dans la victoire des conquistadors ?', 'mcq', '["Leur supériorité numérique","L’aide de l’armée portugaise","Leurs alliances avec des peuples soumis aux Aztèques ou aux Incas","Les canons de leurs navires"]'::jsonb, 2, 'Les armes à feu et les chevaux comptent, mais les alliances avec des peuples dominés sont décisives ; les microbes, eux, tuent le plus.', 4),
    ('ff20a14e-053e-5c33-8b29-143209a7258c'::uuid, 'histoire-geo', '2de', 'Renaissance et Humanisme : les mutations de l’Europe', 'Qui est l’auteur de L’Utopie ?', 'mcq', '["Érasme","Thomas More","Rabelais","Pétrarque"]'::jsonb, 1, 'L’humaniste anglais Thomas More publie L’Utopie en 1516 : il y imagine une société idéale.', 1),
    ('94b63eda-8a31-56f7-abcf-e5e69a6ceb3a'::uuid, 'histoire-geo', '2de', 'Renaissance et Humanisme : les mutations de l’Europe', 'Dans quelle ville Gutenberg met-il au point l’imprimerie ?', 'mcq', '["Mayence","Venise","Paris","Anvers"]'::jsonb, 0, 'C’est à Mayence, vers 1450, que Gutenberg invente les caractères mobiles métalliques.', 2),
    ('c95e0722-d13c-591f-bcce-c77582055e16'::uuid, 'histoire-geo', '2de', 'Renaissance et Humanisme : les mutations de l’Europe', 'Quel Italien inaugure le mouvement humaniste ?', 'mcq', '["Machiavel","Botticelli","Brunelleschi","Pétrarque"]'::jsonb, 3, 'Au XIVe siècle, Pétrarque ouvre le mouvement en Italie en redécouvrant les auteurs latins.', 3),
    ('89156119-5e07-5453-bd4d-01b9809aaf33'::uuid, 'histoire-geo', '2de', 'Renaissance et Humanisme : les mutations de l’Europe', 'Quel château François Ier fait-il bâtir, sous l’influence italienne ?', 'mcq', '["Versailles","Le Louvre","Chambord","Vincennes"]'::jsonb, 2, 'François Ier, qui attire Léonard de Vinci en France, fait bâtir Chambord à partir de 1519.', 4),
    ('7be683c1-4fb1-56dc-b672-c0ecc50b4410'::uuid, 'histoire-geo', '2de', 'Les réformes religieuses', 'À quoi sert l’argent des indulgences dénoncées par Luther ?', 'mcq', '["À financer la reconstruction de Saint-Pierre de Rome","À payer les croisades","À construire des écoles","À payer les soldats du pape"]'::jsonb, 0, 'Les indulgences, remises de peine vendues aux fidèles, financent la basilique Saint-Pierre de Rome.', 1),
    ('3d79f4a8-95fe-5ce3-9ff4-693ac9a11f40'::uuid, 'histoire-geo', '2de', 'Les réformes religieuses', 'Quel ouvrage Calvin publie-t-il en 1536 ?', 'mcq', '["Les 95 thèses","L’Utopie","L’Institution de la religion chrétienne","Le Nouveau Testament en grec"]'::jsonb, 2, 'L’Institution de la religion chrétienne (1536) expose la doctrine calviniste, installée à Genève.', 2),
    ('073933f7-e996-5dbd-a8e9-1e67ad04d008'::uuid, 'histoire-geo', '2de', 'Les réformes religieuses', 'Que crée le concile de Trente pour mieux former les prêtres ?', 'mcq', '["Les universités","Les séminaires","Les monastères","Les collèges de jésuites"]'::jsonb, 1, 'Le concile impose des séminaires pour former les curés, dont l’ignorance était l’une des critiques adressées à l’Église.', 3),
    ('0f9af423-b583-515e-8253-2d37c6800858'::uuid, 'histoire-geo', '2de', 'Les réformes religieuses', 'Quel art la Réforme catholique utilise-t-elle pour relancer la foi par l’émotion ?', 'mcq', '["L’art roman","L’art gothique","L’art classique","L’art baroque"]'::jsonb, 3, 'L’art baroque, spectaculaire et chargé, veut toucher le fidèle par l’émotion, à l’opposé du dépouillement protestant.', 4),
    ('1afe01f7-e5db-5d83-a41b-ed770d47173f'::uuid, 'histoire-geo', '2de', 'Martin Luther et le protestantisme', 'Que signifie le principe du sacerdoce universel ?', 'mcq', '["Tout croyant est prêtre","Le pape est le chef de tous les prêtres","Seuls les prêtres peuvent lire la Bible","Chaque prince nomme les prêtres"]'::jsonb, 0, 'Pour Luther, il n’y a pas de différence de nature entre prêtres et fidèles : tout croyant est prêtre.', 1),
    ('b9eb993a-7fbb-5812-8961-5bdd67706dc9'::uuid, 'histoire-geo', '2de', 'Martin Luther et le protestantisme', 'Que signifie le principe de « l’Écriture seule » ?', 'mcq', '["Seuls les clercs peuvent écrire","La Bible fait autorité, non la tradition de l’Église","La messe doit être lue en latin","Il faut apprendre la Bible par cœur"]'::jsonb, 1, 'Pour Luther, seule la Bible fait autorité ; les traditions ajoutées par l’Église, comme le purgatoire, sont rejetées.', 2),
    ('6ab9c615-fffc-54c5-85e8-29ec3b86b484'::uuid, 'histoire-geo', '2de', 'Martin Luther et le protestantisme', 'Que fait Luther en 1520 de la bulle qui l’excommunie ?', 'mcq', '["Il s’y soumet","Il la fait traduire","Il l’envoie à Charles Quint","Il la brûle"]'::jsonb, 3, 'Luther brûle publiquement la bulle en 1520 : la rupture avec Rome est consommée.', 3),
    ('1b199bfa-9534-5ede-a4e5-7a280242f65e'::uuid, 'histoire-geo', '2de', 'Martin Luther et le protestantisme', 'Dans quelle ville Luther est-il professeur quand il écrit ses 95 thèses ?', 'mcq', '["Worms","Augsbourg","Wittenberg","Genève"]'::jsonb, 2, 'Moine augustin, Luther enseigne à Wittenberg ; Worms est la diète de 1521, Genève la ville de Calvin.', 4),
    ('105a907d-89f7-5eb9-bdd0-b2cee17741d2'::uuid, 'histoire-geo', '2de', 'Léonard de Vinci, symbole de l’humanisme', 'Quel seigneur de Milan est l’un des grands protecteurs de Léonard ?', 'mcq', '["Laurent de Médicis","Ludovic Sforza","César Borgia","Charles Quint"]'::jsonb, 1, 'Léonard sert longtemps Ludovic Sforza à Milan, où il peint la Cène.', 1),
    ('8e409308-a423-5339-b7bb-76a27b694084'::uuid, 'histoire-geo', '2de', 'Léonard de Vinci, symbole de l’humanisme', 'Où Léonard de Vinci finit-il sa vie ?', 'mcq', '["Au Clos Lucé, à Amboise","À Florence","À Rome","À Chambord"]'::jsonb, 0, 'Invité par François Ier, Léonard s’installe au Clos Lucé, à Amboise, où il meurt en 1519.', 2),
    ('b377bfc4-f7b0-578c-8941-d762f57bb7d3'::uuid, 'histoire-geo', '2de', 'Léonard de Vinci, symbole de l’humanisme', 'Comment Léonard écrit-il dans ses carnets ?', 'mcq', '["En grec","En chiffres secrets","En latin uniquement","En miroir, de droite à gauche"]'::jsonb, 3, 'Ses milliers de pages de carnets sont écrites en miroir, de droite à gauche.', 3),
    ('9329b904-2ee8-5449-9e0a-dd0f5509f0d4'::uuid, 'histoire-geo', '2de', 'Léonard de Vinci, symbole de l’humanisme', 'Léonard a laissé beaucoup d’œuvres inachevées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Léonard peint peu et laisse beaucoup d’œuvres inachevées : ses recherches l’occupent autant que la peinture.', 4),
    ('044b923d-98e0-50d6-9435-fdbec111b6ec'::uuid, 'histoire-geo', '2de', 'La naissance de la monarchie absolue en France', 'Avec quel ministre Henri IV rétablit-il les finances du royaume ?', 'mcq', '["Colbert","Richelieu","Sully","Mazarin"]'::jsonb, 2, 'Après l’édit de Nantes (1598), Henri IV rétablit la paix civile et les finances avec Sully.', 1),
    ('85b2a08e-d186-54fa-88f5-6d7f1f267922'::uuid, 'histoire-geo', '2de', 'La naissance de la monarchie absolue en France', 'Quel événement ouvre le règne personnel de Louis XIV en 1661 ?', 'mcq', '["La mort de Mazarin","La fin de la Fronde","L’installation à Versailles","La révocation de l’édit de Nantes"]'::jsonb, 0, 'À la mort de Mazarin, en 1661, Louis XIV décide de gouverner seul, sans ministre principal.', 2),
    ('3e6479bf-1c1d-5606-b294-ad3640347d54'::uuid, 'histoire-geo', '2de', 'La naissance de la monarchie absolue en France', 'De quel milieu sont souvent issus les ministres de Louis XIV, comme Colbert ?', 'mcq', '["De la haute noblesse d’épée","Du clergé","Des princes du sang","De la bourgeoisie"]'::jsonb, 3, 'Louis XIV s’appuie sur des ministres issus de la bourgeoisie : ils lui doivent tout et ne peuvent pas lui faire d’ombre.', 3),
    ('e60430af-1196-51a7-9153-56c63b9388f0'::uuid, 'histoire-geo', '2de', 'La naissance de la monarchie absolue en France', 'Quel symbole Louis XIV choisit-il pour représenter son pouvoir ?', 'mcq', '["Le lys seul","Le soleil","L’aigle","Le coq"]'::jsonb, 1, 'Le symbole solaire, repris dans les décors et les portraits, fait du roi le centre autour duquel tout gravite.', 4),
    ('987bb12d-0b0a-5716-be39-d31de2b6e2af'::uuid, 'histoire-geo', '2de', 'La monarchie française et l’économie', 'Pendant quelle période Colbert est-il contrôleur général des finances ?', 'mcq', '["De 1643 à 1661","De 1665 à 1683","De 1685 à 1715","De 1715 à 1723"]'::jsonb, 1, 'Colbert est contrôleur général des finances de 1665 à sa mort, en 1683.', 1),
    ('53ac8585-e221-50ef-ac9c-016ea328e5d6'::uuid, 'histoire-geo', '2de', 'La monarchie française et l’économie', 'Que produit la manufacture royale des Gobelins ?', 'mcq', '["Des glaces","Du drap","Des tapisseries","Des canons"]'::jsonb, 2, 'Les Gobelins produisent des tapisseries ; Saint-Gobain fabrique des glaces, Villeneuvette du drap.', 2),
    ('d26cfdd3-93ae-5feb-85d3-4d4ab1d21516'::uuid, 'histoire-geo', '2de', 'La monarchie française et l’économie', 'Qui achève le canal du Midi en 1681 ?', 'mcq', '["Riquet","Vauban","Colbert","Mansart"]'::jsonb, 0, 'Pierre-Paul Riquet conçoit et fait creuser le canal du Midi, qui relie l’Atlantique à la Méditerranée.', 3),
    ('52e0e9d8-7677-5794-a7cd-3fbafd8d04ad'::uuid, 'histoire-geo', '2de', 'La monarchie française et l’économie', 'Sur quel postulat repose le mercantilisme ?', 'mcq', '["La richesse naît du travail de la terre","Le commerce enrichit tout le monde","Le marché doit être laissé libre","La richesse du monde est fixe : ce qu’un royaume gagne, un autre le perd"]'::jsonb, 3, 'Pour les mercantilistes, la richesse mondiale est fixe : il faut vendre plus qu’on n’achète pour attirer l’or et l’argent.', 4),
    ('d4cea122-9763-53d2-95ca-f296f251bdfa'::uuid, 'histoire-geo', '2de', 'La construction et les limites de la monarchie absolue face à la noblesse', 'D’où la noblesse de robe tire-t-elle son prestige ?', 'mcq', '["Du service militaire","Des offices de justice et de finance","De la possession de grandes terres","Des charges d’Église"]'::jsonb, 1, 'La noblesse de robe, plus récente, tient son rang d’offices de justice et de finance, souvent achetés ; la noblesse d’épée, du service militaire.', 1),
    ('4eb4b3b2-e401-5b8d-9a45-50ade417ebbe'::uuid, 'histoire-geo', '2de', 'La construction et les limites de la monarchie absolue face à la noblesse', 'Quel inconvénient la vénalité des offices présente-t-elle pour le roi ?', 'mcq', '["Elle ruine le Trésor","Elle interdit aux bourgeois d’entrer dans l’administration","Elle crée des propriétaires de charges difficiles à révoquer","Elle rend les parlements élus"]'::jsonb, 2, 'Vendre les offices enrichit le Trésor, mais leurs acheteurs en deviennent propriétaires : le roi ne peut plus les révoquer à sa guise.', 2),
    ('cfabde2e-15c6-53d3-92c3-1cb244dd8090'::uuid, 'histoire-geo', '2de', 'La construction et les limites de la monarchie absolue face à la noblesse', 'Lequel de ces ministres a échoué à réformer l’impôt sous Louis XVI ?', 'mcq', '["Turgot","Colbert","Richelieu","Sully"]'::jsonb, 0, 'Turgot, comme Necker et Calonne après lui, échoue à toucher aux privilèges fiscaux ; la monarchie finit par convoquer les états généraux.', 3),
    ('85c13653-34c2-5f5a-9d56-c05e84d5027b'::uuid, 'histoire-geo', '2de', 'La construction et les limites de la monarchie absolue face à la noblesse', 'Que deviennent les gouverneurs de province sous la monarchie absolue ?', 'mcq', '["Ils remplacent les intendants","Ils sont élus par les provinces","Ils deviennent ministres","Ils perdent l’essentiel de leur pouvoir réel"]'::jsonb, 3, 'Les gouverneurs, issus de la haute noblesse, gardent leur titre mais perdent l’essentiel de leur pouvoir au profit des intendants.', 4),
    ('b7d34d44-de06-5d1b-a743-6373e82a7bec'::uuid, 'histoire-geo', '2de', 'La monarchie parlementaire anglaise : un modèle à l’opposé de la monarchie française', 'Pendant combien d’années Charles Ier gouverne-t-il sans Parlement ?', 'mcq', '["Deux ans","Cinq ans","Onze ans","Trente ans"]'::jsonb, 2, 'Charles Ier gouverne onze ans sans Parlement en levant des taxes contestées : c’est l’une des causes de la guerre civile.', 1),
    ('834557f9-da98-5e1f-99e0-fb9439435496'::uuid, 'histoire-geo', '2de', 'La monarchie parlementaire anglaise : un modèle à l’opposé de la monarchie française', 'En quelle année la monarchie est-elle restaurée en Angleterre ?', 'mcq', '["1660","1649","1679","1688"]'::jsonb, 0, 'Après la république puis la dictature de Cromwell, la monarchie est restaurée en 1660.', 2),
    ('50807522-e073-586a-b4aa-29cd7b44632d'::uuid, 'histoire-geo', '2de', 'La monarchie parlementaire anglaise : un modèle à l’opposé de la monarchie française', 'Avec qui le cabinet et la fonction de Premier ministre apparaissent-ils ?', 'mcq', '["Cromwell","Guillaume d’Orange","Jacques II","Walpole"]'::jsonb, 3, 'Au XVIIIe siècle, avec Walpole, apparaissent le cabinet et le Premier ministre, qui doit avoir la confiance des Communes.', 3),
    ('efa083f9-117a-54c5-ad01-67335bbf0415'::uuid, 'histoire-geo', '2de', 'La monarchie parlementaire anglaise : un modèle à l’opposé de la monarchie française', 'Selon le Bill of Rights, que le roi ne peut-il plus faire sans le Parlement ?', 'mcq', '["Nommer ses ministres","Lever l’impôt ou entretenir une armée permanente","Choisir sa religion","Signer des traités"]'::jsonb, 1, 'Le Bill of Rights (1689) interdit au roi de lever l’impôt ou d’entretenir une armée permanente sans le Parlement.', 4),
    ('62beac66-d895-5bed-97cf-2e5e8837a2cc'::uuid, 'histoire-geo', '2de', 'Le modèle britannique, un exemple pour les philosophes des Lumières', 'Quel sort les Lettres philosophiques connaissent-elles en France ?', 'mcq', '["Elles sont couronnées par l’Académie","Elles sont condamnées et brûlées","Elles sont offertes au roi","Elles passent inaperçues"]'::jsonb, 1, 'Le livre est condamné et brûlé : comparer la France à l’Angleterre est vécu comme une attaque contre la monarchie.', 1),
    ('2a0b420f-aa8c-589b-a025-01ce32fa0c3e'::uuid, 'histoire-geo', '2de', 'Le modèle britannique, un exemple pour les philosophes des Lumières', 'Selon Montesquieu, quel pouvoir est chargé d’appliquer la loi ?', 'mcq', '["Le pouvoir législatif","Le pouvoir judiciaire","Le pouvoir exécutif","Le pouvoir religieux"]'::jsonb, 2, 'Le législatif fait la loi, l’exécutif l’applique, le judiciaire la dit dans les litiges : ils doivent être distincts.', 2),
    ('cd39e147-6a60-5094-817c-042c706f76f6'::uuid, 'histoire-geo', '2de', 'Le modèle britannique, un exemple pour les philosophes des Lumières', 'Quel ouvrage John Locke publie-t-il en 1690 ?', 'mcq', '["Le Léviathan","Le Contrat social","L’Esprit des lois","Le Traité du gouvernement civil"]'::jsonb, 3, 'Dans le Traité du gouvernement civil (1690), Locke fonde le pouvoir sur un contrat et admet le droit de résistance.', 3),
    ('b723622a-3d68-5e31-be93-9952798b9041'::uuid, 'histoire-geo', '2de', 'Le modèle britannique, un exemple pour les philosophes des Lumières', 'Selon Locke, quel est le rôle de l’État face aux droits naturels ?', 'mcq', '["Il ne les crée pas, il les protège","Il les accorde à ceux qui le méritent","Il peut les supprimer en cas de guerre","Il les réserve aux propriétaires"]'::jsonb, 0, 'Les droits naturels existent avant l’État : il doit les protéger, et peut être renversé s’il les viole.', 4),
    ('fe98e13f-9adb-5791-b021-7935b7b5caa5'::uuid, 'histoire-geo', '2de', 'Les relations entre l’Angleterre et ses colonies américaines', 'Qui rédige la Déclaration d’indépendance de 1776 ?', 'mcq', '["George Washington","Thomas Jefferson","Benjamin Franklin","La Fayette"]'::jsonb, 1, 'Thomas Jefferson rédige la Déclaration : tous les hommes sont créés égaux et dotés de droits inaliénables.', 1),
    ('08c0dbc3-bd3c-57d6-880a-a8b7c9394e8b'::uuid, 'histoire-geo', '2de', 'Les relations entre l’Angleterre et ses colonies américaines', 'Où ont lieu les premiers combats de la guerre d’Indépendance, en 1775 ?', 'mcq', '["À Yorktown","À Boston","À Philadelphie","À Lexington"]'::jsonb, 3, 'Les premiers combats éclatent à Lexington en 1775 ; la guerre se décide à Yorktown en 1781.', 2),
    ('fdb0c1d1-b27f-576d-9e75-2005af86dc5e'::uuid, 'histoire-geo', '2de', 'Les relations entre l’Angleterre et ses colonies américaines', 'En quelle année un traité reconnaît-il l’indépendance des États-Unis ?', 'mcq', '["1776","1781","1783","1787"]'::jsonb, 2, 'Le traité de Paris de 1783 reconnaît les États-Unis ; la Constitution est adoptée en 1787.', 3),
    ('c60e5d61-5b43-5051-a5d1-25185d78fecf'::uuid, 'histoire-geo', '2de', 'Les relations entre l’Angleterre et ses colonies américaines', 'Quelle taxe britannique frappe les colonies en 1765 ?', 'mcq', '["Le Stamp Act","Le Sugar Act","Les Townshend Acts","La taxe sur le thé"]'::jsonb, 0, 'Le Stamp Act (1765) suit le Sugar Act (1764) ; viennent ensuite les Townshend Acts (1767) et la taxe sur le thé (1773).', 4),
    ('4403c5bc-8bcf-5f40-8b82-61d1b0dd4471'::uuid, 'histoire-geo', '2de', 'L’essor d’un nouvel esprit scientifique et technique aux XVIIe et XVIIIe siècles', 'Qu’apporte Kepler à l’astronomie ?', 'mcq', '["L’héliocentrisme","La gravitation universelle","La découverte des satellites de Jupiter","Des orbites planétaires elliptiques"]'::jsonb, 3, 'Au début du XVIIe siècle, Kepler montre que les planètes décrivent des ellipses et non des cercles.', 1),
    ('57d2516e-c6d6-5d49-80e0-0abea3590e5b'::uuid, 'histoire-geo', '2de', 'L’essor d’un nouvel esprit scientifique et technique aux XVIIe et XVIIIe siècles', 'Sur quelle démarche Francis Bacon fonde-t-il la science ?', 'mcq', '["L’induction à partir de l’expérience","Le doute méthodique","L’autorité d’Aristote","La révélation religieuse"]'::jsonb, 0, 'Bacon part de l’expérience pour induire des lois ; Descartes, lui, prône le doute méthodique et la déduction.', 2),
    ('74859b10-54d7-5ed7-a3d1-83495585c567'::uuid, 'histoire-geo', '2de', 'L’essor d’un nouvel esprit scientifique et technique aux XVIIe et XVIIIe siècles', 'Quel est l’apport principal de Linné ?', 'mcq', '["La chimie moderne","L’Histoire naturelle","La classification des espèces","La vaccination"]'::jsonb, 2, 'Linné classe les espèces vivantes ; Buffon écrit l’Histoire naturelle, Lavoisier fonde la chimie moderne.', 3),
    ('1ea28a34-7881-5dd3-8d78-ed09596849bd'::uuid, 'histoire-geo', '2de', 'L’essor d’un nouvel esprit scientifique et technique aux XVIIe et XVIIIe siècles', 'Quelle institution savante est fondée à Londres en 1660 ?', 'mcq', '["L’Académie royale des sciences","La Royal Society","Le Collège de France","L’université d’Oxford"]'::jsonb, 1, 'La Royal Society (1660) précède de six ans l’Académie royale des sciences de Paris (1666).', 4),
    ('7d9c402f-d1d8-5977-b7db-eb422b7d7084'::uuid, 'histoire-geo', '2de', 'Les évolutions économiques et techniques aux origines de la révolution industrielle', 'À quoi sert d’abord la machine de Newcomen, en 1712 ?', 'mcq', '["À faire tourner les métiers à tisser","À épuiser l’eau des mines","À propulser les navires","À tirer les locomotives"]'::jsonb, 1, 'La machine de Newcomen pompe l’eau des mines ; celle de Watt (1769) sera assez efficace pour tout faire tourner.', 1),
    ('09573cb2-2cb6-5c38-a926-3b2b694793be'::uuid, 'histoire-geo', '2de', 'Les évolutions économiques et techniques aux origines de la révolution industrielle', 'Que permet la spinning jenny ?', 'mcq', '["Tisser plus vite","Teindre les étoffes","Filer plusieurs fils à la fois","Carder la laine"]'::jsonb, 2, 'La spinning jenny accélère la filature en filant plusieurs fils à la fois ; la navette volante, elle, accélère le tissage.', 2),
    ('fbe40bd3-9198-590b-b0ad-8d84c6eafcd7'::uuid, 'histoire-geo', '2de', 'Les évolutions économiques et techniques aux origines de la révolution industrielle', 'Qu’apporte l’assolement sans jachère ?', 'mcq', '["La terre produit chaque année","Les champs sont clos","Les paysans deviennent propriétaires","Le blé remplace l’élevage"]'::jsonb, 0, 'En supprimant la jachère, grâce notamment aux prairies artificielles, on cultive la terre chaque année.', 3),
    ('fb930251-0283-5fba-a353-60562ff4a0a2'::uuid, 'histoire-geo', '2de', 'Les évolutions économiques et techniques aux origines de la révolution industrielle', 'Quel atout l’empire colonial offre-t-il à l’industrie anglaise ?', 'mcq', '["Des brevets","Une main-d’œuvre qualifiée","Des banques","Des débouchés et des matières premières"]'::jsonb, 3, 'L’empire colonial fournit à la fois des matières premières, comme le coton, et des marchés pour vendre.', 4),
    ('6a047288-989f-5171-b79e-ff3e213c24d4'::uuid, 'histoire-geo', '2de', 'Le monde rural', 'Sur quel produit porte la gabelle ?', 'mcq', '["Le blé","Le vin","Le sel","Le tabac"]'::jsonb, 2, 'La gabelle est un impôt royal sur le sel, avec la taille et la capitation.', 1),
    ('42d1391b-6b12-5a19-aa4e-29b133cb607c'::uuid, 'histoire-geo', '2de', 'Le monde rural', 'Combien la noblesse compte-t-elle environ de membres à la veille de la Révolution ?', 'mcq', '["35 000","350 000","3,5 millions","13 millions"]'::jsonb, 1, 'Environ 350 000 nobles et 130 000 membres du clergé : les deux ordres privilégiés sont une petite minorité.', 2),
    ('ebe79e70-0cc7-5240-b45b-feef7d19711e'::uuid, 'histoire-geo', '2de', 'Le monde rural', 'Quel système d’exploitation domine dans le Sud-Ouest ?', 'mcq', '["Le métayage","Les grandes fermes céréalières","La petite propriété de montagne","Le bocage"]'::jsonb, 0, 'Dans le métayage, le paysan partage la récolte avec le propriétaire ; le Bassin parisien est celui des grandes fermes.', 3),
    ('87731b4f-7af8-51d0-9a03-55fb6bf56e24'::uuid, 'histoire-geo', '2de', 'Le monde rural', 'À qui le paysan verse-t-il le cens ?', 'mcq', '["Au roi","À l’Église","À l’intendant","Au seigneur"]'::jsonb, 3, 'Le cens est une redevance due au seigneur, comme les banalités et les corvées ; la dîme va à l’Église.', 4),
    ('86cd12d6-c865-5375-9c7c-dbbbedda7d40'::uuid, 'histoire-geo', '2de', 'Le monde urbain', 'Lequel de ces métiers appartient à la bourgeoisie urbaine ?', 'mcq', '["Armateur","Compagnon","Portefaix","Domestique"]'::jsonb, 0, 'Négociants, armateurs, manufacturiers, avocats ou médecins forment la bourgeoisie ; compagnons et portefaix, le peuple des villes.', 1),
    ('d1cc97e4-6776-5ceb-8235-d25d70ae985a'::uuid, 'histoire-geo', '2de', 'Le monde urbain', 'Que manque-t-il à la bourgeoisie du XVIIIe siècle ?', 'mcq', '["La fortune","L’instruction","Le statut : elle reste dans le tiers état","Les compétences"]'::jsonb, 2, 'Riche et compétente, la bourgeoisie reste juridiquement dans le tiers état et supporte mal les privilèges.', 2),
    ('060ea334-fec6-56eb-bb7f-f7128e3ec7db'::uuid, 'histoire-geo', '2de', 'Le monde urbain', 'Que sont les loges maçonniques et les académies de province ?', 'mcq', '["Des tribunaux royaux","Des réseaux de sociabilité lettrée","Des corporations de métiers","Des hospices pour les pauvres"]'::jsonb, 1, 'Comme les salons et les cafés, loges et académies sont des lieux où circulent les idées des Lumières.', 3),
    ('519dcf3e-a543-5122-a292-f9c2f925ad1e'::uuid, 'histoire-geo', '2de', 'Le monde urbain', 'Comment certains bourgeois s’élèvent-ils dans la société ?', 'mcq', '["En entrant dans le clergé","En épousant des paysannes","En refusant de payer l’impôt","En achetant des offices, parfois la noblesse"]'::jsonb, 3, 'La bourgeoisie achète des offices et parfois des titres de noblesse, tout en critiquant de plus en plus les privilèges.', 4),
    ('ddc58301-b469-58c4-998f-4e7d2ccf53c6'::uuid, 'histoire-geo', '2de', 'Les sociétés face aux risques', 'Qu’appelle-t-on une catastrophe ?', 'mcq', '["Un aléa possible","Un risque réalisé","Une zone inconstructible","Une société vulnérable"]'::jsonb, 1, 'La catastrophe est le risque devenu réalité ; le risque, lui, n’est qu’une possibilité.', 1),
    ('63078df8-be7b-50f3-95f1-357c103647d9'::uuid, 'histoire-geo', '2de', 'Les sociétés face aux risques', 'Qu’est-ce qu’un aléa ?', 'mcq', '["Un événement possible, comme un séisme ou une crue","La fragilité d’une population","La capacité à se reconstruire","Le coût des dégâts"]'::jsonb, 0, 'L’aléa est l’événement possible ; il devient un risque quand il menace une société vulnérable.', 2),
    ('1e7b3c1b-2d01-5974-b737-7a94dde7277f'::uuid, 'histoire-geo', '2de', 'Les sociétés face aux risques', 'À quel type de risque appartient le transport de matières dangereuses ?', 'mcq', '["Naturel","Sanitaire","Climatique","Technologique"]'::jsonb, 3, 'Les risques technologiques concernent l’industrie, le nucléaire et le transport de matières dangereuses.', 3),
    ('418a9c19-c75f-5423-a88b-db2f0f489316'::uuid, 'histoire-geo', '2de', 'Les sociétés face aux risques', 'Que concentrent surtout les pays du Nord lors des catastrophes ?', 'mcq', '["L’essentiel des victimes","Les aléas les plus violents","L’essentiel des dégâts matériels","Les épidémies"]'::jsonb, 2, 'Les pays du Sud concentrent les victimes, ceux du Nord les dégâts matériels : on y perd plus de biens que de vies.', 4),
    ('86dbbe06-8480-5ee5-854a-f1df94e6dac2'::uuid, 'histoire-geo', '2de', 'Le changement climatique et ses effets sur un territoire densément peuplé', 'Qu’est-ce que l’atténuation, en matière de climat ?', 'mcq', '["Construire des digues","Replanter des mangroves","Réduire les émissions de gaz à effet de serre","Évacuer les populations"]'::jsonb, 2, 'L’atténuation agit sur la cause, à l’échelle mondiale ; l’adaptation réduit localement les effets subis.', 1),
    ('d5e910b1-6131-5b69-8ef3-c42bdd2c3aee'::uuid, 'histoire-geo', '2de', 'Le changement climatique et ses effets sur un territoire densément peuplé', 'Vers quelle ville se dirigent les migrations climatiques au Bangladesh ?', 'mcq', '["Dacca","Calcutta","Bombay","Karachi"]'::jsonb, 0, 'Les migrants gonflent Dacca, la capitale, l’une des villes les plus denses du monde.', 2),
    ('95fc79cb-c6dc-5433-a5ef-cb712ca0898c'::uuid, 'histoire-geo', '2de', 'Le changement climatique et ses effets sur un territoire densément peuplé', 'Par quelle activité les rizières salinisées sont-elles souvent remplacées ?', 'mcq', '["La culture du thé","L’élevage bovin","Le coton","L’aquaculture de crevettes"]'::jsonb, 3, 'L’eau salée ruine le riz : les rizières cèdent la place à des bassins d’élevage de crevettes.', 3),
    ('e7db5944-21eb-524b-8227-6a0e7f5a8a52'::uuid, 'histoire-geo', '2de', 'Le changement climatique et ses effets sur un territoire densément peuplé', 'Quelles sont les deux causes de la hausse du niveau marin ?', 'mcq', '["Les séismes et les volcans","La dilatation de l’eau et la fonte des glaces","Les pluies de mousson et les crues","L’érosion des côtes et la salinisation"]'::jsonb, 1, 'L’eau se dilate en se réchauffant et la fonte des glaces continentales ajoute de l’eau : le niveau marin monte.', 4),
    ('13a29197-e11e-5fb4-990f-c8abeecd31bd'::uuid, 'histoire-geo', '2de', 'Des ressources majeures sous pression : l’exemple de la forêt amazonienne', 'Quelle part de la forêt amazonienne se trouve au Brésil ?', 'mcq', '["20 %","40 %","60 %","90 %"]'::jsonb, 2, 'Le Brésil abrite 60 % d’une forêt partagée entre neuf pays.', 1),
    ('d2c7f19d-6666-5e1d-a865-714989cc8595'::uuid, 'histoire-geo', '2de', 'Des ressources majeures sous pression : l’exemple de la forêt amazonienne', 'Quelle pollution l’orpaillage provoque-t-il ?', 'mcq', '["Une pollution au mercure","Une pollution aux nitrates","Des marées noires","Des pluies acides"]'::jsonb, 0, 'Les orpailleurs utilisent le mercure pour séparer l’or : il empoisonne les rivières et ceux qui en vivent.', 2),
    ('35b93ccf-c972-5bb6-89bc-8e27225055cf'::uuid, 'histoire-geo', '2de', 'Des ressources majeures sous pression : l’exemple de la forêt amazonienne', 'Quel militant est assassiné en 1988 pour avoir défendu la forêt ?', 'mcq', '["Raoni","Lula","Chico Mendes","Dom Hélder Câmara"]'::jsonb, 2, 'L’assassinat du seringueiro Chico Mendes en 1988 dit la violence des conflits d’usage en Amazonie.', 3),
    ('f5082dbd-6047-5f12-9b72-ae46d63cb7c8'::uuid, 'histoire-geo', '2de', 'Des ressources majeures sous pression : l’exemple de la forêt amazonienne', 'Quelle part du massif amazonien la déforestation cumulée a-t-elle déjà touchée ?', 'mcq', '["Moins de 2 %","Environ 5 %","Plus de 50 %","Plus de 17 %"]'::jsonb, 3, 'La déforestation cumulée dépasse 17 % du massif ; elle progresse le long des routes, en arêtes de poisson.', 4),
    ('84d60fec-745d-55cc-852a-edc5c75d3192'::uuid, 'histoire-geo', '2de', 'L’Arctique : un espace fragile et attractif', 'Quel gaz le dégel du pergélisol libère-t-il ?', 'mcq', '["L’ozone","Le méthane","L’azote","L’hydrogène"]'::jsonb, 1, 'Le méthane libéré est un gaz à effet de serre : il accélère le réchauffement, qui accélère le dégel.', 1),
    ('3e673e69-009b-59fd-bc50-41c7ef7967c3'::uuid, 'histoire-geo', '2de', 'L’Arctique : un espace fragile et attractif', 'Quel gain la route maritime du Nord offre-t-elle entre l’Europe et l’Asie orientale, par rapport à Suez ?', 'mcq', '["Environ un tiers de distance en moins","Environ 5 % de distance en moins","Aucun gain","Deux fois moins de distance"]'::jsonb, 0, 'Elle raccourcit le trajet d’environ un tiers, mais reste saisonnière et coûteuse en assurance et en brise-glaces.', 2),
    ('0f4748b4-7e49-5323-8890-c5d1fc40272f'::uuid, 'histoire-geo', '2de', 'L’Arctique : un espace fragile et attractif', 'Le long de quel pays passe le passage du Nord-Ouest ?', 'mcq', '["La Russie","La Norvège","L’Islande","Le Canada"]'::jsonb, 3, 'Le passage du Nord-Ouest longe le Canada ; la route maritime du Nord longe les côtes russes.', 3),
    ('11a8a5d4-eefa-5fe0-a688-7013710fbcf1'::uuid, 'histoire-geo', '2de', 'L’Arctique : un espace fragile et attractif', 'Selon quelle convention les revendications sur les fonds marins arctiques s’arbitrent-elles ?', 'mcq', '["La convention de Genève","La convention de Montego Bay","Le traité de Tordesillas","L’accord de Paris"]'::jsonb, 1, 'La convention de Montego Bay sur le droit de la mer et la règle du plateau continental encadrent les revendications.', 4),
    ('0334d732-09de-5078-a585-73f19176ae39'::uuid, 'histoire-geo', '2de', 'Les espaces métropolitains et ultramarins français : valorisation et protection', 'Quelle est la superficie approximative de la zone économique exclusive française ?', 'mcq', '["1 million de km²","10,2 millions de km²","550 000 km²","25 millions de km²"]'::jsonb, 1, 'Avec environ 10,2 millions de km², dus à plus de 96 % aux outre-mer, la ZEE française est la deuxième du monde.', 1),
    ('e0306f1b-54b6-5096-aefe-85efaabdf452'::uuid, 'histoire-geo', '2de', 'Les espaces métropolitains et ultramarins français : valorisation et protection', 'Quelle pression menace particulièrement la Guyane ?', 'mcq', '["Le chlordécone","Le blanchissement des coraux","L’orpaillage illégal","Les avalanches"]'::jsonb, 2, 'L’orpaillage illégal pollue les rivières guyanaises ; le chlordécone touche, lui, les Antilles.', 2),
    ('79bbcbbb-a65c-5338-8c62-7cb73e462ac6'::uuid, 'histoire-geo', '2de', 'Les espaces métropolitains et ultramarins français : valorisation et protection', 'Quelle ressource minière fait la richesse de la Nouvelle-Calédonie ?', 'mcq', '["Le nickel","L’or","Le pétrole","L’uranium"]'::jsonb, 0, 'Le nickel calédonien est l’une des grandes ressources valorisées des outre-mer.', 3),
    ('8a994dc2-b99e-555c-b844-12e2d49fb165'::uuid, 'histoire-geo', '2de', 'Les espaces métropolitains et ultramarins français : valorisation et protection', 'Quelles lois encadrent l’urbanisme sur les côtes et en altitude ?', 'mcq', '["Les lois Natura 2000","Les lois Grenelle","Les plans de prévention des risques","Les lois Littoral et Montagne"]'::jsonb, 3, 'Les lois Littoral et Montagne limitent l’urbanisation dans les espaces les plus convoités, donc les plus menacés.', 4),
    ('d742f7ae-866a-5d41-891e-fa17e66a2f31'::uuid, 'histoire-geo', '2de', 'Des trajectoires démographiques différenciées : les défis du nombre et du vieillissement', 'Pendant la transition démographique, quel indicateur baisse en premier ?', 'mcq', '["La mortalité","La natalité","La fécondité","L’espérance de vie"]'::jsonb, 0, 'La mortalité chute d’abord alors que la natalité reste forte : c’est pourquoi la population explose pendant la transition.', 1),
    ('570c2e1b-c95b-5ea8-8e7b-5605baf9471e'::uuid, 'histoire-geo', '2de', 'Des trajectoires démographiques différenciées : les défis du nombre et du vieillissement', 'Comment appelle-t-on l’écart entre natalité et mortalité ?', 'mcq', '["Le solde migratoire","L’indice de fécondité","L’accroissement naturel","Le dividende démographique"]'::jsonb, 2, 'L’accroissement naturel est la différence entre naissances et décès ; le solde migratoire compte, lui, les arrivées et les départs.', 2),
    ('0dcd2077-0921-525a-99d2-65a623877eb0'::uuid, 'histoire-geo', '2de', 'Des trajectoires démographiques différenciées : les défis du nombre et du vieillissement', 'Dans le régime démographique ancien, comment évolue la population ?', 'mcq', '["Elle explose","Elle reste à peu près stable","Elle décline fortement","Elle vieillit"]'::jsonb, 1, 'Natalité et mortalité sont toutes deux fortes : elles s’équilibrent et la population reste stable.', 3),
    ('73afc5c6-6d40-5a1c-9e5d-b9a31af4eab9'::uuid, 'histoire-geo', '2de', 'Des trajectoires démographiques différenciées : les défis du nombre et du vieillissement', 'Lequel de ces pays est en situation post-transitionnelle ?', 'mcq', '["Le Niger","Le Nigeria","L’Éthiopie","La Corée du Sud"]'::jsonb, 3, 'La Corée du Sud, comme le Japon et l’Europe, a une fécondité sous le seuil de renouvellement et une population vieillissante.', 4),
    ('c2bf1a90-fbbe-5f43-8a1d-c99d7a08248d'::uuid, 'histoire-geo', '2de', 'Développement et inégalités : étude comparative Brésil/Inde', 'Quelle est la principale limite du PIB par habitant ?', 'mcq', '["Il ne mesure pas la richesse produite","Il ne dit rien du partage de la richesse","Il ne s’applique qu’aux pays riches","Il ne tient pas compte de la population"]'::jsonb, 1, 'Le PIB par habitant est une moyenne : il ne dit rien de la façon dont la richesse est répartie.', 1),
    ('26fb01dd-0874-515c-a19c-b4234fa323e3'::uuid, 'histoire-geo', '2de', 'Développement et inégalités : étude comparative Brésil/Inde', 'Quel est le moteur économique de l’Inde ?', 'mcq', '["L’agriculture exportatrice","L’industrie lourde","Les services et le numérique","Le pétrole"]'::jsonb, 2, 'L’Inde s’appuie sur les services et le numérique, avec une faible industrialisation de masse ; le Brésil, sur une agriculture exportatrice.', 2),
    ('1458a6ff-abb1-51cd-86d0-892ac5a622cc'::uuid, 'histoire-geo', '2de', 'Développement et inégalités : étude comparative Brésil/Inde', 'Combien d’habitants compte environ le Brésil ?', 'mcq', '["Environ 215 millions","Environ 80 millions","Environ 1,4 milliard","Environ 500 millions"]'::jsonb, 0, 'Le Brésil compte environ 215 millions d’habitants, l’Inde plus de 1,4 milliard.', 3),
    ('c168c482-8eff-5d43-974f-5275d101c686'::uuid, 'histoire-geo', '2de', 'Développement et inégalités : étude comparative Brésil/Inde', 'Qu’est-ce qui a fait reculer la pauvreté au Brésil dans les années 2000 ?', 'mcq', '["La réforme agraire complète","La fin de l’urbanisation","L’abandon de l’agriculture exportatrice","Des programmes de transferts sociaux"]'::jsonb, 3, 'Des programmes de transferts sociaux ont fait reculer la pauvreté, sans effacer de fortes inégalités.', 4),
    ('5cce5308-be4f-5c31-ae3d-55b3494a0a98'::uuid, 'histoire-geo', '2de', 'Enjeux et défis du vieillissement de la population : l’exemple du Japon', 'Combien d’habitants compte environ le Japon ?', 'mcq', '["Environ 60 millions","Environ 124 millions","Environ 200 millions","Environ 300 millions"]'::jsonb, 1, 'Le Japon compte environ 124 millions d’habitants, un nombre en baisse depuis 2010.', 1),
    ('4eae077b-a601-5ab1-9148-e55db7f122ad'::uuid, 'histoire-geo', '2de', 'Enjeux et défis du vieillissement de la population : l’exemple du Japon', 'Dans quels secteurs la pénurie de main-d’œuvre se fait-elle surtout sentir au Japon ?', 'mcq', '["L’électronique et l’automobile","La banque et l’assurance","Les soins, la logistique et le bâtiment","Le tourisme de luxe"]'::jsonb, 2, 'Ce sont les soins, la logistique et le bâtiment qui manquent le plus de bras.', 2),
    ('5ff51396-9361-5c77-a6a4-8fe131b799f8'::uuid, 'histoire-geo', '2de', 'Enjeux et défis du vieillissement de la population : l’exemple du Japon', 'Jusqu’à quel âge de nombreux seniors japonais travaillent-ils ?', 'mcq', '["Souvent au-delà de 70 ans","Jamais au-delà de 55 ans","Jusqu’à 60 ans au plus","Jusqu’à 62 ans, comme en France"]'::jsonb, 0, 'Le Japon mise sur l’emploi des seniors, souvent au-delà de 70 ans, pour compenser le manque d’actifs.', 3),
    ('8c1c8ca6-ef7c-5955-b0bc-c7b3a2142b35'::uuid, 'histoire-geo', '2de', 'Enjeux et défis du vieillissement de la population : l’exemple du Japon', 'Les politiques japonaises ont réussi à inverser le vieillissement de la population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Robotique, emploi des seniors et des femmes, politiques familiales : aucune de ces réponses n’a inversé la tendance à ce jour.', 4),
    ('39cd4823-b982-557d-883d-687dd1383819'::uuid, 'histoire-geo', '2de', 'Dynamiques démographiques et inégalités socio-économiques en France', 'Quelle part de la population française a plus de 65 ans ?', 'mcq', '["Environ 5 %","Environ 10 %","Plus de 40 %","Plus de 21 %"]'::jsonb, 3, 'Plus de 21 % des Français ont plus de 65 ans, une part en hausse.', 1),
    ('47f52a0b-0733-5bce-b24c-7c438d7c896a'::uuid, 'histoire-geo', '2de', 'Dynamiques démographiques et inégalités socio-économiques en France', 'À quoi servent les Maisons France Services ?', 'mcq', '["À construire des logements sociaux","À faciliter l’accès aux services publics","À accueillir les touristes","À former les chômeurs"]'::jsonb, 1, 'Les Maisons France Services rapprochent les services publics des habitants, notamment dans les territoires isolés.', 2),
    ('17d49eab-44f6-566a-a784-a1f748db3340'::uuid, 'histoire-geo', '2de', 'Dynamiques démographiques et inégalités socio-économiques en France', 'Quels territoires le programme « Action cœur de ville » vise-t-il ?', 'mcq', '["Les villes moyennes","Les métropoles","Les stations de ski","Les outre-mer"]'::jsonb, 0, 'Action cœur de ville et Petites villes de demain visent à revitaliser les villes moyennes et petites.', 3),
    ('a167e5ba-384b-54cb-8ae8-8882c5352278'::uuid, 'histoire-geo', '2de', 'Dynamiques démographiques et inégalités socio-économiques en France', 'Outre la diagonale des faibles densités, quels territoires perdent des habitants ?', 'mcq', '["Les littoraux méditerranéens","Les couronnes des métropoles","Les anciennes régions industrielles","Le Sud-Ouest"]'::jsonb, 2, 'Les anciennes régions industrielles perdent des habitants, faute d’avenir professionnel ; littoraux et métropoles en gagnent.', 4),
    ('44237a0c-6476-5c25-ba43-9084151dcd1c'::uuid, 'histoire-geo', '2de', 'Enjeux et défis des migrations internationales', 'Quelle part de l’humanité vit hors de son pays de naissance ?', 'mcq', '["Un peu plus de 3 %","Environ 15 %","Environ 30 %","Moins de 0,5 %"]'::jsonb, 0, 'Environ 281 millions de personnes, soit un peu plus de 3 % de l’humanité : la migration internationale reste minoritaire.', 1),
    ('b2e48c0e-f12e-594b-99ea-fc7003d51999'::uuid, 'histoire-geo', '2de', 'Enjeux et défis des migrations internationales', 'Qu’est-ce qu’un demandeur d’asile ?', 'mcq', '["Un réfugié déjà reconnu","Un migrant économique","Une personne qui attend la décision sur sa demande de protection","Un déplacé qui reste dans son pays"]'::jsonb, 2, 'Le demandeur d’asile attend qu’on statue sur sa demande ; s’il obtient la protection, il devient réfugié.', 2),
    ('6176d434-5ec6-5c90-abb9-5bcc65161efb'::uuid, 'histoire-geo', '2de', 'Enjeux et défis des migrations internationales', 'Quelle route migratoire est la plus meurtrière ?', 'mcq', '["La Manche","Les Balkans","Le golfe d’Aden","La Méditerranée centrale"]'::jsonb, 3, 'La Méditerranée centrale est la route la plus meurtrière ; les contrôles allongent et renchérissent les trajets sans les supprimer.', 3),
    ('9aa61226-9009-57ff-9262-6563fdf2e72b'::uuid, 'histoire-geo', '2de', 'Enjeux et défis des migrations internationales', 'Qu’est-ce qu’une diaspora ?', 'mcq', '["Un camp de réfugiés","Une population dispersée qui garde des liens avec son territoire d’origine","Un groupe de passeurs","Une frontière fermée"]'::jsonb, 1, 'Une diaspora vit dispersée hors de son pays d’origine, mais entretient des liens avec lui, notamment par les remises.', 4),
    ('1d837ad3-4008-5d83-a592-4903f472ba6e'::uuid, 'histoire-geo', '2de', 'Les mobilités touristiques à l’échelle mondiale : étude comparative entre les USA et Dubaï', 'Combien d’arrivées de touristes internationaux compte-t-on par an avant la pandémie ?', 'mcq', '["Environ 100 millions","Plus d’un milliard","Environ 300 millions","Plus de 5 milliards"]'::jsonb, 1, 'Avec plus d’un milliard d’arrivées par an, le tourisme international est la première mobilité de la planète.', 1),
    ('463b1860-1391-55a9-9ff4-1a28ef236363'::uuid, 'histoire-geo', '2de', 'Les mobilités touristiques à l’échelle mondiale : étude comparative entre les USA et Dubaï', 'Quel est l’objectif principal du développement touristique de Dubaï ?', 'mcq', '["Protéger son patrimoine ancien","Accueillir son propre tourisme intérieur","Se diversifier hors de la rente pétrolière","Développer le tourisme de montagne"]'::jsonb, 2, 'Dubaï veut sortir de la dépendance au pétrole et soigner son image : le tourisme est un projet d’État.', 2),
    ('89906301-e286-51c8-beff-8a3db3f3c263'::uuid, 'histoire-geo', '2de', 'Les mobilités touristiques à l’échelle mondiale : étude comparative entre les USA et Dubaï', 'Quelle différence oppose le tourisme intérieur des États-Unis à celui de Dubaï ?', 'mcq', '["Il est massif aux États-Unis, faible à Dubaï","Il est faible aux États-Unis, massif à Dubaï","Il est inexistant dans les deux cas","Il est identique dans les deux cas"]'::jsonb, 0, 'Les Américains voyagent beaucoup dans leur propre pays ; Dubaï vit surtout de visiteurs étrangers.', 3),
    ('2409ffa9-3deb-5cc4-8543-32616b3eba96'::uuid, 'histoire-geo', '2de', 'Les mobilités touristiques à l’échelle mondiale : étude comparative entre les USA et Dubaï', 'Quel effet le tourisme peut-il avoir sur les habitants des lieux très fréquentés ?', 'mcq', '["Une baisse des loyers","La fin de l’emploi local","Une baisse de la consommation d’eau","Une hausse des prix immobiliers qui les chasse"]'::jsonb, 3, 'La pression touristique fait monter les prix immobiliers et peut évincer les habitants de leur quartier.', 4),
    ('09c3c0ed-8f13-5651-81ba-d38d5357496b'::uuid, 'histoire-geo', '2de', 'La mer Méditerranée : un bassin migratoire', 'Dans quel rapport les revenus par habitant varient-ils entre les pays méditerranéens ?', 'mcq', '["De un à deux","De un à dix","De un à cent","Ils sont à peu près égaux"]'::jsonb, 1, 'Les revenus varient dans un rapport de un à dix entre les rives : cet écart alimente les mobilités.', 1),
    ('c4e758db-9ee0-5aed-88c7-30ebce4f6270'::uuid, 'histoire-geo', '2de', 'La mer Méditerranée : un bassin migratoire', 'Quel trajet suit la route migratoire centrale ?', 'mcq', '["Du Maroc vers l’Espagne","De la Turquie vers la Grèce","De la Libye et de la Tunisie vers l’Italie et Malte","De l’Égypte vers Chypre"]'::jsonb, 2, 'La route centrale part de Libye et de Tunisie vers l’Italie et Malte ; c’est la plus meurtrière.', 2),
    ('5c604b25-34aa-5bd0-8b9c-a7efe7758f69'::uuid, 'histoire-geo', '2de', 'La mer Méditerranée : un bassin migratoire', 'Quel trajet suit la route migratoire orientale ?', 'mcq', '["De la Turquie vers la Grèce, puis les Balkans","Du Maroc vers les Canaries","De l’Algérie vers la France","De la Libye vers Malte"]'::jsonb, 0, 'La route orientale mène de Turquie en Grèce, puis remonte par les Balkans.', 3),
    ('1951dbaf-a40a-5fdb-bcbf-85b698cfab73'::uuid, 'histoire-geo', '2de', 'La mer Méditerranée : un bassin migratoire', 'Que finance l’Union européenne pour contrôler les départs ?', 'mcq', '["Des ONG de sauvetage","Des ferries entre les rives","Des visas de travail","Des accords avec la Turquie ou la Libye"]'::jsonb, 3, 'L’UE finance des accords avec des pays de transit comme la Turquie ou la Libye, pour qu’ils retiennent les migrants.', 4),
    ('426f02f8-9a96-5157-b6d3-95d810b0a983'::uuid, 'histoire-geo', '2de', 'La France : mobilités, transports et enjeux d’aménagement', 'En combien de temps le TGV relie-t-il Paris à Lyon ?', 'mcq', '["Environ une heure","Environ trois heures","Environ deux heures","Environ cinq heures"]'::jsonb, 2, 'Le TGV met Lyon à deux heures de Paris et Marseille à trois : le réseau converge vers la capitale.', 1),
    ('3f0d8b6f-d897-5f97-8cc0-82f4b1c6b5c6'::uuid, 'histoire-geo', '2de', 'La France : mobilités, transports et enjeux d’aménagement', 'Comment sont les liaisons transversales, de province à province ?', 'mcq', '["Lentes","Plus rapides que les radiales","Toutes à grande vitesse","Inexistantes"]'::jsonb, 0, 'Dans un réseau en étoile, les liaisons transversales restent lentes : il est souvent plus rapide de passer par Paris.', 2),
    ('6ea53293-bd53-5334-8320-65368230171a'::uuid, 'histoire-geo', '2de', 'La France : mobilités, transports et enjeux d’aménagement', 'Que vise la réouverture de petites lignes ferroviaires ?', 'mcq', '["Relier Paris aux capitales européennes","Remplacer le TGV","Réduire le trafic aérien international","Désenclaver les territoires"]'::jsonb, 3, 'Rouvrir les petites lignes doit désenclaver les territoires ruraux, où la voiture est souvent la seule solution.', 3),
    ('e8383ee6-cc2f-5d18-9c1e-b414a307a7b4'::uuid, 'histoire-geo', '2de', 'La France : mobilités, transports et enjeux d’aménagement', 'Quelle offre de transport trouve-t-on surtout dans les métropoles ?', 'mcq', '["Une seule route","Métros, tramways, RER et vélos en libre-service","Des lignes aériennes intérieures","Uniquement des autoroutes"]'::jsonb, 1, 'Les métropoles offrent de nombreux transports collectifs ; les espaces ruraux et périurbains n’ont souvent qu’une route.', 4),
    ('b7ae4b51-4f54-55de-8293-179004badc53'::uuid, 'histoire-geo', '2de', 'L’aménagement et la valorisation des milieux d’Afrique australe', 'Comment évoluent les précipitations en Afrique australe ?', 'mcq', '["Elles augmentent d’est en ouest","Elles décroissent d’est en ouest","Elles sont partout identiques","Elles augmentent du nord au sud"]'::jsonb, 1, 'Les pluies décroissent d’est en ouest : l’ouest est occupé par les déserts du Namib et du Kalahari.', 1),
    ('9cee4af9-cb39-59d9-853f-0a12e8573620'::uuid, 'histoire-geo', '2de', 'L’aménagement et la valorisation des milieux d’Afrique australe', 'À quoi sert le Lesotho Highlands Water Project ?', 'mcq', '["À produire du charbon","À irriguer le delta de l’Okavango","À alimenter le Gauteng en eau","À protéger les rhinocéros"]'::jsonb, 2, 'Ce projet de barrages et de transferts envoie l’eau des montagnes du Lesotho vers le Gauteng, cœur économique sud-africain.', 2),
    ('8168cb52-ea12-5171-a66b-74bcccb7e325'::uuid, 'histoire-geo', '2de', 'L’aménagement et la valorisation des milieux d’Afrique australe', 'Quel courant rend poissonneuses les côtes atlantiques de la région ?', 'mcq', '["Le courant de Benguela","Le Gulf Stream","Le courant des Aiguilles","Le courant de Humboldt"]'::jsonb, 0, 'Le courant froid de Benguela, sur la côte atlantique, favorise des eaux riches en poissons.', 3),
    ('98a9c8fa-2740-5b10-b17f-2256de97a604'::uuid, 'histoire-geo', '2de', 'L’aménagement et la valorisation des milieux d’Afrique australe', 'Quel pays tire sa richesse minière du cuivre ?', 'mcq', '["Le Botswana","La Namibie","L’Afrique du Sud","La Zambie"]'::jsonb, 3, 'La Zambie exploite le cuivre ; le Botswana, les diamants ; la Namibie, l’uranium ; l’Afrique du Sud, l’or, le platine et le charbon.', 4),
    ('e90c62f5-c478-5b45-b118-d2f32d3ca9f0'::uuid, 'histoire-geo', '2de', 'Les défis de la transition et du développement pour les pays d’Afrique australe inégalement développés', 'Quelles sont les dates de l’apartheid en Afrique du Sud ?', 'mcq', '["1910-1948","1948-1991","1960-1975","1994-2008"]'::jsonb, 1, 'L’apartheid, régime de ségrégation légale, dure de 1948 à 1991 ; Nelson Mandela est élu en 1994.', 1),
    ('b225604e-1e56-5e19-beaa-409fd5cf480d'::uuid, 'histoire-geo', '2de', 'Les défis de la transition et du développement pour les pays d’Afrique australe inégalement développés', 'Lequel de ces pays compte parmi les plus pauvres du monde ?', 'mcq', '["Le Botswana","La Namibie","Le Malawi","L’Afrique du Sud"]'::jsonb, 2, 'Le Malawi, le Mozambique et le Zimbabwe comptent parmi les plus pauvres ; le Botswana et la Namibie ont un revenu intermédiaire.', 2),
    ('889b83f1-2f3a-5964-9ca5-aeecb7fbd1ac'::uuid, 'histoire-geo', '2de', 'Les défis de la transition et du développement pour les pays d’Afrique australe inégalement développés', 'Vers quelles énergies la région cherche-t-elle à se tourner pour moins dépendre du charbon ?', 'mcq', '["Le pétrole et le gaz","Le bois et la tourbe","Le nucléaire uniquement","Le solaire et l’éolien"]'::jsonb, 3, 'La transition vers le solaire et l’éolien doit rendre l’électricité moins dépendante du charbon.', 3),
    ('83bb5593-d78c-596c-80b5-196796ae2142'::uuid, 'histoire-geo', '2de', 'Les défis de la transition et du développement pour les pays d’Afrique australe inégalement développés', 'Quelle question reste non résolue en Afrique du Sud depuis la fin de l’apartheid ?', 'mcq', '["La question foncière","Le droit de vote","L’indépendance","La langue officielle"]'::jsonb, 0, 'L’accès à la terre, confisquée sous la ségrégation, reste une question non résolue, comme le chômage et les townships.', 4),
    ('303e5ce3-f6cd-5140-96b9-9c1f3cc63d94'::uuid, 'histoire-geo', '2de', 'Des territoires d’Afrique australe transformés par les mobilités', 'Dans quelle région se trouvent les mines d’or qui attirent les travailleurs depuis la fin du XIXe siècle ?', 'mcq', '["Le Witwatersrand","Le Kalahari","L’Okavango","Le Cap"]'::jsonb, 0, 'Les mines d’or et de diamants du Witwatersrand ont attiré des travailleurs du Lesotho, du Mozambique, du Malawi et du Zimbabwe.', 1),
    ('79b28765-71c5-5dce-a6f5-9f1ce78e3141'::uuid, 'histoire-geo', '2de', 'Des territoires d’Afrique australe transformés par les mobilités', 'De quels pays viennent surtout les migrants installés en Afrique du Sud ?', 'mcq', '["De Namibie et du Botswana","Du Zimbabwe et du Mozambique","D’Angola et de Zambie","De Madagascar et de Maurice"]'::jsonb, 1, 'Migrants économiques et demandeurs d’asile viennent surtout du Zimbabwe et du Mozambique.', 2),
    ('ef10be1e-b68c-5b6c-8e70-6d5e0cb77c09'::uuid, 'histoire-geo', '2de', 'Des territoires d’Afrique australe transformés par les mobilités', 'Vers où se dirigent les mobilités étudiantes de la région ?', 'mcq', '["Vers les universités chinoises","Vers le Botswana","Vers les universités sud-africaines","Vers le Malawi"]'::jsonb, 2, 'Les étudiants de la région partent surtout vers les universités sud-africaines.', 3),
    ('cdd7a655-6fb5-507d-b911-2c4f6619a54d'::uuid, 'histoire-geo', '2de', 'Des territoires d’Afrique australe transformés par les mobilités', 'Quel effet l’urbanisation rapide a-t-elle sur les campagnes ?', 'mcq', '["Elles se densifient","Elles s’industrialisent","Elles attirent les citadins","Elles se vident de leurs actifs"]'::jsonb, 3, 'Les jeunes actifs partent vers les villes : les campagnes se vident, pendant que les quartiers informels grossissent.', 4),
    ('e459f5e1-4026-555d-9a08-134155104780'::uuid, 'maths', '2de', 'Ensemble des nombres réels et intervalles', 'Que donne la réunion de [0 ; 2] et [1 ; 5] ?', 'mcq', '["[0 ; 5]","[1 ; 2]","[0 ; 1]","[2 ; 5]"]'::jsonb, 0, 'La réunion garde ce qui est dans l’un OU l’autre : de 0 à 5. L’intersection, elle, serait [1 ; 2].', 1),
    ('439d0acf-2b38-54c9-b690-ff777aeb6bee'::uuid, 'maths', '2de', 'Ensemble des nombres réels et intervalles', 'À quel intervalle correspond l’inéquation |x − 1| ≤ 3 ?', 'mcq', '["[−2 ; 4]","[1 ; 3]","[−3 ; 3]","[−4 ; 2]"]'::jsonb, 0, 'C’est l’intervalle centré en 1, de rayon 3 : [1 − 3 ; 1 + 3] = [−2 ; 4].', 2),
    ('b56b64ea-985b-5d2d-888b-e3204ab2273a'::uuid, 'maths', '2de', 'Ensemble des nombres réels et intervalles', 'Quel nombre appartient à ℤ mais pas à ℕ ?', 'mcq', '["−5","5","0,5","√2"]'::jsonb, 0, 'ℤ ajoute les entiers négatifs aux entiers naturels : −5 est un entier relatif, pas un entier naturel.', 3),
    ('d4dddd09-83b0-5323-bbf5-772eab71ff15'::uuid, 'maths', '2de', 'Ensemble des nombres réels et intervalles', 'Comment note-t-on l’ensemble des réels strictement supérieurs à 2 ?', 'mcq', '["]2 ; +∞[","[2 ; +∞[","]2 ; +∞]","]−∞ ; 2["]'::jsonb, 0, '2 est exclu, donc crochet ouvert ; et le crochet est toujours ouvert du côté de l’infini.', 4),
    ('9550dbad-065d-5493-b408-0e951b90b2ff'::uuid, 'maths', '2de', 'Les nombres décimaux, rationnels et irrationnels', 'Laquelle de ces fractions irréductibles est un nombre décimal ?', 'mcq', '["7/20","1/6","2/9","5/12"]'::jsonb, 0, '20 = 2² × 5 ne contient que les facteurs 2 et 5 : 7/20 = 0,35. Les autres dénominateurs contiennent un 3.', 1),
    ('8be1d547-1519-5186-ad9e-8a2ee2427e3e'::uuid, 'maths', '2de', 'Les nombres décimaux, rationnels et irrationnels', 'Que vaut 2/3 × 3/4 ?', 'mcq', '["1/2","6/7","5/12","8/9"]'::jsonb, 0, 'On multiplie terme à terme : 6/12 = 1/2.', 2),
    ('765e3e62-5e8b-5490-90ef-45d5a0ca3732'::uuid, 'maths', '2de', 'Les nombres décimaux, rationnels et irrationnels', 'Que vaut (1/2) ÷ (3/4) ?', 'mcq', '["2/3","3/8","3/2","1/4"]'::jsonb, 0, 'Diviser, c’est multiplier par l’inverse : 1/2 × 4/3 = 4/6 = 2/3.', 3),
    ('e61b7349-1eb5-5aa0-8596-80d02b008adb'::uuid, 'maths', '2de', 'Les nombres décimaux, rationnels et irrationnels', 'Dans la preuve de l’irrationalité de √2, que déduit-on de l’égalité 2q² = p² ?', 'mcq', '["Que p² est pair, donc p est pair","Que q est impair","Que p = 2q","Que √2 est décimal"]'::jsonb, 0, 'p² = 2q² est un multiple de 2, donc pair ; et un entier dont le carré est pair est lui-même pair.', 4),
    ('6c840ce3-ddab-5dcb-8ff5-08d6067d20bd'::uuid, 'maths', '2de', 'Nombres entiers : multiples, diviseurs et nombres premiers', 'Lequel de ces nombres est divisible par 4 ?', 'mcq', '["2 316","1 234","3 318","5 422"]'::jsonb, 0, 'On regarde les deux derniers chiffres : 16 est divisible par 4, alors que 34, 18 et 22 ne le sont pas.', 1),
    ('93c01b58-a426-5821-bb09-95b74d0a5a55'::uuid, 'maths', '2de', 'Nombres entiers : multiples, diviseurs et nombres premiers', 'Quel est le PGCD de 12 = 2² × 3 et 18 = 2 × 3² ?', 'mcq', '["6","36","3","2"]'::jsonb, 0, 'On prend les facteurs communs au plus petit exposant : 2¹ × 3¹ = 6.', 2),
    ('17e9843b-c3c4-5262-8e7c-dd291faec734'::uuid, 'maths', '2de', 'Nombres entiers : multiples, diviseurs et nombres premiers', 'Lequel de ces nombres est premier ?', 'mcq', '["97","87","91","99"]'::jsonb, 0, '√97 < 10 : on teste 2, 3, 5 et 7, aucun ne divise 97. En revanche 87 = 3 × 29, 91 = 7 × 13, 99 = 9 × 11.', 3),
    ('ab2a299c-caf6-5e93-bc66-86fcb71bd8ad'::uuid, 'maths', '2de', 'Nombres entiers : multiples, diviseurs et nombres premiers', 'Lequel de ces nombres est divisible par 9 ?', 'mcq', '["4 527","4 528","3 421","1 118"]'::jsonb, 0, 'La somme des chiffres de 4 527 vaut 4 + 5 + 2 + 7 = 18, divisible par 9.', 4),
    ('56ecba87-d33b-5094-a4bd-694bab0b2686'::uuid, 'maths', '2de', 'Calcul littéral : quotients, puissances, racines carrées', 'Que vaut a⁷ / a² (a non nul) ?', 'mcq', '["a⁵","a⁹","a¹⁴","a^3,5"]'::jsonb, 0, 'Pour un quotient de même base, on soustrait les exposants : 7 − 2 = 5.', 1),
    ('0c1af6ba-4371-5966-8079-7fc0df6a8ac3'::uuid, 'maths', '2de', 'Calcul littéral : quotients, puissances, racines carrées', 'Comment simplifier √50 ?', 'mcq', '["5√2","25√2","2√5","10√5"]'::jsonb, 0, '√50 = √(25 × 2) = √25 × √2 = 5√2.', 2),
    ('ffaa61fb-a0ee-5584-9108-2f22acd863e5'::uuid, 'maths', '2de', 'Calcul littéral : quotients, puissances, racines carrées', 'Que vaut (2x)³ ?', 'mcq', '["8x³","2x³","6x³","6x"]'::jsonb, 0, '(ab)ⁿ = aⁿbⁿ : (2x)³ = 2³ × x³ = 8x³.', 3),
    ('dfbc6eaa-5458-5c07-b5dd-6a0a9be34146'::uuid, 'maths', '2de', 'Calcul littéral : quotients, puissances, racines carrées', 'Quelle est la notation scientifique de 0,00042 ?', 'mcq', '["4,2 × 10⁻⁴","42 × 10⁻⁵","4,2 × 10⁴","0,42 × 10⁻³"]'::jsonb, 0, 'On écrit a × 10ⁿ avec 1 ≤ |a| < 10 : la virgule se déplace de 4 rangs vers la droite, d’où 10⁻⁴.', 4),
    ('6dccc4ff-c33f-5ea1-981a-f1dddffcfc5e'::uuid, 'maths', '2de', 'Les identités remarquables', 'Développez (2x + 7)(2x − 7).', 'mcq', '["4x² − 49","4x² + 49","4x² − 28x − 49","2x² − 49"]'::jsonb, 0, '(a + b)(a − b) = a² − b² avec a = 2x et b = 7 : 4x² − 49.', 1),
    ('cc2fb14b-2c71-5f25-88b1-12add3836008'::uuid, 'maths', '2de', 'Les identités remarquables', 'Comment factoriser 16x² − 25 ?', 'mcq', '["(4x − 5)(4x + 5)","(4x − 5)²","(16x − 25)(16x + 25)","(8x − 5)(8x + 5)"]'::jsonb, 0, '16x² = (4x)² et 25 = 5² : on applique a² − b² = (a − b)(a + b).', 2),
    ('fbbe0df1-03b6-5446-a3c0-cf5c31acd735'::uuid, 'maths', '2de', 'Les identités remarquables', 'Comment factoriser x² − 6x + 9 ?', 'mcq', '["(x − 3)²","(x + 3)²","(x − 3)(x + 3)","(x − 9)(x + 1)"]'::jsonb, 0, 'On reconnaît a² − 2ab + b² avec a = x et b = 3 : le double produit vaut bien 6x.', 3),
    ('4c3c8bef-d1d7-5bb7-b384-3e4857a72613'::uuid, 'maths', '2de', 'Les identités remarquables', 'Que vaut 99² en utilisant une identité remarquable ?', 'mcq', '["9 801","9 999","9 981","10 201"]'::jsonb, 0, '99² = (100 − 1)² = 10 000 − 200 + 1 = 9 801.', 4),
    ('25d2a6e3-23f7-5df1-94f5-45c8f245208b'::uuid, 'maths', '2de', 'Les équations et inéquations', 'Quelle est la solution de 5x − 2 = 3x + 8 ?', 'mcq', '["x = 5","x = 3","x = 10","x = 0,75"]'::jsonb, 0, 'On regroupe : 5x − 3x = 8 + 2, soit 2x = 10, donc x = 5.', 1),
    ('a0b07e21-8401-505c-8e8f-9c4fd9dbbb04'::uuid, 'maths', '2de', 'Les équations et inéquations', 'Quelle est la solution de (x − 1)/(x + 2) = 0 ?', 'mcq', '["x = 1","x = −2","x = 1 et x = −2","Aucune"]'::jsonb, 0, 'Le numérateur doit être nul et le dénominateur non nul : x = 1 convient, −2 est une valeur interdite.', 2),
    ('f02bf32a-70d2-5bb1-9d7d-7acbf467283b'::uuid, 'maths', '2de', 'Les équations et inéquations', 'Résolvez −3x ≤ 12.', 'mcq', '["x ≥ −4","x ≤ −4","x ≥ 4","x ≤ 4"]'::jsonb, 0, 'On divise par −3, nombre négatif : le sens de l’inégalité s’inverse, d’où x ≥ −4.', 3),
    ('52017e9f-8beb-5599-9df0-868bd8eff7a1'::uuid, 'maths', '2de', 'Les équations et inéquations', 'Que signale une double barre dans un tableau de signes ?', 'mcq', '["Une valeur interdite, qui annule un dénominateur","Une solution de l’équation","Un changement de signe obligatoire","Le maximum de la fonction"]'::jsonb, 0, 'Le quotient n’est pas défini en cette valeur : on la marque d’une double barre.', 4),
    ('d1648418-ceb3-5b07-92b0-ab22edff5ef0'::uuid, 'maths', '2de', 'Géométrie plane : triangles et projeté orthogonal d’un point sur une droite', 'Où se coupent les bissectrices d’un triangle ?', 'mcq', '["Au centre du cercle inscrit","Au centre du cercle circonscrit","À l’orthocentre","Au centre de gravité"]'::jsonb, 0, 'Le point de concours des bissectrices est équidistant des trois côtés : c’est le centre du cercle inscrit.', 1),
    ('f83c493d-03e4-53e4-a3e4-42e302fbda31'::uuid, 'maths', '2de', 'Géométrie plane : triangles et projeté orthogonal d’un point sur une droite', 'Dans un triangle rectangle, comment définit-on le sinus d’un angle aigu ?', 'mcq', '["Côté opposé sur hypoténuse","Côté adjacent sur hypoténuse","Côté opposé sur côté adjacent","Hypoténuse sur côté opposé"]'::jsonb, 0, 'Sinus : opposé / hypoténuse ; cosinus : adjacent / hypoténuse ; tangente : opposé / adjacent.', 2),
    ('38fa6757-8c50-5b52-920d-bdbb70848d2f'::uuid, 'maths', '2de', 'Géométrie plane : triangles et projeté orthogonal d’un point sur une droite', 'Dans un triangle rectangle, comment définit-on la tangente d’un angle aigu ?', 'mcq', '["Côté opposé sur côté adjacent","Côté adjacent sur côté opposé","Côté opposé sur hypoténuse","Hypoténuse sur côté adjacent"]'::jsonb, 0, 'La tangente est le rapport du côté opposé au côté adjacent, sans intervention de l’hypoténuse.', 3),
    ('d2a3bc23-9a7f-52fe-b219-97e3ecb6e7bf'::uuid, 'maths', '2de', 'Géométrie plane : triangles et projeté orthogonal d’un point sur une droite', 'De quoi le centre du cercle circonscrit à un triangle est-il équidistant ?', 'mcq', '["Des trois sommets","Des trois côtés","Des trois milieux","Des trois hauteurs"]'::jsonb, 0, 'Il est sur chaque médiatrice, donc à la même distance des trois sommets : c’est le rayon du cercle circonscrit.', 4),
    ('59a8570c-590d-565b-a93f-211d619e7920'::uuid, 'maths', '2de', 'Vecteurs du plan et opérations', 'Que vaut la somme des vecteurs AB + BC + CD ?', 'mcq', '["Le vecteur AD","Le vecteur DA","Le vecteur AC","Le vecteur nul"]'::jsonb, 0, 'On enchaîne la relation de Chasles : AB + BC = AC, puis AC + CD = AD.', 1),
    ('dae34bd1-f782-55a9-9147-85f9f7e12eb7'::uuid, 'maths', '2de', 'Vecteurs du plan et opérations', 'Comparé au vecteur u, que peut-on dire du vecteur 2u ?', 'mcq', '["Même direction, même sens, norme double","Même direction, sens opposé, norme double","Direction différente, même norme","Même sens, norme divisée par deux"]'::jsonb, 0, 'Multiplier par un réel positif conserve direction et sens, et multiplie la norme par ce réel.', 2),
    ('6dfa11d2-6295-5315-9a7a-beca548e6d3a'::uuid, 'maths', '2de', 'Vecteurs du plan et opérations', 'Selon la règle du parallélogramme, où lit-on la somme de deux vecteurs de même origine ?', 'mcq', '["Sur la diagonale issue du point commun","Sur l’autre diagonale","Sur le côté le plus long","Au centre du parallélogramme"]'::jsonb, 0, 'On construit le parallélogramme sur les deux vecteurs : leur somme est la diagonale partant de l’origine commune.', 3),
    ('7db04bd7-9e2b-5643-b200-f8621e4b220f'::uuid, 'maths', '2de', 'Vecteurs du plan et opérations', 'Deux droites ont des vecteurs directeurs colinéaires. Que peut-on en conclure ?', 'mcq', '["Elles sont parallèles","Elles sont perpendiculaires","Elles sont sécantes","Rien"]'::jsonb, 0, 'La colinéarité traduit le parallélisme des directions ; si les droites ont en plus un point commun, elles sont confondues.', 4),
    ('f97b9769-4532-58e4-84a1-2882369e27e7'::uuid, 'maths', '2de', 'Repère et coordonnées de vecteurs', 'Quelles sont les coordonnées de u + v, avec u(1 ; 2) et v(3 ; −5) ?', 'mcq', '["(4 ; −3)","(3 ; −10)","(−2 ; 7)","(4 ; 7)"]'::jsonb, 0, 'On additionne coordonnée par coordonnée : 1 + 3 = 4 et 2 + (−5) = −3.', 1),
    ('8bcd4184-a148-5cc7-8920-262ef5d4d941'::uuid, 'maths', '2de', 'Repère et coordonnées de vecteurs', 'Quelles sont les coordonnées de 3u, avec u(2 ; −1) ?', 'mcq', '["(6 ; −3)","(5 ; 2)","(6 ; −1)","(2 ; −3)"]'::jsonb, 0, 'On multiplie chaque coordonnée par 3.', 2),
    ('4f6359d0-19f3-5bbe-b0f6-03a6fa1b20bc'::uuid, 'maths', '2de', 'Repère et coordonnées de vecteurs', 'Les vecteurs u(2 ; 3) et v(4 ; 5) sont-ils colinéaires ?', 'mcq', '["Non, car 2 × 5 − 3 × 4 = −2","Oui, car 4 = 2 × 2","Oui, car leurs coordonnées augmentent","On ne peut pas le savoir"]'::jsonb, 0, 'Le déterminant xy′ − yx′ vaut 10 − 12 = −2, non nul : ils ne sont pas colinéaires.', 3),
    ('3e8891e6-325c-51f2-92de-9c7243041f02'::uuid, 'maths', '2de', 'Repère et coordonnées de vecteurs', 'Quelle autre méthode prouve qu’un quadrilatère est un parallélogramme ?', 'mcq', '["Ses diagonales ont le même milieu","Ses quatre côtés sont égaux deux à deux consécutifs","Ses diagonales sont perpendiculaires","Il a un angle droit"]'::jsonb, 0, 'Un quadrilatère dont les diagonales se coupent en leur milieu est un parallélogramme : on compare les coordonnées des deux milieux.', 4),
    ('9dbd12e7-8922-56cd-a3ce-985666162bca'::uuid, 'maths', '2de', 'Équations de droites', 'Quelle est l’équation réduite de la droite passant par A(0 ; 1) et B(2 ; 5) ?', 'mcq', '["y = 2x + 1","y = x + 1","y = 2x + 5","y = 3x + 1"]'::jsonb, 0, 'm = (5 − 1)/(2 − 0) = 2, et la droite coupe l’axe des ordonnées en 1 : p = 1.', 1),
    ('cf6d9f38-2385-574a-9f8a-60bd8935ac74'::uuid, 'maths', '2de', 'Équations de droites', 'Quel est un vecteur directeur de la droite d’équation y = 3x + 1 ?', 'mcq', '["(1 ; 3)","(3 ; 1)","(1 ; 1)","(−3 ; 1)"]'::jsonb, 0, 'Pour y = mx + p, le vecteur (1 ; m) est directeur : avancer de 1 fait monter de 3.', 2),
    ('0b0718f6-3770-55f4-9ae9-e44eaff67855'::uuid, 'maths', '2de', 'Équations de droites', 'Quel point appartient à la droite d’équation y = 2x − 3 ?', 'mcq', '["(2 ; 1)","(1 ; 2)","(0 ; 3)","(3 ; 0)"]'::jsonb, 0, 'Pour x = 2, y = 2 × 2 − 3 = 1 : le point (2 ; 1) vérifie l’équation.', 3),
    ('ddfdfe3d-a9aa-538f-b514-3a65bfe9b21c'::uuid, 'maths', '2de', 'Équations de droites', 'Que dire d’une droite dont le coefficient directeur est nul ?', 'mcq', '["Elle est horizontale","Elle est verticale","Elle passe par l’origine","Elle n’existe pas"]'::jsonb, 0, 'y = p : y ne varie pas quand x augmente, la droite est parallèle à l’axe des abscisses.', 4),
    ('b3a3e323-6e8f-557b-8926-cc48e050eab0'::uuid, 'maths', '2de', 'Généralités sur les fonctions', 'Quel est l’ensemble de définition de f(x) = 1/(x − 2) ?', 'mcq', '["ℝ privé de 2","ℝ","[2 ; +∞[","ℝ privé de 0"]'::jsonb, 0, 'On exclut la valeur qui annule le dénominateur : x − 2 = 0 pour x = 2.', 1),
    ('8708afe3-8383-5a30-badb-7f470d079211'::uuid, 'maths', '2de', 'Généralités sur les fonctions', 'Le point M(2 ; 5) appartient-il à la courbe de f(x) = x² + 1 ?', 'mcq', '["Oui, car f(2) = 5","Non, car f(2) = 3","Non, car f(5) = 26","On ne peut pas le savoir"]'::jsonb, 0, 'M(x ; y) est sur la courbe si et seulement si y = f(x) ; ici f(2) = 4 + 1 = 5.', 2),
    ('201bcf3a-fc42-5a13-ade1-20567a0bbd2e'::uuid, 'maths', '2de', 'Généralités sur les fonctions', 'Comment résout-on graphiquement f(x) ≥ k ?', 'mcq', '["On lit les abscisses des points de la courbe situés au-dessus de la droite y = k","On lit l’image de k","On cherche où la courbe coupe l’axe des ordonnées","On lit les ordonnées supérieures à k sur l’axe"]'::jsonb, 0, 'Les solutions sont les abscisses des portions de courbe au-dessus (ou sur) la droite horizontale y = k.', 3),
    ('59fa4fc3-d956-59c8-9843-580e51cf8890'::uuid, 'maths', '2de', 'Généralités sur les fonctions', 'Que fait apparaître un tableau de variations ?', 'mcq', '["Les extremums et les valeurs de x où ils sont atteints","Le signe de f","Les antécédents de 0 uniquement","L’équation de la courbe"]'::jsonb, 0, 'Les flèches résument le sens de variation, et aux changements de sens se lisent les maximums et minimums.', 4),
    ('987f67bb-8b78-5b96-894c-6860a9c035b1'::uuid, 'maths', '2de', 'La fonction affine', 'Quelle fonction affine vérifie f(1) = 5 et f(3) = 9 ?', 'mcq', '["f(x) = 2x + 3","f(x) = 4x + 1","f(x) = 2x + 5","f(x) = 3x + 2"]'::jsonb, 0, 'a = (9 − 5)/(3 − 1) = 2, puis 5 = 2 × 1 + b donne b = 3.', 1),
    ('957ac242-217d-57aa-a03b-49932caec88c'::uuid, 'maths', '2de', 'La fonction affine', 'Un abonnement coûte 10 € par mois plus 2 € par séance. Quelle fonction donne le coût pour x séances ?', 'mcq', '["f(x) = 2x + 10","f(x) = 10x + 2","f(x) = 12x","f(x) = 2x"]'::jsonb, 0, 'Le forfait fixe est l’ordonnée à l’origine, le tarif par unité le coefficient directeur.', 2),
    ('6e7db0e4-16dd-56bf-b4bc-cf8f5884f532'::uuid, 'maths', '2de', 'La fonction affine', 'Que peut-on dire de la droite représentant une fonction linéaire ?', 'mcq', '["Elle passe par l’origine","Elle est horizontale","Elle est verticale","Elle ne coupe jamais l’axe des abscisses"]'::jsonb, 0, 'Pour une fonction linéaire, b = 0 : f(0) = 0, la droite passe par l’origine et traduit une proportionnalité.', 3),
    ('b8f109df-9e65-59f4-bc7c-5662e283858c'::uuid, 'maths', '2de', 'La fonction affine', 'Quel est le signe de f(x) = 3x − 6 pour x < 2 ?', 'mcq', '["Négatif","Positif","Nul","Il dépend de x²"]'::jsonb, 0, 'f s’annule en 2 ; comme a = 3 > 0, f est négative avant 2 et positive après.', 4),
    ('8b347d8e-1f36-5dd5-9965-3cc139e58b0d'::uuid, 'maths', '2de', 'La fonction carré', 'Quelle est la solution de x² > 9 ?', 'mcq', '["]−∞ ; −3[ ∪ ]3 ; +∞[","]3 ; +∞[","]−3 ; 3[","]9 ; +∞["]'::jsonb, 0, 'Les points de la parabole au-dessus de y = 9 ont une abscisse inférieure à −3 ou supérieure à 3 : ne pas oublier la partie négative.', 1),
    ('f27fea08-4a64-52c7-96a7-0d65207e0897'::uuid, 'maths', '2de', 'La fonction carré', 'Quelles sont les solutions de x² = 7 ?', 'mcq', '["√7 et −√7","√7 seulement","3,5 et −3,5","49 et −49"]'::jsonb, 0, 'Pour k > 0, x² = k admet deux solutions, √k et −√k.', 2),
    ('526d762e-1bd4-5891-9323-39c82913ec6c'::uuid, 'maths', '2de', 'La fonction carré', 'Combien de solutions a l’équation x² = 0 ?', 'mcq', '["Une seule : 0","Deux","Aucune","Une infinité"]'::jsonb, 0, 'Le seul réel dont le carré est nul est 0.', 3),
    ('fcfe28e6-0243-5766-aeee-a7df1c7a5631'::uuid, 'maths', '2de', 'La fonction carré', 'Quelles sont les coordonnées du sommet de la parabole représentant x ↦ x² ?', 'mcq', '["(0 ; 0)","(1 ; 1)","(0 ; 1)","(−1 ; 1)"]'::jsonb, 0, 'Le minimum 0 est atteint en x = 0 : le sommet est l’origine du repère.', 4),
    ('a9f9af30-931b-5d17-8318-f3c68ebbbf93'::uuid, 'maths', '2de', 'La fonction cube', 'Quelle est la solution de x³ = 64 ?', 'mcq', '["4","8","−4 et 4","21,3"]'::jsonb, 0, '4³ = 4 × 4 × 4 = 64 ; l’équation x³ = k a toujours une seule solution.', 1),
    ('d95a0332-9c6d-599f-a3b0-ac845319d747'::uuid, 'maths', '2de', 'La fonction cube', 'Que vaut (−2)³ ?', 'mcq', '["−8","8","−6","6"]'::jsonb, 0, '(−2) × (−2) × (−2) = 4 × (−2) = −8 : le cube garde le signe.', 2),
    ('b6cb96ed-523a-5c8c-98ff-8724057c222b'::uuid, 'maths', '2de', 'La fonction cube', 'Combien de solutions a l’équation x³ = k, quel que soit le réel k ?', 'mcq', '["Toujours exactement une","Zéro, une ou deux selon k","Toujours deux","Aucune si k est négatif"]'::jsonb, 0, 'La fonction cube est croissante sur ℝ et prend toutes les valeurs : chaque k a un seul antécédent.', 3),
    ('120470ad-dfb0-5b27-94ed-12a9ed11e3e9'::uuid, 'maths', '2de', 'La fonction cube', 'Comparez 0,5 et 0,5³.', 'mcq', '["0,5³ = 0,125 est plus petit que 0,5","0,5³ = 1,5 est plus grand que 0,5","Ils sont égaux","0,5³ est négatif"]'::jsonb, 0, 'Sur [0 ; 1], élever à une puissance plus grande rapproche de 0 : x³ ≤ x² ≤ x.', 4),
    ('33ca157e-7f81-5aba-b8d5-408a3520ff7f'::uuid, 'maths', '2de', 'La fonction racine carrée', 'Quel est le minimum de la fonction racine carrée ?', 'mcq', '["0, atteint en 0","1, atteint en 1","Elle n’en a pas","−1, atteint en 1"]'::jsonb, 0, 'Croissante sur [0 ; +∞[, elle part de √0 = 0.', 1),
    ('4736aecb-c61c-52e0-9868-90d6d8a06bbd'::uuid, 'maths', '2de', 'La fonction racine carrée', 'Pour x ≥ 1, comment se comparent √x et x ?', 'mcq', '["√x ≤ x","√x ≥ x","Ils sont toujours égaux","On ne peut pas comparer"]'::jsonb, 0, 'Par exemple √16 = 4 ≤ 16 ; l’ordre s’inverse sur [0 ; 1].', 2),
    ('1be80015-15fd-5d21-9c71-5486506c6256'::uuid, 'maths', '2de', 'La fonction racine carrée', 'Quelle est la solution de √x = 1,2 ?', 'mcq', '["x = 1,44","x = 2,4","x = 1,2","x = 0,6"]'::jsonb, 0, 'Pour k ≥ 0, √x = k donne x = k² = 1,44.', 3),
    ('2ffdc17f-95d2-58de-9500-d720c1526b75'::uuid, 'maths', '2de', 'La fonction racine carrée', 'Pour quelles valeurs a-t-on √x = x ?', 'mcq', '["0 et 1","1 seulement","0 seulement","Aucune"]'::jsonb, 0, '√0 = 0 et √1 = 1 : ce sont les points où les courbes de √x et de x se croisent.', 4),
    ('97cc1a91-e529-57e2-951a-11d9852bb638'::uuid, 'maths', '2de', 'La fonction inverse', 'Quelles sont les asymptotes de l’hyperbole de la fonction inverse ?', 'mcq', '["Les deux axes du repère","La droite y = x","La droite y = 1","Elle n’en a pas"]'::jsonb, 0, 'La courbe se rapproche de l’axe des abscisses quand x devient grand, et de l’axe des ordonnées près de 0.', 1),
    ('13024e11-ec4b-586d-85d7-9498d4a9d7fb'::uuid, 'maths', '2de', 'La fonction inverse', 'Combien de solutions a l’équation 1/x = 0 ?', 'mcq', '["Aucune","Une : x = 0","Une : x = 1","Une infinité"]'::jsonb, 0, 'Un quotient de numérateur 1 n’est jamais nul : 1/x ne vaut jamais 0.', 2),
    ('ed25309f-7257-50ce-b038-d0689900e389'::uuid, 'maths', '2de', 'La fonction inverse', 'Quelle est la solution de 1/x = −0,5 ?', 'mcq', '["x = −2","x = 2","x = −0,5","x = 0,5"]'::jsonb, 0, 'Pour k non nul, la solution est x = 1/k = 1/(−0,5) = −2.', 3),
    ('5c5c3b89-7231-59dd-8883-3a19aba4bc3d'::uuid, 'maths', '2de', 'La fonction inverse', 'Que devient 1/x quand x se rapproche de 0 ?', 'mcq', '["Sa valeur absolue devient arbitrairement grande","Il se rapproche de 0","Il se rapproche de 1","Il reste constant"]'::jsonb, 0, 'Diviser 1 par un nombre de plus en plus petit donne un résultat de plus en plus grand en valeur absolue.', 4),
    ('a59cdb5d-9771-5916-a5ac-49f4117703a2'::uuid, 'maths', '2de', 'Information chiffrée', 'Deux hausses successives de 10 % correspondent à quelle hausse globale ?', 'mcq', '["21 %","20 %","11 %","100 %"]'::jsonb, 0, '1,10 × 1,10 = 1,21 : une hausse de 21 %, et non de 20 %.', 1),
    ('7d060b43-2399-5dc5-afbb-c9244e92aa48'::uuid, 'maths', '2de', 'Information chiffrée', 'Après une hausse de 25 %, quelle baisse ramène à la valeur de départ ?', 'mcq', '["20 %","25 %","75 %","12,5 %"]'::jsonb, 0, 'Le coefficient réciproque est 1/1,25 = 0,80, soit une baisse de 20 %.', 2),
    ('6b26ca2d-55b8-5aa3-94bf-0e27b67fae15'::uuid, 'maths', '2de', 'Information chiffrée', 'Un article à 80 € augmente de 15 %. Quel est son nouveau prix ?', 'mcq', '["92 €","95 €","68 €","80,15 €"]'::jsonb, 0, '80 × 1,15 = 92 €.', 3),
    ('9c6268b3-d055-590e-b173-fb821c7e3c1d'::uuid, 'maths', '2de', 'Information chiffrée', 'Dans une classe de 30 élèves, 12 font du latin. Quelle est la proportion de latinistes ?', 'mcq', '["0,4","0,12","2,5","0,18"]'::jsonb, 0, 'Proportion = effectif partiel / effectif total = 12/30 = 0,4, soit 40 %.', 4),
    ('8bf6a1f2-f91a-5256-9418-5c67dcef2169'::uuid, 'maths', '2de', 'Statistique descriptive', 'Quelle est la médiane de la série 2 ; 4 ; 6 ; 8 ; 20 ?', 'mcq', '["6","8","4","10"]'::jsonb, 0, 'La série est ordonnée et compte 5 valeurs : la médiane est la 3e, soit 6. La moyenne (8) est tirée vers le haut par 20.', 1),
    ('cb37291d-4cee-56a2-82d2-f180150a648e'::uuid, 'maths', '2de', 'Statistique descriptive', 'Quelle est l’étendue de la série 2 ; 4 ; 6 ; 8 ; 20 ?', 'mcq', '["18","20","6","22"]'::jsonb, 0, 'L’étendue est l’écart entre la plus grande et la plus petite valeur : 20 − 2 = 18.', 2),
    ('dc034ea4-d89c-5be6-b26c-d4afa9bf1964'::uuid, 'maths', '2de', 'Statistique descriptive', 'Un élève a 12 (coefficient 2) et 15 (coefficient 1). Quelle est sa moyenne pondérée ?', 'mcq', '["13","13,5","14","27"]'::jsonb, 0, '(12 × 2 + 15 × 1) / (2 + 1) = 39 / 3 = 13.', 3),
    ('c7920b5d-a30c-5cad-8215-5a4b6294e852'::uuid, 'maths', '2de', 'Statistique descriptive', 'Quel piège présente une moyenne calculée sur une série bimodale ?', 'mcq', '["Elle cache deux groupes distincts","Elle est toujours nulle","Elle est égale à la médiane","Elle exagère une variation"]'::jsonb, 0, 'Avec deux groupes bien séparés, la moyenne tombe entre les deux et ne décrit aucun d’eux.', 4),
    ('b0935245-8b3b-5b05-a4ee-54f92bbb1fd5'::uuid, 'maths', '2de', 'Probabilités : vocabulaire et outils', 'Quel ensemble correspond à l’événement impossible ?', 'mcq', '["L’ensemble vide","L’univers Ω","Un événement de probabilité 1","Une issue unique"]'::jsonb, 0, 'L’événement impossible ne contient aucune issue : sa probabilité est 0.', 1),
    ('775149cd-a4b7-56de-be17-a1b3fc65db9d'::uuid, 'maths', '2de', 'Probabilités : vocabulaire et outils', 'P(A) = 0,5, P(B) = 0,4 et P(A ∩ B) = 0,2. Que vaut P(A ∪ B) ?', 'mcq', '["0,7","0,9","0,2","1,1"]'::jsonb, 0, 'P(A ∪ B) = 0,5 + 0,4 − 0,2 = 0,7 : on retire l’intersection comptée deux fois.', 2),
    ('3a5c0b86-996f-5f4e-b1e0-81706627650b'::uuid, 'maths', '2de', 'Probabilités : vocabulaire et outils', 'On lance deux pièces équilibrées. Quelle est la probabilité d’obtenir au moins un pile ?', 'mcq', '["3/4","1/2","1/4","2/3"]'::jsonb, 0, 'L’événement contraire « aucun pile » a une probabilité de 1/2 × 1/2 = 1/4 ; donc 1 − 1/4 = 3/4.', 3),
    ('4928f142-3fbc-5590-aded-e4c5c62274c2'::uuid, 'maths', '2de', 'Probabilités : vocabulaire et outils', 'Une expérience a trois issues ; deux ont pour probabilités 0,2 et 0,5. Quelle est la probabilité de la troisième ?', 'mcq', '["0,3","0,7","0,35","0,1"]'::jsonb, 0, 'La somme des probabilités des issues vaut 1 : 1 − 0,2 − 0,5 = 0,3.', 4),
    ('31492c23-2d4e-553c-bec8-7a7b752b0f5e'::uuid, 'maths', '2de', 'Échantillonnage', 'Pour un échantillon de taille n = 400, quelle est la demi-largeur 1/√n de l’intervalle de fluctuation ?', 'mcq', '["0,05","0,0025","0,02","0,5"]'::jsonb, 0, '√400 = 20, donc 1/√n = 1/20 = 0,05.', 1),
    ('79a22dcc-2d73-5fe3-a3ca-a6314e8775fb'::uuid, 'maths', '2de', 'Échantillonnage', 'Quel est l’intervalle de fluctuation au seuil de 95 % pour p = 0,3 et n = 100 ?', 'mcq', '["[0,2 ; 0,4]","[0,29 ; 0,31]","[0,25 ; 0,35]","[0 ; 0,6]"]'::jsonb, 0, '1/√100 = 0,1 : [0,3 − 0,1 ; 0,3 + 0,1] = [0,2 ; 0,4].', 2),
    ('06c1720f-df96-5489-a157-e53a059f42da'::uuid, 'maths', '2de', 'Échantillonnage', 'La fréquence observée tombe dans l’intervalle de fluctuation. Que conclut-on ?', 'mcq', '["On ne rejette pas l’hypothèse, sans pour autant la démontrer","L’hypothèse est démontrée","On rejette l’hypothèse","L’échantillon est biaisé"]'::jsonb, 0, 'Ne pas rejeter une hypothèse n’est pas la prouver : l’échantillon est seulement compatible avec elle.', 3),
    ('15eedb49-0e75-5434-b797-1a25b69745ae'::uuid, 'maths', '2de', 'Échantillonnage', 'Que désigne la proportion p dans le vocabulaire de l’échantillonnage ?', 'mcq', '["La valeur, souvent inconnue, du caractère dans toute la population","La fréquence observée dans l’échantillon","La taille de l’échantillon","La marge d’erreur"]'::jsonb, 0, 'p concerne la population entière ; f est ce qu’on mesure dans l’échantillon.', 4),
    ('379e62ea-06e0-5065-89c0-b148825e7824'::uuid, 'physique-chimie', '2de', 'Corps purs et mélanges', 'Sous pression atmosphérique normale, à quelle température la glace d’eau pure fond-elle ?', 'mcq', '["4 °C","−10 °C","0 °C","100 °C"]'::jsonb, 2, 'La fusion de l’eau pure a lieu à 0 °C sous 1 013 hPa, et la température reste constante pendant tout le changement d’état.', 1),
    ('a6aa3523-d214-53aa-bd4d-18923204a33e'::uuid, 'physique-chimie', '2de', 'Corps purs et mélanges', 'Quelle est l’unité de la densité ?', 'mcq', '["Elle n’a pas d’unité","Le g·cm⁻³","Le kg·m⁻³","Le kilogramme"]'::jsonb, 0, 'La densité est une masse volumique divisée par celle de l’eau : les unités se simplifient, c’est un nombre sans unité.', 2),
    ('740180b0-026d-5fef-8195-bf9cb64a6178'::uuid, 'physique-chimie', '2de', 'Corps purs et mélanges', 'Lequel de ces exemples est un corps pur ?', 'mcq', '["Un alliage","L’eau salée","L’air","Le saccharose"]'::jsonb, 3, 'Le saccharose ne contient qu’une espèce chimique ; eau salée, air et alliage sont des mélanges homogènes.', 3),
    ('b4e717ec-3f8d-5fa5-80fd-e7a001d96540'::uuid, 'physique-chimie', '2de', 'Corps purs et mélanges', 'Quelle technique permet de récupérer le sel dissous dans de l’eau salée ?', 'mcq', '["La filtration","L’évaporation","La décantation","La centrifugation"]'::jsonb, 1, 'Le sel dissous passe à travers un filtre ; en évaporant l’eau, on récupère le solide.', 4),
    ('5de705a1-1c6e-54ca-97a3-cd4b865fd481'::uuid, 'physique-chimie', '2de', 'Composition d’un mélange', 'On dissout 5,0 g de sucre et on complète à 250 mL de solution. Quelle est la concentration en masse ?', 'mcq', '["1,25 g·L⁻¹","20 g·L⁻¹","5,0 g·L⁻¹","50 g·L⁻¹"]'::jsonb, 1, 't = m / V = 5,0 g / 0,250 L = 20 g·L⁻¹ : pense à convertir le volume en litres.', 1),
    ('64989b20-592e-5afc-9dce-afab06a798a6'::uuid, 'physique-chimie', '2de', 'Composition d’un mélange', 'Une solution à 10 g·L⁻¹ est diluée d’un facteur 5. Quelle est la concentration de la solution fille ?', 'mcq', '["15 g·L⁻¹","50 g·L⁻¹","5,0 g·L⁻¹","2,0 g·L⁻¹"]'::jsonb, 3, 'F = t₁ / t₂, donc t₂ = t₁ / F = 10 / 5 = 2,0 g·L⁻¹ : diluer, c’est diminuer la concentration.', 2),
    ('4143f7b6-2253-5551-8065-9ed433d0a4a2'::uuid, 'physique-chimie', '2de', 'Composition d’un mélange', 'Quel gaz est le plus abondant dans l’air, en volume ?', 'mcq', '["Le diazote","Le dioxygène","Le dioxyde de carbone","L’argon"]'::jsonb, 0, 'L’air contient environ 78 % de diazote, 21 % de dioxygène et 1 % d’autres gaz.', 3),
    ('3713a549-82b0-51a2-8248-f3b587377c63'::uuid, 'physique-chimie', '2de', 'Composition d’un mélange', 'Quelle verrerie utilise-t-on pour prélever un volume précis de solution mère lors d’une dilution ?', 'mcq', '["L’erlenmeyer","Le bécher","La pipette jaugée","Le tube à essai"]'::jsonb, 2, 'La pipette jaugée prélève un volume précis ; on l’introduit ensuite dans une fiole jaugée qu’on complète.', 4),
    ('84cc2a6f-7bb1-5b01-9c21-8988ce65e957'::uuid, 'physique-chimie', '2de', 'Identification d’une espèce chimique', 'Quel réactif met en évidence le dioxyde de carbone ?', 'mcq', '["Une bûchette incandescente, qui se rallume","Le sulfate de cuivre anhydre, qui bleuit","L’eau de chaux, qui se trouble","Une flamme, qui provoque une détonation"]'::jsonb, 2, 'Le CO2 trouble l’eau de chaux ; la bûchette rallumée signale le dioxygène, la détonation le dihydrogène.', 1),
    ('16fc9dde-74da-534d-b3fa-2ebcfd86744f'::uuid, 'physique-chimie', '2de', 'Identification d’une espèce chimique', 'Quelle couleur a le précipité obtenu avec la soude en présence d’ions cuivre II ?', 'mcq', '["Bleu","Rouille","Vert","Blanc"]'::jsonb, 0, 'Cuivre II : bleu ; fer III : rouille ; fer II : vert ; zinc ou aluminium : blanc.', 2),
    ('b65e9601-8d39-557c-b35d-c86a541a1280'::uuid, 'physique-chimie', '2de', 'Identification d’une espèce chimique', 'Sur une chromatographie, une tache a migré de 3,0 cm et le front d’éluant de 6,0 cm. Que vaut son Rf ?', 'mcq', '["9,0","2,0","3,0","0,50"]'::jsonb, 3, 'Rf = distance de la tache / distance du front = 3,0 / 6,0 = 0,50 ; un Rf est toujours compris entre 0 et 1.', 3),
    ('9ed1a21f-c7b0-5012-9ec2-43ca3ed3b91a'::uuid, 'physique-chimie', '2de', 'Identification d’une espèce chimique', 'Quel instrument mesure l’indice de réfraction d’un liquide ?', 'mcq', '["Le banc Kofler","Le réfractomètre","L’éprouvette graduée","Le spectrophotomètre"]'::jsonb, 1, 'Le réfractomètre mesure l’indice de réfraction, autre grandeur caractéristique d’une espèce pure.', 4),
    ('14cfdd6d-51d1-594a-bb68-7304394a6c52'::uuid, 'physique-chimie', '2de', 'Le noyau de l’atome', 'Combien de neutrons contient un noyau de carbone 14 (Z = 6) ?', 'mcq', '["6","8","14","20"]'::jsonb, 1, 'Nombre de neutrons = A − Z = 14 − 6 = 8.', 1),
    ('b5d4c5ec-b7a5-5ed8-a4af-6dc754fad195'::uuid, 'physique-chimie', '2de', 'Le noyau de l’atome', 'Environ combien de fois un nucléon est-il plus massif qu’un électron ?', 'mcq', '["10 fois","2 fois","100 000 fois","1 800 fois"]'::jsonb, 3, 'Un nucléon pèse environ 1 800 fois plus qu’un électron : la masse de l’atome est donc concentrée dans le noyau.', 2),
    ('49413165-6f9e-5656-8cd0-33dc3b1b6137'::uuid, 'physique-chimie', '2de', 'Le noyau de l’atome', 'Pourquoi deux isotopes ont-ils les mêmes propriétés chimiques ?', 'mcq', '["Parce qu’ils ont le même nombre d’électrons","Parce qu’ils ont le même nombre de neutrons","Parce qu’ils ont la même masse","Parce qu’ils ont le même nombre de nucléons"]'::jsonb, 0, 'Les propriétés chimiques dépendent des électrons ; deux isotopes ont le même Z, donc le même nombre d’électrons.', 3),
    ('ca6fcaf3-e1e3-5400-b199-5de3071d938d'::uuid, 'physique-chimie', '2de', 'Le noyau de l’atome', 'Que compte le nombre de masse A ?', 'mcq', '["Le nombre d’électrons","Le nombre de protons","Le nombre total de nucléons","Le nombre de neutrons seulement"]'::jsonb, 2, 'A compte protons et neutrons, c’est-à-dire tous les nucléons ; Z compte les protons.', 4),
    ('9ea68535-1c9f-5584-a8b3-8ea725ff594f'::uuid, 'physique-chimie', '2de', 'Configuration électronique d’un atome', 'Quelle est la configuration électronique du sodium (Z = 11) ?', 'mcq', '["1s² 2s² 2p⁶ 3p¹","1s² 2s² 2p⁷","1s² 2s² 2p⁶ 3s¹","1s² 2s⁸ 3s¹"]'::jsonb, 2, 'On remplit 1s (2), 2s (2), 2p (6), soit 10 électrons, puis le onzième va en 3s.', 1),
    ('382d68f8-a88d-5a62-9d63-8679cadd6aa2'::uuid, 'physique-chimie', '2de', 'Configuration électronique d’un atome', 'Combien d’électrons de valence possède le chlore (1s² 2s² 2p⁶ 3s² 3p⁵) ?', 'mcq', '["7","5","17","2"]'::jsonb, 0, 'La couche externe est la couche 3 : 3s² 3p⁵, soit 2 + 5 = 7 électrons de valence.', 2),
    ('adf2ff86-8e20-5b80-b621-a1cff150c837'::uuid, 'physique-chimie', '2de', 'Configuration électronique d’un atome', 'Comment se comportent les halogènes, dans l’avant-dernière colonne ?', 'mcq', '["Ils perdent deux électrons","Ils perdent facilement un électron","Ils sont chimiquement inertes","Ils gagnent facilement un électron"]'::jsonb, 3, 'Il leur manque un électron pour saturer leur couche externe : ils en gagnent facilement un.', 3),
    ('aa3cb43d-70b4-574e-b8d2-cf6fd3ef7861'::uuid, 'physique-chimie', '2de', 'Configuration électronique d’un atome', 'Selon quel critère Mendeleïev a-t-il classé les éléments ?', 'mcq', '["Le numéro atomique croissant","La masse croissante et les propriétés voisines","L’ordre alphabétique","La date de découverte"]'::jsonb, 1, 'Mendeleïev classait par masse croissante en regroupant les propriétés voisines ; le classement actuel suit le numéro atomique.', 4),
    ('3b1069c8-d203-5ead-8608-b08bbcee8cc9'::uuid, 'physique-chimie', '2de', 'Stabilité et charge électrique d’une entité chimique', 'Quel ion forme le magnésium ?', 'mcq', '["Mg⁺","Mg²⁺","Mg²⁻","Mg⁻"]'::jsonb, 1, 'Le magnésium perd deux électrons pour prendre la configuration du néon : il devient Mg²⁺.', 1),
    ('1f93064d-260e-5f99-9289-80ac588d14c6'::uuid, 'physique-chimie', '2de', 'Stabilité et charge électrique d’une entité chimique', 'Quel gaz noble sert de modèle à la règle du duet ?', 'mcq', '["Le krypton","Le néon","L’argon","L’hélium"]'::jsonb, 3, 'La règle du duet vise 2 électrons externes, comme l’hélium ; elle concerne notamment l’hydrogène.', 2),
    ('16253451-9d50-5519-b4f4-4e9f367c7d07'::uuid, 'physique-chimie', '2de', 'Stabilité et charge électrique d’une entité chimique', 'Combien de doublets non liants porte l’oxygène dans la molécule d’eau ?', 'mcq', '["Deux","Aucun","Un","Quatre"]'::jsonb, 0, 'L’oxygène forme deux liaisons O–H et garde deux doublets non liants : il a bien huit électrons autour de lui.', 3),
    ('431598e8-b28d-5c69-9a60-b43a461d8dc0'::uuid, 'physique-chimie', '2de', 'Stabilité et charge électrique d’une entité chimique', 'Que donne une formule brute ?', 'mcq', '["Les doublets non liants","L’enchaînement des liaisons","La nature et le nombre des atomes","La forme de la molécule dans l’espace"]'::jsonb, 2, 'C₂H₆O dit quels atomes et combien ; l’enchaînement des liaisons est donné par la formule développée.', 4),
    ('d7132c58-1197-53ca-adf3-732b43760bf8'::uuid, 'physique-chimie', '2de', 'Compter les entités dans un échantillon de matière', 'Quelle est la masse molaire du dioxyde de carbone CO₂ ? (C : 12,0 ; O : 16,0 g·mol⁻¹)', 'mcq', '["32,0 g·mol⁻¹","28,0 g·mol⁻¹","44,0 g·mol⁻¹","40,0 g·mol⁻¹"]'::jsonb, 2, 'M(CO₂) = 12,0 + 2 × 16,0 = 44,0 g·mol⁻¹.', 1),
    ('b3f2fe21-f9e5-5831-b4e5-96c9a55ce0f5'::uuid, 'physique-chimie', '2de', 'Compter les entités dans un échantillon de matière', 'Quelle quantité de matière représente 12 L de gaz à 20 °C sous 1 013 hPa (V_m = 24,0 L·mol⁻¹) ?', 'mcq', '["0,50 mol","2,0 mol","288 mol","12 mol"]'::jsonb, 0, 'n = V / V_m = 12 / 24,0 = 0,50 mol.', 2),
    ('8d587aaa-5906-5d1d-bacd-bc7a4a26b15c'::uuid, 'physique-chimie', '2de', 'Compter les entités dans un échantillon de matière', 'On dissout 0,20 mol de soluté dans 0,50 L de solution. Quelle est la concentration en quantité de matière ?', 'mcq', '["0,70 mol·L⁻¹","0,10 mol·L⁻¹","2,5 mol·L⁻¹","0,40 mol·L⁻¹"]'::jsonb, 3, 'c = n / V = 0,20 / 0,50 = 0,40 mol·L⁻¹.', 3),
    ('a8a1de2f-07e9-5e41-873a-4602f382c4a0'::uuid, 'physique-chimie', '2de', 'Compter les entités dans un échantillon de matière', 'Combien de molécules contient 2,0 mol d’eau ?', 'mcq', '["Environ 3,0 × 10²³","Environ 1,2 × 10²⁴","Environ 6,02 × 10²³","2,0"]'::jsonb, 1, 'N = n × N_A = 2,0 × 6,02 × 10²³ ≈ 1,2 × 10²⁴ molécules.', 4),
    ('9c76a4df-d5e8-566e-82d7-b2979524c66e'::uuid, 'physique-chimie', '2de', 'Caractéristiques et représentation d’un changement d’état', 'Comment appelle-t-on le passage direct de l’état gazeux à l’état solide ?', 'mcq', '["La liquéfaction","La condensation","La solidification","La sublimation"]'::jsonb, 1, 'Gaz → solide : condensation ; son inverse, solide → gaz, est la sublimation.', 1),
    ('4df4b2ba-8ece-5e7c-9657-a52452331b62'::uuid, 'physique-chimie', '2de', 'Caractéristiques et représentation d’un changement d’état', 'Lequel de ces changements d’état est exothermique ?', 'mcq', '["La sublimation","La fusion","La vaporisation","La solidification"]'::jsonb, 3, 'Solidification, liquéfaction et condensation libèrent de l’énergie ; fusion, vaporisation et sublimation en absorbent.', 2),
    ('d377244e-b56f-55a5-9ab8-abb80042648d'::uuid, 'physique-chimie', '2de', 'Caractéristiques et représentation d’un changement d’état', 'À quoi sert l’énergie apportée pendant le palier de température ?', 'mcq', '["À défaire les interactions entre les entités","À faire monter la température","À transformer les molécules","À rien, elle est perdue"]'::jsonb, 0, 'Pendant le palier, l’énergie ne fait pas monter la température : elle sépare les entités les unes des autres.', 3),
    ('a5227fb4-879a-5654-82ed-566bd598e4b4'::uuid, 'physique-chimie', '2de', 'Caractéristiques et représentation d’un changement d’état', 'Comment les entités sont-elles organisées dans un solide ?', 'mcq', '["Très éloignées et en mouvement rapide","Désordonnées mais en contact","Ordonnées et fixes","Totalement libres, sans forme propre"]'::jsonb, 2, 'Dans un solide, les entités sont ordonnées et fixes : c’est ce qui lui donne une forme propre.', 4),
    ('3612b15c-ab99-5851-bf25-60e592c9e232'::uuid, 'physique-chimie', '2de', 'Écriture et analyse d’une réaction chimique', 'Dans un tableau d’avancement, comment s’écrit la quantité d’un réactif de coefficient 2 à l’avancement x ?', 'mcq', '["n(initial) − x/2","n(initial) + 2x","n(initial) − 2x","2 × n(initial) − x"]'::jsonb, 2, 'Un réactif disparaît : on retire coefficient × x à sa quantité initiale.', 1),
    ('d0f287e6-c361-5c72-8846-7c8210235142'::uuid, 'physique-chimie', '2de', 'Écriture et analyse d’une réaction chimique', 'Réaction 2 H₂ + O₂ donne 2 H₂O, avec 3,0 mol de H₂ et 1,0 mol de O₂. Que vaut x_max ?', 'mcq', '["1,0 mol","1,5 mol","3,0 mol","0,50 mol"]'::jsonb, 0, 'H₂ s’annule pour 3,0 − 2x = 0, soit x = 1,5 mol ; O₂ pour 1,0 − x = 0, soit x = 1,0 mol. On garde la plus petite valeur : O₂ est limitant.', 2),
    ('59c08e59-ca4d-574b-b73b-751bfaafc7a4'::uuid, 'physique-chimie', '2de', 'Écriture et analyse d’une réaction chimique', 'Quel coefficient faut-il placer devant O₂ pour équilibrer « 2 H₂ + … O₂ donne 2 H₂O » ?', 'mcq', '["4","2","3","1"]'::jsonb, 3, 'À droite, 2 H₂O contiennent 2 atomes d’oxygène : une seule molécule O₂ suffit.', 3),
    ('2a09d9c9-3573-5c29-91a8-4e0d5c2bbaa2'::uuid, 'physique-chimie', '2de', 'Écriture et analyse d’une réaction chimique', 'Qu’est-ce qu’une équation de réaction ne donne PAS ?', 'mcq', '["Les proportions dans lesquelles les espèces réagissent","Les quantités réellement engagées","La nature des réactifs","La nature des produits"]'::jsonb, 1, 'L’équation donne les proportions, pas les quantités mises en jeu (ni la vitesse) : c’est le rôle du tableau d’avancement.', 4),
    ('cf970c0f-be30-5274-a4bc-47e6647564b7'::uuid, 'physique-chimie', '2de', 'Synthèse d’une espèce chimique présente dans la nature', 'Une synthèse fournit 0,30 mol de produit pour 0,40 mol attendues au maximum. Quel est le rendement ?', 'mcq', '["133 %","75 %","30 %","40 %"]'::jsonb, 1, 'Rendement = 0,30 / 0,40 = 0,75, soit 75 % : il est toujours inférieur à 100 %.', 1),
    ('349703f5-2fb3-557b-bfff-af434b87c495'::uuid, 'physique-chimie', '2de', 'Synthèse d’une espèce chimique présente dans la nature', 'À quelle étape d’un protocole appartient la recristallisation ?', 'mcq', '["La sécurité","La transformation","L’identification","La séparation"]'::jsonb, 3, 'Recristallisation, filtration, extraction et décantation servent à isoler le produit : c’est l’étape de séparation.', 2),
    ('52c8e380-c669-5721-ac59-8c4029f3e6c0'::uuid, 'physique-chimie', '2de', 'Synthèse d’une espèce chimique présente dans la nature', 'Parmi ces techniques, laquelle sert à identifier le produit obtenu ?', 'mcq', '["La mesure de sa température de fusion","Le chauffage à reflux","La décantation à l’ampoule","La filtration"]'::jsonb, 0, 'L’identification compare le produit à une référence : chromatographie, température de fusion, spectres.', 3),
    ('7b8965cb-ee02-5ab4-9b72-772de8af24c3'::uuid, 'physique-chimie', '2de', 'Synthèse d’une espèce chimique présente dans la nature', 'Lequel de ces arguments justifie de synthétiser une espèce présente dans la nature ?', 'mcq', '["La molécule naturelle n’existe qu’en laboratoire","La molécule de synthèse est toujours plus sûre","La ressource naturelle n’est disponible qu’à certaines saisons","Le corps assimile mieux la molécule de synthèse"]'::jsonb, 2, 'Quantité, coût, saisonnalité ou impact de l’extraction justifient une synthèse ; la molécule obtenue est identique à la naturelle.', 4),
    ('ea4ae49b-de03-5c66-ac8c-002d96035df5'::uuid, 'physique-chimie', '2de', 'Identifier une réaction nucléaire', 'Que se passe-t-il lors d’une désintégration β⁺ ?', 'mcq', '["Un noyau d’hélium est émis","Un électron est émis et Z augmente de 1","Un positon est émis et Z diminue de 1","A diminue de 4"]'::jsonb, 2, 'En β⁺, un positon est émis : A ne change pas, Z diminue de 1.', 1),
    ('0219c851-8488-5269-8d21-6c8b1e03a3f7'::uuid, 'physique-chimie', '2de', 'Identifier une réaction nucléaire', 'L’uranium 238 (Z = 92) subit une désintégration α. Quel noyau obtient-on ?', 'mcq', '["A = 234 et Z = 90","A = 238 et Z = 93","A = 236 et Z = 91","A = 234 et Z = 92"]'::jsonb, 0, 'Lois de Soddy : l’émission d’un noyau d’hélium (A = 4, Z = 2) donne A = 238 − 4 = 234 et Z = 92 − 2 = 90.', 2),
    ('b578ce54-da1b-51ee-b337-720664be464d'::uuid, 'physique-chimie', '2de', 'Identifier une réaction nucléaire', 'Quel est l’ordre de grandeur de l’énergie mise en jeu par une réaction nucléaire, par noyau ?', 'mcq', '["Le joule","L’électronvolt","Le millième d’électronvolt","Le million d’électronvolts"]'::jsonb, 3, 'Les réactions nucléaires libèrent de l’ordre du MeV par noyau, environ un million de fois plus qu’une réaction chimique.', 3),
    ('42aa703a-cb87-5426-9981-41f2152fa7bc'::uuid, 'physique-chimie', '2de', 'Identifier une réaction nucléaire', 'Qu’est-ce qui provoque la fission d’un noyau d’uranium 235 dans une centrale ?', 'mcq', '["Un choc avec un électron","L’impact d’un neutron","La lumière","La fusion de deux noyaux d’hydrogène"]'::jsonb, 1, 'Un neutron frappe le noyau lourd, qui se casse en deux noyaux plus légers en libérant de l’énergie.', 4),
    ('d96c0dfa-4880-500b-9976-c12c09805dd1'::uuid, 'physique-chimie', '2de', 'Relativité du mouvement', 'Quel référentiel choisit-on pour étudier le mouvement d’un satellite autour de la Terre ?', 'mcq', '["Le référentiel héliocentrique","Le référentiel géocentrique","Le référentiel terrestre","Le référentiel du satellite"]'::jsonb, 1, 'Le référentiel géocentrique est centré sur le centre de la Terre : c’est celui des satellites.', 1),
    ('1c288d1b-accf-575e-a3b8-a72abb2b06a7'::uuid, 'physique-chimie', '2de', 'Relativité du mouvement', 'À combien de m·s⁻¹ correspond une vitesse de 72 km·h⁻¹ ?', 'mcq', '["72 m·s⁻¹","259 m·s⁻¹","7,2 m·s⁻¹","20 m·s⁻¹"]'::jsonb, 3, 'Pour passer des km·h⁻¹ aux m·s⁻¹, on divise par 3,6 : 72 / 3,6 = 20 m·s⁻¹.', 2),
    ('5135ea1c-5431-5a2e-8c34-4a4ebb2c3809'::uuid, 'physique-chimie', '2de', 'Relativité du mouvement', 'Quelle est la trajectoire de la valve d’une roue pour le cycliste lui-même ?', 'mcq', '["Un cercle","Une cycloïde","Une droite","Une parabole"]'::jsonb, 0, 'Dans le référentiel du vélo, la valve tourne autour de l’axe de la roue ; c’est pour le piéton au bord de la route qu’elle décrit une cycloïde.', 3),
    ('aedab45c-9e0f-53f5-9de2-9c71b402a4a9'::uuid, 'physique-chimie', '2de', 'Relativité du mouvement', 'Un coureur parcourt 100 m en 20 s. Quelle est sa vitesse moyenne ?', 'mcq', '["0,20 m·s⁻¹","2 000 m·s⁻¹","5,0 m·s⁻¹","80 m·s⁻¹"]'::jsonb, 2, 'v = d / Δt = 100 / 20 = 5,0 m·s⁻¹.', 4),
    ('a1ef52db-ef78-511c-98ab-4c8b84fbb0b8'::uuid, 'physique-chimie', '2de', 'Représentation et variation d’un vecteur vitesse', 'Dans un mouvement circulaire uniforme, vers où est dirigée la variation du vecteur vitesse ?', 'mcq', '["Vers l’extérieur du cercle","Vers l’avant, dans le sens du mouvement","Vers le centre du cercle","Elle est nulle"]'::jsonb, 2, 'Seule la direction change : la variation de vitesse est non nulle et pointe vers le centre.', 1),
    ('ad8563b1-02b4-580e-9864-62f7bee5e72f'::uuid, 'physique-chimie', '2de', 'Représentation et variation d’un vecteur vitesse', 'Dans un mouvement rectiligne accéléré, comment est orientée la variation du vecteur vitesse ?', 'mcq', '["Dans le sens du mouvement","En sens inverse du mouvement","Perpendiculaire à la trajectoire","Elle est nulle"]'::jsonb, 0, 'La valeur de la vitesse augmente sur une droite : la variation est dans le sens du mouvement.', 2),
    ('6731a7cb-fce0-5e33-a340-bbef97d59cba'::uuid, 'physique-chimie', '2de', 'Représentation et variation d’un vecteur vitesse', 'Sur un enregistrement, M(i−1)M(i+1) = 4,0 cm et τ = 0,040 s. Que vaut v(i) ?', 'mcq', '["50 m·s⁻¹","1,0 m·s⁻¹","0,16 m·s⁻¹","0,50 m·s⁻¹"]'::jsonb, 3, 'v(i) ≈ M(i−1)M(i+1) / 2τ = 0,040 m / 0,080 s = 0,50 m·s⁻¹.', 3),
    ('30a8b5b9-26cb-553a-ace1-e74e058f0552'::uuid, 'physique-chimie', '2de', 'Représentation et variation d’un vecteur vitesse', 'À l’échelle 1 cm pour 0,5 m·s⁻¹, quelle longueur de flèche représente une vitesse de 2,0 m·s⁻¹ ?', 'mcq', '["1,0 cm","4,0 cm","2,0 cm","0,25 cm"]'::jsonb, 1, '2,0 / 0,5 = 4 : la flèche mesure 4,0 cm.', 4),
    ('27ebd5c2-5a8a-59c5-a8dc-459c4e6a242a'::uuid, 'physique-chimie', '2de', 'Modélisation d’une action par une force', 'Quel est le poids d’un objet de 2,0 kg à la surface de la Terre (g ≈ 9,8 N·kg⁻¹) ?', 'mcq', '["2,0 N","Environ 20 N","Environ 4,9 N","2,0 kg"]'::jsonb, 1, 'P = m × g = 2,0 × 9,8 ≈ 19,6 N, soit environ 20 N ; un poids s’exprime en newtons, pas en kilogrammes.', 1),
    ('9f8566b1-0d1d-5abb-914f-17804a945b63'::uuid, 'physique-chimie', '2de', 'Modélisation d’une action par une force', 'Parmi ces actions, laquelle est une action à distance ?', 'mcq', '["Les frottements de l’air","La poussée d’une main","La tension d’un fil","L’attraction d’un aimant sur un clou"]'::jsonb, 3, 'Le magnétisme agit sans contact, comme la pesanteur ; fil, main et air agissent par contact.', 2),
    ('33610b5a-0cea-5c5f-8be3-1c5cc130eae4'::uuid, 'physique-chimie', '2de', 'Modélisation d’une action par une force', 'Quelle est la direction du poids ?', 'mcq', '["Verticale, vers le bas","Horizontale","Verticale, vers le haut","Celle du mouvement"]'::jsonb, 0, 'Le poids est vertical, dirigé vers le bas, appliqué au centre de gravité.', 3),
    ('5df37bf0-52de-5ed0-8ffa-11f8bf08f5f4'::uuid, 'physique-chimie', '2de', 'Modélisation d’une action par une force', 'À quoi sert un diagramme objet-interaction ?', 'mcq', '["À tracer la trajectoire","À calculer la masse du système","À n’oublier aucune action qui s’exerce sur le système","À mesurer une vitesse"]'::jsonb, 2, 'On place le système au centre, les acteurs autour, et une double flèche par interaction : l’inventaire est complet.', 4),
    ('8fc4d793-13a3-5546-8cd1-78b49aff49a8'::uuid, 'physique-chimie', '2de', 'Le principe d’inertie', 'Un palet lancé sur une table à coussin d’air conserve sa vitesse et sa direction. Pourquoi ?', 'mcq', '["Parce qu’il n’a pas de masse","Parce qu’une force le pousse en permanence","Parce que les frottements sont presque nuls et les forces se compensent","Parce que son poids est nul"]'::jsonb, 2, 'Le poids est compensé par le coussin d’air et il n’y a presque pas de frottement : le mouvement reste rectiligne uniforme.', 1),
    ('c1f72a3a-0205-57db-a3b0-f9dd0622f7a0'::uuid, 'physique-chimie', '2de', 'Le principe d’inertie', 'Quelle force agit sur une pierre lâchée sans vitesse, si l’on néglige l’air ?', 'mcq', '["Son seul poids","Aucune force","Une force vers le haut","Le poids et une force de lancement"]'::jsonb, 0, 'Seul le poids agit : les forces ne se compensent pas, et la vitesse augmente vers le bas.', 2),
    ('0dc4149e-5314-5064-b286-b0897c891c5f'::uuid, 'physique-chimie', '2de', 'Le principe d’inertie', 'Dans l’air, qu’est-ce qui fait tomber une plume moins vite qu’une bille ?', 'mcq', '["Son poids qui est nul","Sa masse plus faible","Sa couleur","La résistance de l’air"]'::jsonb, 3, 'Dans le vide, elles tombent ensemble : c’est la résistance de l’air, et non la masse, qui les sépare.', 3),
    ('26bd1475-3128-5904-92e2-75a67ba385c5'::uuid, 'physique-chimie', '2de', 'Le principe d’inertie', 'Un livre est immobile sur une table, dans un référentiel galiléen. Que peut-on en conclure ?', 'mcq', '["Aucune force ne s’exerce sur lui","Les forces qui s’exercent sur lui se compensent","Seul son poids agit","Il n’a pas de masse"]'::jsonb, 1, 'Immobile, son vecteur vitesse ne varie pas : d’après le principe d’inertie, son poids est compensé par l’action de la table.', 4),
    ('e7761af5-c967-5178-be26-0132dc43f662'::uuid, 'physique-chimie', '2de', 'Émission et propagation d’un signal sonore', 'Quelle est la célérité du son dans l’eau ?', 'mcq', '["Environ 340 m·s⁻¹","Environ 1 500 m·s⁻¹","Plus de 5 000 m·s⁻¹","Environ 3,0 × 10⁸ m·s⁻¹"]'::jsonb, 1, 'Le son va environ 4 fois plus vite dans l’eau que dans l’air, et encore plus vite dans l’acier.', 1),
    ('c445b024-fde5-5c7c-8d35-bd6a63bcb667'::uuid, 'physique-chimie', '2de', 'Émission et propagation d’un signal sonore', 'Un écho revient 0,40 s après un cri, dans l’air (v = 340 m·s⁻¹). À quelle distance est la paroi ?', 'mcq', '["34 m","136 m","850 m","68 m"]'::jsonb, 3, 'd = v × Δt / 2 = 340 × 0,40 / 2 = 68 m : le son fait l’aller et le retour.', 2),
    ('f1248a21-dd6b-5dfa-9078-e77e6544801f'::uuid, 'physique-chimie', '2de', 'Émission et propagation d’un signal sonore', 'On compte 3 s entre l’éclair et le tonnerre. À quelle distance environ est l’orage ?', 'mcq', '["Environ 1 km","Environ 100 m","Environ 3 km","Environ 10 km"]'::jsonb, 0, 'La lumière arrive presque instantanément ; le son parcourt 340 × 3 ≈ 1 000 m.', 3),
    ('9645ee4a-152a-515b-8765-07aa80849ca8'::uuid, 'physique-chimie', '2de', 'Émission et propagation d’un signal sonore', 'Que fait chaque molécule d’air lors du passage d’un son ?', 'mcq', '["Elle reste parfaitement immobile","Elle voyage de la source jusqu’à l’oreille","Elle oscille autour de sa position d’équilibre","Elle se transforme en énergie"]'::jsonb, 2, 'Le son est une onde mécanique : compressions et dilatations se transmettent de proche en proche, sans transport de matière.', 4),
    ('bfacd544-65e1-5731-99b1-11c79b5d1df9'::uuid, 'physique-chimie', '2de', 'Les sons : fréquence, intensité et perception', 'Deux sources identiques sont placées côte à côte. De combien augmente le niveau sonore ?', 'mcq', '["De 10 dB","Il double","De 3 dB","Il ne change pas"]'::jsonb, 2, 'L’échelle des décibels est logarithmique : doubler l’intensité ajoute seulement 3 dB.', 1),
    ('9b183dd2-9c88-5fe4-aa94-a5c6212510ee'::uuid, 'physique-chimie', '2de', 'Les sons : fréquence, intensité et perception', 'Vers quel niveau sonore se situe le seuil de douleur ?', 'mcq', '["120 dB","60 dB","0 dB","80 dB"]'::jsonb, 0, '0 dB est le seuil d’audibilité, 60 dB une conversation, et la douleur apparaît vers 120 dB.', 2),
    ('8c2322ea-d46e-5490-a430-6cc3755f1846'::uuid, 'physique-chimie', '2de', 'Les sons : fréquence, intensité et perception', 'Qu’appelle-t-on les harmoniques d’un son ?', 'mcq', '["Des échos successifs","Des sons de même intensité","Des sons inaudibles","Des fréquences multiples de la fréquence fondamentale"]'::jsonb, 3, 'Les harmoniques, de fréquences multiples du fondamental, donnent au son son timbre.', 3),
    ('b4fc1cd5-d6d8-59fc-ba9b-3e88754452ac'::uuid, 'physique-chimie', '2de', 'Les sons : fréquence, intensité et perception', 'Comment appelle-t-on les sons de fréquence inférieure à 20 Hz ?', 'mcq', '["Les ultrasons","Les infrasons","Les sons aigus","Les harmoniques"]'::jsonb, 1, 'Sous 20 Hz, ce sont des infrasons, inaudibles pour l’humain mais perçus par certains animaux.', 4),
    ('b4074f55-75cb-509f-ad93-8d443331034b'::uuid, 'physique-chimie', '2de', 'Intensité et tension dans un circuit complexe', 'Comment branche-t-on un voltmètre ?', 'mcq', '["En série dans la branche","En dérivation aux bornes du dipôle","À la place du générateur","Il n’a pas besoin d’être branché"]'::jsonb, 1, 'Le voltmètre mesure une différence entre deux points : il se branche en dérivation ; l’ampèremètre, lui, en série.', 1),
    ('15567905-a505-59f5-a8b7-84f35732216e'::uuid, 'physique-chimie', '2de', 'Intensité et tension dans un circuit complexe', 'Deux lampes en série sur un générateur de 12 V ; l’une a 5,0 V à ses bornes. Quelle tension aux bornes de l’autre ?', 'mcq', '["17 V","12 V","5,0 V","7,0 V"]'::jsonb, 3, 'Loi des mailles : en série, la tension du générateur est la somme des tensions des récepteurs, 12 − 5,0 = 7,0 V.', 2),
    ('649dbac1-b886-5df5-b231-587e2175b464'::uuid, 'physique-chimie', '2de', 'Intensité et tension dans un circuit complexe', '0,80 A arrivent à un nœud ; une branche en emporte 0,30 A. Combien part dans l’autre ?', 'mcq', '["0,50 A","1,1 A","0,30 A","0,80 A"]'::jsonb, 0, 'Loi des nœuds : ce qui arrive repart, 0,80 − 0,30 = 0,50 A.', 3),
    ('a705f524-274d-5aa6-87bf-a2fd18f7bb28'::uuid, 'physique-chimie', '2de', 'Intensité et tension dans un circuit complexe', 'Que traduit la loi des nœuds ?', 'mcq', '["La proportionnalité entre U et I","La conservation de l’énergie thermique","La conservation de la charge électrique","L’égalité des tensions en série"]'::jsonb, 2, 'Aucune charge ne s’accumule à un nœud : tout ce qui arrive repart.', 4),
    ('c1946014-d8af-5fe1-91a3-1b1d6f848d34'::uuid, 'physique-chimie', '2de', 'La loi d’Ohm et la résistance au courant électrique', 'Un conducteur ohmique de 100 Ω est traversé par 0,050 A. Quelle est la tension à ses bornes ?', 'mcq', '["0,50 V","2 000 V","5,0 V","50 V"]'::jsonb, 2, 'U = R × I = 100 × 0,050 = 5,0 V.', 1),
    ('5a66abc6-52d5-5a52-8283-5d8c44059eaf'::uuid, 'physique-chimie', '2de', 'La loi d’Ohm et la résistance au courant électrique', 'Comment varie la résistance d’un fil quand sa section augmente ?', 'mcq', '["Elle diminue","Elle augmente","Elle ne change pas","Elle double toujours"]'::jsonb, 0, 'Un fil plus épais laisse passer le courant plus facilement : sa résistance diminue.', 2),
    ('0715ad55-d31e-57c3-ad68-bce03177cfba'::uuid, 'physique-chimie', '2de', 'La loi d’Ohm et la résistance au courant électrique', 'Comment mesure-t-on une résistance à l’ohmmètre ?', 'mcq', '["On ne peut pas la mesurer","En série, circuit alimenté","En dérivation, circuit alimenté","Directement, hors circuit"]'::jsonb, 3, 'L’ohmmètre mesure la résistance d’un dipôle isolé, hors circuit.', 3),
    ('d6294afa-f044-5d5b-a3b0-91a3b3d07261'::uuid, 'physique-chimie', '2de', 'La loi d’Ohm et la résistance au courant électrique', 'Un radiateur de 1 kW fonctionne 2 h. Quelle énergie consomme-t-il ?', 'mcq', '["0,5 kWh","2 kWh","2 000 kWh","1 kWh"]'::jsonb, 1, 'E = P × Δt = 1 kW × 2 h = 2 kWh, soit 7,2 × 10⁶ J.', 4),
    ('d375ab45-8b84-5737-a7bd-9318193ebeda'::uuid, 'physique-chimie', '2de', 'Propagation et décomposition de la lumière', 'Parmi ces objets, lequel est un objet diffusant, et non une source primaire ?', 'mcq', '["Le Soleil","La Lune","Une flamme","Un écran allumé"]'::jsonb, 1, 'La Lune ne produit pas de lumière : elle renvoie celle du Soleil dans toutes les directions.', 1),
    ('f5ee6678-8137-5d9c-900b-cab4a62ed71f'::uuid, 'physique-chimie', '2de', 'Propagation et décomposition de la lumière', 'Combien de temps la lumière du Soleil met-elle à nous parvenir ?', 'mcq', '["Environ 8 heures","Instantanément","Environ 8 secondes","Environ 8 minutes"]'::jsonb, 3, 'Le Soleil que nous voyons est celui d’il y a environ huit minutes : voir loin, c’est voir tôt.', 2),
    ('8aeab9c5-6d53-5dce-89a5-0d73a9183bba'::uuid, 'physique-chimie', '2de', 'Propagation et décomposition de la lumière', 'Comment appelle-t-on les radiations de longueur d’onde supérieure à 800 nm ?', 'mcq', '["Les infrarouges","Les ultraviolets","Le visible","Les rayons X"]'::jsonb, 0, 'Au-delà du rouge (800 nm), ce sont les infrarouges ; en deçà du violet (400 nm), les ultraviolets.', 3),
    ('bb5b5408-f76c-53cc-a315-b30757e0755d'::uuid, 'physique-chimie', '2de', 'Propagation et décomposition de la lumière', 'Qu’a montré Newton en recombinant le spectre de la lumière blanche ?', 'mcq', '["Que la lumière est un son","Que le prisme colore la lumière","Que le blanc est une superposition de radiations","Que le blanc est une couleur simple"]'::jsonb, 2, 'En recombinant les couleurs, il a retrouvé du blanc : la lumière blanche est composite.', 4),
    ('1d5b2ee7-def7-5c68-81eb-594d088da6ad'::uuid, 'physique-chimie', '2de', 'Réflexion et réfraction de la lumière, le prisme', 'Dans un prisme, quelle radiation est la plus déviée ?', 'mcq', '["Le jaune","Le rouge","Le violet","Toutes sont déviées de la même façon"]'::jsonb, 2, 'L’indice dépend de la longueur d’onde : le violet est plus dévié que le rouge.', 1),
    ('97eda9c4-b29e-55e4-a905-1b9bf96ae74a'::uuid, 'physique-chimie', '2de', 'Réflexion et réfraction de la lumière, le prisme', 'Dans quel cas peut se produire une réflexion totale ?', 'mcq', '["Quand la lumière passe d’un milieu plus réfringent à un milieu moins réfringent","Quand la lumière passe de l’air à l’eau","Quand l’angle d’incidence est nul","Sur toute surface rugueuse"]'::jsonb, 0, 'En sortant d’un milieu plus réfringent, au-delà d’un angle limite, il n’y a plus de rayon réfracté.', 2),
    ('85f22143-7d14-5802-96ac-40d7a58fbe82'::uuid, 'physique-chimie', '2de', 'Réflexion et réfraction de la lumière, le prisme', 'Un rayon passe de l’air (n = 1,00) à l’eau (n = 1,33) avec i₁ = 30°. Que vaut environ i₂ ?', 'mcq', '["60°","30°","40°","22°"]'::jsonb, 3, 'sin i₂ = 1,00 × sin 30° / 1,33 ≈ 0,38, soit i₂ ≈ 22° : le rayon se rapproche de la normale.', 3),
    ('0f2b4d69-3bcc-577c-aec0-7964bbe61cd8'::uuid, 'physique-chimie', '2de', 'Réflexion et réfraction de la lumière, le prisme', 'Quel phénomène explique l’arc-en-ciel ?', 'mcq', '["La réflexion totale dans les nuages","La dispersion de la lumière dans des gouttes d’eau","La diffusion par l’air","L’absorption par la vapeur d’eau"]'::jsonb, 1, 'Comme un prisme, les gouttes d’eau séparent les radiations de la lumière blanche.', 4),
    ('d4c69f4b-b17f-59d2-9ca0-4b6eb056ae11'::uuid, 'physique-chimie', '2de', 'Les lentilles convergentes', 'Que devient un rayon incident passant par le foyer objet F ?', 'mcq', '["Il passe par F′","Il repart parallèle à l’axe optique","Il n’est pas dévié","Il revient en arrière"]'::jsonb, 1, 'C’est le troisième rayon particulier : par F, il ressort parallèle à l’axe.', 1),
    ('f1c660a0-8b85-5ca8-8d7c-fb64293b7b3d'::uuid, 'physique-chimie', '2de', 'Les lentilles convergentes', 'Quelle lentille corrige l’hypermétropie ?', 'mcq', '["Un prisme","Une lentille divergente","Un verre plan","Une lentille convergente"]'::jsonb, 3, 'Chez l’hypermétrope, l’image se forme en arrière de la rétine : une lentille convergente la ramène sur la rétine.', 2),
    ('f76d8eba-dcc7-530e-9a81-c2373b6367e5'::uuid, 'physique-chimie', '2de', 'Les lentilles convergentes', 'Qu’est-ce que l’accommodation ?', 'mcq', '["La déformation du cristallin qui garde l’image nette quand l’objet se rapproche","L’ouverture de la pupille dans le noir","Le fait de s’habituer à des lunettes","Le déplacement de la rétine"]'::jsonb, 0, 'Le cristallin se bombe pour augmenter sa vergence quand on regarde de près.', 3),
    ('8e4a5f2b-3274-54e0-a549-d5ffd3b6df16'::uuid, 'physique-chimie', '2de', 'Les lentilles convergentes', 'Quelle est la vergence d’une lentille de distance focale 50 cm ?', 'mcq', '["0,5 δ","50 δ","2 δ","0,02 δ"]'::jsonb, 2, 'C = 1 / f′ avec f′ en mètres : 1 / 0,50 = 2 δ.', 4),
    ('5a684f69-13f0-581b-8e98-942d9867b6e7'::uuid, 'physique-chimie', '2de', 'Construction de l’image d’un objet', 'Objet à OA = −20 cm d’une lentille de distance focale 10 cm. Où se forme l’image ?', 'mcq', '["À 20 cm du même côté que l’objet","À 10 cm de l’autre côté","À 20 cm de l’autre côté de la lentille","À l’infini"]'::jsonb, 2, '1/OA′ = 1/OF′ + 1/OA = 1/10 − 1/20 = 1/20, donc OA′ = 20 cm.', 1),
    ('3c8003a9-af3f-52d8-bcb4-5b67ba5f9aae'::uuid, 'physique-chimie', '2de', 'Construction de l’image d’un objet', 'Que signifie un grandissement γ = −1 ?', 'mcq', '["L’image est renversée et de même taille que l’objet","L’image est droite et de même taille","L’image est deux fois plus grande","Il n’y a pas d’image"]'::jsonb, 0, 'γ négatif : image renversée ; |γ| = 1 : même taille que l’objet.', 2),
    ('90d45f1b-9097-5fa0-b55a-0710d22cdc33'::uuid, 'physique-chimie', '2de', 'Construction de l’image d’un objet', 'Quelle différence pratique entre une image réelle et une image virtuelle ?', 'mcq', '["Il n’y en a aucune","L’image réelle est toujours plus grande","L’image virtuelle est toujours renversée","L’image réelle se projette sur un écran, l’image virtuelle se regarde à travers la lentille"]'::jsonb, 3, 'Une image réelle se projette, une image virtuelle se regarde, comme à travers une loupe.', 3),
    ('19d0c235-0f39-5596-b415-0199de257b8f'::uuid, 'physique-chimie', '2de', 'Construction de l’image d’un objet', 'Une fois B′ trouvé, où place-t-on A′ ?', 'mcq', '["Au foyer image F′","Sur l’axe optique, à la verticale de B′","Au centre optique O","Sur la lentille"]'::jsonb, 1, 'L’objet AB étant perpendiculaire à l’axe avec A sur l’axe, l’image A′B′ l’est aussi : A′ est sur l’axe, à l’aplomb de B′.', 4),
    ('685d9888-8979-564d-a3de-68143e683f0c'::uuid, 'ses', '2de', 'Les principes de base de l’économie', 'Quel agent économique a pour rôle principal de financer l’économie ?', 'mcq', '["Les ménages","Les administrations publiques","Les banques","Le reste du monde"]'::jsonb, 2, 'Les banques financent ; les ménages consomment et travaillent, les entreprises produisent, les administrations produisent des services non marchands et redistribuent.', 1),
    ('9235d2db-8a25-56ea-a9da-6b48ddd10867'::uuid, 'ses', '2de', 'Les principes de base de l’économie', 'Lequel de ces éléments est un flux réel du circuit économique ?', 'mcq', '["Un salaire versé","Le travail fourni par un salarié","Un impôt payé","Des intérêts versés"]'::jsonb, 1, 'Le travail est un flux réel ; le salaire qui le paie est le flux monétaire, qui circule en sens inverse.', 2),
    ('6931a02d-95dc-530b-804c-2ded4e91aec2'::uuid, 'ses', '2de', 'Les principes de base de l’économie', 'Que signifie l’idée que l’économie est un système ?', 'mcq', '["Chaque agent décide sans tenir compte des autres","Seul l’État organise les échanges","Les prix sont fixés à l’avance","La dépense de l’un est le revenu de l’autre"]'::jsonb, 3, 'Une économie n’est pas une addition de décisions isolées : quand un ménage achète du pain, sa dépense devient le revenu du boulanger.', 3),
    ('0f2a6998-8ba4-514a-8f54-2f4f8e9327a9'::uuid, 'ses', '2de', 'Les principes de base de l’économie', 'Comment appelle-t-on ce qu’un modèle économique suppose au départ ?', 'mcq', '["Ses conclusions","Ses hypothèses","Ses données","Ses prévisions"]'::jsonb, 1, 'Un modèle repose sur des hypothèses simplificatrices ; on le confronte ensuite aux données pour voir s’il éclaire la réalité.', 4),
    ('43f1d4bd-eee2-5a45-873a-93e536955e9c'::uuid, 'ses', '2de', 'Introduction à la sociologie', 'Que met Pierre Bourdieu au centre de son analyse ?', 'mcq', '["Le sens que chacun donne à son action","La contrainte du groupe sur le suicide","Les héritages culturels qui reproduisent les positions sociales","Le monopole de la violence légitime"]'::jsonb, 2, 'Bourdieu montre comment ce que la famille transmet — goûts, langage, rapport à l’école — contribue à reproduire les positions sociales.', 1),
    ('6da12ada-e587-53b9-a9e9-36ff99eb3136'::uuid, 'ses', '2de', 'Introduction à la sociologie', 'Quel est le principe du holisme ?', 'mcq', '["Expliquer par l’agrégation des actions individuelles","Expliquer par les seules motivations personnelles","Refuser toute explication statistique","Expliquer les comportements par le tout, la société"]'::jsonb, 3, 'Le holisme part de la société pour expliquer les individus ; l’individualisme méthodologique fait le chemin inverse.', 2),
    ('4754137c-411b-53e4-ac67-7d2396b20bab'::uuid, 'ses', '2de', 'Introduction à la sociologie', 'Que permet surtout une méthode quantitative ?', 'mcq', '["Comprendre en profondeur une logique d’action","Mesurer et comparer","Recueillir un récit de vie","Observer un groupe de l’intérieur"]'::jsonb, 1, 'Questionnaires et statistiques mesurent et comparent ; entretiens et observation servent plutôt à comprendre.', 3),
    ('76ac00a1-c7b4-57df-91fa-4e2248ce6e94'::uuid, 'ses', '2de', 'Introduction à la sociologie', 'L’observation participante est une méthode quantitative.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le sociologue partage la vie du groupe qu’il étudie pour comprendre ses logiques : c’est une méthode qualitative.', 4),
    ('f2f17157-36d0-5706-aede-d06af31a7862'::uuid, 'ses', '2de', 'Introduction aux sciences politiques', 'Sur quoi repose la domination charismatique ?', 'mcq', '["La coutume et l’hérédité","La règle écrite et le concours","Les qualités exceptionnelles prêtées à une personne","La richesse du chef"]'::jsonb, 2, 'On obéit au chef charismatique parce qu’il fascine : c’est sa personne, et non la tradition ou la loi, qui fonde son autorité.', 1),
    ('85f89063-291f-5194-a629-b26b42a7297d'::uuid, 'ses', '2de', 'Introduction aux sciences politiques', 'Quelle forme de domination légitime domine dans les États modernes ?', 'mcq', '["Traditionnelle","Charismatique","Religieuse","Légale-rationnelle"]'::jsonb, 3, 'Dans un État moderne, on obéit d’abord à des règles écrites et à des personnes désignées selon la loi.', 2),
    ('e74b137a-e58a-5720-84c7-72ef00c0d7fb'::uuid, 'ses', '2de', 'Introduction aux sciences politiques', 'Que signifie la souveraineté d’un État ?', 'mcq', '["Qu’il possède une armée","Qu’aucune autorité ne lui est supérieure","Qu’il est gouverné par un roi","Qu’il a une population nombreuse"]'::jsonb, 1, 'La souveraineté s’ajoute au territoire, à la population et à l’administration : l’État n’a pas d’autorité au-dessus de lui.', 3),
    ('0e79c70b-6291-5ca5-9250-a2468f3e72d7'::uuid, 'ses', '2de', 'Introduction aux sciences politiques', 'Lequel de ces facteurs est une « variable lourde » du vote ?', 'mcq', '["La météo le jour du scrutin","Le diplôme","Un débat télévisé","Un slogan de campagne"]'::jsonb, 1, 'Âge, diplôme, profession, territoire et religion pèsent durablement sur le vote ; la conjoncture de campagne vient s’y ajouter.', 4),
    ('469aa849-2116-5572-88d1-4a8689ddb348'::uuid, 'ses', '2de', 'Une diversité d’organisations productives', 'Qu’est-ce qui distingue une association d’une entreprise privée ?', 'mcq', '["Elle ne produit rien","Elle est financée uniquement par l’impôt","Elle ne redistribue pas de bénéfices : elle sert un projet","Elle ne peut pas employer de salariés"]'::jsonb, 2, 'Une association produit des biens et services, mais sans redistribuer de bénéfices à ses membres : son but est un projet, pas le profit.', 1),
    ('e4eedd89-2458-5885-bedd-61415e855a41'::uuid, 'ses', '2de', 'Une diversité d’organisations productives', 'À quel secteur appartiennent l’industrie et la construction ?', 'mcq', '["Au secteur primaire","Au secteur secondaire","Au secteur tertiaire","À l’économie sociale et solidaire"]'::jsonb, 1, 'Le primaire regroupe l’agriculture et les mines, le secondaire l’industrie et la construction, le tertiaire les services.', 2),
    ('6584c68b-6412-55dd-bc38-098c77806317'::uuid, 'ses', '2de', 'Une diversité d’organisations productives', 'Quelles entreprises concentrent l’essentiel du chiffre d’affaires en France ?', 'mcq', '["Les microentreprises","Les coopératives","Les associations","Les grandes entreprises"]'::jsonb, 3, 'Les très petites entreprises sont les plus nombreuses, mais ce sont les grandes qui réalisent l’essentiel des ventes.', 3),
    ('bcb6434e-feb6-5447-b9e1-65a8a3679a71'::uuid, 'ses', '2de', 'Une diversité d’organisations productives', 'Quel poids l’économie sociale et solidaire représente-t-elle en France ?', 'mcq', '["La moitié des emplois privés","Moins d’un salarié sur mille","Environ un salarié privé sur dix","Les trois quarts des entreprises"]'::jsonb, 2, 'Coopératives, mutuelles, associations et fondations emploient environ un salarié du privé sur dix.', 4),
    ('b1c0af45-fa37-5678-90ef-00f714f21fc9'::uuid, 'ses', '2de', 'Les différents facteurs de production', 'Comment mesure-t-on la quantité de travail utilisée ?', 'mcq', '["Par le montant des salaires","Par le chiffre d’affaires","Par le nombre d’actifs occupés ou d’heures travaillées","Par le nombre de machines"]'::jsonb, 2, 'On compte les personnes qui travaillent ou, plus finement, les heures qu’elles effectuent.', 1),
    ('8a15895e-f890-5546-be5f-5bddc1e27d23'::uuid, 'ses', '2de', 'Les différents facteurs de production', 'Pourquoi le capital fixe fait-il l’objet d’un amortissement ?', 'mcq', '["Parce qu’il est gratuit","Parce qu’il s’use au fil des années","Parce qu’il est détruit en une seule production","Parce qu’il appartient à l’État"]'::jsonb, 1, 'Une machine sert plusieurs années mais perd de la valeur en s’usant : l’amortissement mesure cette usure.', 2),
    ('374dbb80-72ba-57bf-9fe9-1de3abc8b984'::uuid, 'ses', '2de', 'Les différents facteurs de production', 'Que signifie que deux facteurs de production sont complémentaires ?', 'mcq', '["L’un peut remplacer l’autre","Ils coûtent le même prix","L’un rend l’autre inutile","Ils doivent être utilisés ensemble"]'::jsonb, 3, 'Un camion sans chauffeur ne produit rien : quand les facteurs sont complémentaires, il faut les deux à la fois.', 3),
    ('02560071-eff8-5764-859d-d9d44addf335'::uuid, 'ses', '2de', 'Les différents facteurs de production', 'De quoi dépend le choix d’une combinaison productive ?', 'mcq', '["Du coût relatif des facteurs, de la technologie disponible et de la nature du produit","Uniquement du nombre de salariés disponibles","Uniquement des goûts du chef d’entreprise","Du prix de vente fixé par l’État"]'::jsonb, 0, 'Si le travail devient cher par rapport aux machines, l’entreprise a intérêt à une combinaison plus intensive en capital.', 4),
    ('fda9ffb2-e627-5d7a-9d19-36f58e387ab0'::uuid, 'ses', '2de', 'La mesure des richesses produites : l’exemple d’une entreprise', 'Qu’est-ce que le chiffre d’affaires ?', 'mcq', '["Le bénéfice de l’entreprise","Le total des ventes","La valeur ajoutée","La somme des salaires"]'::jsonb, 1, 'Le chiffre d’affaires additionne toutes les ventes ; il inclut ce que l’entreprise a acheté à d’autres, d’où la nécessité de la valeur ajoutée.', 1),
    ('f6252d78-c29a-56e5-a114-b14eaebebfb8'::uuid, 'ses', '2de', 'La mesure des richesses produites : l’exemple d’une entreprise', 'Pour une boulangerie, lequel de ces éléments est une consommation intermédiaire ?', 'mcq', '["Le four","La farine","Le salaire du boulanger","Le bâtiment"]'::jsonb, 1, 'La farine est transformée en pain au cours de la production ; le four et le bâtiment, utilisés plusieurs années, sont du capital fixe.', 2),
    ('de9114a5-74b6-5a81-baed-7e27d28c2b67'::uuid, 'ses', '2de', 'La mesure des richesses produites : l’exemple d’une entreprise', 'Dans le partage de la valeur ajoutée, que reçoivent les prêteurs ?', 'mcq', '["Des dividendes","Des salaires","Des intérêts","Des impôts"]'::jsonb, 2, 'Les prêteurs touchent des intérêts, les propriétaires des dividendes, les salariés des salaires et cotisations, l’État des impôts.', 3),
    ('0e56e1bd-c941-5996-9d53-d97ebc3c86ab'::uuid, 'ses', '2de', 'La mesure des richesses produites : l’exemple d’une entreprise', 'Que donne la somme des valeurs ajoutées de toutes les unités productives d’un pays ?', 'mcq', '["Le chiffre d’affaires national","Le montant de la TVA","L’autofinancement","L’essentiel du PIB"]'::jsonb, 3, 'Additionner les valeurs ajoutées évite de compter plusieurs fois la même farine : c’est la base du calcul du PIB.', 4),
    ('05f47b19-7969-50b5-bafb-2de8ae9c8694'::uuid, 'ses', '2de', 'Le PIB : une mesure des richesses d’un pays', 'Les prix augmentent de 3 % et la production reste la même. Que se passe-t-il ?', 'mcq', '["Le PIB en volume augmente de 3 %","Les deux PIB baissent","Le PIB en valeur augmente d’environ 3 %, le PIB en volume stagne","Rien ne change"]'::jsonb, 2, 'Le PIB en valeur est calculé aux prix courants et gonfle avec l’inflation ; le PIB en volume la neutralise.', 1),
    ('9045de07-1a04-5352-9e50-c30bee826061'::uuid, 'ses', '2de', 'Le PIB : une mesure des richesses d’un pays', 'Que mesure l’indice de Gini ?', 'mcq', '["La santé et l’éducation","Les inégalités","La pression sur la biosphère","La croissance"]'::jsonb, 1, 'L’indice de Gini mesure les inégalités de répartition, ce que le PIB par habitant, simple moyenne, ne montre pas.', 2),
    ('ea675182-5e27-5103-a6f1-4b90f12d8984'::uuid, 'ses', '2de', 'Le PIB : une mesure des richesses d’un pays', 'Qu’ajoute-t-on à la somme des valeurs ajoutées pour obtenir le PIB ?', 'mcq', '["Les salaires et les profits","Les exportations","Les consommations intermédiaires","La TVA et les droits de douane"]'::jsonb, 3, 'Le PIB est la somme des valeurs ajoutées des unités résidentes, plus la TVA et les droits de douane.', 3),
    ('76d792a0-f086-544d-91b3-c9115cc53b38'::uuid, 'ses', '2de', 'Le PIB : une mesure des richesses d’un pays', 'Le PIB déduit la dégradation de l’environnement causée par la production.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La dégradation de l’environnement et l’épuisement des ressources ne sont pas déduits : le PIB compte ce qui est produit, pas ce qui est détruit.', 4),
    ('2100eb65-3e04-52d4-8716-c66481e3ae70'::uuid, 'ses', '2de', 'La croissance économique : un phénomène récent, inégal et irrégulier', 'Qu’est-ce que l’expansion ?', 'mcq', '["Une hausse durable de la production","Un recul du PIB","Une hausse de la production de courte durée","L’amélioration des conditions de vie"]'::jsonb, 2, 'L’expansion est passagère ; la croissance, elle, est une augmentation durable de la production.', 1),
    ('ac4ca6f0-d0d5-5810-94ae-1d9f6fc35cdc'::uuid, 'ses', '2de', 'La croissance économique : un phénomène récent, inégal et irrégulier', 'À quel rythme annuel moyen la France a-t-elle crû pendant les Trente Glorieuses ?', 'mcq', '["Environ 1 %","Environ 5 %","Environ 10 %","Environ 20 %"]'::jsonb, 1, 'Environ 5 % par an entre 1945 et 1975 ; depuis, la croissance des pays anciennement industrialisés est nettement plus faible.', 2),
    ('1a0cb0b6-4949-5c88-8fe3-bb4c82ceac02'::uuid, 'ses', '2de', 'La croissance économique : un phénomène récent, inégal et irrégulier', 'Dans quel pays la révolution industrielle démarre-t-elle, à la fin du XVIIIe siècle ?', 'mcq', '["La France","L’Allemagne","Les États-Unis","L’Angleterre"]'::jsonb, 3, 'L’Angleterre lance la révolution industrielle ; l’Europe et l’Amérique du Nord suivent au XIXe siècle.', 3),
    ('b46fab74-27b8-5348-a191-fba50a737094'::uuid, 'ses', '2de', 'La croissance économique : un phénomène récent, inégal et irrégulier', 'Qu’est-ce qu’une dépression ?', 'mcq', '["Un recul durable et profond de la production, comme après 1929","Un simple ralentissement de la croissance","Deux trimestres de croissance faible","Une baisse passagère des prix"]'::jsonb, 0, 'La dépression est plus grave qu’une récession : le recul de la production dure et s’approfondit.', 4),
    ('0831cb8c-8333-5fe9-a9c4-d8d57e16c1e0'::uuid, 'ses', '2de', 'Les limites écologiques de la croissance économique', 'Laquelle de ces ressources est non renouvelable ?', 'mcq', '["Les forêts","L’eau douce","Les métaux","Les poissons"]'::jsonb, 2, 'Les métaux, comme le pétrole et le gaz, existent en stock limité ; les forêts, l’eau ou les poissons se renouvellent, mais peuvent être surexploités.', 1),
    ('3838b0be-b5d3-5ac8-9552-b8807fe70803'::uuid, 'ses', '2de', 'Les limites écologiques de la croissance économique', 'En quelle année le développement durable a-t-il été défini ?', 'mcq', '["1972","1987","2008","2015"]'::jsonb, 1, 'Il est défini en 1987 ; 1972 est l’année du rapport Meadows sur les limites de la croissance.', 2),
    ('420ebe4c-7d48-5535-aa10-296f4ea09632'::uuid, 'ses', '2de', 'Les limites écologiques de la croissance économique', 'Que conteste la position de la décroissance ?', 'mcq', '["L’existence du réchauffement climatique","L’utilité des normes","La possibilité d’un découplage suffisant entre production et pression environnementale","Le principe pollueur-payeur"]'::jsonb, 2, 'Là où la croissance verte parie sur le progrès technique pour découpler, la décroissance juge ce découplage insuffisant.', 3),
    ('243c0f5c-979d-5da6-a537-705dd2da464a'::uuid, 'ses', '2de', 'Les limites écologiques de la croissance économique', 'Quel instrument cherche à rendre les solutions propres plus compétitives ?', 'mcq', '["Les quotas d’émission","Les interdictions","La taxe carbone","Les subventions aux alternatives"]'::jsonb, 3, 'Subventionner les alternatives en abaisse le coût ; la taxe, à l’inverse, renchérit le comportement polluant.', 4),
    ('e20730be-741e-54fb-adbc-2c35e3aee254'::uuid, 'ses', '2de', 'Les différents types de marchés et d’échanges marchands', 'Que s’échange-t-il sur le marché des changes ?', 'mcq', '["Des actions et des obligations","Les monnaies entre elles","Du pétrole et du blé","La force de travail"]'::jsonb, 1, 'Le marché des changes fixe le prix d’une monnaie dans une autre, par exemple l’euro en dollars.', 1),
    ('9bc68770-8517-51a3-8df3-991c4d4618d2'::uuid, 'ses', '2de', 'Les différents types de marchés et d’échanges marchands', 'Comment appelle-t-on un marché où il n’y a qu’un seul offreur ?', 'mcq', '["Un oligopole","La concurrence parfaite","La concurrence monopolistique","Un monopole"]'::jsonb, 3, 'Monopole : un seul offreur ; oligopole : quelques-uns ; concurrence monopolistique : nombreux, avec des produits différenciés.', 2),
    ('1a82cd58-21b6-5159-8cb5-96f0d342eff7'::uuid, 'ses', '2de', 'Les différents types de marchés et d’échanges marchands', 'Une plateforme de covoiturage en ligne crée un marché…', 'mcq', '["Physique","Financier","Dématérialisé","Des matières premières"]'::jsonb, 2, 'Offreurs et demandeurs s’y rencontrent sans lieu commun : c’est un marché dématérialisé, qui n’existait pas avant la plateforme.', 3),
    ('6e1a32d1-4a23-590a-9b50-449d4cb3ca82'::uuid, 'ses', '2de', 'Les différents types de marchés et d’échanges marchands', 'Pourquoi une autorité de la concurrence peut-elle bloquer un rachat d’entreprise ?', 'mcq', '["Parce que la concentration réduirait trop la concurrence","Parce que tout rachat est interdit","Parce que l’entreprise achetée est étrangère","Parce que le prix du rachat est trop bas"]'::jsonb, 0, 'Les concentrations sont surveillées, comme les ententes et les abus de position dominante, pour préserver la concurrence.', 4),
    ('b5cc8d3a-1d08-59b1-946c-43f0714ff425'::uuid, 'ses', '2de', 'La loi de l’offre et de la demande et la fixation du prix d’équilibre', 'Pourquoi la courbe d’offre est-elle croissante ?', 'mcq', '["Parce que les consommateurs achètent plus quand le prix monte","Parce que produire devient plus rentable quand le prix monte","Parce que l’État l’impose","Parce que les coûts baissent toujours"]'::jsonb, 1, 'Un prix plus élevé rend la production plus rentable : les vendeurs veulent vendre davantage.', 1),
    ('fc983f48-9da8-5ee0-afb9-e57f56f8127b'::uuid, 'ses', '2de', 'La loi de l’offre et de la demande et la fixation du prix d’équilibre', 'Que se passe-t-il quand seul le prix du bien lui-même varie ?', 'mcq', '["La courbe de demande se déplace","La courbe d’offre se déplace","On se déplace le long de la courbe","Les deux courbes disparaissent"]'::jsonb, 2, 'Le prix fait bouger le point sur la courbe ; ce sont les autres changements (revenu, mode, coûts, taxe) qui déplacent la courbe.', 2),
    ('d2e91e3b-9e00-5113-926d-98e81ece6e08'::uuid, 'ses', '2de', 'La loi de l’offre et de la demande et la fixation du prix d’équilibre', 'Pourquoi dit-on du marché concurrentiel qu’il est autorégulateur ?', 'mcq', '["Parce que l’État fixe les prix","Parce que les entreprises s’entendent","Parce que les quantités ne changent jamais","Parce que les écarts entre offre et demande poussent le prix vers l’équilibre"]'::jsonb, 3, 'Invendus, le prix baisse ; pénurie, il monte : sans que personne ne le décide, le prix tend vers l’équilibre.', 3),
    ('e7a1ca5b-4af9-5757-b123-9315c662deab'::uuid, 'ses', '2de', 'La loi de l’offre et de la demande et la fixation du prix d’équilibre', 'Pourquoi une taxe sur le tabac rapporte-t-elle beaucoup à court terme ?', 'mcq', '["Parce que la demande de tabac est peu élastique au prix","Parce que la demande est très élastique","Parce que le tabac est un bien facilement remplaçable","Parce que les fumeurs achètent plus quand le prix monte"]'::jsonb, 0, 'Les fumeurs achètent presque autant malgré la hausse : la consommation baisse peu et la recette de la taxe reste élevée.', 4),
    ('811e8c01-2dfc-5acd-8f5b-53de323b4d77'::uuid, 'ses', '2de', 'L’intervention publique permet de remédier aux effets indésirables du marché sur l’environnement', 'Quand une externalité négative n’est pas payée, que devient la quantité produite ?', 'mcq', '["Trop faible","Exactement optimale","Trop élevée","Nulle"]'::jsonb, 2, 'Le prix, trop bas car il ignore la pollution, pousse à produire et consommer davantage que ce qui serait collectivement souhaitable.', 1),
    ('c9654247-40c9-5275-943a-c6b4bd89de55'::uuid, 'ses', '2de', 'L’intervention publique permet de remédier aux effets indésirables du marché sur l’environnement', 'Quelle est la faiblesse d’un marché de quotas d’émission ?', 'mcq', '["Il faut un prix suffisant et une allocation initiale équitable des droits","Il ne fixe aucun plafond d’émissions","Il ne rapporte jamais rien","Il interdit toute production"]'::jsonb, 0, 'Le plafond est garanti, mais si les quotas sont trop nombreux ou distribués gratuitement sans discernement, leur prix reste trop bas pour inciter.', 2),
    ('ee39b267-b2e4-5ce9-91f7-6c0696b1f1fb'::uuid, 'ses', '2de', 'L’intervention publique permet de remédier aux effets indésirables du marché sur l’environnement', 'Comment rendre une taxe environnementale plus acceptable ?', 'mcq', '["En la rendant secrète","En compensant les ménages modestes et en montrant à quoi servent les recettes","En la doublant chaque année","En supprimant les alternatives"]'::jsonb, 1, 'Compensations, alternatives disponibles et affectation visible des recettes sont les trois leviers d’acceptabilité.', 3),
    ('f8a2902a-1e5f-59f0-ac59-f6a3508caa74'::uuid, 'ses', '2de', 'L’intervention publique permet de remédier aux effets indésirables du marché sur l’environnement', 'Les zones à faibles émissions relèvent de quel instrument ?', 'mcq', '["La taxation","Le marché de quotas","La subvention","La réglementation"]'::jsonb, 3, 'Elles interdisent l’accès de certains véhicules : réglementer, c’est interdire ou plafonner.', 4),
    ('3f91b63a-7e72-55a2-ba8c-fe0b49aaa2dc'::uuid, 'ses', '2de', 'Qu’est-ce que la socialisation ?', 'Quelle instance de socialisation a son moment fort à l’adolescence ?', 'mcq', '["La famille","Le travail","Les groupes de pairs","Les partis politiques"]'::jsonb, 2, 'Les amis du même âge pèsent surtout à l’adolescence ; la famille domine dans l’enfance, le travail à l’âge adulte.', 1),
    ('96f8157e-eae2-573f-ae94-526bee5d0ea5'::uuid, 'ses', '2de', 'Qu’est-ce que la socialisation ?', 'En quoi consiste l’inculcation explicite ?', 'mcq', '["Imiter sans s’en rendre compte","Énoncer la règle, récompenser, sanctionner","Regarder la télévision","Choisir librement ses normes"]'::jsonb, 1, 'L’inculcation explicite passe par des consignes et des sanctions, à l’inverse de l’imprégnation qui agit par imitation.', 2),
    ('66c66677-8bda-573f-baf2-f827c701d3fe'::uuid, 'ses', '2de', 'Qu’est-ce que la socialisation ?', 'Pourquoi une norme intériorisée n’est-elle plus ressentie comme une contrainte ?', 'mcq', '["Parce qu’elle a été abolie","Parce qu’elle n’est plus sanctionnée","Parce qu’elle ne concerne que les enfants","Parce qu’elle est devenue une manière naturelle d’agir"]'::jsonb, 3, 'On ne se force pas à dire bonjour, on le fait : la règle est devenue une partie de soi.', 3),
    ('5c211d30-b6c7-53ba-8e78-eea5be44d839'::uuid, 'ses', '2de', 'Qu’est-ce que la socialisation ?', 'Que façonne surtout la socialisation primaire ?', 'mcq', '["La langue, les manières, les goûts et les repères moraux","Les compétences professionnelles","L’engagement dans un parti","Les habitudes de couple"]'::jsonb, 0, 'Dans l’enfance se fixent les apprentissages les plus profonds ; le travail, le couple ou les partis relèvent de la socialisation secondaire.', 4),
    ('4de026f9-d986-5a5c-9343-6e63554cc43b'::uuid, 'ses', '2de', 'La socialisation et la construction d’une identité sociale', 'Qu’est-ce qu’un groupe d’appartenance ?', 'mcq', '["Le groupe que l’on rêve de rejoindre","Un groupe imposé par la loi","Le groupe auquel on appartient effectivement","Le groupe de ses anciens camarades"]'::jsonb, 2, 'Il se distingue du groupe de référence, auquel on aspire et dont on imite les manières.', 1),
    ('89554dd5-8a78-54a7-8818-829ca8098b7e'::uuid, 'ses', '2de', 'La socialisation et la construction d’une identité sociale', 'Comment l’identité sociale se construit-elle ?', 'mcq', '["Elle est donnée à la naissance et ne change pas","Dans l’interaction, à travers le regard des autres","Uniquement par choix personnel","Uniquement par la loi"]'::jsonb, 1, 'L’identité n’est ni figée ni entièrement choisie : on se définit aussi par la façon dont les autres nous voient.', 2),
    ('f8b56bdf-57bf-50e5-a6e8-24852a986297'::uuid, 'ses', '2de', 'La socialisation et la construction d’une identité sociale', 'Lequel de ces exemples illustre une resocialisation ?', 'mcq', '["Apprendre à lire","Changer de coupe de cheveux","Passer en classe supérieure","Entrer à l’armée"]'::jsonb, 3, 'L’armée, une conversion, une immigration ou un changement radical de milieu transforment en profondeur les normes et les rôles intériorisés.', 3),
    ('cae91448-4758-5878-abad-cd9d480f4d1e'::uuid, 'ses', '2de', 'La socialisation et la construction d’une identité sociale', 'Que produisent des appartenances qui se renforcent ?', 'mcq', '["Une identité cohérente","Un conflit de rôles","Une resocialisation","Un déclassement"]'::jsonb, 0, 'Quand les appartenances vont dans le même sens, l’identité est cohérente ; quand elles s’opposent, naît un conflit de rôles.', 4),
    ('26106221-5244-5dc7-a7ea-c1ab075ccae6'::uuid, 'ses', '2de', 'La socialisation en fonction du genre et du milieu social', 'Dans quelle filière les filles restent-elles très minoritaires ?', 'mcq', '["Les filières littéraires","Les filières de santé","Les langues","L’informatique"]'::jsonb, 3, 'Les filles sont majoritaires en lettres et en santé, très minoritaires en informatique : un effet de la socialisation différenciée.', 1),
    ('26289933-36c3-5d3d-80fb-176ff620ca5f'::uuid, 'ses', '2de', 'La socialisation en fonction du genre et du milieu social', 'Quel exemple illustre la socialisation de genre dès la petite enfance ?', 'mcq', '["Le choix du prénom selon l’état civil","Une tolérance différente aux pleurs ou à l’agitation selon le sexe de l’enfant","La vaccination obligatoire","L’âge d’entrée à l’école"]'::jsonb, 1, 'Couleurs, jouets, vocabulaire, mais aussi tolérance à l’émotion ou à l’agitation : la différenciation commence dès la naissance.', 2),
    ('d93477b7-ebcd-5b7a-bb70-62e29888c26a'::uuid, 'ses', '2de', 'La socialisation en fonction du genre et du milieu social', 'Quelles familles transmettent le plus souvent une familiarité avec la culture scolaire ?', 'mcq', '["Les familles de cadres","Les familles d’agriculteurs","Les familles nombreuses","Les familles urbaines"]'::jsonb, 0, 'Ce capital culturel avantage leurs enfants à l’école sans qu’aucune règle ne le prévoie.', 3),
    ('9ce0f9cc-a414-58c7-860c-30144210e4aa'::uuid, 'ses', '2de', 'La socialisation en fonction du genre et du milieu social', 'Quel effet la socialisation selon le milieu produit-elle sur les aspirations ?', 'mcq', '["Elle les rend identiques pour tous","Elle les supprime","Des horizons professionnels perçus comme plus ou moins accessibles","Elle ne joue que sur les loisirs"]'::jsonb, 2, 'Selon le milieu, certains métiers paraissent « pour soi » ou « pas pour soi » : les aspirations elles-mêmes sont socialement différenciées.', 4),
    ('df70fc0d-54b9-567d-a45c-532b76ca0443'::uuid, 'ses', '2de', 'Le système politique démocratique', 'Lequel de ces dispositifs relève de la démocratie directe ?', 'mcq', '["L’élection des députés","Le vote d’une loi par le Parlement","Le référendum","La nomination des ministres"]'::jsonb, 2, 'Dans un référendum, les citoyens décident eux-mêmes ; dans la démocratie représentative, ce sont leurs élus.', 1),
    ('607b3500-c900-5e6f-85e9-f668bb208473'::uuid, 'ses', '2de', 'Le système politique démocratique', 'Qu’est-ce qu’un régime hybride ?', 'mcq', '["Une démocratie sans élections","Un régime qui garde les élections en vidant les libertés","Un régime mêlant monarchie et république","Un État fédéral"]'::jsonb, 1, 'L’affaiblissement des contre-pouvoirs — justice, presse, Parlement — est le signal de ces régimes.', 2),
    ('b5152fbf-5614-5881-94c7-d95c50068421'::uuid, 'ses', '2de', 'Le système politique démocratique', 'Quel critère démocratique signifie que la majorité ne peut pas tout ?', 'mcq', '["Le suffrage universel","La souveraineté du peuple","La séparation des pouvoirs","Le respect des minorités"]'::jsonb, 3, 'Même élue, une majorité doit respecter les droits de ceux qui ne l’ont pas choisie.', 3),
    ('779e5e6b-fc39-5689-8f4b-a3c10543b3ee'::uuid, 'ses', '2de', 'Le système politique démocratique', 'Qu’empêche une justice indépendante ?', 'mcq', '["L’impunité","Le secret","La décision solitaire","L’abstention"]'::jsonb, 0, 'Chaque contre-pouvoir empêche un abus : la justice l’impunité, la presse le secret, le Parlement la décision solitaire.', 4),
    ('99fe3871-69ec-5d69-8916-19705b66f8a5'::uuid, 'ses', '2de', 'L’organisation des pouvoirs au sein de la Ve République', 'Pour combien de temps les sénateurs sont-ils élus ?', 'mcq', '["Quatre ans","Cinq ans","Six ans","Sept ans"]'::jsonb, 2, 'Les 348 sénateurs sont élus pour six ans au suffrage indirect ; les 577 députés pour cinq ans.', 1),
    ('e9cfd143-17aa-5225-95e4-128445fe1ba5'::uuid, 'ses', '2de', 'L’organisation des pouvoirs au sein de la Ve République', 'Depuis quand le mandat présidentiel dure-t-il cinq ans ?', 'mcq', '["Depuis 1958","Depuis la réforme du quinquennat de 2000","Depuis 1962","Depuis 2008"]'::jsonb, 1, 'Le quinquennat, adopté en 2000, a remplacé le septennat ; 1962 est la date de l’élection au suffrage universel direct.', 2),
    ('cb3ae007-1363-502f-a796-6ecb72c38518'::uuid, 'ses', '2de', 'L’organisation des pouvoirs au sein de la Ve République', 'Lequel de ces pouvoirs appartient au président de la République ?', 'mcq', '["Voter le budget","Contrôler la constitutionnalité des lois","Renverser le gouvernement","Dissoudre l’Assemblée nationale"]'::jsonb, 3, 'Le président peut dissoudre l’Assemblée ; c’est elle, à l’inverse, qui peut renverser le gouvernement.', 3),
    ('90e8d70c-0338-5f81-a87f-e3673788ed45'::uuid, 'ses', '2de', 'L’organisation des pouvoirs au sein de la Ve République', 'En cas de désaccord persistant entre les deux chambres, qui a le dernier mot ?', 'mcq', '["L’Assemblée nationale","Le Sénat","Le Conseil constitutionnel","Le président de la République"]'::jsonb, 0, 'Le Parlement vote la loi à deux chambres, mais l’Assemblée, élue au suffrage direct, peut trancher en dernier ressort.', 4),
    ('03b269c2-6446-52bb-9bde-946faa72f86d'::uuid, 'ses', '2de', 'L’importance du mode de scrutin dans la désignation des représentants', 'Quel est le principal inconvénient du scrutin majoritaire ?', 'mcq', '["Il rend les majorités instables","Beaucoup de voix ne sont pas représentées et les petits partis sont écrasés","Il oblige à former des coalitions","Il supprime le lien entre l’élu et sa circonscription"]'::jsonb, 1, 'Le majoritaire fabrique des gouvernements stables, au prix d’une représentation déformée des opinions.', 1),
    ('8901641a-dc69-57de-a015-3832fd3959bd'::uuid, 'ses', '2de', 'L’importance du mode de scrutin dans la désignation des représentants', 'Quel est le principal inconvénient du scrutin proportionnel ?', 'mcq', '["Il écrase les petits partis","Il déforme la diversité des opinions","Il est difficile d’y dégager une majorité, d’où coalitions et instabilité","Il interdit les listes"]'::jsonb, 2, 'Le proportionnel reflète fidèlement les opinions, mais une assemblée très divisée peine à former une majorité.', 2),
    ('17140e92-f362-5721-be2e-3d174375311d'::uuid, 'ses', '2de', 'L’importance du mode de scrutin dans la désignation des représentants', 'Comment se combinent les règles aux élections municipales et régionales françaises ?', 'mcq', '["Proportionnelle intégrale","Scrutin uninominal à un tour","Tirage au sort","Une prime majoritaire et une répartition proportionnelle"]'::jsonb, 3, 'La liste arrivée en tête reçoit une prime de sièges, le reste est réparti à la proportionnelle : un système mixte.', 3),
    ('34693ab6-54e4-5f22-82d4-69d26a1152e1'::uuid, 'ses', '2de', 'L’importance du mode de scrutin dans la désignation des représentants', 'Dans un scrutin de liste, qu’est-ce qui décide qui est réellement élu ?', 'mcq', '["L’ordre des candidats sur la liste","L’âge des candidats","Le tirage au sort","Le nombre de réunions publiques"]'::jsonb, 0, 'Les premiers de liste sont élus en priorité : cet ordre pèse autant que le mode de scrutin lui-même.', 4),
    ('23312dda-6f67-5687-bb44-6e86ecc66663'::uuid, 'ses', '2de', 'Les différents acteurs de la vie politique démocratique', 'Quel groupe d’intérêt défend une profession réglementée ?', 'mcq', '["Une ONG","Un ordre professionnel","Un parti politique","Un institut de sondage"]'::jsonb, 1, 'Les ordres, comme celui des médecins ou des avocats, défendent une profession réglementée ; syndicats et organisations patronales défendent des intérêts professionnels.', 1),
    ('e8400a8f-8f17-5d4c-b0db-7e8bc8eb3c93'::uuid, 'ses', '2de', 'Les différents acteurs de la vie politique démocratique', 'Quel est le rôle des médias dans la vie politique ?', 'mcq', '["Voter les lois","Sélectionner les candidats","Financer les partis","Informer, hiérarchiser l’information et donner la parole"]'::jsonb, 3, 'Les réseaux sociais transforment ce rôle : diffusion accélérée, bulles de filtre, concurrence des sources.', 2),
    ('2de81241-165d-51c9-ae80-e441aeb32334'::uuid, 'ses', '2de', 'Les différents acteurs de la vie politique démocratique', 'Quelle forme de participation politique est la plus durable ?', 'mcq', '["Signer une pétition","Voter","Adhérer à un parti et militer","Boycotter un produit"]'::jsonb, 2, 'Le vote est ponctuel, la pétition ciblée ; le militantisme engage sur la durée.', 3),
    ('a85ce4d2-aece-5010-89c8-6f7f1da302dc'::uuid, 'ses', '2de', 'Les différents acteurs de la vie politique démocratique', 'Quelle place les sondages tiennent-ils dans le débat public ?', 'mcq', '["Ils le nourrissent sans le décider","Ils remplacent les élections","Ils sont interdits en France","Ils fixent le programme des partis"]'::jsonb, 0, 'Les sondages éclairent l’opinion à un moment donné, mais ce sont les électeurs qui décident.', 4),
    ('12308a2e-4398-57c5-818b-e4023538ee7a'::uuid, 'ses', '2de', 'Un emploi qualifié suppose un investissement en capital humain', 'Lequel de ces éléments est un coût direct des études ?', 'mcq', '["Le salaire non perçu","Le temps libre perdu","Les frais de logement étudiant","Le risque de chômage"]'::jsonb, 2, 'Frais de scolarité, logement et matériel sont des coûts directs ; les salaires non perçus sont un coût indirect, le coût d’opportunité.', 1),
    ('477c2303-1aac-5cea-a2bd-2af4747d674b'::uuid, 'ses', '2de', 'Un emploi qualifié suppose un investissement en capital humain', 'Qu’est-ce que la qualification ?', 'mcq', '["Le poste occupé","Les savoirs et savoir-faire reconnus par un diplôme ou une convention collective","Le nombre d’années d’ancienneté","Le salaire obtenu"]'::jsonb, 1, 'La qualification appartient à la personne ; on peut occuper un poste qui en demande moins, c’est le déclassement.', 2),
    ('6dae6d91-e7e8-5273-bead-f5210e0bf992'::uuid, 'ses', '2de', 'Un emploi qualifié suppose un investissement en capital humain', 'Selon la théorie du capital humain, pourquoi un diplômé est-il mieux payé ?', 'mcq', '["Parce que son diplôme est rare","Parce qu’il négocie mieux","Parce que l’État l’impose","Parce que sa formation l’a réellement rendu plus productif"]'::jsonb, 3, 'C’est la différence avec la théorie du signal, pour laquelle le diplôme renseigne surtout l’employeur sur des qualités cachées.', 3),
    ('8b68c1b9-8206-5d36-b5af-8fc1cf1b94f7'::uuid, 'ses', '2de', 'Un emploi qualifié suppose un investissement en capital humain', 'Selon la théorie du signal, quelle qualité le diplôme révèle-t-il à l’employeur ?', 'mcq', '["La persévérance et la capacité d’apprentissage","La taille du réseau familial","Le lieu de résidence","L’âge du candidat"]'::jsonb, 0, 'Ces qualités sont difficiles à observer lors d’un entretien : le diplôme sert d’indice. Dans la réalité, les deux mécanismes coexistent.', 4),
    ('4e34c136-59ef-5f09-908d-4aaf9927d82c'::uuid, 'ses', '2de', 'Le manque de qualifications : une des causes du chômage', 'Qu’est-ce que la population active ?', 'mcq', '["Les seuls salariés","Toute la population en âge de travailler","Les actifs occupés plus les chômeurs","Les personnes inscrites à France Travail"]'::jsonb, 2, 'Un chômeur fait partie de la population active : il n’a pas d’emploi, mais il en cherche un et il est disponible.', 1),
    ('3f054cc5-dae7-5c2f-9807-efcb3cbe8a4c'::uuid, 'ses', '2de', 'Le manque de qualifications : une des causes du chômage', 'Qu’est-ce que le chômage conjoncturel ?', 'mcq', '["Le chômage lié au temps de recherche entre deux emplois","Le chômage dû à une demande insuffisante en période de ralentissement","Le chômage lié au manque de qualification","Le chômage des saisonniers"]'::jsonb, 1, 'Il suit le cycle économique : quand l’activité ralentit, les entreprises embauchent moins.', 2),
    ('0277bf96-0225-5e1e-922c-0a07c3717b97'::uuid, 'ses', '2de', 'Le manque de qualifications : une des causes du chômage', 'Quelle politique vise d’abord le chômage conjoncturel ?', 'mcq', '["L’apprentissage","La formation continue","Les aides à la mobilité","Le soutien à la demande"]'::jsonb, 3, 'Formation et apprentissage traitent le chômage structurel ; relancer la demande répond à un chômage dû au ralentissement.', 3),
    ('5516905d-f0df-5827-b81b-cb9909b4d375'::uuid, 'ses', '2de', 'Le manque de qualifications : une des causes du chômage', 'Comment se manifeste l’inadéquation des qualifications ?', 'mcq', '["Des postes non pourvus coexistent avec des chômeurs","Tous les postes sont pourvus","Les salaires baissent partout","Le chômage disparaît dans les métiers qualifiés comme non qualifiés"]'::jsonb, 0, 'Les emplois offerts demandent des qualifications que les chômeurs n’ont pas : offre et demande de travail ne se rencontrent pas.', 4),
    ('5ee78599-0ccb-5757-87fe-995fef65c352'::uuid, 'ses', '2de', 'L’influence du diplôme et de l’expérience sur le niveau de salaire', 'Comment évolue l’écart de salaire entre diplômés et non-diplômés au fil de la carrière ?', 'mcq', '["Il disparaît","Il reste identique","Il se creuse","Il s’inverse"]'::jsonb, 2, 'Les diplômés du supérieur partent plus haut et progressent plus vite : l’écart grandit avec les années.', 1),
    ('3160146d-4d7b-57f0-8ab8-a81a562ce05f'::uuid, 'ses', '2de', 'L’influence du diplôme et de l’expérience sur le niveau de salaire', 'Pour quelle catégorie l’effet de l’âge sur le salaire est-il le plus marqué ?', 'mcq', '["Les ouvriers","Les cadres","Les apprentis","Les salariés au salaire minimum"]'::jsonb, 1, 'La courbe salaire-âge monte plus fortement chez les cadres que chez les ouvriers.', 2),
    ('b9645753-aa0c-5d40-9e3b-c6cc541ea0fc'::uuid, 'ses', '2de', 'L’influence du diplôme et de l’expérience sur le niveau de salaire', 'Pourquoi la région influence-t-elle le salaire ?', 'mcq', '["Parce que la loi fixe un salaire par région","Parce que les diplômes diffèrent selon les régions","Parce que l’ancienneté n’y compte pas","Par le coût de la vie et la tension du marché du travail local"]'::jsonb, 3, 'Là où la vie coûte cher et où les employeurs peinent à recruter, les salaires sont plus élevés.', 3),
    ('0647a33f-0a08-5553-927b-272ab3f1d51f'::uuid, 'ses', '2de', 'L’influence du diplôme et de l’expérience sur le niveau de salaire', 'Qu’est-ce qui tend à élever le salaire d’une qualification ?', 'mcq', '["Sa rareté sur le marché du travail","Son ancienneté historique","Le nombre de personnes qui la possèdent","Sa facilité d’acquisition"]'::jsonb, 0, 'Le salaire dépend de la productivité attendue, mais aussi de la rareté : une qualification recherchée et peu répandue se paie cher.', 4),
    ('0aa2159d-e9fc-52c0-ac8f-6bc5b0b158f6'::uuid, 'ses', '2de', 'L’influence du genre et de l’origine sociale sur les trajectoires professionnelles', 'Quel écart de salaire subsiste entre femmes et hommes à poste et profil comparables ?', 'mcq', '["Aucun","Environ 30 %","Environ 4 %","Environ 14 %"]'::jsonb, 2, 'Environ 14 % en équivalent temps plein, environ 4 % à poste et profil comparables : le reste s’explique par le temps partiel, la ségrégation professionnelle et les interruptions de carrière.', 1),
    ('d79d34f7-af52-5a3e-b813-ffb0e57ce0a9'::uuid, 'ses', '2de', 'L’influence du genre et de l’origine sociale sur les trajectoires professionnelles', 'À quoi sert l’index d’égalité professionnelle ?', 'mcq', '["À fixer le salaire minimum","À rendre transparents les écarts entre femmes et hommes","À réserver des postes aux femmes","À calculer les retraites"]'::jsonb, 1, 'Il oblige les entreprises à mesurer et publier leurs écarts, pour rendre visible ce qui ne l’était pas.', 2),
    ('34adf4f3-8917-5be8-9eea-f4f89b4b4f6d'::uuid, 'ses', '2de', 'L’influence du genre et de l’origine sociale sur les trajectoires professionnelles', 'Où la reproduction sociale reste-t-elle la plus forte ?', 'mcq', '["Au milieu de l’échelle sociale","Nulle part","Uniquement chez les agriculteurs","Aux deux extrémités de l’échelle sociale"]'::jsonb, 3, 'Les enfants de cadres et les enfants d’ouvriers occupent plus souvent que les autres une position proche de celle de leurs parents.', 3),
    ('371d89a7-6aae-527a-ad75-450089a856c8'::uuid, 'ses', '2de', 'L’influence du genre et de l’origine sociale sur les trajectoires professionnelles', 'Qu’est-ce qui a surtout alimenté la mobilité sociale ?', 'mcq', '["La hausse du niveau de diplôme","La suppression des examens","La baisse des salaires","La disparition des cadres"]'::jsonb, 0, 'Beaucoup d’enfants occupent une position différente de celle de leurs parents, notamment parce qu’ils sont plus diplômés.', 4),
    ('e2e250e7-e188-5d37-9d00-5de97a698d06'::uuid, 'snt', '2de', 'Internet : le réseau des réseaux', 'Combien de sites américains ARPANET relie-t-il en 1969 ?', 'mcq', '["Deux","Quatre","Dix","Cent"]'::jsonb, 1, 'ARPANET relie quatre sites, trois universités et un institut de recherche ; l’objectif est de faire circuler l’information même si une partie du réseau tombe.', 1),
    ('a2f3cbb8-b315-5765-8985-8593f98ae4b0'::uuid, 'snt', '2de', 'Internet : le réseau des réseaux', 'De quoi s’occupe la couche Internet du modèle TCP/IP ?', 'mcq', '["Du support physique","De l’acheminement fiable","De l’adressage, avec le protocole IP","De ce que voit l’utilisateur"]'::jsonb, 2, 'La couche Internet gère l’adressage grâce à IP ; TCP et UDP relèvent de la couche transport.', 2),
    ('68177bf4-d21d-5c35-b1b1-a07f20cd48b8'::uuid, 'snt', '2de', 'Internet : le réseau des réseaux', 'À quelle couche du modèle TCP/IP appartiennent HTTP, SMTP et DNS ?', 'mcq', '["Application","Transport","Internet","Accès réseau"]'::jsonb, 0, 'Ce sont des protocoles de la couche application, celle des services que voit l’utilisateur.', 3),
    ('f96ff0c4-a8e9-5039-9ace-e9ff3deba37b'::uuid, 'snt', '2de', 'Internet : le réseau des réseaux', 'Le courrier électronique est une application du Web.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le courrier électronique est une application d’Internet, indépendante du Web, comme la messagerie instantanée.', 4),
    ('900cef41-6270-5371-a01a-9c1e4a1e7a07'::uuid, 'snt', '2de', 'Internet', 'Qu’est-ce que le protocole IP ne garantit pas ?', 'mcq', '["L’adressage des paquets","L’acheminement vers la destination","Le découpage en paquets","Que les paquets arrivent"]'::jsonb, 3, 'IP achemine les paquets grâce aux adresses mais ne garantit pas leur arrivée : c’est le rôle de TCP.', 1),
    ('61e887ca-d1cd-5bc0-9d85-7d0bb967ae8f'::uuid, 'snt', '2de', 'Internet', 'Que connaît un routeur pour acheminer un paquet ?', 'mcq', '["Le chemin complet jusqu’à la destination","Seulement le prochain saut vers la destination","Le contenu du paquet","Le nom de l’expéditeur"]'::jsonb, 1, 'Un routeur ne connaît pas tout le trajet : il choisit seulement vers quel voisin envoyer le paquet.', 2),
    ('41064541-64d9-5aed-8b09-538b29f6ad24'::uuid, 'snt', '2de', 'Internet', 'Combien d’adresses IPv4 différentes existe-t-il environ ?', 'mcq', '["Environ 4,3 milliards","Environ 65 000","Environ 16,7 millions","Un nombre pratiquement illimité"]'::jsonb, 0, 'Codées sur 32 bits, les adresses IPv4 sont environ 4,3 milliards : elles sont épuisées, d’où IPv6.', 3),
    ('5120952f-deb9-527f-9e42-33774f2d1488'::uuid, 'snt', '2de', 'Internet', 'Sur combien de bits une adresse IPv6 est-elle codée ?', 'mcq', '["32 bits","64 bits","128 bits","256 bits"]'::jsonb, 2, 'IPv6 code les adresses sur 128 bits, ce qui en offre un nombre pratiquement illimité.', 4),
    ('13f92647-4fca-5125-ae20-8f3495ac3fab'::uuid, 'snt', '2de', 'Adressage (IP)', 'Laquelle de ces adresses IPv4 est bien écrite ?', 'mcq', '["192.168.1.256","192.168.1","192.168.1.10","300.12.5.1"]'::jsonb, 2, 'Une adresse IPv4 compte quatre nombres de 0 à 255 séparés par des points : 256 et 300 sont impossibles.', 1),
    ('3038cd9e-0a03-5c4c-8a5a-69d5ebe4e3b0'::uuid, 'snt', '2de', 'Adressage (IP)', 'À quoi sert le NAT ?', 'mcq', '["À traduire les adresses privées vers l’unique adresse publique du foyer","À attribuer les adresses privées","À traduire un nom de domaine en adresse IP","À chiffrer les échanges"]'::jsonb, 0, 'Le NAT de la box fait sortir toutes les machines du foyer sous une seule adresse publique ; le DHCP, lui, distribue les adresses privées.', 2),
    ('1dcda134-3f42-597c-a24a-abd5349b9d49'::uuid, 'snt', '2de', 'Adressage (IP)', 'Combien d’adresses publiques un foyer reçoit-il généralement ?', 'mcq', '["Une par appareil","Aucune","Une par personne","Une seule, portée par la box"]'::jsonb, 3, 'Le foyer a une seule adresse publique, portée par la box ; les appareils ont des adresses privées dans le réseau local.', 3),
    ('da7aeb67-c2ef-52c8-a664-c1a5d5c8bed7'::uuid, 'snt', '2de', 'Adressage (IP)', 'Comment s’écrit une adresse IPv6 ?', 'mcq', '["En décimal, avec des points","En hexadécimal, séparée par des deux-points","En binaire, avec des tirets","En lettres, comme un nom de domaine"]'::jsonb, 1, 'Une adresse IPv6 s’écrit en hexadécimal, par groupes séparés par des deux-points.', 4),
    ('f3ba9628-2900-5ad9-93e5-44e7c378e8e8'::uuid, 'snt', '2de', 'Le Web', 'Que décrit le langage CSS ?', 'mcq', '["La structure du contenu","La présentation : couleurs, polices, mise en page","Le transfert des pages","L’adresse des ressources"]'::jsonb, 1, 'HTML décrit la structure, CSS la présentation : on peut changer l’apparence d’un site sans toucher à son contenu.', 1),
    ('3e58e9e2-7c63-51f3-9d40-dec88c688965'::uuid, 'snt', '2de', 'Le Web', 'Dans le modèle client-serveur du Web, quel est le rôle du navigateur ?', 'mcq', '["Il est le client qui demande la page","Il est le serveur qui stocke la page","Il route les paquets","Il indexe les pages"]'::jsonb, 0, 'Le navigateur est le client : il demande la page, et le serveur la lui renvoie.', 2),
    ('a9200fec-48ed-52c9-8d0f-e87ce790e431'::uuid, 'snt', '2de', 'Le Web', 'Quel est le rôle du protocole HTTP ?', 'mcq', '["Décrire une page","Donner une adresse à chaque ressource","Classer les résultats de recherche","Transférer la ressource entre serveur et client"]'::jsonb, 3, 'HTTP transfère la ressource ; HTML la décrit et l’URL lui donne une adresse unique.', 3),
    ('b77d7b99-06b4-50c4-b73c-21121dbb65a4'::uuid, 'snt', '2de', 'Le Web', 'Que se passe-t-il quand une page est échangée en HTTP, sans le S ?', 'mcq', '["Elle ne s’affiche pas","Elle est plus lente","Son contenu circule en clair et peut être lu par un intermédiaire","Elle n’est pas indexée"]'::jsonb, 2, 'Sans HTTPS, rien n’est chiffré : n’importe quel intermédiaire du réseau peut lire ce qui circule.', 4),
    ('69726071-4060-5cab-b8ce-ed7e11a95285'::uuid, 'snt', '2de', 'Routage (TCP)', 'Quel protocole de routage est utilisé entre les grands opérateurs d’Internet ?', 'mcq', '["RIP","OSPF","BGP","DHCP"]'::jsonb, 2, 'BGP relie les grands opérateurs ; RIP et OSPF servent au routage à l’intérieur d’un réseau.', 1),
    ('0ffc76f0-d21f-5924-962c-f6a2f5d78a3a'::uuid, 'snt', '2de', 'Routage (TCP)', 'Pourquoi TCP numérote-t-il les paquets ?', 'mcq', '["Pour pouvoir les remettre dans l’ordre","Pour les chiffrer","Pour choisir leur route","Pour réduire leur taille"]'::jsonb, 0, 'Les paquets pouvant arriver dans le désordre, la numérotation permet de les remettre dans l’ordre à l’arrivée.', 2),
    ('e31a8d45-8455-5c9e-a18a-7a0f87f439a5'::uuid, 'snt', '2de', 'Routage (TCP)', 'À quoi servent les accusés de réception de TCP ?', 'mcq', '["À accélérer le transfert","À donner une adresse aux machines","À choisir le routeur suivant","À confirmer que les paquets sont bien arrivés"]'::jsonb, 3, 'L’expéditeur attend un accusé de réception : sans lui, il sait qu’un paquet s’est perdu et le renvoie.', 3),
    ('d26ce1e2-9e30-554a-9b2c-56778ba02833'::uuid, 'snt', '2de', 'Routage (TCP)', 'Pourquoi TCP ajuste-t-il son débit ?', 'mcq', '["Pour économiser de l’énergie","Pour éviter la congestion du réseau","Pour chiffrer les données","Pour changer de route"]'::jsonb, 1, 'En ralentissant quand le réseau sature, TCP évite la congestion.', 4),
    ('c204852e-bd7a-56be-8776-46672c416ff6'::uuid, 'snt', '2de', 'Les réseaux sociaux', 'Que mesure la centralité d’un sommet dans un graphe social ?', 'mcq', '["Son nombre de relations","À quel point il est un passage obligé","Sa date d’inscription","Sa distance au sommet le plus éloigné"]'::jsonb, 1, 'La centralité dit à quel point un sommet est un passage obligé entre les autres ; le degré compte ses relations.', 1),
    ('ee1f32e5-772b-5b31-af55-d61a41fc0968'::uuid, 'snt', '2de', 'Les réseaux sociaux', 'En quelle année l’expérience de Milgram a-t-elle lieu ?', 'mcq', '["1945","1989","2004","1967"]'::jsonb, 3, 'L’expérience de Milgram, en 1967, a popularisé l’idée des « six degrés de séparation ».', 2),
    ('f94c5c93-3b0b-57d0-a320-86e5138c726d'::uuid, 'snt', '2de', 'Les réseaux sociaux', 'Qu’encadre le DSA européen, entré en application en 2023 ?', 'mcq', '["La modération et la transparence des plateformes","Les données personnelles","Les droits d’auteur","Les tarifs des opérateurs"]'::jsonb, 0, 'Le DSA encadre la modération et la transparence ; les données personnelles relèvent du RGPD.', 3),
    ('dc5cf701-d2cc-549f-93af-63d28f23f282'::uuid, 'snt', '2de', 'Les réseaux sociaux', 'Sur quoi les algorithmes de recommandation des réseaux sociaux sont-ils optimisés ?', 'mcq', '["La véracité","La diversité des opinions","L’engagement","L’ordre chronologique"]'::jsonb, 2, 'Optimisés sur l’engagement, ils favorisent ce qui fait réagir, d’où la viralité des contenus clivants.', 4),
    ('7b956239-f6c7-55ae-9ffb-b7ba8e82e8d1'::uuid, 'snt', '2de', 'Les données structurées', 'Dans une table de données, que représente une colonne ?', 'mcq', '["Un enregistrement","Un attribut","Un fichier","Une jointure"]'::jsonb, 1, 'Les lignes sont les enregistrements, les colonnes les attributs qui les décrivent.', 1),
    ('fcce1cba-b4c9-563f-a14e-595640ed42f6'::uuid, 'snt', '2de', 'Les données structurées', 'Pourquoi le type d’un attribut compte-t-il ?', 'mcq', '["Il fixe la couleur de la colonne","Il détermine la taille du fichier","Il autorise ou interdit un traitement","Il indique l’auteur des données"]'::jsonb, 2, 'On ne fait pas la moyenne d’une chaîne de caractères : c’est le type qui dit quels traitements sont possibles.', 2),
    ('953dc99d-b863-5bba-be45-97a635db57bd'::uuid, 'snt', '2de', 'Les données structurées', 'Que fait l’opération de filtrage sur une table ?', 'mcq', '["Elle garde seulement les lignes qui vérifient un critère","Elle ordonne les lignes","Elle fusionne deux tables","Elle calcule une moyenne"]'::jsonb, 0, 'Filtrer, c’est ne garder que les lignes qui vérifient un critère ; trier, c’est les ordonner.', 3),
    ('ded848e7-affb-56ba-a32e-8fb45e7bf745'::uuid, 'snt', '2de', 'Les données structurées', '« 37,2 °C est une température corporelle normale » relève de…', 'mcq', '["La donnée","L’information","Le format","La connaissance"]'::jsonb, 3, '37,2 est une donnée, « 37,2 °C, température corporelle » une information ; la juger normale, c’est une connaissance, fruit de l’interprétation.', 4),
    ('88d59c15-07a7-5b1f-b6f2-b2980aa42046'::uuid, 'snt', '2de', 'Deux modèles de service : les réseaux client-serveur et pair-à-pair', 'Quelle parade protège un service contre la panne d’un serveur ?', 'mcq', '["La réplication sur plusieurs machines","Le pair-à-pair","Le chiffrement","La compression"]'::jsonb, 0, 'En répliquant les données sur plusieurs machines, le service survit à la panne de l’une d’elles.', 1),
    ('6a56577f-b4e0-5463-a51b-32a2bf99bde4'::uuid, 'snt', '2de', 'Deux modèles de service : les réseaux client-serveur et pair-à-pair', 'Qu’est-ce qui répond au problème de l’éloignement géographique d’un serveur ?', 'mcq', '["Les fermes de serveurs","Les réseaux de distribution de contenu","Les tables de routage","Le DHCP"]'::jsonb, 1, 'Les réseaux de distribution de contenu placent des copies près des utilisateurs, pour raccourcir le trajet.', 2),
    ('34528137-558c-5d1e-b2a0-b649bcf86aed'::uuid, 'snt', '2de', 'Deux modèles de service : les réseaux client-serveur et pair-à-pair', 'Quelle force le pair-à-pair présente-t-il ?', 'mcq', '["Il garantit la qualité des contenus","Il facilite le retrait des contenus illicites","Il résiste à la censure et aux pannes","Il repose sur un serveur unique"]'::jsonb, 2, 'Sans centre, le pair-à-pair résiste à la censure et aux pannes ; en contrepartie, retirer un contenu illicite est difficile.', 3),
    ('99dc107b-e204-5a5e-9252-4176adf32956'::uuid, 'snt', '2de', 'Deux modèles de service : les réseaux client-serveur et pair-à-pair', 'Où se trouve le contenu dans un réseau pair-à-pair ?', 'mcq', '["Sur un serveur central","Dans le navigateur","Chez le fournisseur d’accès","Réparti entre les participants"]'::jsonb, 3, 'Chaque participant détient une partie du contenu et le partage avec les autres.', 4),
    ('40cb079a-85ac-5ab9-9319-3a07b85cfb8d'::uuid, 'snt', '2de', 'L’hypertexte', 'Qui invente le mot « hypertexte », en 1965 ?', 'mcq', '["Vannevar Bush","Tim Berners-Lee","Ted Nelson","Vinton Cerf"]'::jsonb, 2, 'Ted Nelson invente le mot en 1965 ; Vannevar Bush avait imaginé le Memex dès 1945.', 1),
    ('99ac14cd-c22d-54b5-a6ea-53473b1a2b80'::uuid, 'snt', '2de', 'L’hypertexte', 'Dans une URL, que trouve-t-on après le point d’interrogation ?', 'mcq', '["Le protocole","Des paramètres transmis à la page","Le nom de domaine","L’extension du domaine"]'::jsonb, 1, 'Après le point d’interrogation viennent les paramètres, des données transmises à la page.', 2),
    ('197bddeb-ea7e-510f-9942-5c5174899a74'::uuid, 'snt', '2de', 'L’hypertexte', 'Dans l’URL https://exemple.fr/cours/page.html, que désigne /cours/page.html ?', 'mcq', '["Le chemin vers la page visée","Le protocole","Le nom de domaine","Les paramètres"]'::jsonb, 0, 'https est le protocole, exemple.fr le nom de domaine, /cours/page.html le chemin vers la ressource.', 3),
    ('aa23f300-bdb8-50d3-9b31-31ed2525de77'::uuid, 'snt', '2de', 'L’hypertexte', 'Quelle brique du Web permet de demander une ressource à un serveur ?', 'mcq', '["HTML","L’URL","Le DNS","HTTP"]'::jsonb, 3, 'HTTP est le protocole de la demande ; l’URL donne l’adresse, HTML décrit la page et ses liens.', 4),
    ('5da66ad7-147d-5d7f-9e05-a4459d1a2c4d'::uuid, 'snt', '2de', 'Localisation et photographie numérique', 'Comment s’appelle la trame qui transporte les données de position d’un récepteur GPS ?', 'mcq', '["EXIF","RVB","NMEA","HTML"]'::jsonb, 2, 'La trame NMEA transporte les données de position ; EXIF désigne les métadonnées d’une photo.', 1),
    ('0d542035-d1ae-5b13-8dd4-35998059e163'::uuid, 'snt', '2de', 'Localisation et photographie numérique', 'Que mesure la résolution d’une image ?', 'mcq', '["La densité des pixels, en points par pouce","Le nombre total de pixels","Le poids du fichier","Le nombre de couleurs"]'::jsonb, 0, 'La résolution est la densité des pixels ; la définition, leur nombre total.', 2),
    ('c66b2c25-af2d-5ee6-8787-d77874763d00'::uuid, 'snt', '2de', 'Localisation et photographie numérique', 'À quoi sert le quatrième satellite dans le calcul GPS ?', 'mcq', '["À augmenter la vitesse","À afficher la carte","À envoyer la position au satellite","À corriger l’horloge du récepteur"]'::jsonb, 3, 'Trois satellites suffisent pour la position ; le quatrième corrige l’horloge du récepteur, dont une erreur d’un millionième de seconde fausse la position de 300 mètres.', 3),
    ('7d4d43bd-5369-5bcc-b9be-3a8b007a03fd'::uuid, 'snt', '2de', 'Localisation et photographie numérique', 'Entre quelles valeurs varie chaque composante d’un pixel en RVB ?', 'mcq', '["Entre 0 et 100","Entre 0 et 255","Entre 1 et 3","Entre 0 et 16,7 millions"]'::jsonb, 1, 'Chaque composante, codée sur un octet, varie de 0 à 255.', 4),
    ('476ff54d-0d75-5ad8-9c56-6ae10d581da1'::uuid, 'snt', '2de', 'La page web (HTTP et langages HTML et CSS)', 'Que signifie le code de réponse HTTP 500 ?', 'mcq', '["Succès","Redirection","Ressource introuvable","Erreur du serveur"]'::jsonb, 3, '200 signifie succès, 301 redirection, 404 introuvable et 500 erreur du serveur.', 1),
    ('fa5eb6aa-243b-5b96-b4dc-5f6d675fd35a'::uuid, 'snt', '2de', 'La page web (HTTP et langages HTML et CSS)', 'Quelle balise HTML crée un lien ?', 'mcq', '["a","p","img","ul"]'::jsonb, 0, 'La balise a crée un lien ; p un paragraphe, img une image, ul une liste.', 2),
    ('a1d9c382-ece5-5305-9962-9a15eb03db2b'::uuid, 'snt', '2de', 'La page web (HTTP et langages HTML et CSS)', 'En HTTPS, qu’est-ce qui authentifie l’identité du site ?', 'mcq', '["Le cookie","Le certificat","L’adresse IP","La feuille de style"]'::jsonb, 1, 'Le chiffrement TLS rend le contenu illisible pour un tiers, et le certificat authentifie l’identité du site.', 3),
    ('b19a1bca-ebc5-51b6-838c-797918c0bb3d'::uuid, 'snt', '2de', 'La page web (HTTP et langages HTML et CSS)', 'Que signifie le code de réponse HTTP 301 ?', 'mcq', '["Erreur du serveur","Succès","Redirection","Accès interdit"]'::jsonb, 2, 'Le code 301 indique une redirection : la ressource a changé d’adresse.', 4),
    ('6b445354-88d2-5694-9fa6-9c7b49a29880'::uuid, 'snt', '2de', 'Navigateur web et sécurité sur Internet', 'Quelle est la première étape d’un navigateur pour afficher un site ?', 'mcq', '["Exécuter le JavaScript","Dessiner la page","Résoudre le DNS pour trouver l’adresse IP du site","Télécharger les images"]'::jsonb, 2, 'Le navigateur doit d’abord trouver l’adresse IP du site par le DNS, avant d’envoyer sa requête HTTP.', 1),
    ('9bf0ab8e-f243-5811-81a0-ee8f0192ada7'::uuid, 'snt', '2de', 'Navigateur web et sécurité sur Internet', 'À quoi sert un cookie propre au site visité ?', 'mcq', '["À se souvenir de vous : panier, connexion, préférences","À vous suivre d’un site à l’autre","À chiffrer la connexion","À bloquer les publicités"]'::jsonb, 0, 'Le cookie propre au site mémorise panier, connexion et préférences ; ce sont les cookies tiers qui pistent d’un site à l’autre.', 2),
    ('4dfaf1af-7d4f-57d5-bf3f-f9f6fa1880ba'::uuid, 'snt', '2de', 'Navigateur web et sécurité sur Internet', 'Pourquoi faut-il limiter le nombre d’extensions du navigateur ?', 'mcq', '["Elles consomment trop de batterie","Elles empêchent HTTPS","Elles effacent l’historique","Chacune peut voir tout ce que vous faites"]'::jsonb, 3, 'Une extension a accès à ce que vous faites dans le navigateur : chacune est une porte d’entrée possible.', 3),
    ('a3978d6e-f206-5d9d-bac6-b83ae53466ee'::uuid, 'snt', '2de', 'Navigateur web et sécurité sur Internet', 'Pourquoi utiliser un mot de passe différent pour chaque site ?', 'mcq', '["Pour que les sites se chargent plus vite","Pour qu’une fuite n’en compromette qu’un seul","Parce que la loi l’impose","Pour éviter les cookies"]'::jsonb, 1, 'Si un site se fait voler ses mots de passe, un mot de passe unique ne donne accès qu’à ce compte ; un gestionnaire aide à les retenir.', 4),
    ('0e5f4333-4531-582e-be8f-02ce0e00d069'::uuid, 'snt', '2de', 'Moteur de recherche : principes et usages', 'Que mesure le critère de pertinence dans le classement ?', 'mcq', '["Le nombre de liens entrants","Le nombre de visiteurs","La présence des mots de la requête dans la page, son titre, ses liens","L’âge du site"]'::jsonb, 2, 'La pertinence vérifie la présence des mots de la requête ; la popularité, les liens entrants.', 1),
    ('b64bfeb6-4173-58cd-bc2a-7081225d1f6f'::uuid, 'snt', '2de', 'Moteur de recherche : principes et usages', 'Qu’appelle-t-on le référencement ?', 'mcq', '["L’optimisation faite par les sites eux-mêmes pour être mieux classés","Le paiement d’un lien sponsorisé","L’index inversé","L’historique de l’utilisateur"]'::jsonb, 0, 'Les sites s’optimisent eux-mêmes pour remonter dans les résultats : c’est le référencement.', 2),
    ('97fb89ab-9e61-53b1-a57f-792d966cdfc0'::uuid, 'snt', '2de', 'Moteur de recherche : principes et usages', 'Un moteur de recherche parcourt le Web au moment où l’on tape sa requête.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le moteur a tout exploré et indexé à l’avance : à la requête, il interroge son propre index.', 3),
    ('d22922d4-7c5c-580f-a7d4-84586b3f09e5'::uuid, 'snt', '2de', 'Moteur de recherche : principes et usages', 'Que faut-il faire avant de citer une information trouvée en ligne ?', 'mcq', '["La partager","Vérifier qu’elle est en première page","Lire les commentaires","La recouper : auteur, date, source, autre origine"]'::jsonb, 3, 'Recouper, c’est vérifier l’auteur, la date et la source, et croiser avec une autre origine.', 4),
    ('be675e34-4c4e-5887-bc05-dde013d1391f'::uuid, 'snt', '2de', 'Le web 2.0, ou web participatif', 'Que permet un wiki ?', 'mcq', '["Écrire à plusieurs sur la même page","Publier des vidéos","Chiffrer ses messages","Classer des résultats de recherche"]'::jsonb, 0, 'Un wiki, comme Wikipédia, permet à plusieurs personnes d’écrire et de corriger la même page.', 1),
    ('4a215834-86d3-5e2c-adc1-096edc1f545d'::uuid, 'snt', '2de', 'Le web 2.0, ou web participatif', 'Qu’est-ce qui change vraiment avec le web 2.0 ?', 'mcq', '["Le protocole HTTP","L’interface, qui permet de publier sans savoir coder","Le réseau physique","Les adresses IP"]'::jsonb, 1, 'Les techniques existaient déjà : c’est l’interface qui permet à chacun de publier sans programmer.', 2),
    ('2450d23f-1dd2-5631-b214-62ec0e889fa7'::uuid, 'snt', '2de', 'Le web 2.0, ou web participatif', 'Quelle conséquence économique les effets de réseau favorisent-ils ?', 'mcq', '["La multiplication des petits acteurs","La baisse des prix","La concentration en quelques très grands acteurs","La disparition de la publicité"]'::jsonb, 2, 'Plus un service a d’utilisateurs, plus il est coûteux de le quitter : le marché se concentre.', 3),
    ('d7d7dd18-ff38-5045-a196-318872bc2b0e'::uuid, 'snt', '2de', 'Le web 2.0, ou web participatif', 'À partir de quand le Web devient-il participatif ?', 'mcq', '["Dès 1969","En 1989","Dans les années 2020","À partir des années 2000"]'::jsonb, 3, 'Le premier Web se lisait ; à partir des années 2000, il s’écrit.', 4),
    ('3998b2c3-53cf-5b81-b132-c7186d688057'::uuid, 'snt', '2de', 'Open data', 'Une donnée ouverte peut-elle être réutilisée à des fins commerciales ?', 'mcq', '["Non, jamais","Oui","Seulement par l’État","Seulement après autorisation du maire"]'::jsonb, 1, 'L’open data se consulte, se réutilise et se redistribue librement, y compris à des fins commerciales.', 1),
    ('da06f47b-17bf-57bc-9b1b-62755d5aa695'::uuid, 'snt', '2de', 'Open data', 'Que signifie qu’une donnée est « lisible par machine » ?', 'mcq', '["Qu’elle est exploitable sans ressaisie","Qu’elle est imprimable","Qu’elle est chiffrée","Qu’elle est affichée sur un écran"]'::jsonb, 0, 'Une donnée lisible par machine se traite directement par un programme, sans devoir la recopier à la main.', 2),
    ('884c1809-95eb-59f4-9bf4-6b01f2ffff48'::uuid, 'snt', '2de', 'Open data', 'Comment appelle-t-on les enquêtes fondées sur des chiffres publics ?', 'mcq', '["Le big data","Le référencement","Le crowdfunding","Le journalisme de données"]'::jsonb, 3, 'Le journalisme de données exploite les jeux publics pour enquêter, au même titre que le contrôle citoyen.', 3),
    ('a1242f18-b51e-554f-b4d9-ee59ed8e8fa2'::uuid, 'snt', '2de', 'Open data', 'Pourquoi certaines données publiques ne peuvent-elles pas être ouvertes ?', 'mcq', '["Elles sont trop volumineuses","Elles sont en format CSV","Elles relèvent du secret statistique ou de la sécurité","Elles datent de plus de dix ans"]'::jsonb, 2, 'Le secret statistique et la sécurité interdisent de publier certaines données, comme les données personnelles non anonymisées.', 4),
    ('edde1edf-ec6f-5740-8af5-79460bacc1c9'::uuid, 'snt', '2de', 'Cloud et datacenters', 'Quel est le principal poste d’émissions du numérique ?', 'mcq', '["Les datacenters","La fabrication des terminaux","Les câbles sous-marins","Les box internet"]'::jsonb, 1, 'La fabrication des terminaux pèse le plus ; les datacenters consomment surtout pour l’électricité et le refroidissement.', 1),
    ('56f75024-dbae-5802-9123-c088656df708'::uuid, 'snt', '2de', 'Cloud et datacenters', 'Que fournit le cloud au niveau « logiciel » ?', 'mcq', '["Des machines et du stockage","Un environnement d’exécution","Un câble réseau","Une application prête à l’emploi"]'::jsonb, 3, 'Trois niveaux : l’infrastructure (machines, stockage), la plateforme (environnement d’exécution) et le logiciel (application prête à l’emploi).', 2),
    ('8a780fd3-edb6-5272-822e-3b2220e061fe'::uuid, 'snt', '2de', 'Cloud et datacenters', 'Pourquoi un datacenter a-t-il une alimentation redondante et des groupes électrogènes ?', 'mcq', '["Pour survivre à une coupure de courant","Pour refroidir les serveurs","Pour chiffrer les données","Pour réduire la facture"]'::jsonb, 0, 'Un datacenter doit rester joignable en toutes circonstances : il double son alimentation et prévoit des groupes électrogènes.', 3),
    ('c22f8c71-f312-5db4-9cd7-551cf1e90825'::uuid, 'snt', '2de', 'Cloud et datacenters', 'Que signifie une capacité « élastique » dans le cloud ?', 'mcq', '["Elle ne tombe jamais en panne","Elle est gratuite","Elle s’ajuste à la demande sans investir dans du matériel","Elle stocke les données chez l’utilisateur"]'::jsonb, 2, 'On loue plus ou moins de ressources selon les besoins, sans acheter de machines ; en contrepartie, le coût grimpe avec le volume.', 4),
    ('a3bfd7c7-7985-525b-994d-f19beabc63ba'::uuid, 'snt', '2de', 'Les réseaux sociaux, l’expérience du petit monde et les graphes', 'Qu’appelle-t-on la distance entre deux sommets d’un graphe ?', 'mcq', '["Le nombre total d’arêtes","La longueur de la plus courte chaîne qui les relie","La longueur de la plus longue chaîne","Le degré du plus grand des deux"]'::jsonb, 1, 'La distance est la longueur de la plus courte chaîne ; le diamètre est la plus grande de ces distances.', 1),
    ('eb8c69b8-4fd1-555b-aea6-e891ec1f3141'::uuid, 'snt', '2de', 'Les réseaux sociaux, l’expérience du petit monde et les graphes', 'Quelle relation se modélise par un graphe orienté ?', 'mcq', '["Deux personnes qui sont amies","Deux villes reliées par une route","Deux cousins","Je te suis sans que tu me suives"]'::jsonb, 3, 'Dans un graphe orienté, une arête a un sens : suivre quelqu’un n’implique pas d’être suivi en retour.', 2),
    ('d4e3efe1-7749-54fe-aac5-3477622e46eb'::uuid, 'snt', '2de', 'Les réseaux sociaux, l’expérience du petit monde et les graphes', 'Que révèle une forte densité de triangles dans un réseau social ?', 'mcq', '["Mes amis sont souvent amis entre eux","Le réseau a un grand diamètre","Les comptes sont faux","Il y a peu de liens faibles"]'::jsonb, 0, 'Un triangle, ce sont trois personnes toutes reliées : sur les réseaux sociaux, mes amis sont souvent amis entre eux.', 3),
    ('5fb4e553-b937-58c9-b9e3-45db9ff2a283'::uuid, 'snt', '2de', 'Les réseaux sociaux, l’expérience du petit monde et les graphes', 'En quoi consistait le protocole de l’expérience de Milgram ?', 'mcq', '["Envoyer un courriel à des inconnus","Compter les amis de chaque participant","Faire parvenir une lettre à un inconnu de Boston en passant uniquement par des connaissances","Appeler au hasard des numéros de téléphone"]'::jsonb, 2, 'Chaque lettre devait passer de connaissance en connaissance jusqu’au destinataire : environ six intermédiaires suffisaient.', 4),
    ('6251c1bd-47d1-5660-b99e-a8d12a9c3954'::uuid, 'snt', '2de', 'Filtrage de l’information', 'Qui a popularisé la notion de bulle de filtre ?', 'mcq', '["Stanley Milgram","Eli Pariser","Tim Berners-Lee","Mark Zuckerberg"]'::jsonb, 1, 'Eli Pariser a popularisé l’expression pour désigner l’enfermement algorithmique dans des contenus conformes à ses opinions.', 1),
    ('929e0c69-a192-5bdd-8a63-7f9cf0db851a'::uuid, 'snt', '2de', 'Filtrage de l’information', 'Qu’appelle-t-on l’effet de répétition ?', 'mcq', '["Ce qu’on lit souvent finit par paraître vrai","On oublie ce qu’on a lu deux fois","Un message répété est bloqué","Un contenu répété perd sa visibilité"]'::jsonb, 0, 'À force d’être lue, une affirmation paraît vraie, même si elle est fausse : c’est un ressort de la désinformation.', 2),
    ('8cc3f5e7-0fab-5b32-bc0a-18addcf2b920'::uuid, 'snt', '2de', 'Filtrage de l’information', 'Pourquoi se méfier d’un titre qui provoque une forte indignation ?', 'mcq', '["Parce qu’il est toujours faux","Parce qu’il est trop long","Parce qu’il est écrit par un robot","Parce que cette émotion est précisément le levier utilisé pour le faire circuler"]'::jsonb, 3, 'La surprise et l’indignation font circuler une infox plus vite qu’une information vérifiée : sa propre émotion est le levier.', 3),
    ('aad44d5f-53ef-598c-a140-73e562ebf8b2'::uuid, 'snt', '2de', 'Filtrage de l’information', 'Sur quoi un système de recommandation s’appuie-t-il pour prédire vos réactions ?', 'mcq', '["Sur l’avis d’un journaliste","Sur l’ordre chronologique des publications","Sur vos clics, le temps passé et vos interactions","Sur un tirage au sort"]'::jsonb, 2, 'Clics, temps passé et interactions nourrissent la prédiction : l’algorithme vous montre ce qui a le plus de chances de vous faire réagir.', 4),
    ('31165b9a-a958-57f4-915c-89305daebf61'::uuid, 'snt', '2de', 'Exister en ligne', 'Une photo que l’on publie soi-même est une trace…', 'mcq', '["Volontaire","Involontaire","Héritée","Anonyme"]'::jsonb, 0, 'Ce que l’on publie est une trace volontaire ; ce que la machine laisse est involontaire ; ce que les autres publient sur nous est hérité.', 1),
    ('7a6ca3bd-7dc8-5053-a24b-f460390125d7'::uuid, 'snt', '2de', 'Exister en ligne', 'Que permet le droit à la portabilité ?', 'mcq', '["Effacer ses données","Récupérer ses données pour les transférer ailleurs","Corriger une erreur","Refuser un traitement"]'::jsonb, 1, 'La portabilité permet de récupérer ses données pour les transférer à un autre service.', 2),
    ('efe263be-df24-5375-971c-a5f661365a98'::uuid, 'snt', '2de', 'Exister en ligne', 'Qu’appelle-t-on la résurgence d’une publication ?', 'mcq', '["Sa suppression automatique","Son chiffrement","Son ressurgissement, des années plus tard, hors de son contexte","Sa traduction"]'::jsonb, 2, 'Recopiée, une publication peut ressortir des années plus tard, par exemple lors d’un recrutement.', 3),
    ('4c55d9cc-2950-5f6c-8009-702bb6a4b0c1'::uuid, 'snt', '2de', 'Exister en ligne', 'Quelle bonne pratique protège son identité numérique ?', 'mcq', '["Utiliser le même compte pour tout","Publier sous son adresse personnelle","Accepter tous les cookies","Séparer les usages personnel, scolaire et professionnel"]'::jsonb, 3, 'Séparer les usages, régler la confidentialité et réfléchir avant de publier l’image d’autrui limitent les risques.', 4),
    ('dbccba53-dd27-5643-a313-672b78f7f4b1'::uuid, 'snt', '2de', 'L’image numérique', 'Quel est le poids brut d’une image en niveaux de gris de 1000 × 1000 pixels, à un octet par pixel ?', 'mcq', '["Mille octets","Un million d’octets","Trois millions d’octets","Un milliard d’octets"]'::jsonb, 1, 'Poids brut = nombre de pixels × octets par pixel : 1 000 000 × 1 = un million d’octets.', 1),
    ('8930f11d-8854-5c44-990b-2c82392ea925'::uuid, 'snt', '2de', 'L’image numérique', 'Quelles composantes RVB donnent un rouge vif ?', 'mcq', '["(0, 0, 0)","(255, 255, 255)","(0, 255, 255)","(255, 0, 0)"]'::jsonb, 3, 'Rouge au maximum, vert et bleu à zéro : (255, 0, 0). (0, 0, 0) est le noir, (255, 255, 255) le blanc.', 2),
    ('ab86d75a-6201-50be-981a-d76cf681ac56'::uuid, 'snt', '2de', 'L’image numérique', 'Quelle est la limite du format GIF ?', 'mcq', '["Il ne gère pas l’animation","Il est toujours vectoriel","Il est limité à 256 couleurs","Il ne se compresse pas"]'::jsonb, 2, 'Le GIF est limité à 256 couleurs : il sert surtout pour de petites animations.', 3),
    ('a6de792c-96c0-5bcd-8d29-bfb18b6be558'::uuid, 'snt', '2de', 'L’image numérique', 'Quel type de compression utilise le format JPEG ?', 'mcq', '["Une compression avec perte","Une compression sans perte","Aucune compression","Une compression vectorielle"]'::jsonb, 0, 'Le JPEG compresse avec perte : adapté aux photos, il laisse des artefacts visibles si on compresse trop.', 4),
    ('33547257-88f1-50ff-83f5-7b2b719fa242'::uuid, 'snt', '2de', 'La colorisation d’une image', 'Quel est le négatif du pixel rouge vif (255, 0, 0) ?', 'mcq', '["(0, 0, 0)","(0, 255, 255)","(255, 255, 0)","(128, 0, 0)"]'::jsonb, 1, 'Chaque composante devient 255 moins sa valeur : (0, 255, 255), c’est-à-dire du cyan.', 1),
    ('d3426157-32a8-596a-820d-b93f56ec2d2d'::uuid, 'snt', '2de', 'La colorisation d’une image', 'Avec la méthode de la moyenne, quel niveau de gris donne le pixel (30, 60, 90) ?', 'mcq', '["30","90","180","60"]'::jsonb, 3, '(30 + 60 + 90) / 3 = 180 / 3 = 60.', 2),
    ('a2c3154e-48ba-5ab7-9609-ed0d6200c30e'::uuid, 'snt', '2de', 'La colorisation d’une image', 'Lors d’un seuillage, que devient un pixel dont la valeur dépasse le seuil ?', 'mcq', '["Il devient blanc","Il devient noir","Il garde sa valeur","Il devient gris"]'::jsonb, 0, 'Au-dessus du seuil, le pixel devient blanc ; en dessous, noir : on sépare la forme du fond.', 3),
    ('c67f06ae-2459-5703-a9d5-97e3e4bc1a92'::uuid, 'snt', '2de', 'La colorisation d’une image', 'Comment obtient-on une teinte sépia ?', 'mcq', '["En supprimant le bleu","En inversant les composantes","Par une combinaison linéaire des trois composantes","Par un seuillage"]'::jsonb, 2, 'Chaque nouvelle composante est une somme pondérée des trois anciennes : c’est une combinaison linéaire.', 4),
    ('c0a1b09f-92f4-5c9a-b116-e24873346590'::uuid, 'snt', '2de', 'Traitement par histogramme', 'Que porte l’axe des abscisses d’un histogramme d’image ?', 'mcq', '["Le nombre de pixels","La position des pixels","Le poids du fichier","Les valeurs de 0 à 255, des sombres aux clairs"]'::jsonb, 3, 'En abscisse, les valeurs de 0 (sombre, à gauche) à 255 (clair, à droite) ; en ordonnée, le nombre de pixels.', 1),
    ('589a7105-f6c6-51dc-a5f2-e0d830a68f85'::uuid, 'snt', '2de', 'Traitement par histogramme', 'Que révèle un histogramme tassé vers la droite ?', 'mcq', '["Une image sous-exposée","Une image surexposée","Une image peu contrastée","Une image bien équilibrée"]'::jsonb, 1, 'Les pixels s’entassent dans les valeurs claires : l’image est surexposée.', 2),
    ('735e5b8e-968d-53cc-bf3a-69aa329a8bfc'::uuid, 'snt', '2de', 'Traitement par histogramme', 'Les pixels d’une image vont de 80 à 170. Après étirement, que devient la valeur 170 ?', 'mcq', '["255","170","85","0"]'::jsonb, 0, 'L’étirement étale les valeurs sur toute la plage : 80 devient 0 et 170 devient 255.', 3),
    ('5cd90309-30e0-586a-afcc-142cc4a2182e'::uuid, 'snt', '2de', 'Traitement par histogramme', 'Quel inconvénient l’égalisation d’histogramme présente-t-elle ?', 'mcq', '["Elle réduit le contraste","Elle supprime les couleurs","Elle accentue le bruit","Elle diminue la définition"]'::jsonb, 2, 'L’égalisation renforce fortement le contraste local, mais accentue aussi le bruit et peut donner une image peu naturelle.', 4),
    ('a35bfa76-9552-53ee-a15c-8563544552f4'::uuid, 'snt', '2de', 'Résolution et filtrage d’une image', 'Combien de pixels compte une image de 4000 × 3000 ?', 'mcq', '["7 000","1,2 million","120 millions","12 millions"]'::jsonb, 3, '4000 × 3000 = 12 000 000 pixels : c’est la définition de l’image.', 1),
    ('d2aa7e18-95fe-5ebd-92ee-c5f1c6b0198b'::uuid, 'snt', '2de', 'Résolution et filtrage d’une image', 'En quelle unité exprime-t-on la résolution ?', 'mcq', '["En pixels","En points par pouce","En octets","En hertz"]'::jsonb, 1, 'La résolution est une densité, en points par pouce ; la définition se compte en pixels, le poids en octets.', 2),
    ('a2ce6b68-66bc-5556-9c64-94027e00e23c'::uuid, 'snt', '2de', 'Résolution et filtrage d’une image', 'Quel est le poids brut d’une image couleur de 1000 × 1000 pixels codée sur 3 octets par pixel ?', 'mcq', '["3 millions d’octets","1 million d’octets","3 000 octets","24 millions d’octets"]'::jsonb, 0, 'Poids = définition × octets par pixel : 1 000 000 × 3 = 3 millions d’octets.', 3),
    ('6624c48c-cd2c-566b-89a4-b539d91f1200'::uuid, 'snt', '2de', 'Résolution et filtrage d’une image', 'Que forment les filtres de convolution une fois empilés ?', 'mcq', '["Un format de compression","Un histogramme","Les premières couches des réseaux de neurones de vision","Une table de routage"]'::jsonb, 2, 'Les mêmes opérations de convolution, empilées, constituent les premières couches des réseaux de neurones qui analysent les images.', 4),
    ('520f075d-de0b-5535-addd-edf6c9d0c159'::uuid, 'snt', '2de', 'Comment est captée une image ?', 'Quel composant transforme la charge d’un photosite en nombre entier ?', 'mcq', '["Le convertisseur analogique-numérique","La matrice de Bayer","L’objectif","Le dématriçage"]'::jsonb, 0, 'Le convertisseur analogique-numérique traduit chaque charge électrique en nombre entier.', 1),
    ('14480e41-926d-54d5-9137-4e2ca9ddf97e'::uuid, 'snt', '2de', 'Comment est captée une image ?', 'Sur combien de bits le format RAW code-t-il souvent chaque composante ?', 'mcq', '["1 bit","4 bits","8 bits","12 ou 14 bits"]'::jsonb, 3, 'Le RAW garde souvent 12 ou 14 bits par composante, bien plus que les 256 niveaux du 8 bits.', 2),
    ('b9eed004-7c5f-5485-a6c4-49d2600bfa0a'::uuid, 'snt', '2de', 'Comment est captée une image ?', 'Qu’est-ce qui détermine la quantité de lumière reçue par le capteur ?', 'mcq', '["Le nombre de mégapixels","L’ouverture et la durée d’exposition","Le format du fichier","La taille de l’écran"]'::jsonb, 1, 'Plus l’ouverture est grande et la pose longue, plus le capteur reçoit de lumière.', 3),
    ('b666ffb0-8d10-5887-bb0c-2e71cc6c2362'::uuid, 'snt', '2de', 'Comment est captée une image ?', 'Qu’est-ce qui est aujourd’hui décisif pour la qualité des photos de téléphone ?', 'mcq', '["La taille de l’écran","La matrice de Bayer","Le traitement logiciel embarqué","Le format JPEG"]'::jsonb, 2, 'Sur un téléphone, au petit capteur, le traitement logiciel embarqué est devenu décisif.', 4),
    ('8b549b69-154f-5e19-a35e-5814f9b8253f'::uuid, 'snt', '2de', 'Géolocalisation', 'Quel pays a développé le système de positionnement Beidou ?', 'mcq', '["La Russie","Les États-Unis","La Chine","Le Japon"]'::jsonb, 2, 'Beidou est chinois, GLONASS russe, GPS américain et Galileo européen.', 1),
    ('97d764bb-7590-5c68-8b0f-1c7180be7a45'::uuid, 'snt', '2de', 'Géolocalisation', 'Avec un seul satellite, quel est l’ensemble des positions possibles du récepteur ?', 'mcq', '["Une sphère","Un cercle","Deux points","Un point unique"]'::jsonb, 0, 'Une distance à un satellite place le récepteur sur une sphère ; deux sphères se coupent en un cercle, trois en deux points.', 2),
    ('1d134956-5175-5313-a23c-ad134b5515b1'::uuid, 'snt', '2de', 'Géolocalisation', 'Quelle précision le GPS atteint-il en terrain dégagé ?', 'mcq', '["Quelques centimètres","Quelques kilomètres","Une centaine de mètres","Quelques mètres"]'::jsonb, 3, 'En terrain dégagé, la précision est de quelques mètres ; elle se dégrade en ville, sous les arbres ou en intérieur.', 3),
    ('c064468f-943b-570a-b887-56f685606a8e'::uuid, 'snt', '2de', 'Géolocalisation', 'À quoi servent l’accéléromètre et le gyroscope d’un téléphone pour la localisation ?', 'mcq', '["À recevoir les satellites","À assurer la continuité entre deux positions","À corriger l’horloge atomique","À chiffrer la position"]'::jsonb, 1, 'Ces capteurs internes estiment le déplacement entre deux points mesurés, par exemple dans un tunnel.', 4),
    ('c52829c9-8bdc-5e8e-be32-a776d4984f5b'::uuid, 'snt', '2de', 'Calcul d’itinéraire', 'Dans le graphe d’un réseau routier, que représente un sommet ?', 'mcq', '["Un tronçon de route","Une intersection","Une durée","Un véhicule"]'::jsonb, 1, 'Les sommets sont les intersections, les arêtes les tronçons de route, et le poids ce que l’on cherche à minimiser.', 1),
    ('a8763533-97d2-50cd-af89-aca5fddcbaf8'::uuid, 'snt', '2de', 'Calcul d’itinéraire', 'Quelle condition l’algorithme de Dijkstra impose-t-il aux poids ?', 'mcq', '["Ils doivent être positifs","Ils doivent être entiers","Ils doivent être tous égaux","Ils doivent être des distances"]'::jsonb, 0, 'Dijkstra ne fonctionne qu’avec des poids positifs.', 2),
    ('f4ff89ba-587a-5395-80da-8f3d35e10bc7'::uuid, 'snt', '2de', 'Calcul d’itinéraire', 'À quoi servent les prétraitements des calculateurs d’itinéraire ?', 'mcq', '["À dessiner la carte","À mesurer le trafic","À hiérarchiser le réseau, les autoroutes d’abord","À supprimer les péages"]'::jsonb, 2, 'Sur des millions de sommets, Dijkstra seul explore trop : on hiérarchise le réseau pour aller plus vite.', 3),
    ('95a6e9b9-5ef7-5846-8d75-666dac20abe8'::uuid, 'snt', '2de', 'Calcul d’itinéraire', 'Quel poids faut-il minimiser pour obtenir le trajet le plus rapide ?', 'mcq', '["La distance","Le nombre d’intersections","La pente","La durée"]'::jsonb, 3, 'Minimiser la durée donne le plus rapide ; minimiser la distance donne le plus court, qui n’est pas forcément le même.', 4),
    ('798ec51b-7776-58da-b9b8-8aebc6afc999'::uuid, 'snt', '2de', 'Systèmes automatisés', 'Quel composant joue souvent le rôle de partie commande ?', 'mcq', '["Un vérin","Un microcontrôleur","Un capteur de lumière","Une vanne"]'::jsonb, 1, 'Le microcontrôleur applique le programme ; vérins et vannes sont des actionneurs.', 1),
    ('2b712418-e78e-57c6-aae7-621a6e88aca5'::uuid, 'snt', '2de', 'Systèmes automatisés', 'Lequel de ces éléments est un actionneur ?', 'mcq', '["Un capteur de présence","Un thermomètre","Un microcontrôleur","Un vérin"]'::jsonb, 3, 'Le vérin agit sur le monde physique ; thermomètre et capteur de présence mesurent, le microcontrôleur décide.', 2),
    ('c8e4d4ed-1663-5e91-9dd7-c74802cc07b5'::uuid, 'snt', '2de', 'Systèmes automatisés', 'Quel risque apparaît dès qu’un système automatisé est connecté ?', 'mcq', '["La cybersécurité","La rouille","La surchauffe","La perte de la consigne"]'::jsonb, 0, 'Connecté, un système devient attaquable à distance : la cybersécurité devient un enjeu.', 3),
    ('3587c251-c8e3-5c52-9c8a-1a6e22d2ee9c'::uuid, 'snt', '2de', 'Systèmes automatisés', 'Qu’est-ce que la consigne d’un thermostat ?', 'mcq', '["La température mesurée","Le mode d’emploi","La température visée, à laquelle la mesure est comparée","La résistance chauffante"]'::jsonb, 2, 'La consigne est la valeur à atteindre ; le thermostat compare la mesure à la consigne et corrige.', 4),
    ('201e9a0b-bd57-5320-a686-fafaa2c90f4f'::uuid, 'snt', '2de', 'L’Internet des objets (ou IoT)', 'Qu’apporte l’Internet des objets à l’industrie ?', 'mcq', '["La maintenance prédictive","Les compteurs communicants","La domotique","La traçabilité des colis"]'::jsonb, 0, 'Dans l’industrie, les capteurs permettent d’anticiper les pannes : c’est la maintenance prédictive.', 1),
    ('0b13b74e-7138-539c-b60d-3a1d8cc284ac'::uuid, 'snt', '2de', 'L’Internet des objets (ou IoT)', 'Quel rôle joue le cloud dans l’Internet des objets ?', 'mcq', '["Il fabrique les capteurs","Il stocke et traite les flux de données collectés","Il remplace le wifi","Il attribue les adresses IPv6"]'::jsonb, 1, 'Les objets envoient leurs mesures vers le cloud, qui les stocke et les traite.', 2),
    ('df5d657b-b9f1-518b-a164-0390f05d5ef4'::uuid, 'snt', '2de', 'L’Internet des objets (ou IoT)', 'Quelle est la conséquence de l’absence de chiffrement sur un objet connecté ?', 'mcq', '["L’objet consomme plus","L’objet ne se connecte plus","Les données circulent en clair","Les mises à jour sont bloquées"]'::jsonb, 2, 'Sans chiffrement, n’importe qui sur le chemin peut lire les données envoyées par l’objet.', 3),
    ('4dc2137b-4d4e-51a2-8ac1-eb948067199b'::uuid, 'snt', '2de', 'L’Internet des objets (ou IoT)', 'Quel est l’enjeu environnemental de l’Internet des objets ?', 'mcq', '["Le manque d’adresses IP","La lenteur du réseau","Le coût des abonnements","La fabrication, les terres rares, l’obsolescence et les déchets électroniques"]'::jsonb, 3, 'Des milliards d’objets à fabriquer, souvent vite obsolètes, pèsent sur les ressources et produisent des déchets électroniques.', 4),
    ('db29a2b4-91d0-5449-bfc3-4f0583731de3'::uuid, 'svt', '2de', 'Les êtres vivants pluricellulaires et la spécialisation des cellules', 'Quel est l’ordre de grandeur de la taille d’une bactérie ?', 'mcq', '["Quelques nanomètres","Environ 100 micromètres","Quelques micromètres","Quelques millimètres"]'::jsonb, 2, 'Une bactérie mesure quelques micromètres : elle est environ dix fois plus petite qu’une cellule animale.', 1),
    ('ac564b1a-4d07-5b2e-86db-7a875d97d055'::uuid, 'svt', '2de', 'Les êtres vivants pluricellulaires et la spécialisation des cellules', 'Quel est le rôle de la membrane plasmique ?', 'mcq', '["Délimiter un milieu intérieur","Produire l’énergie de la cellule","Porter l’information génétique","Fabriquer les protéines contractiles"]'::jsonb, 0, 'La membrane plasmique sépare l’intérieur de la cellule du milieu extérieur ; l’information génétique, elle, est portée par l’ADN.', 2),
    ('fef6ca37-3247-5909-9c38-103e6497cab0'::uuid, 'svt', '2de', 'Les êtres vivants pluricellulaires et la spécialisation des cellules', 'Comment se nomme un ensemble de plusieurs organes qui travaillent ensemble ?', 'mcq', '["Un tissu","Une cellule-œuf","Un organite","Un appareil"]'::jsonb, 3, 'Cellules → tissu → organe → appareil : l’appareil digestif, par exemple, réunit estomac, intestin, foie…', 3),
    ('24039157-7518-5063-ab93-2abdbc1b1f41'::uuid, 'svt', '2de', 'Les êtres vivants pluricellulaires et la spécialisation des cellules', 'Quelle caractéristique de la cellule intestinale est liée à sa fonction d’absorption ?', 'mcq', '["L’absence de noyau","Des replis qui augmentent sa surface","De longs prolongements","Des protéines contractiles"]'::jsonb, 1, 'Les replis multiplient la surface d’échange : plus de surface, plus d’absorption. La forme d’une cellule spécialisée est liée à sa fonction.', 4),
    ('fa019729-8c77-537d-95eb-4327694b213c'::uuid, 'svt', '2de', 'Le métabolisme des cellules', 'D’où une cellule hétérotrophe tire-t-elle sa matière et son énergie ?', 'mcq', '["De la lumière","De matière organique déjà formée","De la matière minérale","Du dioxyde de carbone de l’air"]'::jsonb, 1, 'Une cellule hétérotrophe utilise de la matière organique produite par d’autres êtres vivants, qui lui fournit à la fois matière et énergie.', 1),
    ('bb354299-c5b1-5003-abb4-1b74d61cfa06'::uuid, 'svt', '2de', 'Le métabolisme des cellules', 'Où se déroule la fermentation ?', 'mcq', '["Dans les mitochondries","Dans le noyau","Dans les chloroplastes","Dans le cytoplasme"]'::jsonb, 3, 'La fermentation a lieu dans le cytoplasme, sans dioxygène ; la respiration, elle, se termine dans les mitochondries.', 2),
    ('9aaecc0a-b977-5ece-8382-618961de52c7'::uuid, 'svt', '2de', 'Le métabolisme des cellules', 'Quels sont les produits de la respiration cellulaire ?', 'mcq', '["Du dioxyde de carbone et de l’eau","De l’éthanol et du CO2","Du glucose et du dioxygène","De l’acide lactique"]'::jsonb, 0, 'La respiration dégrade complètement le glucose en CO2 et en eau, en utilisant du dioxygène.', 3),
    ('9f79bae3-1067-5f24-b5df-29445edee746'::uuid, 'svt', '2de', 'Le métabolisme des cellules', 'Que fait une levure privée de dioxygène ?', 'mcq', '["Elle meurt immédiatement","Elle fait de la photosynthèse","Elle fermente","Elle respire plus vite"]'::jsonb, 2, 'Avec le même génome, la levure respire en présence de dioxygène et fermente en son absence : l’environnement influence le métabolisme.', 4),
    ('e3ced48a-3de1-5901-9a1f-c19a9fb50175'::uuid, 'svt', '2de', 'Biosphère et diversité des écosystèmes', 'Qu’est-ce que le biotope d’un écosystème ?', 'mcq', '["L’ensemble des êtres vivants","Les relations de prédation","Le milieu physique et chimique : température, lumière, eau, sol","Les décomposeurs du sol"]'::jsonb, 2, 'Le biotope est la composante non vivante de l’écosystème ; les êtres vivants et leurs relations forment la biocénose.', 1),
    ('b785b2ad-8b43-56a8-a8a2-ff0a8ae07325'::uuid, 'svt', '2de', 'Biosphère et diversité des écosystèmes', 'Dans quelle relation l’un gagne et l’autre perd, sans que ce soit de la prédation ?', 'mcq', '["Le parasitisme","La compétition","La coopération","Le commensalisme"]'::jsonb, 0, 'Le parasite vit aux dépens de son hôte, sans le manger d’un coup comme le ferait un prédateur.', 2),
    ('8a769761-dec6-5d16-a6c2-e14322c9a017'::uuid, 'svt', '2de', 'Biosphère et diversité des écosystèmes', 'Combien d’espèces ont été décrites à ce jour, environ ?', 'mcq', '["Environ 2 000","Environ 2 milliards","Environ 200 millions","Environ 2 millions"]'::jsonb, 3, 'Environ 2 millions d’espèces sont décrites, alors que le total est estimé entre quelques millions et plusieurs dizaines de millions.', 3),
    ('3221e0e8-032d-538b-9435-a3810212422d'::uuid, 'svt', '2de', 'Biosphère et diversité des écosystèmes', 'Contrairement à l’énergie, la matière circule en cycle dans un écosystème.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’énergie entre par la photosynthèse puis se dissipe ; la matière (carbone, azote, eau) est recyclée grâce aux décomposeurs.', 4),
    ('c035f2cc-49b9-5b6a-9beb-87d8b03c6735'::uuid, 'svt', '2de', 'La diversité génétique au sein d’une espèce', 'Combien d’allèles de chaque gène possède un individu diploïde ?', 'mcq', '["Un seul","Deux","Quatre","Autant que de cellules"]'::jsonb, 1, 'Un individu diploïde a deux chromosomes de chaque paire, donc deux allèles de chaque gène, identiques ou différents.', 1),
    ('4fb6e031-b759-59c3-a637-443c946bd55f'::uuid, 'svt', '2de', 'La diversité génétique au sein d’une espèce', 'Qu’est-ce que le brassage intrachromosomique ?', 'mcq', '["La répartition indépendante des chromosomes de chaque paire","Des échanges de segments entre chromosomes homologues, le crossing-over","La réunion au hasard de deux gamètes","L’apparition d’un nouvel allèle par mutation"]'::jsonb, 1, 'Le crossing-over échange des morceaux entre chromosomes homologues et crée de nouvelles combinaisons d’allèles sur un même chromosome.', 2),
    ('1911d51f-cf04-5a2f-b373-e0b3a74aca32'::uuid, 'svt', '2de', 'La diversité génétique au sein d’une espèce', 'Parmi ces facteurs, lequel est un agent mutagène ?', 'mcq', '["La fécondation","La lumière visible faible","Le dioxygène de l’air","Les rayons UV"]'::jsonb, 3, 'Les UV, les rayons X et certaines substances chimiques augmentent la fréquence des mutations : ils les provoquent.', 3),
    ('8715744f-980c-5b62-a1b8-25c3cfb465ed'::uuid, 'svt', '2de', 'La diversité génétique au sein d’une espèce', 'Pourquoi un cheptel très sélectionné est-il fragile ?', 'mcq', '["Parce que sa faible diversité génétique réduit la probabilité qu’un individu porte un allèle avantageux","Parce qu’il mute trop","Parce qu’il se reproduit trop vite","Parce que ses individus ont plus de chromosomes"]'::jsonb, 0, 'Moins de diversité, moins de chances qu’au moins certains individus résistent à une maladie ou à un changement du milieu.', 4),
    ('08f5a394-94df-5a2f-9810-21193b7c9dae'::uuid, 'svt', '2de', 'La biodiversité et son évolution dans le temps', 'Dans une très grande population, que deviennent les effets de la dérive génétique ?', 'mcq', '["Ils s’amplifient","Ils font toujours disparaître un allèle","Ils s’annulent en grande partie","Ils créent de nouveaux allèles"]'::jsonb, 2, 'Dans une grande population, les écarts dus au hasard se compensent ; c’est dans une petite population qu’un allèle peut disparaître par hasard.', 1),
    ('65378aa2-774a-5db7-b568-0715e709ca35'::uuid, 'svt', '2de', 'La biodiversité et son évolution dans le temps', 'Pourquoi la forme sombre de la phalène est-elle devenue majoritaire pendant l’industrialisation ?', 'mcq', '["La suie a fait muter les papillons clairs","Les papillons se sont teints pour se cacher","Sur les troncs noircis, elle était moins visible des oiseaux et survivait mieux","Par pur hasard, comme la dérive"]'::jsonb, 2, 'Les formes sombres, moins repérées par les prédateurs, laissaient plus de descendants : c’est de la sélection naturelle, pas une mutation provoquée.', 2),
    ('f7be1f37-3775-5aac-ac7d-18c7a79bef91'::uuid, 'svt', '2de', 'La biodiversité et son évolution dans le temps', 'Quelle étape précède l’accumulation de différences génétiques menant à la spéciation ?', 'mcq', '["L’isolement des populations","L’hybridation","La fécondation croisée","Une crise biologique"]'::jsonb, 0, 'Une barrière géographique, un décalage des périodes de reproduction ou un comportement différent isole les populations, dont les différences s’accumulent ensuite.', 3),
    ('4f78239e-fdaa-520d-a8e0-b23848a363b8'::uuid, 'svt', '2de', 'La biodiversité et son évolution dans le temps', 'Qu’est-ce qui augmente la fréquence d’un allèle par sélection naturelle ?', 'mcq', '["Le fait qu’il soit récent","Le fait qu’il soit rare","Le fait qu’il soit dominant","Le fait qu’il donne un avantage de survie ou de reproduction"]'::jsonb, 3, 'Les porteurs d’un allèle avantageux dans un environnement donné laissent en moyenne plus de descendants.', 4),
    ('74bb2a61-add9-5f65-af9d-5ecfb605e25f'::uuid, 'svt', '2de', 'Variation naturelle et impact humain', 'Lequel de ces exemples relève de la surexploitation ?', 'mcq', '["La pollution lumineuse","La pêche excessive","L’introduction du frelon asiatique","La construction d’une autoroute"]'::jsonb, 1, 'La surexploitation désigne les prélèvements excessifs : pêche, chasse, cueillette. La route fragmente les habitats, le frelon est une espèce envahissante.', 1),
    ('1703c3da-b49c-530a-87f6-ae7307598c8c'::uuid, 'svt', '2de', 'Variation naturelle et impact humain', 'Que mesurent les indices d’abondance ?', 'mcq', '["Le nombre d’espèces d’un pays","L’évolution des effectifs des populations","Le risque d’extinction d’une espèce","La surface des aires protégées"]'::jsonb, 1, 'Ils suivent les effectifs : ils montrent que même des espèces communes, comme les oiseaux des champs, reculent.', 2),
    ('ebab3850-533c-5db6-aee2-d6d1e110702a'::uuid, 'svt', '2de', 'Variation naturelle et impact humain', 'À quoi sert la convention CITES ?', 'mcq', '["À créer des corridors écologiques","À réduire les émissions de CO2","À classer les espèces sur liste rouge","À encadrer le commerce international des espèces"]'::jsonb, 3, 'La CITES réglemente les prélèvements en encadrant le commerce des espèces menacées.', 3),
    ('c70e6763-d907-5198-b859-06549863d2aa'::uuid, 'svt', '2de', 'Variation naturelle et impact humain', 'Pourquoi une espèce disparaît-elle rarement pour une seule cause ?', 'mcq', '["Parce que les causes s’additionnent : habitat réduit, climat qui change, prélèvements excessifs","Parce que seule la dérive génétique fait disparaître les espèces","Parce que les crises naturelles sont toujours en cause","Parce que les espèces protégées ne disparaissent jamais"]'::jsonb, 0, 'C’est l’addition de plusieurs pressions qui fait basculer une espèce déjà affaiblie.', 4),
    ('88872e9b-f374-551f-a5c3-c5613da9d7f6'::uuid, 'svt', '2de', 'Communication intraspécifique et sélection sexuelle', 'Par quel canal les fourmis tracent-elles une piste vers une source de nourriture ?', 'mcq', '["Sonore","Visuel","Chimique, par des phéromones","Électrique"]'::jsonb, 2, 'Les fourmis déposent des phéromones sur le sol : leurs congénères suivent cette piste chimique.', 1),
    ('3f792550-d3ea-5bf6-a8c8-97693e8f5cdd'::uuid, 'svt', '2de', 'Communication intraspécifique et sélection sexuelle', 'Le bois des cerfs est un exemple de quelle forme de sélection sexuelle ?', 'mcq', '["Intersexuelle : le choix des femelles","Sélection naturelle de survie","Intrasexuelle : l’affrontement entre mâles","Dérive génétique"]'::jsonb, 2, 'Les mâles s’affrontent entre eux pour l’accès aux femelles : c’est la compétition intrasexuelle.', 2),
    ('7df42033-214e-5271-a703-a183ee55aa0d'::uuid, 'svt', '2de', 'Communication intraspécifique et sélection sexuelle', 'Qu’appelle-t-on le dimorphisme sexuel ?', 'mcq', '["Les différences de taille, de couleur ou d’ornements entre mâles et femelles","L’existence de deux chromosomes sexuels","Le choix du partenaire par les femelles","Le fait de se reproduire deux fois par an"]'::jsonb, 0, 'La sélection sexuelle explique une grande part de ces différences, comme la queue du paon mâle.', 3),
    ('feac37a6-31f3-55ee-a358-2b03ea55ab56'::uuid, 'svt', '2de', 'Communication intraspécifique et sélection sexuelle', 'Quel avantage apporte un signal de dissuasion entre rivaux ?', 'mcq', '["Il attire les prédateurs","Il sert à digérer","Il augmente la fécondité","Il permet de défendre un territoire sans combattre"]'::jsonb, 3, 'Dissuader un rival par un chant ou une posture évite un combat coûteux et risqué pour les deux.', 4),
    ('16b5ecb6-5d5e-5741-b44c-e259a7674cc5'::uuid, 'svt', '2de', 'L’érosion, phénomène naturel et inexorable', 'Qu’est-ce qui caractérise l’altération physique ?', 'mcq', '["Elle transforme les minéraux","Elle fragmente la roche sans changer sa composition","Elle ne se produit qu’en climat chaud","Elle dissout le calcaire"]'::jsonb, 1, 'Gel, variations de température, racines ou abrasion cassent la roche en morceaux, sans modifier ses minéraux.', 1),
    ('19f1c4ba-4bf6-52f8-a228-462e8a12d21b'::uuid, 'svt', '2de', 'L’érosion, phénomène naturel et inexorable', 'Quel minéral du granite résiste à l’altération et subsiste en grains ?', 'mcq', '["Le feldspath","Le quartz","Le mica","L’argile"]'::jsonb, 1, 'Le feldspath devient argile, le mica se dégrade, le quartz reste : c’est souvent lui qu’on retrouve en grain de sable.', 2),
    ('3545c0af-65cf-5afa-879d-e66219a8ca75'::uuid, 'svt', '2de', 'L’érosion, phénomène naturel et inexorable', 'Qu’est-ce que l’ablation, deuxième étape de l’érosion ?', 'mcq', '["Le soulèvement des reliefs","Le dépôt des sédiments","La dissolution des roches","L’arrachement des débris"]'::jsonb, 3, 'Après l’altération qui fragilise la roche sur place, l’ablation arrache les débris, puis le transport les emporte.', 3),
    ('787ab712-1ffe-5969-920f-b14429725ab4'::uuid, 'svt', '2de', 'L’érosion, phénomène naturel et inexorable', 'Pourquoi l’érosion n’a-t-elle pas encore aplani tous les continents ?', 'mcq', '["Parce que les forces internes soulèvent de nouveaux reliefs","Parce que les roches sont indestructibles","Parce que l’érosion s’arrête en hiver","Parce que la végétation l’empêche totalement"]'::jsonb, 0, 'Les paysages résultent d’une course entre la surrection, qui crée du relief, et l’érosion, qui l’use.', 4),
    ('c7ff6b7a-e359-5f56-9993-ec909e2b5c0e'::uuid, 'svt', '2de', 'La sédimentation et les roches sédimentaires', 'Quel sédiment se dépose en eau calme, là où le courant est faible ?', 'mcq', '["Les blocs","Les graviers","Les argiles","Les sables"]'::jsonb, 2, 'Plus le courant est faible, plus les particules déposées sont fines : les argiles se déposent en eau calme.', 1),
    ('23ccc04c-16b3-54e8-b8a4-7edecf6c7a7f'::uuid, 'svt', '2de', 'La sédimentation et les roches sédimentaires', 'Que se passe-t-il lors de la compaction ?', 'mcq', '["Des minéraux précipitent et collent les grains","La roche fond","Le poids des dépôts supérieurs chasse l’eau","Les grains s’arrondissent"]'::jsonb, 2, 'La compaction chasse l’eau sous le poids des couches ; la cimentation colle ensuite les grains.', 2),
    ('978cafa3-3d64-5549-b4a5-0231ed2d6c12'::uuid, 'svt', '2de', 'La sédimentation et les roches sédimentaires', 'De quoi la craie du Bassin parisien est-elle constituée ?', 'mcq', '["De squelettes microscopiques d’algues marines","De grains de quartz cimentés","De sel précipité","De lave refroidie"]'::jsonb, 0, 'La craie est une roche biogène, construite par l’accumulation de minuscules squelettes calcaires d’algues.', 3),
    ('ad778269-3e41-541a-ac53-f74483a58cf2'::uuid, 'svt', '2de', 'La sédimentation et les roches sédimentaires', 'Qu’est-ce qu’un conglomérat ?', 'mcq', '["Une roche biogène faite de coquilles","Une roche chimique comme le gypse","Une roche magmatique","Une roche détritique faite de débris"]'::jsonb, 3, 'Le conglomérat, comme le grès et l’argilite, est une roche détritique formée de débris cimentés.', 4),
    ('6be69b2f-bae6-5369-8cb2-38acf2c3ad3c'::uuid, 'svt', '2de', 'Érosion et activité humaine', 'Pourquoi la déforestation aggrave-t-elle l’érosion ?', 'mcq', '["Elle fait geler le sol","Elle augmente le ruissellement et réduit la retenue des sols","Elle empêche la pluie de tomber","Elle dissout les roches"]'::jsonb, 1, 'Sans arbres ni racines, l’eau ruisselle plus et emporte le sol qu’elle ne retient plus.', 1),
    ('39ab2210-8c6b-5ee1-9f5c-063dada320a3'::uuid, 'svt', '2de', 'Érosion et activité humaine', 'À quoi servent les sables industriels ?', 'mcq', '["À fabriquer des briques","À produire du verre et des composants électroniques","À fertiliser les champs","À construire des barrages"]'::jsonb, 1, 'Les sables industriels, très purs, servent au verre et à l’électronique ; les argiles, elles, servent à la brique et à la céramique.', 2),
    ('da7dbbcf-3fea-5e33-ab3a-d5560a69fa3f'::uuid, 'svt', '2de', 'Érosion et activité humaine', 'Quel effet a le surpâturage sur un sol ?', 'mcq', '["Il l’enrichit en humus","Il augmente sa végétation","Il le rend imperméable comme le béton","Il met le sol à nu"]'::jsonb, 3, 'Trop de bétail arrache le couvert végétal : le sol nu est ensuite emporté par l’eau et le vent.', 3),
    ('76a2a196-313a-55c7-ba48-93df3c75a5ca'::uuid, 'svt', '2de', 'Érosion et activité humaine', 'Parmi ces moyens, lequel sert à retenir les particules de sol ?', 'mcq', '["Les bandes enherbées et les haies","Le labour dans le sens de la pente","L’imperméabilisation","L’extraction de granulats"]'::jsonb, 0, 'Haies, talus et bandes enherbées freinent l’eau et piègent les particules avant qu’elles ne partent.', 4),
    ('482092a4-eaaa-51a4-8192-533955b533b6'::uuid, 'svt', '2de', 'L’agriculture, la biomasse végétale et les sols', 'Combien de micro-organismes contient environ un gramme de sol ?', 'mcq', '["Une dizaine","Quelques milliers","Des centaines de millions","Aucun"]'::jsonb, 2, 'Un seul gramme de sol abrite des centaines de millions de micro-organismes : le sol est un écosystème.', 1),
    ('230ef669-eed4-5a68-a6df-20a57fddac4c'::uuid, 'svt', '2de', 'L’agriculture, la biomasse végétale et les sols', 'Quel est l’effet du tassement du sol par les engins lourds ?', 'mcq', '["Le sol s’enrichit en humus","Le sol devient salé","L’air et l’eau ne circulent plus","Les racines poussent mieux"]'::jsonb, 2, 'Un sol tassé perd ses pores : l’air et l’eau n’y circulent plus, la vie du sol et les racines en souffrent.', 2),
    ('b4e9d927-5ef8-549d-874e-07c1a238ed3c'::uuid, 'svt', '2de', 'L’agriculture, la biomasse végétale et les sols', 'Qu’est-ce qui provoque la salinisation d’un sol ?', 'mcq', '["Une irrigation mal maîtrisée","L’apport de fumier","La plantation de haies","La rotation des cultures"]'::jsonb, 0, 'Une irrigation mal conduite accumule des sels en surface et peut rendre le sol stérile.', 3),
    ('7aaa34a4-d09a-5461-aca2-c39ef0983d0a'::uuid, 'svt', '2de', 'L’agriculture, la biomasse végétale et les sols', 'D’où vient la matière minérale d’un sol ?', 'mcq', '["De la décomposition des feuilles","De l’air","Des engrais uniquement","De l’altération de la roche mère"]'::jsonb, 3, 'Sables, limons et argiles proviennent de l’altération de la roche mère ; l’humus, lui, vient de la décomposition de la matière organique.', 4),
    ('5ef20ee1-f669-56c1-96e3-e89b29f1b39c'::uuid, 'svt', '2de', 'Une agriculture pour nourrir les hommes', 'Que devient l’essentiel de l’énergie qui ne passe pas au maillon suivant d’une chaîne alimentaire ?', 'mcq', '["Elle est stockée dans le sol","Elle est dissipée par la respiration et les déchets","Elle est transmise aux producteurs","Elle est détruite par les décomposeurs seulement"]'::jsonb, 1, 'Environ 90 % de l’énergie est perdue à chaque maillon, surtout par la respiration et les déchets.', 1),
    ('73f241ae-a8c3-54db-aab0-02396135f25e'::uuid, 'svt', '2de', 'Une agriculture pour nourrir les hommes', 'Quel modèle agricole cherche d’abord à nourrir la famille du producteur, avec peu d’intrants ?', 'mcq', '["L’agriculture intensive","L’agriculture vivrière","L’agriculture de précision","L’agriculture extensive d’exportation"]'::jsonb, 1, 'L’agriculture vivrière produit d’abord pour la consommation du foyer.', 2),
    ('19311b92-f399-56da-a75b-9df88e1dd869'::uuid, 'svt', '2de', 'Une agriculture pour nourrir les hommes', 'Quel risque est associé à une irrigation intensive ?', 'mcq', '["L’eutrophisation","La hausse de la biodiversité","La résistance des ravageurs","L’épuisement des nappes"]'::jsonb, 3, 'L’irrigation lève la contrainte en eau, mais puiser trop peut épuiser les nappes souterraines.', 3),
    ('1ab71989-e855-5dea-926f-9dfe0454f94d'::uuid, 'svt', '2de', 'Une agriculture pour nourrir les hommes', 'Sur quoi l’agroécologie s’appuie-t-elle ?', 'mcq', '["Sur les régulations naturelles","Sur les OGM","Sur la seule mécanisation","Sur les engrais de synthèse"]'::jsonb, 0, 'L’agroécologie utilise le fonctionnement des écosystèmes (auxiliaires, diversité des cultures) plutôt que des intrants.', 4),
    ('827b20db-f044-5c46-b9f5-4d2a323081bc'::uuid, 'svt', '2de', 'Amélioration des rendements agricoles, santé et environnement', 'Qu’est-ce que le remembrement ?', 'mcq', '["La rotation des cultures","La plantation de haies","Le regroupement des parcelles en grandes parcelles mécanisables","L’irrigation des champs"]'::jsonb, 2, 'Le remembrement a créé de grandes parcelles adaptées aux machines, souvent au prix de la disparition des haies.', 1),
    ('534a9939-9638-5612-a42b-dae213b3ff19'::uuid, 'svt', '2de', 'Amélioration des rendements agricoles, santé et environnement', 'Quel est l’intérêt des rotations longues ?', 'mcq', '["Augmenter la dose d’engrais","Supprimer toute mécanisation","Casser les cycles des ravageurs","Accélérer l’irrigation"]'::jsonb, 2, 'Changer de culture d’une année à l’autre empêche les ravageurs spécialisés de s’installer durablement.', 2),
    ('c0947319-d2e4-5e0f-99e6-e1a1b55f74be'::uuid, 'svt', '2de', 'Amélioration des rendements agricoles, santé et environnement', 'Qui sont les « auxiliaires » des cultures ?', 'mcq', '["Des organismes, comme les coccinelles, qui régulent les ravageurs","Des ouvriers agricoles saisonniers","Des engrais naturels","Des variétés de blé résistantes"]'::jsonb, 0, 'Les auxiliaires, favorisés par les haies, mangent ou parasitent les ravageurs : une régulation gratuite.', 3),
    ('5031cabd-8195-5a9c-b0f1-749c1c5c5c21'::uuid, 'svt', '2de', 'Amélioration des rendements agricoles, santé et environnement', 'Qui est exposé au risque « professionnel » lié aux pesticides ?', 'mcq', '["Les consommateurs","Les animaux d’élevage uniquement","Les touristes","Les agriculteurs"]'::jsonb, 3, 'Ce sont les agriculteurs, qui manipulent et épandent les produits, qui y sont exposés dans leur travail.', 4),
    ('2b098982-04de-5488-a784-470ebd2159dd'::uuid, 'svt', '2de', 'De la fécondation à la puberté', 'Quel chromosome sexuel l’ovule apporte-t-il toujours ?', 'mcq', '["Un chromosome Y","Un chromosome X","Un X ou un Y selon les cas","Aucun chromosome sexuel"]'::jsonb, 1, 'L’ovule apporte toujours un X ; c’est le spermatozoïde, porteur d’un X ou d’un Y, qui détermine le sexe chromosomique.', 1),
    ('9a87d847-181f-57d9-b75c-c2fe79cf204c'::uuid, 'svt', '2de', 'De la fécondation à la puberté', 'Quel est le rôle de l’hormone antimüllérienne chez le fœtus masculin ?', 'mcq', '["Elle développe les testicules","Elle fait régresser l’un des deux jeux de conduits","Elle déclenche la puberté","Elle détermine le sexe chromosomique"]'::jsonb, 1, 'L’embryon possède deux ébauches de conduits ; chez le fœtus masculin, la testostérone développe l’une et l’hormone antimüllérienne fait régresser l’autre.', 2),
    ('1d76f05c-1a81-5eca-af3c-481c458767c8'::uuid, 'svt', '2de', 'De la fécondation à la puberté', 'De quoi dérivent les appareils génitaux masculin et féminin ?', 'mcq', '["D’ébauches différentes dès la fécondation","Du chromosome Y seul","Des gonades de la mère","Des mêmes ébauches embryonnaires"]'::jsonb, 3, 'Même point de départ, deux trajectoires : les deux appareils se développent à partir des mêmes ébauches.', 3),
    ('e765e8f1-0cbf-51ec-baa7-f76bafde0281'::uuid, 'svt', '2de', 'De la fécondation à la puberté', 'Un décalage de plusieurs années dans l’âge de la puberté entre deux adolescents est anormal.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’âge de la puberté varie fortement d’un individu à l’autre, entre 10 et 16 ans environ : cette variabilité est normale.', 4),
    ('a2b72278-9214-5d54-870e-8d0c24f073ef'::uuid, 'svt', '2de', 'Le système nerveux et la sexualité', 'Qu’est-ce qu’un réflexe ?', 'mcq', '["Une réponse automatique par un circuit court, sans décision consciente","Une réponse décidée consciemment","Une hormone","Un apprentissage culturel"]'::jsonb, 0, 'Un réflexe associe un stimulus à une réponse par un circuit court, ici dans la moelle épinière.', 1),
    ('630d9117-a68f-5ee0-b172-b28baf8fa748'::uuid, 'svt', '2de', 'Le système nerveux et la sexualité', 'Quel est le rôle du cerveau vis-à-vis des réflexes sexuels ?', 'mcq', '["Il les supprime toujours","Il les produit seul","Il les module","Il n’a aucun rôle"]'::jsonb, 2, 'Le cerveau module les réponses automatiques de la moelle épinière, en fonction du contexte, des émotions et de la relation.', 2),
    ('dfd9e7d3-a256-5920-9cf3-5b545ce9abeb'::uuid, 'svt', '2de', 'Le système nerveux et la sexualité', 'Que signifie un consentement « éclairé » ?', 'mcq', '["Donné sans contrainte","Donné devant témoins","Donné en connaissance de cause","Donné une fois pour toutes"]'::jsonb, 2, 'Éclairé veut dire que la personne sait à quoi elle consent ; « libre » signifie sans contrainte ni pression.', 3),
    ('5ae2c412-f09d-5fcc-b0b7-ac5f5208def5'::uuid, 'svt', '2de', 'Le système nerveux et la sexualité', 'Quel facteur influence la sexualité humaine au même titre que la biologie ?', 'mcq', '["La culture et les normes sociales","La saison uniquement","La couleur des yeux","Le groupe sanguin"]'::jsonb, 0, 'Histoire personnelle, apprentissages, culture et relation façonnent la sexualité humaine, qui ne dépend pas que des hormones.', 4),
    ('d28ca527-2763-5730-95e5-536fe1f0890d'::uuid, 'svt', '2de', 'Le rôle des hormones dans la reproduction', 'Quel organe commande l’hypophyse ?', 'mcq', '["L’utérus","L’ovaire","Le testicule","L’hypothalamus"]'::jsonb, 3, 'L’hypothalamus produit une hormone de commande qui agit sur l’hypophyse, laquelle sécrète FSH et LH.', 1),
    ('0e300c3a-52c5-5df9-853c-2f544568c096'::uuid, 'svt', '2de', 'Le rôle des hormones dans la reproduction', 'Quel est le rôle de la FSH chez la femme en première phase du cycle ?', 'mcq', '["Déclencher les règles","Permettre la maturation d’un follicule ovarien","Produire la progestérone","Bloquer l’ovulation"]'::jsonb, 1, 'La FSH fait mûrir un follicule ; c’est ensuite le pic de LH qui déclenche l’ovulation.', 2),
    ('609054df-3998-5253-a054-c5650b3eb4d9'::uuid, 'svt', '2de', 'Le rôle des hormones dans la reproduction', 'Comment agit la contraception d’urgence ?', 'mcq', '["Elle détruit l’embryon","Elle retarde l’ovulation","Elle protège des IST","Elle agit comme une barrière mécanique"]'::jsonb, 1, 'La contraception d’urgence retarde l’ovulation : elle doit être prise au plus vite après le rapport.', 3),
    ('594e4ad5-5e25-56cc-bfd9-4364e47c74f8'::uuid, 'svt', '2de', 'Le rôle des hormones dans la reproduction', 'Chez l’homme, comment se fait la production de spermatozoïdes ?', 'mcq', '["Par cycles de 28 jours","Une fois par an","Uniquement à la puberté","De façon continue"]'::jsonb, 3, 'Chez l’homme, la production est continue et le taux de testostérone reste stable grâce au rétrocontrôle négatif.', 4),
    ('87400f52-e467-5ba2-ba38-85714aed6fce'::uuid, 'svt', '2de', 'Agents pathogènes et maladies à vecteur', 'Quel type d’agent pathogène cause une mycose ?', 'mcq', '["Un champignon microscopique","Un virus","Une bactérie","Un protozoaire"]'::jsonb, 0, 'Les mycoses sont causées par des champignons microscopiques, qui sont des eucaryotes.', 1),
    ('1cc178ed-e0f7-5748-86c5-008b598d50c1'::uuid, 'svt', '2de', 'Agents pathogènes et maladies à vecteur', 'Quelle est la nature de l’agent de la maladie de Lyme ?', 'mcq', '["Un virus","Un protozoaire","Une bactérie","Un champignon"]'::jsonb, 2, 'La tique transmet une bactérie ; le moustique tigre, lui, transmet des virus (dengue, chikungunya, Zika).', 2),
    ('38609618-eb2b-5133-95e0-27a36a71553e'::uuid, 'svt', '2de', 'Agents pathogènes et maladies à vecteur', 'Pourquoi la lutte contre une maladie à vecteur est-elle complexe ?', 'mcq', '["Parce qu’il n’existe aucun moyen de prévention","Parce que les vecteurs sont invisibles","Parce que le parasite accomplit souvent une partie de son cycle dans le vecteur","Parce que ces maladies ne touchent que les animaux"]'::jsonb, 2, 'Le vecteur n’est pas un simple transporteur : il fait partie du cycle de vie du parasite.', 3),
    ('2d213d59-f43a-517e-b378-d143a1b884c4'::uuid, 'svt', '2de', 'Agents pathogènes et maladies à vecteur', 'Une salmonellose attrapée en mangeant un aliment contaminé relève de quel mode de transmission ?', 'mcq', '["Indirecte","Directe","Vectorielle","Héréditaire"]'::jsonb, 0, 'La transmission indirecte passe par l’eau, les aliments ou les objets, sans contact entre les personnes.', 4),
    ('ec0ccb3d-d446-5463-b35f-05d8312f452d'::uuid, 'svt', '2de', 'Symbiose et microbiote humain', 'Qu’est-ce que le commensalisme ?', 'mcq', '["Les deux partenaires y gagnent","Les deux y perdent","L’un gagne aux dépens de l’autre","L’un gagne, l’autre est indifférent"]'::jsonb, 3, 'Dans le commensalisme, l’un profite de l’association sans nuire ni bénéficier à l’autre.', 1),
    ('6766e412-e815-5312-bf1d-cd9e86112fff'::uuid, 'svt', '2de', 'Symbiose et microbiote humain', 'Qu’apportent les micro-organismes du rumen aux ruminants ?', 'mcq', '["De l’azote de l’air","La digestion de la cellulose","La photosynthèse","Une protection contre les prédateurs"]'::jsonb, 1, 'Les ruminants ne savent pas dégrader la cellulose : ce sont les micro-organismes de leur rumen qui le font.', 2),
    ('20f9b239-c418-5746-8d16-6c8bc278a30f'::uuid, 'svt', '2de', 'Symbiose et microbiote humain', 'Comment le nombre de cellules du microbiote se compare-t-il à celui des cellules du corps humain ?', 'mcq', '["Il est mille fois plus faible","Il est du même ordre de grandeur","Il est un million de fois plus grand","Il est nul chez l’adulte"]'::jsonb, 1, 'Le microbiote compte à peu près autant de cellules que le corps, mais porte bien plus de gènes que le génome humain.', 3),
    ('a3b02df7-16d8-59eb-8189-29515d07c462'::uuid, 'svt', '2de', 'Symbiose et microbiote humain', 'Parmi ces fonctions, laquelle est assurée par le microbiote ?', 'mcq', '["La production d’hémoglobine","La transmission des messages nerveux","La contraction des muscles","La maturation du système immunitaire"]'::jsonb, 3, 'Le microbiote éduque le système immunitaire, en plus de participer à la digestion, à la synthèse de vitamines et à l’effet barrière.', 4),
    ('fe6426dc-6544-5c4a-a657-7002cca3a0c8'::uuid, 'svt', '2de', 'Microbiote intestinal et santé', 'Pourquoi avons-nous besoin du microbiote pour tirer profit des fibres ?', 'mcq', '["Parce que nos propres enzymes ne savent pas les digérer","Parce que les fibres sont toxiques","Parce que l’estomac les détruit","Parce qu’elles sont absorbées par la peau"]'::jsonb, 0, 'Nos enzymes ne dégradent pas les fibres : le microbiote les transforme en acides gras à chaîne courte utiles à la paroi intestinale.', 1),
    ('e87bc26b-ca83-5c37-bd84-6d8bc46882e3'::uuid, 'svt', '2de', 'Microbiote intestinal et santé', 'Quel type d’alimentation appauvrit la diversité du microbiote ?', 'mcq', '["Une alimentation riche en légumes et légumineuses","Une alimentation riche en aliments fermentés","Une alimentation pauvre en fibres et riche en produits ultratransformés","Une alimentation variée"]'::jsonb, 2, 'Moins de fibres, c’est moins de nourriture pour les bactéries utiles : la diversité recule.', 2),
    ('61244a55-4a34-5564-82f5-0283a25421d9'::uuid, 'svt', '2de', 'Microbiote intestinal et santé', 'Que peut-on dire du lien entre dysbiose et obésité, d’après le cours ?', 'mcq', '["La dysbiose cause l’obésité, c’est démontré","Il n’existe aucun lien","C’est une association, pas une cause démontrée","L’obésité guérit la dysbiose"]'::jsonb, 2, 'Une association statistique ne prouve pas qu’un facteur cause l’autre : la recherche est encore en cours.', 3),
    ('44c52212-2c29-5169-b24c-c06cba674f48'::uuid, 'svt', '2de', 'Microbiote intestinal et santé', 'Contre quelle bactérie la transplantation de microbiote fécal est-elle reconnue ?', 'mcq', '["Clostridioides difficile","Le bacille de la tuberculose","Le streptocoque de l’angine","Rhizobium"]'::jsonb, 0, 'Elle traite des infections récidivantes à Clostridioides difficile, là où les antibiotiques échouent.', 4),
    ('4b076c60-f60d-5dda-8ff6-47c636c5dadb'::uuid, 'sport', '2de', 'S’entraîner et planifier', 'Comment se mesure l’intensité d’un entraînement ?', 'mcq', '["En nombre de séances par semaine","En pourcentage de VMA ou de charge maximale","En temps de récupération entre les séries","En kilomètres parcourus au total"]'::jsonb, 1, 'L’intensité, c’est la difficulté du travail : on la règle en pourcentage de la VMA ou de la charge maximale.', 1),
    ('191283f3-4dbd-5467-b33d-78870d049fd7'::uuid, 'sport', '2de', 'S’entraîner et planifier', 'De combien augmenter la charge d’une semaine à l’autre, au plus ?', 'mcq', '["De 50 %","Du double","De 5 à 10 %","De 25 à 30 %"]'::jsonb, 2, 'La progressivité impose des paliers de 5 à 10 % par semaine : au-delà, le risque de blessure grimpe.', 2),
    ('319262d3-2ee5-51af-88af-ad82947b35fb'::uuid, 'sport', '2de', 'S’entraîner et planifier', 'Pourquoi ne modifier qu’un seul paramètre de la charge à la fois ?', 'mcq', '["Pour savoir lequel a produit le progrès, ou la blessure","Pour que la séance soit plus courte","Parce que le règlement l’impose","Parce que les autres paramètres ne comptent pas"]'::jsonb, 0, 'Deux changements simultanés rendent l’effet illisible : on ne sait plus lequel a agi.', 3),
    ('5877506d-cca2-510e-b262-3d44391a4072'::uuid, 'sport', '2de', 'S’entraîner et planifier', 'Que se passe-t-il si l’on reprend l’entraînement trop tôt, en pleine fatigue ?', 'mcq', '["On progresse plus vite","On atteint directement la surcompensation","On ne perd rien","On s’épuise sans construire"]'::jsonb, 3, 'Reprendre pendant la phase de fatigue empêche la récupération : c’est elle qui fait progresser, pas l’effort seul.', 4),
