    ('0ef0dcdb-345c-52fe-b91d-0b15362e7f51'::uuid, 'sport', '2de', 'Sport, société et valeurs', 'Quels Jeux olympiques ont servi de vitrine au régime nazi ?', 'mcq', '["Mexico 1968","Berlin 1936","Moscou 1980","Paris 1924"]'::jsonb, 1, 'Les Jeux de Berlin, en 1936, ont été utilisés par le régime nazi pour sa propagande.', 1),
    ('d3784d97-5ebc-5f65-9ec7-7eed0a82958a'::uuid, 'sport', '2de', 'Sport, société et valeurs', 'Que révèlent les boycotts croisés des Jeux de 1980 et 1984 ?', 'mcq', '["Le problème du dopage","L’inégalité femmes-hommes","La guerre froide jusque dans le stade","La naissance du sport professionnel"]'::jsonb, 2, 'Les Américains boycottent Moscou en 1980, les Soviétiques Los Angeles en 1984 : la guerre froide s’invite aux Jeux.', 2),
    ('5bbb465b-0b76-52d0-b122-d6e148e4d34f'::uuid, 'sport', '2de', 'Sport, société et valeurs', 'Quelles valeurs l’olympisme affiche-t-il ?', 'mcq', '["Excellence, amitié, respect","Victoire, argent, gloire","Force, vitesse, endurance","Liberté, égalité, fraternité"]'::jsonb, 0, 'Les Jeux modernes se réclament de l’excellence, de l’amitié et du respect — tout en étant aussi une scène politique.', 3),
    ('8ced66e8-fc0a-52b4-8292-9adab8b1440c'::uuid, 'sport', '2de', 'Sport, société et valeurs', 'Depuis 2016, que peut prescrire un médecin pour une maladie chronique ?', 'mcq', '["Un produit dopant autorisé","Une dispense définitive de sport","Une boisson énergisante","Une activité physique adaptée"]'::jsonb, 3, 'L’activité physique adaptée peut être prescrite comme un soin : la sédentarité est un facteur de risque majeur.', 4),
    ('4f36a37a-0e9f-5a44-b8fc-544273922837'::uuid, 'sport', '1re', 'Sport, société et valeurs', 'Quels Jeux olympiques ont servi de vitrine au régime nazi ?', 'mcq', '["Mexico 1968","Berlin 1936","Moscou 1980","Paris 1924"]'::jsonb, 1, 'Les Jeux de Berlin, en 1936, ont été utilisés par le régime nazi pour sa propagande.', 1),
    ('97119381-78ca-5814-a81e-b86b0a782424'::uuid, 'sport', '1re', 'Sport, société et valeurs', 'Que révèlent les boycotts croisés des Jeux de 1980 et 1984 ?', 'mcq', '["Le problème du dopage","L’inégalité femmes-hommes","La guerre froide jusque dans le stade","La naissance du sport professionnel"]'::jsonb, 2, 'Les Américains boycottent Moscou en 1980, les Soviétiques Los Angeles en 1984 : la guerre froide s’invite aux Jeux.', 2),
    ('f8c5fff8-fe19-5635-9a51-8c7181ff80c8'::uuid, 'sport', '1re', 'Sport, société et valeurs', 'Quelles valeurs l’olympisme affiche-t-il ?', 'mcq', '["Excellence, amitié, respect","Victoire, argent, gloire","Force, vitesse, endurance","Liberté, égalité, fraternité"]'::jsonb, 0, 'Les Jeux modernes se réclament de l’excellence, de l’amitié et du respect — tout en étant aussi une scène politique.', 3),
    ('3efa86b8-c773-5393-9297-ae85673de045'::uuid, 'sport', '1re', 'Sport, société et valeurs', 'Depuis 2016, que peut prescrire un médecin pour une maladie chronique ?', 'mcq', '["Un produit dopant autorisé","Une dispense définitive de sport","Une boisson énergisante","Une activité physique adaptée"]'::jsonb, 3, 'L’activité physique adaptée peut être prescrite comme un soin : la sédentarité est un facteur de risque majeur.', 4),
    ('0b357184-2192-58d4-a287-b681a554d88e'::uuid, 'sport', 'Tle', 'Sport, société et valeurs', 'Quels Jeux olympiques ont servi de vitrine au régime nazi ?', 'mcq', '["Mexico 1968","Berlin 1936","Moscou 1980","Paris 1924"]'::jsonb, 1, 'Les Jeux de Berlin, en 1936, ont été utilisés par le régime nazi pour sa propagande.', 1),
    ('ccffc132-842b-5b4b-addf-ce693f6717c8'::uuid, 'sport', 'Tle', 'Sport, société et valeurs', 'Que révèlent les boycotts croisés des Jeux de 1980 et 1984 ?', 'mcq', '["Le problème du dopage","L’inégalité femmes-hommes","La guerre froide jusque dans le stade","La naissance du sport professionnel"]'::jsonb, 2, 'Les Américains boycottent Moscou en 1980, les Soviétiques Los Angeles en 1984 : la guerre froide s’invite aux Jeux.', 2),
    ('d39d5531-79be-5a5e-aebc-ef00c504223c'::uuid, 'sport', 'Tle', 'Sport, société et valeurs', 'Quelles valeurs l’olympisme affiche-t-il ?', 'mcq', '["Excellence, amitié, respect","Victoire, argent, gloire","Force, vitesse, endurance","Liberté, égalité, fraternité"]'::jsonb, 0, 'Les Jeux modernes se réclament de l’excellence, de l’amitié et du respect — tout en étant aussi une scène politique.', 3),
    ('720c6db7-0ff8-53ea-b3ba-43275992c342'::uuid, 'sport', 'Tle', 'Sport, société et valeurs', 'Depuis 2016, que peut prescrire un médecin pour une maladie chronique ?', 'mcq', '["Un produit dopant autorisé","Une dispense définitive de sport","Une boisson énergisante","Une activité physique adaptée"]'::jsonb, 3, 'L’activité physique adaptée peut être prescrite comme un soin : la sédentarité est un facteur de risque majeur.', 4),
    ('c64b4397-a8aa-5324-bb1d-c95833030f78'::uuid, 'maths', '1re', 'Les suites numériques', 'Pour la suite définie par u(n) = 3n − 2, que vaut u(4) ?', 'mcq', '["12","7","10","14"]'::jsonb, 2, 'On remplace n par 4 : 3 × 4 − 2 = 10. C’est l’avantage d’une définition explicite.', 1),
    ('f893c589-8c7c-5864-9cc4-53ab75b12610'::uuid, 'maths', '1re', 'Les suites numériques', 'On a u(0) = 5 et u(n+1) = 2 u(n) + 1. Que vaut u(2) ?', 'mcq', '["11","23","21","13"]'::jsonb, 1, 'u(1) = 2 × 5 + 1 = 11, puis u(2) = 2 × 11 + 1 = 23 : avec une récurrence, on avance pas à pas.', 2),
    ('9c25b968-12de-5a3e-af83-5a83935491dd'::uuid, 'maths', '1re', 'Les suites numériques', 'Quand peut-on comparer u(n+1) / u(n) à 1 pour étudier les variations ?', 'mcq', '["Pour n’importe quelle suite","Seulement si la suite est arithmétique","Seulement si la suite est majorée","Seulement si tous les termes sont strictement positifs"]'::jsonb, 3, 'Si un terme était négatif, l’inégalité changerait de sens en multipliant : la méthode du quotient exige des termes strictement positifs.', 3),
    ('93ef82e5-0d1f-5dbd-8993-5919c971c6a8'::uuid, 'maths', '1re', 'Les suites numériques', 'Que signifie « la suite (u) est majorée » ?', 'mcq', '["Il existe un nombre M tel que u(n) ≤ M pour tout n","Elle est croissante","Tous ses termes sont positifs","Elle tend vers plus l’infini"]'::jsonb, 0, 'Un majorant est un plafond que la suite ne dépasse jamais ; une suite croissante peut très bien ne pas en avoir.', 4),
    ('07362931-873c-5c23-866c-7ab332dce6db'::uuid, 'maths', '1re', 'Les suites arithmétiques et géométriques', 'Une suite arithmétique vérifie u(3) = 10 et a pour raison r = 4. Que vaut u(10) ?', 'mcq', '["40","38","50","44"]'::jsonb, 1, 'On utilise u(n) = u(p) + (n − p) × r : u(10) = 10 + 7 × 4 = 38.', 1),
    ('5a2bb672-7584-5a8d-b511-0e5b7ce76de5'::uuid, 'maths', '1re', 'Les suites arithmétiques et géométriques', 'Comment se représentent graphiquement les termes d’une suite arithmétique ?', 'mcq', '["Par des points alignés","Par une courbe qui s’emballe","Par une parabole","Par des points sur un cercle"]'::jsonb, 0, 'Chaque pas ajoute la même raison r : les points (n ; u(n)) sont sur une droite, c’est une croissance linéaire.', 2),
    ('88bfde8d-d0a5-5850-87f6-b708970f4c20'::uuid, 'maths', '1re', 'Les suites arithmétiques et géométriques', 'Quelle est la raison de la suite géométrique qui modélise une baisse de 5 % par an ?', 'mcq', '["0,05","−0,05","0,95","1,05"]'::jsonb, 2, 'Une évolution de t % revient à multiplier par 1 + t / 100 ; ici 1 − 0,05 = 0,95.', 3),
    ('d71a9937-6577-52b3-a155-b80803a7d7ae'::uuid, 'maths', '1re', 'Les suites arithmétiques et géométriques', 'Que vaut la somme 1 + 2 + 2² + … + 2⁵ ?', 'mcq', '["32","64","31","63"]'::jsonb, 3, 'Avec q = 2 et n = 5 : (1 − 2⁶) / (1 − 2) = (1 − 64) / (−1) = 63.', 4),
    ('e01af88a-ed77-57bb-8519-9a9cf8baf492'::uuid, 'maths', '1re', 'Le second degré', 'Pour f(x) = x² − 5x + 6, que vaut le discriminant Δ ?', 'mcq', '["1","49","−1","11"]'::jsonb, 0, 'Δ = b² − 4ac = 25 − 24 = 1 : il est positif, donc le trinôme a deux racines, 2 et 3.', 1),
    ('1c39ca98-49a0-5ce9-8d53-283880f17288'::uuid, 'maths', '1re', 'Le second degré', 'Dans la forme canonique a (x − α)² + β, que représente le point (α ; β) ?', 'mcq', '["Les deux racines","Le sommet de la parabole","L’ordonnée à l’origine","Le point d’intersection avec l’axe des abscisses"]'::jsonb, 1, 'La forme canonique donne à lire le sommet, avec α = −b / (2a) et β = f(α).', 2),
    ('b287d9d9-cbab-5113-859e-a1e2ed8458b2'::uuid, 'maths', '1re', 'Le second degré', 'Quelle forme du trinôme donne directement l’ordonnée à l’origine ?', 'mcq', '["La forme canonique","La forme factorisée","La forme développée","Aucune des trois"]'::jsonb, 2, 'Dans a x² + b x + c, f(0) = c : la forme développée donne l’ordonnée à l’origine sans calcul.', 3),
    ('c0393f59-e848-5baa-9887-2f048a5aefaf'::uuid, 'maths', '1re', 'Le second degré', 'Que vaut le produit des racines d’un trinôme a x² + b x + c qui en a deux ?', 'mcq', '["−b / a","b / a","−c / a","c / a"]'::jsonb, 3, 'La somme des racines vaut −b / a et leur produit c / a : de quoi vérifier un calcul de racines en un instant.', 4),
    ('278e0958-f906-5dc7-92dd-2e596cbf910e'::uuid, 'maths', '1re', 'Dérivation', 'Quelle est la dérivée de √x, pour x > 0 ?', 'mcq', '["2√x","1 / (2√x)","√x / 2","1 / √x"]'::jsonb, 1, '(√x)’ = 1 / (2√x) ; elle n’est définie que pour x strictement positif.', 1),
    ('99fa891d-b53e-5ca3-8b94-c38135dd491d'::uuid, 'maths', '1re', 'Dérivation', 'Quelle est la dérivée de f(x) = x³ ?', 'mcq', '["3x²","x²","3x³","3x"]'::jsonb, 0, 'On applique (x puissance n)’ = n × x puissance (n − 1) avec n = 3.', 2),
    ('6a075b36-271e-5fc0-9151-b83295e9e048'::uuid, 'maths', '1re', 'Dérivation', 'Que vaut la dérivée de 1 / v ?', 'mcq', '["1 / v’","v’ / v²","−1 / v²","−v’ / v²"]'::jsonb, 3, '(1 / v)’ = −v’ / v² : on retrouve −1 / x² pour v(x) = x.', 3),
    ('661dc514-c591-51d9-8b79-9203dbd6f941'::uuid, 'maths', '1re', 'Dérivation', 'Pour f(x) = x³, que se passe-t-il en 0 ?', 'mcq', '["f admet un maximum","f admet un minimum","La tangente est horizontale mais f reste croissante","f n’est pas dérivable"]'::jsonb, 2, 'f’(0) = 0 sans changement de signe : il n’y a pas d’extremum. C’est le contre-exemple classique.', 4),
    ('499975a5-00b5-529f-a859-69f112089365'::uuid, 'maths', '1re', 'Variations et courbes représentatives de fonctions', 'Quelle valeur faut-il exclure de l’ensemble de définition de f(x) = 1 / (x − 2) ?', 'mcq', '["0","2","−2","1"]'::jsonb, 1, 'La division par zéro est interdite : x − 2 ne doit pas s’annuler, donc x ≠ 2.', 1),
    ('e6e1aac5-d570-52e4-8f48-e0f90f661f69'::uuid, 'maths', '1re', 'Variations et courbes représentatives de fonctions', 'Qu’appelle-t-on un extremum global ?', 'mcq', '["Un extremum sur tout l’ensemble de définition","Un extremum sur un petit intervalle autour du point","Un point où la courbe coupe l’axe des abscisses","Un point où la dérivée est positive"]'::jsonb, 0, 'Un extremum local ne vaut qu’autour du point ; un extremum global vaut sur tout l’ensemble de définition.', 2),
    ('aef3b7d5-3c43-5049-998e-11364ae3695b'::uuid, 'maths', '1re', 'Variations et courbes représentatives de fonctions', 'Quelle symétrie a la courbe d’une fonction impaire ?', 'mcq', '["Par rapport à l’axe des abscisses","Par rapport à l’axe des ordonnées","Par rapport à la droite y = x","Par rapport à l’origine"]'::jsonb, 3, 'Une fonction impaire vérifie f(−x) = −f(x) : sa courbe est symétrique par rapport à l’origine.', 3),
    ('0c81d028-c94f-5701-bdc3-deed530d0bb5'::uuid, 'maths', '1re', 'Variations et courbes représentatives de fonctions', 'Sans stricte monotonie, que garantit encore le théorème des valeurs intermédiaires pour une fonction continue ?', 'mcq', '["Rien du tout","L’unicité de la solution","L’existence d’au moins une solution","Que la solution est un entier"]'::jsonb, 2, 'La continuité suffit pour l’existence ; c’est la stricte monotonie qui apporte l’unicité.', 4),
    ('d3ce7cc5-c442-5557-bd37-c8ff11d44694'::uuid, 'maths', '1re', 'Fonction exponentielle', 'Que vaut e puissance (−a) ?', 'mcq', '["−e puissance a","1 / (e puissance a)","e puissance a","0"]'::jsonb, 1, 'Puisque e puissance a × e puissance (−a) = e puissance 0 = 1, on a e puissance (−a) = 1 / (e puissance a).', 1),
    ('069080a2-9341-5873-b7ec-aecd935533e6'::uuid, 'maths', '1re', 'Fonction exponentielle', 'Quelle est une valeur approchée du nombre e ?', 'mcq', '["2,718","3,142","1,414","1,618"]'::jsonb, 0, 'e ≈ 2,718 est l’image de 1 par la fonction exponentielle ; 3,142 est π, 1,414 est √2.', 2),
    ('f6ce71ae-5069-5a79-9d18-454887f6c7a3'::uuid, 'maths', '1re', 'Fonction exponentielle', 'Quelle est la dérivée de e puissance (x²) ?', 'mcq', '["e puissance (x²)","x² e puissance (x²)","e puissance (2x)","2x e puissance (x²)"]'::jsonb, 3, 'On applique (e puissance u)’ = u’ × e puissance u avec u = x², donc u’ = 2x.', 3),
    ('89c8ec89-7017-5abb-bdc3-50e0eef4a7aa'::uuid, 'maths', '1re', 'Fonction exponentielle', 'On étudie le signe de (x − 1) × e puissance x. De quoi dépend-il ?', 'mcq', '["Du signe de e puissance x","Des deux facteurs à la fois","Uniquement du signe de x − 1","Il est toujours positif"]'::jsonb, 2, 'L’exponentielle est strictement positive : elle ne change jamais le signe d’un produit.', 4),
    ('b9a53d21-4825-5b88-bbd3-e3595688a819'::uuid, 'maths', '1re', 'Fonctions trigonométriques', 'Combien de radians valent 45° ?', 'mcq', '["π/4","π/6","π/3","π/2"]'::jsonb, 0, '180° correspondent à π radians ; 45° en sont le quart, soit π/4.', 1),
    ('6bc1dce2-2857-5bcc-8def-7e2bc928ceb1'::uuid, 'maths', '1re', 'Fonctions trigonométriques', 'Que vaut cos(π − x) ?', 'mcq', '["cos x","−cos x","sin x","−sin x"]'::jsonb, 1, 'Les points associés à x et à π − x sont symétriques par rapport à l’axe des ordonnées : même sinus, cosinus opposés.', 2),
    ('c0c58139-c0df-53a2-b5f0-a9dcf98a3265'::uuid, 'maths', '1re', 'Fonctions trigonométriques', 'Quelle est la dérivée de la fonction sinus ?', 'mcq', '["−sin x","−cos x","cos x","sin x"]'::jsonb, 2, '(sin x)’ = cos x ; c’est la dérivée du cosinus qui porte un signe moins.', 3),
    ('dc7da18f-7e8c-5039-a082-9f774ae1c7f4'::uuid, 'maths', '1re', 'Fonctions trigonométriques', 'Que vaut sin(π/6) ?', 'mcq', '["√3 / 2","√2 / 2","1","1/2"]'::jsonb, 3, 'À π/6 (30°), le sinus vaut 1/2 et le cosinus √3 / 2 ; à π/3, c’est l’inverse.', 4),
    ('691c9afe-2a50-5f98-b4c8-1be69b9386e8'::uuid, 'maths', '1re', 'Calcul vectoriel et produit scalaire', 'Que vaut le produit scalaire des vecteurs u(2 ; 3) et v(4 ; −1) en repère orthonormé ?', 'mcq', '["11","5","8","−3"]'::jsonb, 1, 'u · v = x x’ + y y’ = 2 × 4 + 3 × (−1) = 8 − 3 = 5.', 1),
    ('0cd67de8-d1f0-5688-b5ac-637303f41bf1'::uuid, 'maths', '1re', 'Calcul vectoriel et produit scalaire', 'Deux vecteurs de normes 3 et 4 forment un angle de 60°. Que vaut leur produit scalaire ?', 'mcq', '["6","12","7","6√3"]'::jsonb, 0, 'u · v = 3 × 4 × cos 60° = 12 × 1/2 = 6.', 2),
    ('d7ba06a1-b207-5c54-809a-43b54779ae27'::uuid, 'maths', '1re', 'Calcul vectoriel et produit scalaire', 'Que permet d’écrire la bilinéarité du produit scalaire ?', 'mcq', '["u · v = v · u","u · u = norme de u au carré","u · (v + w) = u · v + u · w","u · v = 0 si u et v sont orthogonaux"]'::jsonb, 2, 'La bilinéarité, c’est la distributivité et la sortie des coefficients : u · (v + w) = u · v + u · w et (k u) · v = k (u · v).', 3),
    ('30cbd4f6-55a6-5984-8f1a-83c4bb3c0b4b'::uuid, 'maths', '1re', 'Calcul vectoriel et produit scalaire', 'Quelle formule donne le théorème d’Al-Kashi dans un triangle ABC ?', 'mcq', '["a² = b² + c²","a² = b² + c² + 2 b c cos A","a = b + c − 2 cos A","a² = b² + c² − 2 b c cos A"]'::jsonb, 3, 'Al-Kashi vaut dans tout triangle ; quand A = 90°, cos A = 0 et l’on retrouve Pythagore.', 4),
    ('613198c2-47b5-5a41-8521-b40952d152dc'::uuid, 'maths', '1re', 'Géométrie repérée', 'Quel est un vecteur normal à la droite d’équation 2x − 3y + 1 = 0 ?', 'mcq', '["n(2 ; −3)","n(3 ; 2)","n(−3 ; 2)","n(1 ; 2)"]'::jsonb, 0, 'Pour a x + b y + c = 0, le vecteur n(a ; b) est normal ; le vecteur directeur est u(−b ; a), ici u(3 ; 2).', 1),
    ('423a3635-a85f-5e0b-9a89-f5de21b4da23'::uuid, 'maths', '1re', 'Géométrie repérée', 'Quel est le milieu du segment [AB] avec A(2 ; 4) et B(6 ; −2) ?', 'mcq', '["(8 ; 2)","(4 ; 1)","(2 ; −3)","(4 ; 3)"]'::jsonb, 1, 'On fait la moyenne des coordonnées : ((2 + 6) / 2 ; (4 − 2) / 2) = (4 ; 1).', 2),
    ('1d6597b7-bec2-5b71-8b48-2f99b363e8f0'::uuid, 'maths', '1re', 'Géométrie repérée', 'Quel est le coefficient directeur de la droite (AB) avec A(1 ; 2) et B(3 ; 8) ?', 'mcq', '["2","1/3","6","3"]'::jsonb, 3, 'm = (y(B) − y(A)) / (x(B) − x(A)) = (8 − 2) / (3 − 1) = 3.', 3),
    ('09ddf131-d6f4-59ad-bca9-9e0eee2876ec'::uuid, 'maths', '1re', 'Géométrie repérée', 'Après avoir complété les carrés, on obtient (x − 1)² + (y + 2)² = −4. Quel est l’ensemble ?', 'mcq', '["Un cercle de rayon 2","Le point (1 ; −2)","L’ensemble vide","Un cercle de rayon 4"]'::jsonb, 2, 'Une somme de carrés ne peut pas valoir un nombre négatif : aucun point ne convient.', 4),
    ('7be4edb1-5b85-501b-81dc-0fc33b44ef51'::uuid, 'maths', '1re', 'Probabilités conditionnelles et indépendance', 'On a P(A) = 0,4 et P(A)(B) = 0,5. Que vaut P(A inter B) ?', 'mcq', '["0,9","0,2","0,8","0,1"]'::jsonb, 1, 'P(A inter B) = P(A) × P(A)(B) = 0,4 × 0,5 = 0,2 : c’est le produit des branches du chemin.', 1),
    ('b2f71276-0bc5-5be2-b33d-c0d60680a2d4'::uuid, 'maths', '1re', 'Probabilités conditionnelles et indépendance', 'Comment obtient-on la probabilité d’un événement à partir d’un arbre pondéré ?', 'mcq', '["En additionnant les probabilités des chemins qui y mènent","En multipliant toutes les branches de l’arbre","En prenant la branche la plus probable","En divisant par le nombre de chemins"]'::jsonb, 0, 'On multiplie le long d’un chemin, puis on additionne les chemins qui mènent à l’événement : c’est la formule des probabilités totales.', 2),
    ('835f456d-d840-5d70-8680-6a4da9f2814b'::uuid, 'maths', '1re', 'Probabilités conditionnelles et indépendance', 'A et B sont indépendants avec P(B) = 0,3. Que vaut P(A)(B) ?', 'mcq', '["0,7","0","1","0,3"]'::jsonb, 3, 'L’indépendance signifie que savoir A ne change rien : P(A)(B) = P(B).', 3),
    ('3c94c9c1-de64-53b4-802c-8663e3721bbd'::uuid, 'maths', '1re', 'Probabilités conditionnelles et indépendance', 'Comment prouve-t-on que deux événements sont indépendants ?', 'mcq', '["On le voit sur l’énoncé","On vérifie qu’ils sont incompatibles","On vérifie par le calcul que P(A inter B) = P(A) × P(B)","On vérifie que P(A) = P(B)"]'::jsonb, 2, 'L’indépendance ne se devine pas, elle se démontre par un calcul.', 4),
    ('9e411ad3-12b8-52d2-a529-cd405e09bb3c'::uuid, 'maths', '1re', 'Variable aléatoire et loi de probabilité', 'Quelle est l’espérance du lancer d’un dé équilibré à six faces ?', 'mcq', '["3","3,5","4","6"]'::jsonb, 1, '(1 + 2 + 3 + 4 + 5 + 6) / 6 = 21 / 6 = 3,5 : une valeur que le dé ne peut jamais donner.', 1),
    ('aa37abbb-b43f-5d5e-baaa-d5cba5650597'::uuid, 'maths', '1re', 'Variable aléatoire et loi de probabilité', 'Une espérance de gain de −0,50 € signifie que le jeu est…', 'mcq', '["favorable au joueur","équitable","favorable à l’organisateur","impossible à jouer"]'::jsonb, 2, 'En moyenne, sur un grand nombre de parties, le joueur perd 50 centimes par partie : l’organisateur gagne.', 2),
    ('983ea762-c49f-531f-8e7f-f3ac105d837e'::uuid, 'maths', '1re', 'Variable aléatoire et loi de probabilité', 'Que vaut E(2X + 3) si E(X) = 5 ?', 'mcq', '["13","10","16","8"]'::jsonb, 0, 'E(aX + b) = a E(X) + b = 2 × 5 + 3 = 13 ; contrairement à la variance, b reste.', 3),
    ('9389d00c-9e5c-5c03-8889-5e78c4a7f27e'::uuid, 'maths', '1re', 'Variable aléatoire et loi de probabilité', 'Si X est une durée en minutes, en quelle unité s’exprime sa variance ?', 'mcq', '["En minutes","Sans unité","En pourcentage","En minutes au carré"]'::jsonb, 3, 'La variance est dans le carré de l’unité de X ; l’écart type, sa racine, revient en minutes et s’interprète.', 4),
    ('33f0a199-0a2a-53af-aabb-2159e8c66b08'::uuid, 'physique-chimie', '1re', 'La statique des fluides', 'Combien de pascals vaut 1 bar ?', 'mcq', '["1 000 Pa","100 000 Pa","1 013 Pa","10 Pa"]'::jsonb, 1, '1 bar = 100 000 Pa = 10⁵ Pa ; la pression atmosphérique, environ 1 013 hPa, en est très proche.', 1),
    ('77460fcd-f148-5c87-9c32-085398027d49'::uuid, 'physique-chimie', '1re', 'La statique des fluides', 'Quelle est la valeur approximative de la pression atmosphérique au niveau de la mer ?', 'mcq', '["Environ 100 hPa","Environ 10 hPa","Environ 1 013 hPa","Environ 1 013 Pa"]'::jsonb, 2, '1 013 hectopascals, soit environ 101 300 Pa : à peu près 1 bar.', 2),
    ('7b076330-d61b-5d53-b6f3-9a84d9c0a184'::uuid, 'physique-chimie', '1re', 'La statique des fluides', 'Quelle est la direction de la poussée d’Archimède ?', 'mcq', '["Horizontale","Verticale, vers le bas","Perpendiculaire au mouvement du corps","Verticale, vers le haut"]'::jsonb, 3, 'La poussée d’Archimède est toujours verticale et orientée vers le haut, quelle que soit la forme du corps.', 3),
    ('60b7da9d-aaa7-5aaa-9510-0e22fe1717ea'::uuid, 'physique-chimie', '1re', 'La statique des fluides', 'Un gaz occupe 2,0 L sous 1,0 bar. À température constante, on le comprime jusqu’à 0,50 L. Quelle est sa nouvelle pression ?', 'mcq', '["4,0 bar","0,25 bar","2,0 bar","1,0 bar"]'::jsonb, 0, 'Loi de Mariotte : p × V reste constant, donc p = 1,0 × 2,0 / 0,50 = 4,0 bar. Volume divisé par quatre, pression multipliée par quatre.', 4),
    ('57e6d5a5-4bfa-5259-8977-a147285dcf8f'::uuid, 'physique-chimie', '1re', 'Mouvements et cinématique', 'Un passager est assis dans un train qui roule. Dans le référentiel du sol, il est…', 'mcq', '["immobile","en mouvement","sans vitesse définie","en chute libre"]'::jsonb, 1, 'Dans le référentiel du train, il est immobile ; dans celui du sol, il se déplace avec le train. Le mouvement dépend toujours du référentiel.', 1),
    ('c14533c1-387a-570d-b472-5163ddfaaadb'::uuid, 'physique-chimie', '1re', 'Mouvements et cinématique', 'Vers où est dirigée l’accélération d’un mobile en mouvement circulaire uniforme ?', 'mcq', '["Vers l’extérieur du cercle","Dans le sens du mouvement","Vers le centre du cercle","Elle n’a pas de direction, elle est nulle"]'::jsonb, 2, 'La valeur de la vitesse ne change pas, mais sa direction tourne : l’accélération est dirigée vers le centre.', 2),
    ('44beb72f-9b01-5c65-84d4-2a6b93fe1554'::uuid, 'physique-chimie', '1re', 'Mouvements et cinématique', 'Dans un mouvement rectiligne uniformément accéléré, comment varie la vitesse ?', 'mcq', '["Elle reste constante","Elle varie comme le carré du temps","Elle diminue toujours","Elle varie linéairement avec le temps"]'::jsonb, 3, 'L’accélération est constante : la vitesse augmente (ou diminue) de la même quantité à chaque seconde.', 3),
    ('b533e285-511d-5ac7-8a5d-c7e6c8fd0204'::uuid, 'physique-chimie', '1re', 'Mouvements et cinématique', 'Quelle est la première étape de la méthode pour étudier un mouvement ?', 'mcq', '["Définir le système","Appliquer la deuxième loi de Newton","Faire le bilan des forces","Intégrer pour obtenir la position"]'::jsonb, 0, 'On définit le système, puis le référentiel, on fait le bilan des forces, on applique la deuxième loi et on intègre.', 4),
    ('860ad4be-5612-5b72-8497-cbc2833feb76'::uuid, 'physique-chimie', '1re', 'Le champ gravitationnel', 'Par combien est divisée la force gravitationnelle si la distance entre deux corps est triplée ?', 'mcq', '["Par trois","Par six","Par neuf","Par vingt-sept"]'::jsonb, 2, 'La force varie en 1 / d² : tripler d divise la force par 3² = 9.', 1),
    ('cf22ce17-d2a6-55de-99cb-6ddb407ef1ba'::uuid, 'physique-chimie', '1re', 'Le champ gravitationnel', 'Quelle est la valeur approximative du champ de pesanteur sur la Lune ?', 'mcq', '["9,8 N/kg","1,6 N/kg","3,7 N/kg","0 N/kg"]'::jsonb, 1, 'Environ 1,6 N/kg, soit six fois moins que sur Terre : même masse, poids six fois plus faible.', 2),
    ('bb9a00eb-c80d-5eeb-bd24-fbcb7f0d90a4'::uuid, 'physique-chimie', '1re', 'Le champ gravitationnel', 'Quel est le poids d’un élève de 60 kg sur Terre, avec g = 9,8 N/kg ?', 'mcq', '["588 N","60 N","6,1 N","69,8 N"]'::jsonb, 0, 'P = m × g = 60 × 9,8 = 588 N. La masse se compte en kilogrammes, le poids en newtons.', 3),
    ('456b09b8-7790-5e2e-adba-b3d11c2fe4be'::uuid, 'physique-chimie', '1re', 'Le champ gravitationnel', 'Quelle est la valeur de la constante de gravitation universelle G, en unités du Système international ?', 'mcq', '["9 × 10⁹","6,02 × 10²³","3,00 × 10⁸","6,67 × 10⁻¹¹"]'::jsonb, 3, 'G ≈ 6,67 × 10⁻¹¹ : sa petitesse explique qu’on ne ressente pas l’attraction entre deux objets ordinaires.', 4),
    ('63301cd1-24f9-585d-a54b-6cf5beef397b'::uuid, 'physique-chimie', '1re', 'Champ électrique et électrostatique', 'Quelle est l’unité du champ électrique ?', 'mcq', '["Le newton par kilogramme","Le coulomb","L’ampère","Le volt par mètre"]'::jsonb, 3, 'Le champ électrique se mesure en V/m, ce que confirme la relation E = U / d.', 1),
    ('1f5db84e-e4c8-5441-8bd4-2421715df24e'::uuid, 'physique-chimie', '1re', 'Champ électrique et électrostatique', 'Quelle est la valeur de la charge élémentaire ?', 'mcq', '["Environ 1,6 × 10⁻¹⁹ C","Environ 6,63 × 10⁻³⁴ C","Environ 9 × 10⁹ C","Environ 6,02 × 10²³ C"]'::jsonb, 0, 'e ≈ 1,6 × 10⁻¹⁹ C : c’est la charge d’un proton, et l’opposée de celle d’un électron.', 2),
    ('28453c62-863a-5a86-bcd9-2f3880f9d5ed'::uuid, 'physique-chimie', '1re', 'Champ électrique et électrostatique', 'Un condensateur plan est soumis à une tension de 100 V, ses plaques sont distantes de 2,0 cm. Que vaut le champ entre elles ?', 'mcq', '["50 V/m","200 V/m","5 000 V/m","2 V/m"]'::jsonb, 2, 'E = U / d = 100 / 0,020 = 5 000 V/m. Il faut convertir la distance en mètres.', 3),
    ('e5ee0951-2246-5cc2-842e-37b37fb937d6'::uuid, 'physique-chimie', '1re', 'Champ électrique et électrostatique', 'Entre deux protons, comment se comparent la répulsion électrique et l’attraction gravitationnelle ?', 'mcq', '["La gravitation l’emporte largement","La répulsion électrique est environ 10³⁶ fois plus grande","Elles sont égales","Elles s’annulent exactement"]'::jsonb, 1, 'Même forme en 1 / d², mais une intensité sans commune mesure : à l’échelle des particules, la gravitation est négligeable.', 4),
    ('7a3cc7fd-456c-50ee-80ba-110860efe5e9'::uuid, 'physique-chimie', '1re', 'Définition des ondes', 'Une onde a une période de 0,01 s. Quelle est sa fréquence ?', 'mcq', '["0,01 Hz","100 Hz","10 Hz","1 000 Hz"]'::jsonb, 1, 'f = 1 / T = 1 / 0,01 = 100 Hz : cent motifs par seconde.', 1),
    ('9b7d84f5-2233-5d65-b2c2-e00cb8e992b5'::uuid, 'physique-chimie', '1re', 'Définition des ondes', 'Sur une corde qu’on secoue, la perturbation est perpendiculaire à la propagation. L’onde est…', 'mcq', '["longitudinale","électromagnétique","transversale","sonore"]'::jsonb, 2, 'Transversale : la perturbation est perpendiculaire à la direction de propagation, comme sur une corde ou une vague.', 2),
    ('621b45f2-e982-57e8-b229-0e648f841764'::uuid, 'physique-chimie', '1re', 'Définition des ondes', 'On compte 3 s entre l’éclair et le tonnerre. À quelle distance environ est l’orage ?', 'mcq', '["Environ 100 m","Environ 3 km","Environ 10 km","Environ 1 km"]'::jsonb, 3, 'τ = d / v donne d = v × τ ≈ 340 × 3 ≈ 1 000 m. La lumière arrive quasi instantanément.', 3),
    ('7ef36ab5-2b1a-5313-813b-b5a09e350355'::uuid, 'physique-chimie', '1re', 'Définition des ondes', 'Quelle est la célérité approximative du son dans l’eau ?', 'mcq', '["Environ 1 500 m/s","Environ 340 m/s","Environ 5 000 m/s","Environ 3,00 × 10⁸ m/s"]'::jsonb, 0, 'Environ 1 500 m/s : plus que dans l’air (340 m/s), moins que dans l’acier (5 000 m/s). Plus le milieu est rigide, plus l’onde va vite.', 4),
    ('7add0f51-07ed-5ef6-aadb-51baf7ae6ec5'::uuid, 'physique-chimie', '1re', 'Ondes et spectre électromagnétiques', 'Quel rayonnement sert à la radiographie ?', 'mcq', '["L’ultraviolet","L’infrarouge","Les micro-ondes","Les rayons X"]'::jsonb, 3, 'Les rayons X, de longueur d’onde environ 0,01 à 10 nm, traversent les tissus mous mais pas les os.', 1),
    ('0a300c24-b01f-54fa-a92c-d85f118f4320'::uuid, 'physique-chimie', '1re', 'Ondes et spectre électromagnétiques', 'Qu’est-ce qu’une onde électromagnétique ?', 'mcq', '["La propagation couplée d’un champ électrique et d’un champ magnétique","Une vibration de la matière","Un déplacement d’électrons dans un fil","Une onde de pression"]'::jsonb, 0, 'Deux champs couplés qui se propagent sans support : c’est pourquoi la lumière traverse le vide.', 2),
    ('b7cf5116-e664-5cd8-9f0c-e259f13668a9'::uuid, 'physique-chimie', '1re', 'Ondes et spectre électromagnétiques', 'Quand la température d’un corps chaud augmente, où se déplace le maximum de son spectre continu ?', 'mcq', '["Vers le rouge","Vers le bleu","Il ne bouge pas","Vers les ondes radio"]'::jsonb, 1, 'Plus un corps est chaud, plus son maximum d’émission se décale vers les courtes longueurs d’onde, donc vers le bleu.', 3),
    ('e5e9f330-c6a3-5fef-98d2-9d1a8273ccce'::uuid, 'physique-chimie', '1re', 'Ondes et spectre électromagnétiques', 'Où se placent les raies noires du spectre d’absorption d’un gaz ?', 'mcq', '["À des positions choisies au hasard","Uniquement dans l’infrarouge","Exactement là où ce même gaz émettrait ses raies","Toujours au milieu du spectre visible"]'::jsonb, 2, 'Absorption et émission se font aux mêmes longueurs d’onde : c’est la signature de l’élément.', 4),
    ('68e54616-64f4-5820-a884-d51e4149204f'::uuid, 'physique-chimie', '1re', 'Les photons et l’interaction matière-lumière', 'Quelle est la valeur de la constante de Planck h ?', 'mcq', '["1,60 × 10⁻¹⁹ J·s","3,00 × 10⁸ J·s","6,63 × 10⁻³⁴ J·s","6,02 × 10²³ J·s"]'::jsonb, 2, 'h ≈ 6,63 × 10⁻³⁴ J·s : elle relie l’énergie d’un photon à sa fréquence, E = h × f.', 1),
    ('0b2b39ab-4ae3-538b-8f25-066ed311db3d'::uuid, 'physique-chimie', '1re', 'Les photons et l’interaction matière-lumière', 'Si la longueur d’onde d’une lumière double, que devient l’énergie de ses photons ?', 'mcq', '["Elle double","Elle est divisée par deux","Elle quadruple","Elle ne change pas"]'::jsonb, 1, 'E = h × c / λ : l’énergie est inversement proportionnelle à la longueur d’onde.', 2),
    ('d91bd1e4-b9e8-58a7-9a14-2d65800f7c9e'::uuid, 'physique-chimie', '1re', 'Les photons et l’interaction matière-lumière', 'Un atome passe d’un niveau à −3,4 eV au niveau −13,6 eV. Quelle est l’énergie du photon émis ?', 'mcq', '["17,0 eV","3,4 eV","13,6 eV","10,2 eV"]'::jsonb, 3, 'E(photon) = E(haut) − E(bas) = −3,4 − (−13,6) = 10,2 eV.', 3),
    ('fa627be5-c15e-5081-aa90-23e6d3c2bff3'::uuid, 'physique-chimie', '1re', 'Les photons et l’interaction matière-lumière', 'Sur quel phénomène repose le laser ?', 'mcq', '["Une émission provoquée entre deux niveaux d’énergie","Un spectre continu de corps chaud","L’absorption d’un photon par un métal","La réfraction de la lumière"]'::jsonb, 0, 'L’émission provoquée donne une lumière monochromatique et très directive.', 4),
    ('efdb79a7-5d17-56b9-b3ec-731c14846240'::uuid, 'physique-chimie', '1re', 'Vergence, image, grandissement et relation de conjugaison', 'Une lentille de distance focale f’ = 0,10 m donne d’un objet placé à OA = −0,30 m une image. Où est-elle ?', 'mcq', '["OA’ = 0,15 m","OA’ = 0,30 m","OA’ = 0,075 m","OA’ = −0,15 m"]'::jsonb, 0, '1 / OA’ = 1 / f’ + 1 / OA = 10 − 3,33 ≈ 6,67, donc OA’ ≈ 0,15 m : une image réelle, de l’autre côté de la lentille.', 1),
    ('e9f542ae-62cf-583c-a34e-dbbd3125c39f'::uuid, 'physique-chimie', '1re', 'Vergence, image, grandissement et relation de conjugaison', 'Le grandissement vaut γ = −0,5. Comment est l’image ?', 'mcq', '["Droite et deux fois plus grande","Renversée et deux fois plus petite","Renversée et deux fois plus grande","Droite et deux fois plus petite"]'::jsonb, 1, 'Le signe moins indique une image renversée ; une valeur absolue de 0,5 signifie qu’elle est deux fois plus petite.', 2),
    ('c5937182-cff6-519e-8852-96e967a8c547'::uuid, 'physique-chimie', '1re', 'Vergence, image, grandissement et relation de conjugaison', 'Que devient un rayon passant par le foyer objet F ?', 'mcq', '["Il passe par F’","Il n’est pas dévié","Il est réfléchi","Il ressort parallèle à l’axe optique"]'::jsonb, 3, 'C’est le « retour » du rayon parallèle à l’axe : ce qui arrive par F ressort parallèle à l’axe.', 3),
    ('69c251f1-db7c-591c-b9a7-1df2e470f937'::uuid, 'physique-chimie', '1re', 'Vergence, image, grandissement et relation de conjugaison', 'Quel instrument utilise une image virtuelle, droite et agrandie ?', 'mcq', '["L’appareil photo","L’œil","La loupe","Le projecteur de diapositives"]'::jsonb, 2, 'L’objet est placé entre O et F : on voit à travers la lentille une image droite et agrandie. L’œil et l’appareil photo forment des images réelles.', 4),
    ('9ae53b21-1603-5e46-ac51-b64cc4e8cb37'::uuid, 'physique-chimie', '1re', 'Couleurs', 'Quelle est la couleur complémentaire du vert ?', 'mcq', '["Le cyan","Le magenta","Le jaune","Le rouge"]'::jsonb, 1, 'Vert et magenta (rouge + bleu) superposés donnent du blanc en synthèse additive.', 1),
    ('d5454bbf-b995-5cf1-a467-de6c1c2efac0'::uuid, 'physique-chimie', '1re', 'Couleurs', 'De quelle couleur apparaît une feuille blanche éclairée en lumière rouge ?', 'mcq', '["Rouge","Blanche","Noire","Cyan"]'::jsonb, 0, 'Un objet blanc diffuse toutes les lumières qu’il reçoit : il ne reçoit que du rouge, il renvoie du rouge.', 2),
    ('abe3c03f-18d3-5cfe-a608-d8f7dd43414c'::uuid, 'physique-chimie', '1re', 'Couleurs', 'Qu’est-ce qui détermine la couleur d’un objet transparent ?', 'mcq', '["La lumière qu’il diffuse","La lumière qu’il absorbe","La lumière qu’il transmet","Sa température"]'::jsonb, 2, 'Un vitrail ou un filtre a la couleur de la lumière qui le traverse ; il absorbe le reste.', 3),
    ('aa2ed656-0db1-5e57-adf4-527979672837'::uuid, 'physique-chimie', '1re', 'Couleurs', 'D’où vient le daltonisme ?', 'mcq', '["D’une absence de bâtonnets","D’un cristallin opaque","D’un excès de lumière","D’une déficience d’un type de cônes"]'::jsonb, 3, 'Les trois types de cônes sont sensibles au rouge, au vert et au bleu ; s’il en manque un, certaines couleurs se confondent.', 4),
    ('20a44c50-6818-5e4a-945b-b7ee381ff831'::uuid, 'physique-chimie', '1re', 'L’énergie mécanique : énergies cinétique et potentielle', 'Quelle est l’énergie cinétique d’un objet de 2,0 kg lancé à 3,0 m/s ?', 'mcq', '["6,0 J","3,0 J","18 J","9,0 J"]'::jsonb, 3, 'Ec = ½ × m × v² = ½ × 2,0 × 3,0² = 9,0 J. Attention au carré de la vitesse.', 1),
    ('717653ed-0e75-5afc-9171-5d23cccbd48b'::uuid, 'physique-chimie', '1re', 'L’énergie mécanique : énergies cinétique et potentielle', 'Quelle est l’énergie potentielle de pesanteur d’un objet de 10 kg à 5,0 m d’altitude, avec g = 10 N/kg ?', 'mcq', '["50 J","500 J","5 000 J","2,0 J"]'::jsonb, 1, 'Epp = m × g × z = 10 × 10 × 5,0 = 500 J, en prenant le sol comme origine des altitudes.', 2),
    ('9e1891cc-e935-5ef4-a779-5d6468c53d01'::uuid, 'physique-chimie', '1re', 'L’énergie mécanique : énergies cinétique et potentielle', 'Une force de 10 N déplace un objet de 5,0 m en faisant un angle de 60° avec le déplacement. Quel est son travail ?', 'mcq', '["25 J","50 J","0 J","43 J"]'::jsonb, 0, 'W = F × d × cos α = 10 × 5,0 × 0,5 = 25 J.', 3),
    ('2b887da7-e00d-5dd3-a5a4-9b864672928c'::uuid, 'physique-chimie', '1re', 'L’énergie mécanique : énergies cinétique et potentielle', 'Quand des frottements interviennent, à quoi est égale la variation d’énergie mécanique ?', 'mcq', '["À zéro","Au travail du poids","Au travail des frottements, qui est négatif","À l’énergie cinétique finale"]'::jsonb, 2, 'Les frottements font diminuer l’énergie mécanique : ΔEm égale leur travail, négatif.', 4),
    ('cf7ab408-8f0d-538f-88e8-48d0153aaa34'::uuid, 'physique-chimie', '1re', 'L’énergie électrique', 'Une lampe de 60 W reste allumée 2 heures. Quelle énergie consomme-t-elle ?', 'mcq', '["120 kWh","0,12 kWh","30 kWh","1,2 kWh"]'::jsonb, 1, 'E = P × Δt = 60 W × 2 h = 120 Wh = 0,12 kWh.', 1),
    ('c7b2416b-90f1-5fa7-baa6-54008863398e'::uuid, 'physique-chimie', '1re', 'L’énergie électrique', 'Un générateur de force électromotrice E = 12 V et de résistance interne r = 2,0 Ω débite 1,0 A. Quelle tension délivre-t-il ?', 'mcq', '["14 V","12 V","10 V","6,0 V"]'::jsonb, 2, 'U = E − r × I = 12 − 2,0 × 1,0 = 10 V : la résistance interne fait chuter la tension.', 2),
    ('8889fc4c-4462-5ed3-a704-f04d292192bc'::uuid, 'physique-chimie', '1re', 'L’énergie électrique', 'Un moteur reçoit 100 J et en restitue 80 J sous forme mécanique. Quel est son rendement ?', 'mcq', '["1,25","20 %","80 J","0,80"]'::jsonb, 3, 'η = E(utile) / E(reçue) = 80 / 100 = 0,80, soit 80 % ; les 20 J restants sont dissipés.', 3),
    ('a2e40e36-7405-5613-ac86-129d4744ec2c'::uuid, 'physique-chimie', '1re', 'L’énergie électrique', 'Quel est le rendement lumineux approximatif d’une lampe à incandescence ?', 'mcq', '["Moins de 5 %","Environ 50 %","Plus de 90 %","Exactement 100 %"]'::jsonb, 0, 'Presque toute l’énergie part en chaleur par effet Joule ; une LED fait bien mieux, largement plus de 30 %.', 4),
    ('75d1665d-059b-59b6-827b-da439b6923b6'::uuid, 'physique-chimie', '1re', 'La mole et ses formules', 'Quelle est la masse molaire du dioxyde de carbone CO₂ (C = 12,0 g/mol ; O = 16,0 g/mol) ?', 'mcq', '["28,0 g/mol","44,0 g/mol","32,0 g/mol","40,0 g/mol"]'::jsonb, 1, 'On additionne tous les atomes : 12,0 + 2 × 16,0 = 44,0 g/mol.', 1),
    ('d07750a0-9690-5aaa-a7e1-95ab5ea888a1'::uuid, 'physique-chimie', '1re', 'La mole et ses formules', 'Quelle quantité de matière représentent 48 L de gaz, avec un volume molaire de 24 L/mol ?', 'mcq', '["0,50 mol","24 mol","1 152 mol","2,0 mol"]'::jsonb, 3, 'n = V / V(m) = 48 / 24 = 2,0 mol, quel que soit le gaz.', 2),
    ('483a8ae8-8c9c-5172-ad22-5ac9cbaa8225'::uuid, 'physique-chimie', '1re', 'La mole et ses formules', 'Avec quelle verrerie prélève-t-on la solution mère lors d’une dilution ?', 'mcq', '["Une éprouvette graduée","Un bécher","Une pipette jaugée","Une burette graduée"]'::jsonb, 2, 'La pipette jaugée est précise ; on verse ensuite dans une fiole jaugée qu’on complète au trait de jauge.', 3),
    ('2ecb8ecc-2640-5f3b-b4c9-bb2929bed847'::uuid, 'physique-chimie', '1re', 'La mole et ses formules', 'Comment se calcule le facteur de dilution ?', 'mcq', '["C(mère) / C(fille)","C(fille) / C(mère)","V(prélevé) / V(fille)","C(mère) × V(fille)"]'::jsonb, 0, 'Il est supérieur à 1 : c’est aussi V(fille) / V(prélevé), puisque la quantité de soluté ne change pas.', 4),
    ('e85caeb7-74e2-5aae-b029-73005aa4d50d'::uuid, 'physique-chimie', '1re', 'Absorbance et spectre d’absorption', 'Autour de quelle longueur d’onde une solution bleue absorbe-t-elle le plus ?', 'mcq', '["450 nm","600 nm","800 nm","300 nm"]'::jsonb, 1, 'Elle absorbe la couleur complémentaire du bleu, le jaune-orangé, vers 600 nm.', 1),
    ('c3715113-1833-5fab-991f-6c65a477ed11'::uuid, 'physique-chimie', '1re', 'Absorbance et spectre d’absorption', 'Une solution à 2,0 mmol/L a une absorbance de 0,40. Une autre, de la même espèce, mesurée dans les mêmes conditions, a une absorbance de 0,60. Quelle est sa concentration ?', 'mcq', '["1,5 mmol/L","4,0 mmol/L","3,0 mmol/L","0,60 mmol/L"]'::jsonb, 2, 'A = k × C : l’absorbance est multipliée par 1,5, la concentration aussi, soit 3,0 mmol/L.', 2),
    ('ce600d0a-64a1-572a-8237-9e452b027e94'::uuid, 'physique-chimie', '1re', 'Absorbance et spectre d’absorption', 'De quoi dépend le coefficient k de la loi de Beer-Lambert ?', 'mcq', '["De la concentration de la solution","Du volume de solution dans la cuve","De la couleur du bécher","De l’espèce, de la longueur d’onde et de la longueur de cuve traversée"]'::jsonb, 3, 'k ne dépend pas de la concentration : c’est ce qui rend l’absorbance proportionnelle à C.', 3),
    ('7c91c54c-868e-5d15-ae1f-ad426a30e08f'::uuid, 'physique-chimie', '1re', 'Absorbance et spectre d’absorption', 'Pourquoi mesure-t-on à λ(max) ?', 'mcq', '["Parce que la variation d’absorbance y est la plus forte","Parce que l’absorbance y est nulle","Pour éviter de faire le blanc","Parce que la loi de Beer-Lambert n’y est plus valable"]'::jsonb, 0, 'À λ(max), la mesure est la plus sensible, et un petit écart de réglage change peu le résultat.', 4),
    ('18dd9590-e4b0-5da7-82a3-efe291402a01'::uuid, 'physique-chimie', '1re', 'Modélisation de l’évolution d’une réaction chimique', 'Pour 2 H₂ + O₂ → 2 H₂O, on part de 3,0 mol de H₂ et 2,0 mol de O₂. Que vaut x(max) ?', 'mcq', '["2,0 mol","3,0 mol","1,5 mol","1,0 mol"]'::jsonb, 2, 'Rapports : 3,0 / 2 = 1,5 pour H₂ et 2,0 / 1 = 2,0 pour O₂. Le plus petit, 1,5 mol, donne x(max) et désigne H₂ comme limitant.', 1),
    ('1551b8ef-477d-5c05-811a-835dab2deed6'::uuid, 'physique-chimie', '1re', 'Modélisation de l’évolution d’une réaction chimique', 'Pour N₂ + 3 H₂ → 2 NH₃, on part de 2,0 mol de N₂ et 3,0 mol de H₂. Quel est le réactif limitant ?', 'mcq', '["N₂","H₂","Aucun : le mélange est stœchiométrique","NH₃"]'::jsonb, 1, 'Rapports : 2,0 / 1 = 2,0 pour N₂ et 3,0 / 3 = 1,0 pour H₂. H₂ est limitant, bien qu’il soit le plus abondant.', 2),
    ('fc3a5afd-d8cf-5415-9b84-791a015f4c27'::uuid, 'physique-chimie', '1re', 'Modélisation de l’évolution d’une réaction chimique', 'Un réactif de coefficient 2 est introduit à 5,0 mol. Combien en reste-t-il pour un avancement x = 1,5 mol ?', 'mcq', '["3,5 mol","6,5 mol","0,50 mol","2,0 mol"]'::jsonb, 3, 'n = n(initial) − coefficient × x = 5,0 − 2 × 1,5 = 2,0 mol.', 3),
    ('6c3f7b7a-c568-5d4c-b7f4-8eba1deb3581'::uuid, 'physique-chimie', '1re', 'Modélisation de l’évolution d’une réaction chimique', 'On obtient 0,50 mol d’eau (M = 18 g/mol). Quelle masse cela représente-t-il ?', 'mcq', '["9,0 g","36 g","18,5 g","0,028 g"]'::jsonb, 0, 'm = n × M = 0,50 × 18 = 9,0 g.', 4),
    ('b5ece3bb-e281-53bf-b32f-0314a0e18c71'::uuid, 'physique-chimie', '1re', 'Dosage par titrage', 'Où se trouve le réactif titrant ?', 'mcq', '["Dans le bécher","Dans la burette graduée","Dans la fiole jaugée","Dans la pipette jaugée"]'::jsonb, 1, 'Le titrant, de concentration connue, est versé progressivement à la burette ; le titré est dans le bécher.', 1),
    ('54be537b-2515-53b6-8171-eaa771cf93f3'::uuid, 'physique-chimie', '1re', 'Dosage par titrage', 'Avant l’équivalence, quel est le réactif limitant ?', 'mcq', '["Le titrant","Le titré","Aucun","L’eau distillée"]'::jsonb, 0, 'Tant qu’il reste du titré dans le bécher, chaque goutte de titrant versée est entièrement consommée.', 2),
    ('b7de89fd-f1e5-5b84-a8b4-68671ad4f963'::uuid, 'physique-chimie', '1re', 'Dosage par titrage', 'On titre 20,0 mL d’une solution par un titrant à 0,10 mol/L (réaction 1-1). L’équivalence est à 12,0 mL. Quelle est la concentration du titré ?', 'mcq', '["0,17 mol/L","0,24 mol/L","0,0060 mol/L","0,060 mol/L"]'::jsonb, 3, 'C(titré) = C(titrant) × V(éq) / V(titré) = 0,10 × 12,0 / 20,0 = 0,060 mol/L.', 3),
    ('d6bae5cb-96c1-5aa2-b75f-e6ea00394d33'::uuid, 'physique-chimie', '1re', 'Dosage par titrage', 'Dans un titrage colorimétrique, où repère-t-on l’équivalence ?', 'mcq', '["À la première goutte versée","Quand la burette est à moitié vide","Au premier changement de couleur persistant","Quand la solution devient incolore puis recolorée plusieurs fois"]'::jsonb, 2, 'L’indicateur coloré, ou la décoloration du permanganate, signale l’équivalence par un changement qui persiste.', 4),
    ('b73dc06b-1e14-5280-8459-936f930e43dd'::uuid, 'physique-chimie', '1re', 'Représentation de Lewis d’un atome et d’une molécule', 'Combien d’électrons de valence possède le chlore, dans la colonne 17 ?', 'mcq', '["17","5","1","7"]'::jsonb, 3, 'On retranche 10 au numéro de colonne pour les colonnes 13 à 18 : 17 − 10 = 7.', 1),
    ('10371404-a4db-52d4-8050-f94cadccb292'::uuid, 'physique-chimie', '1re', 'Représentation de Lewis d’un atome et d’une molécule', 'Quelle est la géométrie autour d’un atome entouré de quatre doublets ?', 'mcq', '["Linéaire","Triangulaire plane","Tétraédrique","Carrée"]'::jsonb, 2, 'Les quatre doublets se repoussent et s’écartent au maximum : ils pointent vers les sommets d’un tétraèdre.', 2),
    ('468333dd-758e-5cd8-acb2-fea12d97ccc5'::uuid, 'physique-chimie', '1re', 'Représentation de Lewis d’un atome et d’une molécule', 'Quelle est la première étape pour établir un schéma de Lewis ?', 'mcq', '["Compter le total des électrons de valence de tous les atomes","Placer les doublets non liants","Former les liaisons doubles","Dessiner la géométrie de la molécule"]'::jsonb, 0, 'On compte d’abord tous les électrons de valence (en ajoutant ou retranchant pour un ion), puis on place les liaisons simples.', 3),
    ('7aebdde7-e1b6-5021-be33-9eb4e97666ac'::uuid, 'physique-chimie', '1re', 'Représentation de Lewis d’un atome et d’une molécule', 'Combien de doublets non liants porte l’atome d’azote dans l’ammoniac NH₃ ?', 'mcq', '["Aucun","Un","Deux","Trois"]'::jsonb, 1, 'L’azote a 5 électrons de valence : 3 dans les liaisons avec H, et 2 formant un doublet non liant.', 4),
    ('48333dd5-0952-52d4-8d7a-6790bd48d8f6'::uuid, 'physique-chimie', '1re', 'Électronégativité des atomes et polarité des molécules', 'Comment varie l’électronégativité de haut en bas dans une colonne ?', 'mcq', '["Elle augmente","Elle diminue","Elle reste constante","Elle double à chaque ligne"]'::jsonb, 1, 'Elle augmente de gauche à droite et diminue de haut en bas : le fluor, en haut à droite, est le plus électronégatif.', 1),
    ('0271c316-0abc-5bbb-ade6-9617c4bed46d'::uuid, 'physique-chimie', '1re', 'Électronégativité des atomes et polarité des molécules', 'Dans une liaison O–H de l’eau, quel atome porte la charge partielle δ− ?', 'mcq', '["L’hydrogène","Aucun des deux","L’oxygène","Les deux à la fois"]'::jsonb, 2, 'L’oxygène, plus électronégatif, attire le doublet de la liaison : il porte δ−, l’hydrogène δ+.', 2),
    ('d3e3d8a3-d40e-511f-9d4b-50dad9c96707'::uuid, 'physique-chimie', '1re', 'Électronégativité des atomes et polarité des molécules', 'Quels éléments sont peu électronégatifs ?', 'mcq', '["Les halogènes","Les métaux","L’oxygène et l’azote","Le fluor et le chlore"]'::jsonb, 1, 'Les métaux, à gauche du tableau, attirent peu les électrons ; ils ont plutôt tendance à en céder.', 3),
    ('5c919f4b-4328-5aee-8bbb-aafda00219da'::uuid, 'physique-chimie', '1re', 'Électronégativité des atomes et polarité des molécules', 'À quelle condition une molécule est-elle polaire ?', 'mcq', '["Il suffit qu’elle contienne de l’oxygène","Il suffit qu’elle soit linéaire","Il suffit que ses atomes soient identiques","Ses liaisons sont polarisées et les charges partielles ne se compensent pas"]'::jsonb, 3, 'Il faut les deux : c’est pourquoi CO₂, aux liaisons polarisées mais linéaire et symétrique, est apolaire.', 4),
    ('ad16b1c3-0456-58c4-a4a6-1dc57fcddd75'::uuid, 'physique-chimie', '1re', 'Cohésion de la matière', 'Comment se comparent les interactions faibles et les liaisons covalentes ?', 'mcq', '["Elles sont dix à cent fois moins énergétiques","Elles ont la même énergie","Elles sont dix à cent fois plus énergétiques","Elles sont un million de fois plus énergétiques"]'::jsonb, 0, 'C’est pourquoi un changement d’état se fait à bien plus basse température qu’une réaction chimique.', 1),
    ('514d57ac-9207-508d-af06-5f1e6c93fd05'::uuid, 'physique-chimie', '1re', 'Cohésion de la matière', 'Qu’est-ce qu’une liaison ionique ?', 'mcq', '["Un doublet partagé entre deux atomes","Une liaison hydrogène entre deux molécules","Une interaction de Van der Waals","L’attraction entre des ions de charges opposées"]'::jsonb, 3, 'Elle forme un solide ionique, empilement régulier d’ions, électriquement neutre dans son ensemble.', 2),
    ('a1236799-fc0e-5119-a34c-61a0b2f42058'::uuid, 'physique-chimie', '1re', 'Cohésion de la matière', 'Quelle est la dernière étape de la dissolution d’un solide ionique ?', 'mcq', '["La dissociation","La solvatation","La dispersion","La cristallisation"]'::jsonb, 2, 'Dissociation des ions, solvatation par les molécules d’eau, puis dispersion des ions solvatés dans le solvant.', 3),
    ('3c57217a-88b2-558d-ac70-0f6693eb9c22'::uuid, 'physique-chimie', '1re', 'Cohésion de la matière', 'Pourquoi l’eau dissout-elle bien les solides ioniques ?', 'mcq', '["Parce qu’elle est liquide","Parce qu’elle est polaire","Parce qu’elle est linéaire","Parce qu’elle contient des ions"]'::jsonb, 1, 'Ses molécules orientent leur pôle opposé vers chaque ion : c’est la solvatation, possible grâce à sa polarité.', 4),
    ('66924523-76b0-5b6f-82df-02e81ad8ccba'::uuid, 'physique-chimie', '1re', 'Solubilité et extraction par solvant', 'Qu’est-ce que la solubilité d’une espèce ?', 'mcq', '["La masse maximale qu’on peut dissoudre dans un litre de solvant, à une température donnée","La vitesse à laquelle elle se dissout","Sa masse volumique","La masse de solvant nécessaire pour la dissoudre"]'::jsonb, 0, 'Au-delà de cette masse, l’espèce ne se dissout plus : la solution est saturée.', 1),
    ('07407ad9-5e4a-54ce-9cde-9f07354f34b2'::uuid, 'physique-chimie', '1re', 'Solubilité et extraction par solvant', 'Comment évolue la solubilité d’un solide quand la température monte ?', 'mcq', '["Elle diminue toujours","Elle augmente presque toujours","Elle ne change pas","Elle devient nulle"]'::jsonb, 1, 'C’est l’inverse pour un gaz, dont la solubilité diminue quand on chauffe.', 2),
    ('84eb17a9-5e08-5095-aafa-d2f14600c1b5'::uuid, 'physique-chimie', '1re', 'Solubilité et extraction par solvant', 'On extrait une espèce de l’eau avec du dichlorométhane (1,33 g/mL). Où se trouve la phase organique ?', 'mcq', '["Au-dessus de l’eau","Mélangée à l’eau","En dessous de l’eau","Elle s’évapore pendant l’agitation"]'::jsonb, 2, 'Le dichlorométhane est plus dense que l’eau : la phase organique est en bas. Avec l’éther (0,71 g/mL), elle serait en haut.', 3),
    ('67d13714-165d-5030-badc-3e54ba09fd68'::uuid, 'physique-chimie', '1re', 'Solubilité et extraction par solvant', 'Comment récupère-t-on l’espèce extraite une fois les phases séparées ?', 'mcq', '["Par filtration","Par décantation","Par titrage","Par évaporation du solvant extracteur"]'::jsonb, 3, 'On élimine le solvant extracteur par évaporation : il ne reste que l’espèce extraite.', 4),
    ('d4c4d34e-4b2c-51eb-93bc-aea7c4d905ea'::uuid, 'physique-chimie', '1re', 'Les différentes représentations des molécules et leur nomenclature', 'Quelle est la formule brute du butane ?', 'mcq', '["C₄H₈","C₄H₁₀","CH₄","C₅H₁₂"]'::jsonb, 1, 'Le butane est un alcane à 4 carbones : C₄H₁₀. C₄H₈ serait un alcène.', 1),
    ('4f947c42-3687-5d93-adab-c3a45f6041d8'::uuid, 'physique-chimie', '1re', 'Les différentes représentations des molécules et leur nomenclature', 'Quelle famille porte la terminaison -al ?', 'mcq', '["Les alcools","Les cétones","Les aldéhydes","Les alcanes"]'::jsonb, 2, 'Aldéhyde : -al ; cétone : -one ; alcool : -ol ; alcane : -ane.', 2),
    ('d834b853-e78f-5dba-89ae-cd90be60efa2'::uuid, 'physique-chimie', '1re', 'Les différentes représentations des molécules et leur nomenclature', 'Dans une formule semi-développée, qu’est-ce qui n’est pas dessiné ?', 'mcq', '["Les liaisons avec les atomes d’hydrogène","Les atomes de carbone","Les doubles liaisons","Les atomes d’oxygène"]'::jsonb, 0, 'On écrit par exemple CH₃−CH₂−CH₂−CH₃ : les liaisons C–H sont sous-entendues.', 3),
    ('123b0b2d-e537-58a0-8b84-1ad11540777c'::uuid, 'physique-chimie', '1re', 'Les différentes représentations des molécules et leur nomenclature', 'Combien d’atomes de carbone compte la chaîne principale de l’hexan-1-ol ?', 'mcq', '["Cinq","Quatre","Sept","Six"]'::jsonb, 3, 'Le préfixe hex- signifie six carbones ; la terminaison -ol indique un alcool, sur le carbone 1.', 4),
    ('2548a3c4-be97-50a7-87d7-bc7b87c24c60'::uuid, 'physique-chimie', '1re', 'Synthèse organique', 'Quand isole-t-on le produit par filtration sur Büchner ?', 'mcq', '["Quand le produit est solide","Quand le produit est un gaz","Quand il est dissous dans l’eau","Quand deux liquides sont miscibles"]'::jsonb, 0, 'La filtration sous vide sur Büchner sépare rapidement un solide du liquide qui l’entoure.', 1),
    ('1278b797-12fe-50b5-90cf-b053ec62762c'::uuid, 'physique-chimie', '1re', 'Synthèse organique', 'Lors d’une recristallisation, où restent les impuretés ?', 'mcq', '["Dans les cristaux formés","Dans la solution, car elles y sont plus solubles","Dans le réfrigérant","Dans la pierre ponce"]'::jsonb, 1, 'On dissout à chaud puis on refroidit lentement : le produit cristallise, les impuretés plus solubles restent dissoutes.', 2),
    ('9acb29e9-dc97-5087-8583-68261f20177e'::uuid, 'physique-chimie', '1re', 'Synthèse organique', 'Que révèle la RMN d’un produit de synthèse ?', 'mcq', '["Ses groupes fonctionnels","Sa couleur","Son squelette carboné","Sa masse"]'::jsonb, 2, 'L’infrarouge révèle les groupes fonctionnels ; la RMN renseigne sur le squelette carboné.', 3),
    ('a6c542e7-e369-5d16-b805-0e7f6f851956'::uuid, 'physique-chimie', '1re', 'Synthèse organique', 'On obtient 0,30 mol de produit pour 0,40 mol attendues au maximum. Quel est le rendement ?', 'mcq', '["133 %","30 %","40 %","75 %"]'::jsonb, 3, 'η = n(obtenu) / n(théorique) = 0,30 / 0,40 = 0,75, soit 75 %.', 4),
    ('b296172d-a2cf-5626-9a82-dee1b7a2c961'::uuid, 'physique-chimie', '1re', 'Les réactions de combustion', 'Dans l’équation C₃H₈ + … O₂ → 3 CO₂ + 4 H₂O, quel coefficient faut-il devant O₂ ?', 'mcq', '["3","4","5","7"]'::jsonb, 2, 'À droite : 3 × 2 + 4 × 1 = 10 atomes d’oxygène, donc 5 O₂. On ajuste l’oxygène en dernier.', 1),
    ('3e52b5ff-7dad-541c-85a7-ed9d739aa269'::uuid, 'physique-chimie', '1re', 'Les réactions de combustion', 'Pourquoi le monoxyde de carbone est-il mortel ?', 'mcq', '["Il se fixe sur l’hémoglobine à la place du dioxygène","Il brûle les voies respiratoires","Il acidifie le sang","Il est plus dense que l’air et chasse l’oxygène de la pièce"]'::jsonb, 0, 'Inodore et incolore, il empêche le sang de transporter le dioxygène : première cause d’intoxication domestique liée au chauffage.', 2),
    ('e80e01fc-7eef-5591-8bf7-b707c40d60a4'::uuid, 'physique-chimie', '1re', 'Les réactions de combustion', 'Quelle énergie libère la combustion complète de 2,0 kg de bois, de pouvoir calorifique 15 MJ/kg ?', 'mcq', '["7,5 MJ","17 MJ","13 MJ","30 MJ"]'::jsonb, 3, 'E = m × pouvoir calorifique = 2,0 × 15 = 30 MJ.', 3),
    ('1bb0fae8-0199-5e5e-8964-876564395bc4'::uuid, 'physique-chimie', '1re', 'Les réactions de combustion', 'Pour une réaction exothermique, quel est le signe du bilan calculé par les énergies de liaison ?', 'mcq', '["Positif","Nul","Négatif","Il dépend du combustible"]'::jsonb, 2, 'Former les liaisons des produits libère plus d’énergie que rompre celles des réactifs n’en coûte : le bilan est négatif.', 4),
    ('3e6f4d60-f4c3-52d7-a6a5-ca5c11a6cbe5'::uuid, 'svt', '1re', 'La division cellulaire chez les eucaryotes', 'Quelles phases du cycle cellulaire forment l’interphase ?', 'mcq', '["Prophase, métaphase, anaphase","G1, S et G2","Méiose I et méiose II","Télophase et cytodiérèse"]'::jsonb, 1, 'L’interphase regroupe la croissance (G1), la réplication (S) et la préparation à la division (G2) ; la mitose vient ensuite.', 1),
    ('03669670-572c-59b8-8a67-04751ec3c514'::uuid, 'svt', '1re', 'La division cellulaire chez les eucaryotes', 'Pendant quelle phase de la mitose les chromosomes s’alignent-ils à l’équateur de la cellule ?', 'mcq', '["La prophase","La télophase","L’anaphase","La métaphase"]'::jsonb, 3, 'En métaphase, les chromosomes condensés forment la plaque équatoriale, juste avant que leurs chromatides se séparent.', 2),
    ('a1e7677a-6fc4-59d0-bb34-be2779f8b7e9'::uuid, 'svt', '1re', 'La division cellulaire chez les eucaryotes', 'Combien de combinaisons le seul brassage interchromosomique offre-t-il chez l’humain ?', 'mcq', '["2 puissance 23, soit plus de 8 millions","23","46","2 × 23, soit 46"]'::jsonb, 0, 'Chacune des 23 paires d’homologues se répartit au hasard : 2 puissance 23 combinaisons, avant même le crossing-over et la fécondation.', 3),
    ('d5992524-639a-5e2d-a9b1-ad51aab5f51a'::uuid, 'svt', '1re', 'La division cellulaire chez les eucaryotes', 'Quel est le rôle des points de contrôle du cycle cellulaire ?', 'mcq', '["Accélérer la réplication de l’ADN","Déclencher la méiose","Vérifier l’intégrité de l’ADN et l’attachement des chromosomes","Fusionner les deux noyaux fils"]'::jsonb, 2, 'Ces vérifications empêchent une cellule endommagée de se diviser ; leur défaillance est l’un des mécanismes de la cancérisation.', 4),
    ('71e18d49-65d9-5def-ae29-e726db2fd57e'::uuid, 'svt', '1re', 'La réplication de l’ADN', 'Quelle expérience a confirmé en 1958 le modèle semi-conservatif ?', 'mcq', '["Celle de Meselson et Stahl","Celle de Watson et Crick","Celle de Mendel","Celle de Pasteur"]'::jsonb, 0, 'Meselson et Stahl ont écarté les hypothèses conservative et dispersive : chaque molécule fille garde un brin parental.', 1),
    ('6cea9f49-e74b-58dc-8647-2ac319775259'::uuid, 'svt', '1re', 'La réplication de l’ADN', 'Que prévoyait l’hypothèse conservative, écartée ensuite ?', 'mcq', '["Des fragments anciens et neufs mêlés sur chaque brin","Un brin ancien et un brin neuf par molécule","Une molécule intacte et une molécule entièrement neuve","La destruction de la molécule parentale"]'::jsonb, 2, 'Le modèle conservatif gardait la molécule parentale entière ; l’expérience a montré qu’il était faux.', 2),
    ('a0d3abb9-a096-58dd-bfbf-45cd2739bf85'::uuid, 'svt', '1re', 'La réplication de l’ADN', 'Pourquoi un des deux brins est-il copié par fragments ?', 'mcq', '["Parce que l’hélicase le coupe","Parce que l’ADN polymérase ne synthétise que dans un seul sens","Parce que ce brin contient des introns","Parce que ce brin est plus court"]'::jsonb, 1, 'La synthèse est orientée : sur l’un des brins la polymérase avance avec la fourche, sur l’autre elle doit repartir par fragments.', 3),
    ('777a2fe2-af12-54e6-b609-d3d918e22923'::uuid, 'svt', '1re', 'La réplication de l’ADN', 'Quel est l’ordre de grandeur des erreurs qui subsistent après la réplication et les réparations ?', 'mcq', '["Une erreur par dizaine de nucléotides","Une erreur par millier de nucléotides","Aucune erreur","Une erreur par milliard de nucléotides"]'::jsonb, 3, 'Grâce à la correction par la polymérase et aux systèmes de réparation, il ne reste qu’environ une erreur par milliard : ce sont les mutations.', 4),
    ('b607a2f5-8811-539b-951a-5921beaf4e6e'::uuid, 'svt', '1re', 'L’expression du patrimoine génétique', 'Quelle enzyme réalise la transcription ?', 'mcq', '["L’ADN polymérase","L’ADN hélicase","L’ARN polymérase","La ligase"]'::jsonb, 2, 'L’ARN polymérase copie le brin transcrit du gène en ARN pré-messager, dans le noyau.', 1),
    ('42ee913a-74ca-5079-9895-badb2fd41266'::uuid, 'svt', '1re', 'L’expression du patrimoine génétique', 'Que signifie « le code génétique est universel » ?', 'mcq', '["Il est le même chez presque tous les êtres vivants","Chaque codon code tous les acides aminés","Tous les gènes codent une protéine","Il ne change jamais par mutation"]'::jsonb, 0, 'Cette universalité rend possible le génie génétique : un gène humain peut être traduit par une bactérie.', 2),
    ('18f047de-01c6-582d-8b6a-18dd2c578bca'::uuid, 'svt', '1re', 'L’expression du patrimoine génétique', 'Combien de codons le code génétique compte-t-il pour 20 acides aminés ?', 'mcq', '["20","32","61","64"]'::jsonb, 3, 'Il existe 64 codons (4 × 4 × 4) pour 20 acides aminés : d’où des codons synonymes, c’est la redondance.', 3),
    ('0aaf5b0d-6c15-5484-896f-70dba2a29b0c'::uuid, 'svt', '1re', 'L’expression du patrimoine génétique', 'Qu’est-ce qui arrête la traduction ?', 'mcq', '["La fin de l’ARN de transfert","Un codon stop","Un intron","Le premier codon de l’ARN messager"]'::jsonb, 1, 'Le ribosome allonge la chaîne d’acides aminés jusqu’à rencontrer un codon stop, qui ne code aucun acide aminé.', 4),
    ('7cf61088-892a-52e8-86c2-7d14eb146ee2'::uuid, 'svt', '1re', 'Les mutations de l’ADN et la variabilité génétique', 'Qu’est-ce qu’une mutation faux-sens ?', 'mcq', '["Une mutation qui remplace un acide aminé par un autre","Une mutation qui fait apparaître un codon stop","Une mutation qui donne un codon synonyme","Une mutation qui supprime le gène entier"]'::jsonb, 0, 'La protéine obtenue peut rester fonctionnelle, devenir moins efficace ou être inactive selon l’acide aminé touché.', 1),
    ('837bde1a-cd4a-54fc-8c10-df5aea096906'::uuid, 'svt', '1re', 'Les mutations de l’ADN et la variabilité génétique', 'Quelle délétion ne décale pas le cadre de lecture ?', 'mcq', '["La délétion d’un nucléotide","La délétion de deux nucléotides","La délétion de trois nucléotides","Toute délétion décale le cadre"]'::jsonb, 2, 'Une délétion d’un multiple de trois retire des codons entiers : le cadre de lecture est conservé en aval.', 2),
    ('04a3191a-fc12-51e5-a31c-8352a54bddbf'::uuid, 'svt', '1re', 'Les mutations de l’ADN et la variabilité génétique', 'Pourquoi seules les mutations germinales comptent-elles pour l’évolution des espèces ?', 'mcq', '["Parce qu’elles sont plus fréquentes","Parce qu’elles sont transmises à la descendance","Parce qu’elles sont toujours avantageuses","Parce qu’elles touchent tous les organes"]'::jsonb, 1, 'Une mutation somatique disparaît avec l’individu ; seule une mutation de la lignée reproductrice passe à la génération suivante.', 3),
    ('fc4c0e24-420e-58f5-9b72-16829e3584c2'::uuid, 'svt', '1re', 'Les mutations de l’ADN et la variabilité génétique', 'Quel exemple montre qu’un allèle peut être avantageux selon l’environnement ?', 'mcq', '["La mucoviscidose dans les régions froides","L’hémophilie en altitude","Le daltonisme sous les tropiques","L’allèle de la drépanocytose, qui protège du paludisme"]'::jsonb, 3, 'Là où le paludisme sévit, les porteurs de cet allèle sont mieux protégés : c’est l’environnement qui fait la valeur d’un allèle.', 4),
    ('c2d1b6e4-3fd7-5b83-9309-88d4012b35c2'::uuid, 'svt', '1re', 'L’histoire humaine lue dans les génomes', 'Que signifie le fait que deux populations partagent beaucoup de marqueurs génétiques ?', 'mcq', '["Elles ont divergé très tôt","Elles ont divergé récemment","Elles vivent sous le même climat","Elles n’ont jamais été séparées par une mer"]'::jsonb, 1, 'Plus la séparation est récente, moins les mutations neutres ont eu le temps de s’accumuler différemment dans chaque lignée.', 1),
    ('f4aefe10-3699-52c7-adda-43a5c720fc8b'::uuid, 'svt', '1re', 'L’histoire humaine lue dans les génomes', 'Chez quelles populations trouve-t-on de l’ADN de Denisova ?', 'mcq', '["Chez toutes les populations africaines","Uniquement en Europe","Chez certaines populations d’Asie et d’Océanie","Chez aucune population actuelle"]'::jsonb, 2, 'Ces métissages anciens ont laissé quelques pour cent d’ADN dénisovien dans certaines populations d’Asie et d’Océanie.', 2),
    ('ba63f940-075c-5d98-bdff-6dccfc53d3f3'::uuid, 'svt', '1re', 'L’histoire humaine lue dans les génomes', 'Quelle adaptation génétique récente s’observe chez les Tibétains ?', 'mcq', '["Des variants facilitant la vie en haute altitude","La persistance de la lactase","Une résistance au froid polaire","Une peau plus claire"]'::jsonb, 0, 'Des allèles favorisant la vie en altitude ont été sélectionnés dans cette population.', 3),
    ('d4060736-0c7b-5301-bc68-50fa301c1698'::uuid, 'svt', '1re', 'L’histoire humaine lue dans les génomes', 'Quel argument appuie l’origine africaine d’Homo sapiens ?', 'mcq', '["L’absence de fossiles hors d’Afrique","La présence d’ADN néandertalien en Afrique","La couleur de peau","La diversité génétique maximale en Afrique"]'::jsonb, 3, 'La population la plus ancienne a eu le plus de temps pour accumuler des mutations : sa diversité est la plus grande.', 4),
    ('2ce71e12-20a9-5e65-b195-ddb3f4f8ceda'::uuid, 'svt', '1re', 'Le rôle des enzymes dans les réactions métaboliques', 'Qu’appelle-t-on métabolisme ?', 'mcq', '["L’ensemble des réactions chimiques d’une cellule","La seule digestion des aliments","La division des cellules","La synthèse des protéines uniquement"]'::jsonb, 0, 'Presque toutes ces réactions seraient trop lentes à température corporelle sans les enzymes qui les catalysent.', 1),
    ('f4ad8f25-da58-56d2-b1ee-11ec50f325f4'::uuid, 'svt', '1re', 'Le rôle des enzymes dans les réactions métaboliques', 'Comment appelle-t-on la zone de l’enzyme où se fixe le substrat ?', 'mcq', '["Le codon","Le site actif","Le plasmide","Le promoteur"]'::jsonb, 1, 'Le site actif a une forme complémentaire du substrat : c’est l’origine de la spécificité de substrat.', 2),
    ('a3e6e915-94d4-5c89-ab3d-25d20efeb411'::uuid, 'svt', '1re', 'Le rôle des enzymes dans les réactions métaboliques', 'Quel modèle affine l’image « clé-serrure » de la fixation du substrat ?', 'mcq', '["Le modèle semi-conservatif","Le modèle de la sélection clonale","L’ajustement induit","L’équilibre isostatique"]'::jsonb, 2, 'Dans l’ajustement induit, le site actif se déforme légèrement au contact du substrat pour l’enserrer.', 3),
    ('049e7ca0-e9f3-58de-b7a0-047dafb69a6e'::uuid, 'svt', '1re', 'Le rôle des enzymes dans les réactions métaboliques', 'Quelle maladie résulte d’une enzyme déficiente qui interrompt la dégradation d’un acide aminé ?', 'mcq', '["La mucoviscidose","Le diabète de type 2","L’hémophilie","La phénylcétonurie"]'::jsonb, 3, 'La phénylcétonurie montre le contrôle génétique du métabolisme : un gène muté, une enzyme inactive, une voie bloquée.', 4),
    ('768ba10f-0bd4-5751-a570-2fa5184acfea'::uuid, 'svt', '1re', 'La surface de la Terre, contrastes entre les continents et les océans', 'Quels éléments rendent la croûte océanique plus riche que la croûte continentale ?', 'mcq', '["Le fer et le magnésium","La silice et l’aluminium","Le calcium et le carbone","L’uranium et le thorium"]'::jsonb, 0, 'La croûte océanique basaltique est riche en fer et magnésium ; la croûte continentale granitique, en silice et aluminium.', 1),
    ('941a88f1-0204-5e45-b1d4-29d5c8a1faec'::uuid, 'svt', '1re', 'La surface de la Terre, contrastes entre les continents et les océans', 'Quelle est la densité moyenne de la croûte continentale ?', 'mcq', '["Environ 1","Environ 2,7","Environ 3,3","Environ 5,5"]'::jsonb, 1, 'Environ 2,7 contre 2,9 pour la croûte océanique : plus légère, la croûte continentale flotte plus haut.', 2),
    ('026b5b89-5944-5759-9678-623cc3d6cc10'::uuid, 'svt', '1re', 'La surface de la Terre, contrastes entre les continents et les océans', 'Pourquoi la croûte océanique est-elle toujours jeune ?', 'mcq', '["Parce qu’elle fond sous l’effet du Soleil","Parce que l’érosion la détruit","Parce qu’elle est renouvelée en permanence","Parce qu’elle s’est formée récemment sur toute la Terre"]'::jsonb, 2, 'Elle naît aux dorsales et disparaît en subduction : elle ne dépasse pas 200 millions d’années, alors que les continents sont conservés.', 3),
    ('0d4e821a-d09b-5b40-bdbf-5e030a94e9a2'::uuid, 'svt', '1re', 'La surface de la Terre, contrastes entre les continents et les océans', 'À quelle altitude se situe le maximum de la courbe hypsométrique correspondant aux fonds océaniques ?', 'mcq', '["Entre 0 et 1 000 m","Vers −11 000 m","Vers −200 m","Entre −4 000 et −5 000 m"]'::jsonb, 3, 'Le second maximum, entre −4 000 et −5 000 m, correspond aux plaines abyssales ; le premier, entre 0 et 1 000 m, aux continents.', 4),
    ('0166ac39-46cb-586b-b5b7-456e5436688e'::uuid, 'svt', '1re', 'Sismologie et structure de la Terre', 'Quelle onde sismique est la plus rapide ?', 'mcq', '["L’onde S","L’onde P","Les deux vont à la même vitesse","Cela dépend uniquement de la magnitude"]'::jsonb, 1, 'L’onde P, de compression, arrive la première ; l’onde S, de cisaillement, est plus lente.', 1),
    ('4b86bbfe-7b4c-5805-9cd6-533df068c9ea'::uuid, 'svt', '1re', 'Sismologie et structure de la Terre', 'Que sépare la discontinuité de Lehmann ?', 'mcq', '["La croûte et le manteau","Le manteau et le noyau externe","La lithosphère et l’asthénosphère","Le noyau externe et la graine"]'::jsonb, 3, 'Vers 5 100 km, elle sépare le noyau externe liquide de la graine solide.', 2),
    ('9bbe5a34-6563-506d-9a70-8e2df473c790'::uuid, 'svt', '1re', 'Sismologie et structure de la Terre', 'De quoi dépend la vitesse des ondes sismiques dans un milieu ?', 'mcq', '["De sa rigidité et de sa densité","De sa couleur","De sa température de surface seulement","De la distance à l’épicentre uniquement"]'::jsonb, 0, 'Une variation brutale de vitesse trahit un changement de milieu : c’est ainsi qu’on repère les discontinuités.', 3),
    ('39e79ac1-7fed-5ef2-b441-f103e10a3671'::uuid, 'svt', '1re', 'Sismologie et structure de la Terre', 'Quelle est l’épaisseur approximative de la lithosphère ?', 'mcq', '["Environ 7 km","Environ 2 900 km","Environ 100 km","Environ 700 km"]'::jsonb, 2, 'La lithosphère rigide réunit la croûte et le sommet du manteau sur environ 100 km, au-dessus de l’asthénosphère ductile.', 4),
    ('8bc9c527-58fc-5589-8159-c9e92cd9cd56'::uuid, 'svt', '1re', 'Mécanismes de transferts thermiques', 'Quelle part de la chaleur interne provient de la radioactivité naturelle ?', 'mcq', '["Environ 10 %","Environ 50 %","Environ 80 %","La totalité"]'::jsonb, 2, 'Environ 80 % viennent de la désintégration de l’uranium, du thorium et du potassium 40 ; le reste est une chaleur résiduelle.', 1),
    ('ee3cbb68-6f89-54e7-ad8c-23a6d4255ef7'::uuid, 'svt', '1re', 'Mécanismes de transferts thermiques', 'Pourquoi la conduction est-elle un mode de transfert peu efficace dans la lithosphère ?', 'mcq', '["Parce que la roche est un mauvais conducteur de la chaleur","Parce que la lithosphère est liquide","Parce qu’elle déplace trop de matière","Parce qu’elle ne fonctionne que la nuit"]'::jsonb, 0, 'Transmise de proche en proche sans déplacement de matière, la chaleur traverse lentement la roche.', 2),
    ('5b86d0ed-72bd-59fd-a116-161edd730dbb'::uuid, 'svt', '1re', 'Mécanismes de transferts thermiques', 'Comment le manteau peut-il convecter alors qu’il est solide ?', 'mcq', '["Il fond chaque hiver","Il est gazeux en profondeur","Il se brise en blocs qui tombent","Il flue comme un solide ductile, à quelques centimètres par an"]'::jsonb, 3, 'À haute température et sur des millions d’années, la roche solide se déforme lentement : c’est ce fluage qui permet la convection.', 3),
    ('63a15ceb-aaf5-5f39-82fb-87fb30fdb9da'::uuid, 'svt', '1re', 'Mécanismes de transferts thermiques', 'Qu’est-ce que le flux géothermique ?', 'mcq', '["La vitesse de déplacement des plaques","La puissance thermique évacuée par unité de surface","La température au centre de la Terre","La quantité de magma émise par an"]'::jsonb, 1, 'Élevé aux dorsales et faible sur les vieux boucliers, il dessine à lui seul les frontières de plaques.', 4),
    ('8972f59e-729d-5f59-8fbd-3f7c026c2848'::uuid, 'svt', '1re', 'La tectonique des plaques, caractérisation de la mobilité horizontale', 'Quels fossiles Wegener a-t-il retrouvés sur des continents aujourd’hui séparés ?', 'mcq', '["Mesosaurus et Glossopteris","Des ammonites et des trilobites","Des dinosaures et des mammouths","Des coraux et des éponges"]'::jsonb, 0, 'La présence de ce reptile d’eau douce et de cette fougère de part et d’autre de l’Atlantique suggérait des continents autrefois réunis.', 1),
    ('9e1d6390-0e96-5462-a98f-a34ee209a751'::uuid, 'svt', '1re', 'La tectonique des plaques, caractérisation de la mobilité horizontale', 'Qu’enregistrent les bandes d’anomalies magnétiques du plancher océanique ?', 'mcq', '["Les séismes passés","Les variations du niveau de la mer","Les inversions successives du champ magnétique terrestre","Les éruptions des points chauds"]'::jsonb, 2, 'En refroidissant, le basalte fige l’orientation du champ de son époque ; Vine et Matthews ont montré leur symétrie en 1963.', 2),
    ('29541760-d032-560d-ad40-2af3f12d0804'::uuid, 'svt', '1re', 'La tectonique des plaques, caractérisation de la mobilité horizontale', 'Dans la chaîne d’Hawaï, comment varie l’âge des volcans ?', 'mcq', '["Il est identique pour tous","Il croît en s’éloignant du point chaud actif","Il diminue en s’éloignant du point chaud","Il varie au hasard"]'::jsonb, 1, 'La plaque défile au-dessus d’un point chaud fixe : les volcans les plus éloignés sont les plus anciens.', 3),
    ('2af03be2-829c-55e3-8397-b1fde542923b'::uuid, 'svt', '1re', 'La tectonique des plaques, caractérisation de la mobilité horizontale', 'Qu’a apporté le GPS à partir des années 1990 ?', 'mcq', '["La découverte des dorsales","La preuve de la dérive par les fossiles","La datation des sédiments","Une mesure directe des déplacements, cohérente avec les anomalies magnétiques"]'::jsonb, 3, 'Les quelques centimètres par an mesurés en temps réel concordent avec les vitesses déduites des anomalies : la discussion est close.', 4),
    ('13037e71-7dd4-52a4-9ac6-d1204451f550'::uuid, 'svt', '1re', 'Les zones de divergence entre les plaques lithosphériques', 'Quelle est la longueur approximative du réseau des dorsales océaniques ?', 'mcq', '["600 km","6 000 km","60 000 km","600 000 km"]'::jsonb, 2, 'Cette chaîne sous-marine de 60 000 km fait le tour du globe : c’est là que naît la croûte océanique.', 1),
    ('424bc861-65fd-5a31-83e8-c38faee57dcc'::uuid, 'svt', '1re', 'Les zones de divergence entre les plaques lithosphériques', 'Quelle structure présente un basalte refroidi brutalement au contact de l’eau ?', 'mcq', '["Une structure microlitique","Une structure grenue","Une structure feuilletée","Une structure cristalline entière"]'::jsonb, 0, 'Le refroidissement brutal ne laisse pas le temps aux cristaux de grandir : quelques microlites dans du verre.', 2),
    ('4fa0d5a4-7a1f-5478-bb95-7c4b316d690d'::uuid, 'svt', '1re', 'Les zones de divergence entre les plaques lithosphériques', 'Quelle est la vitesse d’écartement d’une dorsale lente comme celle de l’Atlantique ?', 'mcq', '["Jusqu’à 15 cm par an","2 à 3 cm par an","Quelques mètres par an","Quelques millimètres par siècle"]'::jsonb, 1, 'La dorsale atlantique, lente, présente un rift axial profond ; les dorsales rapides du Pacifique est atteignent 15 cm par an.', 3),
    ('84778a30-015f-5153-9f21-ef3a634ae2fd'::uuid, 'svt', '1re', 'Les zones de divergence entre les plaques lithosphériques', 'Comment la lithosphère océanique s’épaissit-elle en s’éloignant de la dorsale ?', 'mcq', '["Par dépôt de laves en surface","Par collision avec un continent","Par fusion de sa base","Par accrétion du manteau refroidi à sa base"]'::jsonb, 3, 'En refroidissant, le manteau sous-jacent s’ajoute à la lithosphère : elle s’épaissit et devient plus dense.', 4),
    ('76df7099-a119-5859-874b-b81f73d20bcd'::uuid, 'svt', '1re', 'Les zones de subduction entre les plaques lithosphériques', 'Pourquoi la lithosphère continentale ne subduit-elle pas ?', 'mcq', '["Parce qu’elle est trop peu dense","Parce qu’elle est trop chaude","Parce qu’elle est liquide","Parce qu’elle est trop mince"]'::jsonb, 0, 'Trop légère pour s’enfoncer dans l’asthénosphère, elle est conservée : d’où l’âge très ancien des continents.', 1),
    ('6bb64988-82bb-5863-a2b5-ddb841928234'::uuid, 'svt', '1re', 'Les zones de subduction entre les plaques lithosphériques', 'Jusqu’à quelle profondeur environ observe-t-on des foyers sismiques dans une subduction ?', 'mcq', '["30 km","100 km","2 900 km","700 km"]'::jsonb, 3, 'Le plan de Wadati-Benioff descend jusqu’à environ 700 km : c’est la preuve directe de la plongée de la plaque.', 2),
    ('a81ba48a-6513-5aab-8d83-8ebaaaba8813'::uuid, 'svt', '1re', 'Les zones de subduction entre les plaques lithosphériques', 'Qu’est-ce qui libère l’eau de la croûte océanique plongeante ?', 'mcq', '["L’érosion","Des transformations métamorphiques","La fusion du noyau","L’évaporation en surface"]'::jsonb, 1, 'En s’enfonçant, la croûte hydratée change de minéraux et relâche son eau dans le manteau sus-jacent.', 3),
    ('f61d633d-5c5e-5ef6-b82e-1e92f95036b4'::uuid, 'svt', '1re', 'Les zones de subduction entre les plaques lithosphériques', 'Quelles roches volcaniques se forment en surface dans une zone de subduction ?', 'mcq', '["Gabbros et péridotites","Basaltes en coussins","Andésites et rhyolites","Granites et gneiss"]'::jsonb, 2, 'Le magma riche en silice donne andésites et rhyolites en surface, granodiorites en profondeur.', 4),
    ('5feb48e4-c2d6-514a-accf-42ff2702bfb7'::uuid, 'svt', '1re', 'Les zones de collision continentales (convergence)', 'Qu’est-ce qui déclenche la collision entre deux continents ?', 'mcq', '["L’apparition d’un point chaud","La disparition complète de la lithosphère océanique qui les séparait","L’ouverture d’un rift","La fonte d’une calotte glaciaire"]'::jsonb, 1, 'Une fois l’océan entièrement subduit, aucun des deux blocs trop légers ne peut plonger : la croûte s’épaissit.', 1),
    ('136caff5-5652-5116-a521-6c03f12f47e3'::uuid, 'svt', '1re', 'Les zones de collision continentales (convergence)', 'Quels minéraux permettent de reconstituer le trajet pression-température d’une roche ?', 'mcq', '["Glaucophane, disthène, sillimanite, grenat","Quartz, calcite, sel gemme","Olivine seule","Argiles et gypse"]'::jsonb, 0, 'Ces minéraux métamorphiques n’apparaissent que dans certaines conditions : ils racontent l’histoire de l’enfouissement.', 2),
    ('88535995-d2be-5e12-98f0-bf7455477437'::uuid, 'svt', '1re', 'Les zones de collision continentales (convergence)', 'Quel est l’ordre des étapes du cycle de Wilson ?', 'mcq', '["Subduction, rift, collision, océanisation, érosion","Collision, rift, subduction, érosion, océanisation","Rift, océanisation, subduction, collision, érosion","Océanisation, rift, érosion, subduction, collision"]'::jsonb, 2, 'Un océan s’ouvre, s’élargit, se referme par subduction, puis les continents entrent en collision avant que la chaîne soit érodée.', 3),
    ('eb6796ee-8554-5b8e-994c-06b5fbac4388'::uuid, 'svt', '1re', 'Les zones de collision continentales (convergence)', 'Quelle chaîne est une chaîne ancienne aujourd’hui très usée ?', 'mcq', '["Les Alpes","L’Himalaya","Les Andes","Le Massif central"]'::jsonb, 3, 'Le Massif central, comme les Appalaches, n’est plus qu’un relief usé ; Alpes et Himalaya s’élèvent encore.', 4),
    ('43f9b506-9446-57fb-bd62-7335c6ee035c'::uuid, 'svt', '1re', 'Les écosystèmes : des interactions dynamiques entre les êtres vivants et avec leur milieu', 'Comment appelle-t-on une interaction où l’un gagne et l’autre reste indifférent ?', 'mcq', '["Le commensalisme","Le parasitisme","Le mutualisme","La compétition"]'::jsonb, 0, 'Les épiphytes, qui poussent sur un arbre sans lui nuire, en sont un exemple.', 1),
    ('a7edf411-db69-59f6-b381-7e5bd4309e56'::uuid, 'svt', '1re', 'Les écosystèmes : des interactions dynamiques entre les êtres vivants et avec leur milieu', 'Pourquoi les chaînes alimentaires comptent-elles rarement plus de quatre ou cinq maillons ?', 'mcq', '["Parce que les prédateurs se mangent entre eux","Parce que l’énergie se dégrade fortement à chaque niveau","Parce que la matière disparaît","Parce que les producteurs sont trop peu nombreux"]'::jsonb, 1, 'Environ 10 % seulement de l’énergie passe au niveau suivant : très vite, il n’en reste plus assez pour un maillon de plus.', 2),
    ('11eb99a1-c78a-58b7-8894-3525bfac8248'::uuid, 'svt', '1re', 'Les écosystèmes : des interactions dynamiques entre les êtres vivants et avec leur milieu', 'Quelle interaction illustrent les nodosités à Rhizobium sur les racines des légumineuses ?', 'mcq', '["Le parasitisme","La prédation","Le commensalisme","Le mutualisme"]'::jsonb, 3, 'La bactérie fixe l’azote de l’air pour la plante, qui lui fournit en échange des sucres : les deux y gagnent.', 3),
    ('48e99af9-2a68-5618-8063-0061e3c40601'::uuid, 'svt', '1re', 'Les écosystèmes : des interactions dynamiques entre les êtres vivants et avec leur milieu', 'Que se passe-t-il quand une perturbation dépasse le seuil de résilience d’un écosystème ?', 'mcq', '["Il retrouve toujours son état initial","Il devient plus productif","Il bascule vers un autre état","Il cesse de recevoir de l’énergie"]'::jsonb, 2, 'La résilience n’est pas illimitée : au-delà d’un seuil, l’écosystème ne revient pas à son fonctionnement antérieur.', 4),
    ('b4b78070-1b7e-5e1f-b43f-cbe3eb27f74c'::uuid, 'svt', '1re', 'L’humanité et les écosystèmes : les services écosystémiques et leur gestion', 'Le stockage du carbone par une forêt est un service…', 'mcq', '["d’approvisionnement","culturel","de régulation","de production industrielle"]'::jsonb, 2, 'Comme la pollinisation ou l’épuration de l’eau, le stockage du carbone régule le fonctionnement du milieu.', 1),
    ('014c32f5-93c3-5c25-8941-21f260b88ac3'::uuid, 'svt', '1re', 'L’humanité et les écosystèmes : les services écosystémiques et leur gestion', 'Quelle pression humaine regroupe la pêche excessive, la chasse et la coupe de bois ?', 'mcq', '["La surexploitation","La fragmentation des habitats","L’eutrophisation","Les espèces envahissantes"]'::jsonb, 0, 'Prélever plus vite que la ressource ne se renouvelle l’épuise : c’est la surexploitation.', 2),
    ('7aebfb17-6ba0-5f68-b8c8-2cb00d6d3244'::uuid, 'svt', '1re', 'L’humanité et les écosystèmes : les services écosystémiques et leur gestion', 'En quoi le changement climatique menace-t-il la biodiversité ?', 'mcq', '["Il supprime la photosynthèse","Il déplace les aires de répartition plus vite que les espèces ne suivent","Il augmente la pollinisation","Il n’a aucun effet sur les espèces"]'::jsonb, 1, 'Les conditions favorables se déplacent ; les espèces trop lentes à migrer se retrouvent hors de leur aire.', 3),
    ('67ef5dc7-77f8-5699-b008-72151ab614ca'::uuid, 'svt', '1re', 'L’humanité et les écosystèmes : les services écosystémiques et leur gestion', 'Que désignent les « trames verte et bleue » ?', 'mcq', '["Des zones de pêche autorisée","Des cultures sans engrais","Des parcs urbains","Des corridors écologiques reliant les habitats"]'::jsonb, 3, 'Ces réseaux relient les milieux naturels terrestres (verte) et aquatiques (bleue) pour que les espèces puissent circuler.', 4),
    ('ad23c358-3b82-5384-b1c2-5f48841b740d'::uuid, 'svt', '1re', 'Mutations, patrimoine génétique et santé', 'Dans une maladie autosomique dominante, quelle proportion des enfants d’un parent atteint hétérozygote hérite de l’allèle muté ?', 'mcq', '["Aucun","La moitié","Le quart","Tous"]'::jsonb, 1, 'Le parent transmet l’un de ses deux allèles au hasard : un enfant sur deux reçoit l’allèle muté, qui suffit à exprimer la maladie.', 1),
    ('bbc0e02d-024b-50a5-8b1f-153bbf4bd114'::uuid, 'svt', '1re', 'Mutations, patrimoine génétique et santé', 'Laquelle de ces maladies est liée à l’X ?', 'mcq', '["La mucoviscidose","La chorée de Huntington","L’hémophilie","La drépanocytose"]'::jsonb, 2, 'L’hémophilie, comme le daltonisme et la myopathie de Duchenne, touche surtout les garçons, qui n’ont qu’un X.', 2),
    ('60e42df9-0d2d-581d-a785-305d24bde46d'::uuid, 'svt', '1re', 'Mutations, patrimoine génétique et santé', 'Quelle maladie est multifactorielle ?', 'mcq', '["Le diabète de type 2","La mucoviscidose","La chorée de Huntington","L’hémophilie"]'::jsonb, 0, 'Plusieurs gènes de prédisposition et l’environnement (alimentation, activité) interviennent ; elle ne suit pas les lois de Mendel.', 3),
    ('efbfeda1-a3c4-5e4b-ab18-c8bbc40ac6a5'::uuid, 'svt', '1re', 'Mutations, patrimoine génétique et santé', 'En quoi consiste la thérapie génique ?', 'mcq', '["Supprimer le chromosome porteur de la mutation","Greffer un organe sain","Prescrire des antibiotiques ciblés","Apporter aux cellules une version fonctionnelle du gène"]'::jsonb, 3, 'Elle compense le gène défectueux ; l’édition du génome par CRISPR-Cas9 vise, elle, à corriger directement la séquence.', 4),
    ('2fc6bf77-0b97-528f-b8db-274d6ea7283d'::uuid, 'svt', '1re', 'Origine et mécanismes de la cancérisation', 'Quel est le rôle normal d’un gène suppresseur de tumeur ?', 'mcq', '["Stimuler la division cellulaire","Freiner la division, déclencher la réparation ou l’apoptose","Former les vaisseaux sanguins","Produire des anticorps"]'::jsonb, 1, 'Sa mutation entraîne une perte de fonction : c’est le frein qui lâche.', 1),
    ('5bd2dcd6-186e-5edb-a45d-bebb82e184fa'::uuid, 'svt', '1re', 'Origine et mécanismes de la cancérisation', 'Quelle est la première étape de la cancérisation ?', 'mcq', '["Les métastases","La progression","La promotion","L’initiation"]'::jsonb, 3, 'L’initiation est une première mutation ; suivent la promotion, la progression, puis les métastases.', 2),
    ('771e2636-ba76-519e-959c-8a100c6eea5a'::uuid, 'svt', '1re', 'Origine et mécanismes de la cancérisation', 'Que se transmet-il dans les formes familiales de cancer, comme avec BRCA1 ?', 'mcq', '["Une prédisposition","Le cancer lui-même","Une tumeur déjà formée","Une infection virale"]'::jsonb, 0, 'L’allèle hérité augmente la probabilité de cancer ; il faudra encore d’autres mutations somatiques pour qu’il se déclare.', 3),
    ('4af22906-7658-5476-afad-7921b4785bcb'::uuid, 'svt', '1re', 'Origine et mécanismes de la cancérisation', 'Quelle mesure relève de la prévention primaire du cancer du col de l’utérus ?', 'mcq', '["La chimiothérapie","La radiothérapie","La vaccination contre le papillomavirus","L’immunothérapie"]'::jsonb, 2, 'Le papillomavirus est un facteur de risque : s’en protéger par la vaccination prévient le cancer avant qu’il apparaisse.', 4),
    ('21f10596-f83f-59a4-890d-fd560367c166'::uuid, 'svt', '1re', 'Variation génétique des bactéries et résistance aux antibiotiques', 'Comment appelle-t-on la capture par une bactérie d’ADN libre présent dans le milieu ?', 'mcq', '["La conjugaison","La transduction","La transformation","La réplication"]'::jsonb, 2, 'Avec la conjugaison et la transduction, c’est l’un des transferts de gènes qui accélèrent la diffusion des résistances.', 1),
    ('4ed40a8b-0866-5465-8ed1-41753b43fc62'::uuid, 'svt', '1re', 'Variation génétique des bactéries et résistance aux antibiotiques', 'Pourquoi la sélection de bactéries résistantes s’observe-t-elle en quelques jours ?', 'mcq', '["Parce que les antibiotiques provoquent des mutations","Parce que leurs générations se succèdent en une vingtaine de minutes","Parce que les bactéries sont peu nombreuses","Parce qu’elles ne mutent jamais"]'::jsonb, 1, 'Avec des populations immenses et des générations très courtes, la sélection naturelle agit à vue d’œil.', 2),
    ('3a76ef44-e298-53d8-936a-01d3fd919fd5'::uuid, 'svt', '1re', 'Variation génétique des bactéries et résistance aux antibiotiques', 'Qu’est-ce que la phagothérapie ?', 'mcq', '["L’usage de virus bactériophages pour détruire des bactéries","La phagocytose par les macrophages","Un antibiotique à large spectre","Un vaccin antibactérien"]'::jsonb, 0, 'Piste de recherche contre les bactéries résistantes, elle ne dispense pas du bon usage des antibiotiques.', 3),
    ('52548e04-5d59-55da-82cb-d0660bf2b9ab'::uuid, 'svt', '1re', 'Variation génétique des bactéries et résistance aux antibiotiques', 'Où la transmission des souches résistantes est-elle particulièrement surveillée ?', 'mcq', '["Dans les écoles","Dans les forêts","En haute montagne","À l’hôpital"]'::jsonb, 3, 'D’où l’isolement des patients porteurs et le lavage des mains, leviers d’hygiène contre la diffusion.', 4),
    ('018025c2-7aba-5d81-a10f-dc1e1db05eef'::uuid, 'svt', '1re', 'L’immunité innée', 'Quelle cause explique le gonflement (œdème) lors d’une inflammation ?', 'mcq', '["La vasoconstriction","L’augmentation de la perméabilité des vaisseaux","La destruction des nerfs","La production d’anticorps"]'::jsonb, 1, 'Le plasma sort des vaisseaux devenus plus perméables et s’accumule dans les tissus.', 1),
    ('0498b855-3176-51bf-90b6-d54a915e97aa'::uuid, 'svt', '1re', 'L’immunité innée', 'Lequel de ces éléments n’est PAS une cellule sentinelle ?', 'mcq', '["Le macrophage","Le mastocyte","La cellule dendritique","Le plasmocyte"]'::jsonb, 3, 'Le plasmocyte, producteur d’anticorps, appartient à l’immunité adaptative ; les sentinelles résident dans les tissus.', 2),
    ('1b05a947-2825-54c3-b934-64e61ae98731'::uuid, 'svt', '1re', 'L’immunité innée', 'Où la cellule dendritique présente-t-elle les fragments de l’intrus ?', 'mcq', '["Dans un ganglion lymphatique","Dans l’estomac","Dans la moelle épinière","Dans le foie"]'::jsonb, 0, 'Devenue cellule présentatrice de l’antigène, elle y déclenche l’immunité adaptative.', 3),
    ('431cc0b2-9dd3-5f18-9d9f-a33bc0a8d0ac'::uuid, 'svt', '1re', 'L’immunité innée', 'Quelle molécule fait partie des médiateurs de l’inflammation ?', 'mcq', '["L’hémoglobine","L’insuline","L’histamine","L’amylase"]'::jsonb, 2, 'Histamine, prostaglandines et cytokines provoquent la vasodilatation et attirent les phagocytes.', 4),
    ('88e8a9d8-f451-5837-bb79-d9365ab88be8'::uuid, 'svt', '1re', 'L’immunité adaptative', 'Quand le répertoire des récepteurs des lymphocytes est-il engendré ?', 'mcq', '["Après la rencontre avec l’antigène","Avant toute rencontre avec un antigène","Seulement après une vaccination","Pendant la réaction inflammatoire"]'::jsonb, 1, 'Des milliards de spécificités existent déjà : l’antigène ne fait que sélectionner le clone qui le reconnaît.', 1),
    ('00c60c9f-432b-58d0-8b9d-ac7dc5a24356'::uuid, 'svt', '1re', 'L’immunité adaptative', 'Contre quoi la voie humorale est-elle efficace ?', 'mcq', '["Les agents présents dans les liquides de l’organisme","Les virus à l’intérieur des cellules","Les cellules cancéreuses uniquement","Les mutations de l’ADN"]'::jsonb, 0, 'Les anticorps circulent dans les liquides et n’entrent pas dans les cellules : les agents intracellulaires relèvent des LT8.', 2),
    ('0a6bde65-f94e-522b-bf30-5e314c9b27ae'::uuid, 'svt', '1re', 'L’immunité adaptative', 'Quelles molécules le lymphocyte T auxiliaire sécrète-t-il pour amplifier la réponse ?', 'mcq', '["Des anticorps","Des enzymes digestives","Des histamines","Des interleukines"]'::jsonb, 3, 'Les interleukines stimulent la prolifération et la différenciation des lymphocytes B et T cytotoxiques.', 3),
    ('59777441-6d9b-54b1-a58d-d0ad47ca674f'::uuid, 'svt', '1re', 'L’immunité adaptative', 'Combien de temps faut-il à l’immunité adaptative pour se mettre en place lors d’un premier contact ?', 'mcq', '["Quelques secondes","Quelques minutes","Plusieurs jours","Plusieurs années"]'::jsonb, 2, 'Sélection, prolifération et différenciation des clones prennent plusieurs jours, contre une réponse immédiate pour l’innée.', 4),
    ('88d5fe07-2330-5eb2-ab1d-ed4377d7e4c5'::uuid, 'svt', '1re', 'La vaccination et l’immunothérapie', 'Pourquoi le seuil d’immunité collective est-il très élevé pour la rougeole ?', 'mcq', '["Parce que le vaccin est peu efficace","Parce que la maladie est très contagieuse","Parce que la maladie est bénigne","Parce qu’elle ne touche que les adultes"]'::jsonb, 1, 'Plus une maladie est contagieuse, plus il faut de personnes immunisées pour rompre la chaîne de transmission.', 1),
    ('b62e9642-3894-5f68-b0da-2835a9495d66'::uuid, 'svt', '1re', 'La vaccination et l’immunothérapie', 'Qu’injecte-t-on lors d’une vaccination ?', 'mcq', '["Des anticorps déjà formés","Des lymphocytes mémoire","Un antigène inoffensif","Des antibiotiques"]'::jsonb, 2, 'Agent inactivé, atténué, fragment protéique ou ARN messager : le système immunitaire travaille et construit sa mémoire.', 2),
    ('33e1f5f2-c301-52b0-bb77-e31c4ee64b93'::uuid, 'svt', '1re', 'La vaccination et l’immunothérapie', 'En quoi consiste la thérapie cellulaire CAR-T ?', 'mcq', '["Modifier en laboratoire les lymphocytes du patient, puis les réinjecter","Injecter des anticorps de cheval","Greffer de la moelle osseuse d’un donneur","Vacciner contre une tumeur"]'::jsonb, 0, 'Les lymphocytes T du patient reçoivent un récepteur qui leur fait reconnaître la tumeur.', 3),
    ('22062ee4-3480-5a97-bf55-089772e8e11a'::uuid, 'svt', '1re', 'La vaccination et l’immunothérapie', 'À quoi sont destinés les anticorps monoclonaux en immunothérapie antitumorale ?', 'mcq', '["À remplacer les globules rouges","À stimuler la cicatrisation","À bloquer la réplication de l’ADN viral","À se fixer sur une cible de la tumeur"]'::jsonb, 3, 'Produits en laboratoire, tous identiques, ils sont dirigés contre une molécule précise des cellules tumorales.', 4),
    ('69168057-2e93-5d9d-afb6-22aca6631e4e'::uuid, 'nsi', '1re', 'Une machine à calculer : le bit', 'Combien de bits faut-il au minimum pour coder 300 valeurs différentes ?', 'mcq', '["8","10","9","300"]'::jsonb, 2, '8 bits donnent 256 valeurs, trop peu ; 9 bits en donnent 512, ce qui suffit.', 1),
    ('596674e7-8eae-5910-8f1c-0dd7d47f3241'::uuid, 'nsi', '1re', 'Une machine à calculer : le bit', 'Que se passe-t-il quand on ajoute un bit à un codage ?', 'mcq', '["Le nombre de valeurs représentables double","Il augmente de un","Il est multiplié par dix","Il ne change pas"]'::jsonb, 0, 'Avec n bits, on code 2 puissance n valeurs : un bit de plus multiplie ce nombre par 2.', 2),
    ('cda3cc20-1e52-5b23-a2d5-6595768ecae9'::uuid, 'nsi', '1re', 'Une machine à calculer : le bit', 'Combien de valeurs peut-on coder sur 10 bits ?', 'mcq', '["100","20","512","1 024"]'::jsonb, 3, '2 puissance 10 = 1 024 : c’est pour cela que « kilo » a longtemps désigné 1 024 en informatique.', 3),
    ('96263669-b637-5cbb-bdb9-0826fa76f467'::uuid, 'nsi', '1re', 'Une machine à calculer : le bit', 'Qu’est-ce qui distingue une opération logique bit à bit (ET, OU) d’une addition binaire ?', 'mcq', '["Elle se fait en base 10","Elle se fait position par position, sans retenue","Elle ne s’applique qu’à un seul bit","Elle donne toujours 0"]'::jsonb, 1, 'L’addition propage une retenue dès 1 + 1 ; une opération logique traite chaque position indépendamment.', 4),
    ('d3262abf-0ebb-5c6b-a7d1-d6ceaebb6a59'::uuid, 'nsi', '1re', 'Une machine à calculer : l’octet', 'Combien d’octets vaut un kibioctet (Kio) ?', 'mcq', '["1 000","1 024","8","100"]'::jsonb, 1, 'Le préfixe binaire kibi vaut 2 puissance 10 = 1 024 ; le kilo décimal vaut 1 000.', 1),
    ('4b545112-c8ba-50af-b9ef-f9e039911c9d'::uuid, 'nsi', '1re', 'Une machine à calculer : l’octet', 'Combien de caractères le code ASCII permet-il de représenter ?', 'mcq', '["128","256","65 536","26"]'::jsonb, 0, 'L’ASCII tient sur 7 bits, soit 128 caractères : alphabet latin non accentué, chiffres et ponctuation.', 2),
    ('448b2e89-6669-51e4-9d1e-395817188a9b'::uuid, 'nsi', '1re', 'Une machine à calculer : l’octet', 'Combien de chiffres hexadécimaux faut-il pour écrire un octet ?', 'mcq', '["Un","Quatre","Huit","Deux"]'::jsonb, 3, 'Un chiffre hexadécimal vaut quatre bits : deux suffisent pour les huit bits d’un octet.', 3),
    ('efd8c32e-2759-5079-a89b-d96c65fbb9e0'::uuid, 'nsi', '1re', 'Une machine à calculer : l’octet', 'Combien de couleurs peut-on représenter avec trois octets par pixel ?', 'mcq', '["Environ 256","Environ 65 000","Plus de 16 millions","Exactement 24"]'::jsonb, 2, '3 octets font 24 bits, soit 2 puissance 24 ≈ 16,7 millions de couleurs.', 4),
    ('74b4fba0-d9a2-5eeb-a422-2a57bf100b9b'::uuid, 'nsi', '1re', 'Une machine électronique', 'Quel est le rôle de l’unité de commande dans l’architecture de von Neumann ?', 'mcq', '["Elle calcule","Elle séquence les instructions","Elle stocke les données","Elle relie la machine au monde"]'::jsonb, 1, 'L’unité arithmétique et logique calcule ; l’unité de commande organise l’enchaînement des instructions.', 1),
    ('274636a6-ca5d-5c6c-980d-1d74a37341a1'::uuid, 'nsi', '1re', 'Une machine électronique', 'Qu’est-ce qu’une porte logique ?', 'mcq', '["Un circuit fait de quelques transistors réalisant NON, ET, OU…","Une mémoire permanente","Un port USB","Un programme du système"]'::jsonb, 0, 'Des transistors forment des portes, des portes forment des circuits combinatoires comme l’additionneur.', 2),
    ('4d96ec05-23b5-52f7-8d30-15a188b7d1d4'::uuid, 'nsi', '1re', 'Une machine électronique', 'Combien de cycles par seconde effectue un processeur cadencé à 3 GHz ?', 'mcq', '["Trois mille","Trois millions","Trente","Trois milliards"]'::jsonb, 3, 'Le préfixe giga vaut un milliard : 3 GHz, ce sont trois milliards de cycles par seconde.', 3),
    ('02dba71a-e232-58ac-9d6c-e37e47b41677'::uuid, 'nsi', '1re', 'Une machine électronique', 'Quelle mémoire est la plus rapide ?', 'mcq', '["La mémoire vive","Le stockage","Les registres","Le cache"]'::jsonb, 2, 'Les registres, au cœur du processeur, sont les plus rapides et les plus petits : quelques mots seulement.', 4),
    ('18b83dba-a896-585a-8616-00590bfadb79'::uuid, 'nsi', '1re', 'Une machine programmable', 'Pourquoi 0,1 + 0,2 ne donne-t-il pas exactement 0,3 en machine ?', 'mcq', '["Parce que 0,1 n’a pas d’écriture binaire finie","Parce que le processeur arrondit à l’entier","Parce que Python est interprété","Parce que l’addition des flottants est interdite"]'::jsonb, 0, 'Comme 1/3 en décimal, 0,1 s’écrit en binaire avec une infinité de chiffres : il est stocké de façon approchée.', 1),
    ('267fb762-42a8-5ddb-a597-252b658f8f58'::uuid, 'nsi', '1re', 'Une machine programmable', 'Python étant interprété, quand une division par zéro en fin de programme est-elle détectée ?', 'mcq', '["Avant le lancement","Jamais","À l’installation de Python","Au moment où la ligne est atteinte"]'::jsonb, 3, 'C’est une erreur d’exécution : le programme peut tourner longtemps avant de s’arrêter sur la faute. Une erreur de syntaxe, elle, empêche le lancement.', 2),
    ('1dcd038d-df58-5f6d-bd10-07819e1b736e'::uuid, 'nsi', '1re', 'Une machine programmable', 'Quel est l’inconvénient d’un exécutable compilé ?', 'mcq', '["Il est lent","Il est lié à une plateforme","Il ne détecte aucune erreur","Il doit être retraduit à chaque lancement"]'::jsonb, 1, 'La compilation donne un programme rapide, mais traduit pour un jeu d’instructions et un système précis.', 3),
    ('05a96c81-ab22-56df-8c25-a6a3fd90e764'::uuid, 'nsi', '1re', 'Une machine programmable', 'L’indécidabilité de l’arrêt d’un programme est…', 'mcq', '["une limite technique qui sera levée","un problème de vitesse des processeurs","un résultat démontré","propre au langage Python"]'::jsonb, 2, 'Aucun programme ne peut décider, dans le cas général, si un autre s’arrête : c’est un théorème, pas un manque de puissance.', 4),
    ('5923d581-138a-5856-9752-10c38bb7cdd2'::uuid, 'nsi', '1re', 'Système d’exploitation et logiciel', 'D’où part un chemin relatif ?', 'mcq', '["De la racine","Du répertoire courant","Du disque dur","Du répertoire de l’utilisateur administrateur"]'::jsonb, 1, 'Un chemin absolu part de la racine de l’arborescence ; un chemin relatif part du répertoire où l’on se trouve.', 1),
    ('2a4febea-77ee-5763-b5f1-9234b1fa9d74'::uuid, 'nsi', '1re', 'Système d’exploitation et logiciel', 'Qu’appelle-t-on les métadonnées d’un fichier ?', 'mcq', '["Son nom, sa taille, ses dates et ses droits","Son contenu chiffré","Une copie de sauvegarde","Le programme qui l’a créé"]'::jsonb, 0, 'Un fichier est une suite d’octets accompagnée de ces informations, gérées par le système de fichiers.', 2),
    ('6a8500c5-206d-53ab-a8c3-cad7e91b13a6'::uuid, 'nsi', '1re', 'Système d’exploitation et logiciel', 'Comment l’ordonnanceur donne-t-il l’illusion que plusieurs programmes tournent en même temps ?', 'mcq', '["En les exécutant sur autant d’ordinateurs","En les compilant ensemble","En supprimant les programmes inactifs","En donnant à chacun de très courtes tranches de temps"]'::jsonb, 3, 'Les processus se relaient si vite sur le processeur que tout paraît simultané.', 3),
    ('633d1858-bb35-5dd8-80c1-54bb87f6468a'::uuid, 'nsi', '1re', 'Système d’exploitation et logiciel', 'Un logiciel gratuit est-il forcément libre ?', 'mcq', '["Oui, toujours","Oui, s’il est téléchargeable","Non, il peut être fermé","Non, un logiciel gratuit ne peut jamais être libre"]'::jsonb, 2, 'Le libre garantit des libertés (étudier, modifier, redistribuer le code) ; la gratuité ne dit rien du code.', 4),
    ('7e4221b8-adcd-5cb2-8511-52e7c14ee002'::uuid, 'nsi', '1re', 'Périphériques', 'Dans quelle famille ranger un micro ?', 'mcq', '["Entrée","Sortie","Stockage","Entrée-sortie"]'::jsonb, 0, 'Un micro convertit une grandeur du monde réel, le son, en données : c’est un périphérique d’entrée.', 1),
    ('9a1e0a04-8335-557d-a75a-05685c41bddb'::uuid, 'nsi', '1re', 'Périphériques', 'Quel est le principe d’un disque dur (HDD) ?', 'mcq', '["De la mémoire flash sans pièce mobile","Une gravure optique","Des plateaux magnétiques lus par une tête mobile","De la mémoire vive alimentée en permanence"]'::jsonb, 2, 'Ses pièces mobiles le rendent plus lent et fragile aux chocs, mais sa capacité reste bon marché.', 2),
    ('a1f37ac5-7c1a-5caa-af86-934b3ad48ed6'::uuid, 'nsi', '1re', 'Périphériques', 'Quel support convient à l’archivage longue durée ?', 'mcq', '["Les registres","La mémoire vive","Le cache","Les bandes magnétiques"]'::jsonb, 3, 'Bandes et supports optiques ont un accès lent mais conviennent à la conservation longue.', 3),
    ('5c148dae-7f11-5b5a-ad92-f7926e1f0670'::uuid, 'nsi', '1re', 'Périphériques', 'Pourquoi la scrutation est-elle moins efficace que l’interruption ?', 'mcq', '["Elle est plus compliquée à programmer","Elle consomme du temps de calcul à vérifier sans cesse le périphérique","Elle ne marche qu’avec le Wi-Fi","Elle fait perdre des données"]'::jsonb, 1, 'Avec l’interruption, c’est le périphérique qui prévient le processeur : celui-ci ne perd pas son temps à surveiller.', 4),
    ('cf2f1ffe-1de6-5938-a675-8c2700557c99'::uuid, 'nsi', '1re', 'IP et le réseau local', 'Avec le masque 255.255.255.0, quelle partie de l’adresse 192.168.1.42 identifie la machine ?', 'mcq', '["192","192.168","42","192.168.1"]'::jsonb, 2, 'Les trois premiers octets désignent le réseau (192.168.1), le dernier la machine (42).', 1),
    ('4fa080e4-61ab-56ae-ae61-540efec99473'::uuid, 'nsi', '1re', 'IP et le réseau local', 'Sur combien d’octets s’écrit une adresse IPv6 ?', 'mcq', '["4","16","6","8"]'::jsonb, 1, 'IPv6 utilise 16 octets, un espace pratiquement illimité ; l’espace d’IPv4, sur 4 octets, est épuisé.', 2),
    ('cccdadcb-4bc9-5d6b-8a49-6830ab5f8864'::uuid, 'nsi', '1re', 'IP et le réseau local', 'Quel équipement distribue les trames dans un réseau local d’après l’adresse MAC ?', 'mcq', '["Le commutateur","Le routeur","Le serveur DNS","La passerelle Internet"]'::jsonb, 0, 'Le commutateur (switch) travaille dans le réseau local ; le routeur relie des réseaux différents d’après l’adresse IP.', 3),
    ('7fbad327-955c-5618-a502-3aa5cae03f6d'::uuid, 'nsi', '1re', 'IP et le réseau local', 'Le destinataire n’est pas sur mon réseau. À qui remet-on le paquet ?', 'mcq', '["Directement au destinataire","Au serveur DNS","Au commutateur, qui le diffuse partout","À la passerelle, c’est-à-dire au routeur"]'::jsonb, 3, 'Le masque dit si le destinataire est local ; sinon, on confie le paquet à la passerelle.', 4),
    ('51b8c21e-42a1-50a7-848a-4cd75a0299b9'::uuid, 'nsi', '1re', 'TCP et le bit alterné', 'Dans le bit alterné, quelle perte provoque un doublon chez le récepteur ?', 'mcq', '["La perte de l’accusé de réception","La perte du message","La perte de la connexion","Aucune perte"]'::jsonb, 0, 'Si l’ACK se perd, l’émetteur renvoie un message déjà reçu : c’est ce doublon que le numéro permet de repérer.', 1),
    ('a1c6a98e-ccb9-58ac-b780-f05051ab2bdb'::uuid, 'nsi', '1re', 'TCP et le bit alterné', 'Quelle suite de numéros portent les messages successifs du bit alterné ?', 'mcq', '["1, 2, 3, 4…","0, 0, 0, 0…","Des numéros aléatoires","0, 1, 0, 1…"]'::jsonb, 3, 'Le numéro alterne entre 0 et 1 ; chaque accusé rappelle le numéro qu’il acquitte.', 2),
    ('67dfb1eb-6b0d-59d7-abba-fc53e3a6ff31'::uuid, 'nsi', '1re', 'TCP et le bit alterné', 'À quoi sert le contrôle de flux de TCP ?', 'mcq', '["À chiffrer les données","À ne pas noyer un récepteur lent","À choisir le chemin des paquets","À traduire les noms de domaine"]'::jsonb, 1, 'Le contrôle de flux protège le récepteur ; le contrôle de congestion, lui, protège le réseau.', 3),
    ('47e1d210-c895-50ed-8c50-1f31a2d1907b'::uuid, 'nsi', '1re', 'TCP et le bit alterné', 'Pour télécharger un fichier, quel protocole utilise-t-on ?', 'mcq', '["UDP, car il est plus rapide","Aucun, IP suffit","TCP, car chaque octet doit arriver, dans l’ordre","Le bit alterné seul"]'::jsonb, 2, 'Un fichier doit être complet et ordonné : TCP retransmet et remet en ordre. UDP convient au direct.', 4),
    ('24e6e0f6-e1ee-565d-9d5b-a68d983008d2'::uuid, 'nsi', '1re', 'Interactions client-serveur', 'Quel port utilise d’ordinaire une connexion HTTPS ?', 'mcq', '["80","443","21","8080"]'::jsonb, 1, 'HTTP utilise le port 80, HTTPS le port 443.', 1),
    ('83f20770-b539-528a-ad7d-df67131adb89'::uuid, 'nsi', '1re', 'Interactions client-serveur', 'Que signifie un code de statut commençant par 5, comme 500 ?', 'mcq', '["Une erreur du serveur","Une redirection","Une faute du client","Un succès"]'::jsonb, 0, 'Le premier chiffre situe : 2 succès, 3 redirection, 4 faute du client, 5 faute du serveur.', 2),
    ('83fac551-a0ac-55dd-a650-d570d13b8fbf'::uuid, 'nsi', '1re', 'Interactions client-serveur', 'Quelle méthode HTTP convient à l’envoi d’un mot de passe ?', 'mcq', '["GET","HEAD","Aucune, c’est impossible","POST"]'::jsonb, 3, 'POST place les données dans le corps de la requête : elles n’apparaissent ni dans l’URL ni dans l’historique.', 3),
    ('18157aca-277c-5ffe-bc18-a7267e505749'::uuid, 'nsi', '1re', 'Interactions client-serveur', 'Quelle est la première étape quand on ouvre une page web par son nom de domaine ?', 'mcq', '["Envoyer la requête HTTP","Analyser le HTML","Interroger le DNS pour obtenir l’adresse IP","Télécharger les images"]'::jsonb, 2, 'Il faut d’abord l’adresse IP du serveur ; viennent ensuite la connexion TCP, la requête et la réponse.', 4),
    ('a30d730f-6b69-5666-88f1-c65984945540'::uuid, 'nsi', '1re', 'Pages interactives', 'Quel langage gère la présentation d’une page : couleurs, polices, marges ?', 'mcq', '["HTML","JavaScript","CSS","HTTP"]'::jsonb, 2, 'HTML donne la structure, CSS la présentation, JavaScript le comportement.', 1),
    ('9512f07e-f0f0-5f67-805f-7f882e989a7f'::uuid, 'nsi', '1re', 'Pages interactives', 'Pourquoi la séparation HTML / CSS aide-t-elle les lecteurs d’écran ?', 'mcq', '["Ils s’appuient sur la structure HTML","Ils lisent les couleurs du CSS","Ils exécutent le JavaScript plus vite","Ils n’ont besoin d’aucun des trois"]'::jsonb, 0, 'Une structure HTML propre (titres, listes, liens) permet à un lecteur d’écran de restituer la page.', 2),
    ('435f12b1-f869-577b-a1bf-a4fa95941234'::uuid, 'nsi', '1re', 'Pages interactives', 'Pourquoi une validation en JavaScript ne protège-t-elle de rien ?', 'mcq', '["JavaScript est trop lent","Elle ne marche que sur ordinateur","Elle ne s’exécute que sur le serveur","N’importe qui peut envoyer la requête sans passer par la page"]'::jsonb, 3, 'Le code client est sous le contrôle du visiteur : toute donnée doit être revérifiée côté serveur.', 3),
    ('c37922b8-9d33-5742-91f0-95218ca53e46'::uuid, 'nsi', '1re', 'Pages interactives', 'Un champ de type « courriel » dans un formulaire garantit-il une adresse valide côté serveur ?', 'mcq', '["Oui, le navigateur le garantit","Non, c’est une aide à la saisie, pas une garantie","Oui, si le formulaire utilise POST","Oui, s’il est en HTTPS"]'::jsonb, 1, 'Les types de champ aident l’utilisateur ; le serveur doit toujours vérifier ce qu’il reçoit.', 4),
    ('04f2ca74-4107-5bfb-96b2-6ab89e930a99'::uuid, 'nsi', '1re', 'Langages de programmation', 'Que provoque 3 + "4" en Python ?', 'mcq', '["Le nombre 7","La chaîne \"34\"","Une erreur de type","Le nombre 34"]'::jsonb, 2, 'Le typage fort de Python refuse d’additionner un entier et une chaîne, sans conversion silencieuse.', 1),
    ('af128d4b-ec52-55c1-9ce5-10502dd176cc'::uuid, 'nsi', '1re', 'Langages de programmation', 'Lequel de ces types Python n’est PAS modifiable en place ?', 'mcq', '["Le tuple","La liste","Le dictionnaire","Aucun des trois"]'::jsonb, 0, 'La liste et le dictionnaire se modifient en place ; le tuple et la chaîne non.', 2),
    ('fafc435a-446f-54be-8d9e-f41a90943a38'::uuid, 'nsi', '1re', 'Langages de programmation', 'Qu’est-ce que la sémantique d’un langage ?', 'mcq', '["Les règles d’écriture correcte","La liste de ses mots-clés","Sa vitesse d’exécution","Ce que signifie un programme"]'::jsonb, 3, 'La syntaxe dit ce qui est bien écrit ; la sémantique, ce que cela veut dire.', 3),
    ('085edfac-3c9e-5e41-88f8-cdedcb06e8e4'::uuid, 'nsi', '1re', 'Langages de programmation', 'Quelle est la force principale du langage C ?', 'mcq', '["Il s’exécute dans tout navigateur","Il est rapide et proche de la machine","Il n’a pas de types","Il est le plus fourni en bibliothèques scientifiques"]'::jsonb, 1, 'C est rapide et proche de la machine ; JavaScript s’exécute dans le navigateur ; Python brille par ses bibliothèques.', 4),
    ('f6b60f30-6e9f-5c79-9675-14d39c7c2c5e'::uuid, 'nsi', '1re', 'Fonctions et structure du code', 'Dans def carre(x): return x * x puis carre(5), que sont x et 5 ?', 'mcq', '["x est l’argument, 5 le paramètre","x est le paramètre, 5 l’argument","Ce sont deux paramètres","Ce sont deux valeurs de retour"]'::jsonb, 1, 'Le paramètre est le nom dans la définition ; l’argument, la valeur passée à l’appel.', 1),
    ('e692073a-ea94-586e-be7d-c1166ad29443'::uuid, 'nsi', '1re', 'Fonctions et structure du code', 'Où s’écrit la spécification d’une fonction en Python ?', 'mcq', '["Dans la docstring, juste sous la ligne de définition","Dans un fichier à part","Dans le nom de la fonction","Dans un commentaire en fin de fichier"]'::jsonb, 0, 'La docstring dit ce que fait la fonction, ce qu’elle reçoit, ce qu’elle rend et ce qu’elle garantit.', 2),
    ('0bb3bfab-0016-5628-b1dd-7ac89e0fa900'::uuid, 'nsi', '1re', 'Fonctions et structure du code', 'Comment appelle-t-on les conditions que doivent remplir les entrées d’une fonction ?', 'mcq', '["Les postconditions","Les invariants","Les préconditions","Les effets de bord"]'::jsonb, 2, 'Les préconditions portent sur ce que la fonction reçoit ; les postconditions sur ce qu’elle garantit en sortie.', 3),
    ('b14e1ab8-4e23-56e8-92ca-e79359fa2bb1'::uuid, 'nsi', '1re', 'Fonctions et structure du code', 'Quel est l’avantage de découper un programme en fonctions pour la correction des bugs ?', 'mcq', '["Le programme devient plus rapide","Les bugs disparaissent","Python l’exige","Une correction faite une fois vaut partout où la fonction sert"]'::jsonb, 3, 'Réutiliser une fonction, c’est aussi corriger en un seul endroit ; on peut en plus la tester séparément.', 4),
    ('641e8d2f-95a7-57b0-9c60-51d0a10d64bd'::uuid, 'nsi', '1re', 'Vérifications', 'Lequel de ces cas est un cas limite pour une fonction qui traite une liste ?', 'mcq', '["Une liste de dix nombres ordinaires","La liste vide","Une liste triée de valeurs moyennes","Une liste de nombres pairs"]'::jsonb, 1, 'Liste vide, un seul élément, zéro, valeur extrême : c’est là que se cachent les bugs.', 1),
    ('1a16ffb1-b78f-58b1-8f21-60df1fcfaad3'::uuid, 'nsi', '1re', 'Vérifications', 'Que vérifie un test d’intégration ?', 'mcq', '["Que les fonctions travaillent bien ensemble","Une seule fonction isolée","La vitesse du programme","L’orthographe des commentaires"]'::jsonb, 0, 'Le test unitaire vérifie une fonction ; le test d’intégration, leur coopération.', 2),
    ('435556aa-9209-51de-8807-2373caef78d8'::uuid, 'nsi', '1re', 'Vérifications', 'Que doit expliquer un bon commentaire ?', 'mcq', '["Ce que fait chaque ligne","Le nom de l’auteur","La date de modification","Pourquoi le code est écrit ainsi"]'::jsonb, 3, 'Le code dit déjà le « quoi » ; le commentaire doit dire le « pourquoi ».', 3),
    ('c56714ec-fb91-553b-9b11-1765c30c2ebb'::uuid, 'nsi', '1re', 'Vérifications', 'Que faut-il faire avant de corriger un bug qu’on a localisé ?', 'mcq', '["Supprimer la fonction","Corriger au hasard et relancer","Comprendre sa cause","Ajouter des commentaires partout"]'::jsonb, 2, 'Une correction faite sans comprendre la cause déplace le bug plus qu’elle ne le supprime.', 4),
    ('6b249885-2817-5c97-a73d-a622e52f6f7b'::uuid, 'nsi', '1re', 'Terminaison et complexité', 'Pour quel type de boucle faut-il prouver la terminaison ?', 'mcq', '["La boucle bornée (for)","La boucle non bornée (while)","Aucune, elles terminent toujours","Seulement les boucles imbriquées"]'::jsonb, 1, 'Une boucle for a un nombre de tours fixé d’avance ; une boucle while peut tourner indéfiniment.', 1),
    ('a71726db-843b-5984-83d1-92897af69982'::uuid, 'nsi', '1re', 'Terminaison et complexité', 'Quelle est la complexité de l’accès à la case i d’un tableau ?', 'mcq', '["Linéaire","Logarithmique","Quadratique","Constante"]'::jsonb, 3, 'L’accès par indice est immédiat, quelle que soit la taille du tableau.', 2),
    ('6dfae1c2-9d67-51a0-b514-ede0e89b5335'::uuid, 'nsi', '1re', 'Terminaison et complexité', 'Pourquoi un algorithme exponentiel est-il impraticable ?', 'mcq', '["Au-delà de quelques dizaines d’éléments, le nombre d’opérations explose","Il ne termine jamais","Il donne des résultats faux","Il demande un tableau trié"]'::jsonb, 0, 'Essayer toutes les combinaisons de n éléments demande de l’ordre de 2 puissance n opérations.', 3),
    ('7c2af943-d7a8-59e7-a39a-1c75ed018b21'::uuid, 'nsi', '1re', 'Terminaison et complexité', 'Dans une recherche séquentielle, quel est le meilleur cas ?', 'mcq', '["L’élément est absent","L’élément est au milieu","L’élément est en tête","L’élément est en dernière position"]'::jsonb, 2, 'Une seule comparaison suffit s’il est en tête ; s’il est absent, il en faut n, c’est le pire cas.', 4),
    ('efed2bcb-042f-51ae-b9d5-9ebd669aae87'::uuid, 'nsi', '1re', 'Tableaux et matrices', 'Quel est l’indice du dernier élément d’un tableau de n éléments ?', 'mcq', '["n","n + 1","1","n − 1"]'::jsonb, 3, 'Les indices vont de 0 à n − 1 ; demander l’indice n provoque une erreur.', 1),
    ('3dd97b86-63ff-50ed-a224-47a33d901f9f'::uuid, 'nsi', '1re', 'Tableaux et matrices', 'Que produit le tranchage t[1:3] d’une liste t ?', 'mcq', '["Une nouvelle liste, indépendante de t","Une vue qui modifie t","Un tuple","Une erreur"]'::jsonb, 0, 'Le tranchage fabrique une nouvelle liste : c’est une façon simple d’obtenir une copie.', 2),
    ('5ab3a331-7dd6-51c0-86bb-292f298b0854'::uuid, 'nsi', '1re', 'Tableaux et matrices', 'Quelle façon de construire un tableau est à la fois plus lisible et plus rapide ?', 'mcq', '["Par ajouts successifs dans une boucle","Par compréhension","En multipliant une liste par un entier","En le recopiant à la main"]'::jsonb, 1, 'Une liste par compréhension, comme [i * i for i in range(10)], tient en une ligne.', 3),
    ('1167dd92-cab1-5c17-bdd4-e65c12dfddd0'::uuid, 'nsi', '1re', 'Tableaux et matrices', 'On crée m = [[0] * 3] * 3 puis on exécute m[0][0] = 1. Que devient m ?', 'mcq', '["Seule la première case vaut 1","Toute la matrice vaut 1","La première case de chaque ligne vaut 1","Python lève une erreur"]'::jsonb, 2, 'Les trois lignes sont la même liste : modifier une case la modifie dans chaque ligne. Il faut construire chaque ligne par compréhension.', 4),
    ('7b0bd8de-005d-5fa9-abf1-0baeabf6c739'::uuid, 'nsi', '1re', 'Algorithmes sur les tableaux', 'Que se passe-t-il si l’on applique la dichotomie à un tableau non trié ?', 'mcq', '["Python lève une erreur","Elle devient linéaire","Elle trie le tableau au passage","Elle peut rendre un résultat faux sans le signaler"]'::jsonb, 3, 'Rien ne prévient : la dichotomie élimine une moitié à tort et répond faux.', 1),
    ('83a9e84f-bb4a-5e69-af61-a21f69420469'::uuid, 'nsi', '1re', 'Algorithmes sur les tableaux', 'Quel est l’invariant du calcul du maximum ?', 'mcq', '["Après i tours, le candidat est le maximum des i premiers éléments","Le candidat est toujours le premier élément","Le tableau est trié après chaque tour","Le candidat diminue à chaque tour"]'::jsonb, 0, 'Cet invariant, vrai à la fin du parcours, prouve que le candidat est le maximum de tout le tableau.', 2),
    ('e671338d-7e1b-54ac-a678-0b9850c108f8'::uuid, 'nsi', '1re', 'Algorithmes sur les tableaux', 'Sur quel tableau le tri par insertion est-il quasi linéaire ?', 'mcq', '["Un tableau trié à l’envers","Un tableau presque trié","Un tableau aléatoire","Un tableau de taille paire"]'::jsonb, 1, 'Chaque élément est déjà presque à sa place : il y a très peu de décalages à faire.', 3),
    ('a2e3dc46-7920-5615-962f-389efbb5a388'::uuid, 'nsi', '1re', 'Algorithmes sur les tableaux', 'Quel est le point fort du tri par sélection ?', 'mcq', '["Il est en n log n","Il est linéaire sur un tableau trié","Il fait un nombre d’échanges minimal","Il ne fait aucune comparaison"]'::jsonb, 2, 'Chaque tour place un élément à sa position finale par un seul échange ; les comparaisons restent quadratiques.', 4),
    ('bcd2df97-e382-59cc-b3e9-9c8283f8d1ba'::uuid, 'nsi', '1re', 'Traitement de tables matricielles (tableur)', 'Que représente une ligne dans une table de données ?', 'mcq', '["Un descripteur","Un enregistrement","Un séparateur","Un type"]'::jsonb, 1, 'Chaque ligne est un enregistrement, chaque colonne un descripteur.', 1),
    ('f582955a-2e9a-5e80-83b9-0197212d5c03'::uuid, 'nsi', '1re', 'Traitement de tables matricielles (tableur)', 'Pourquoi une liste de listes est-elle fragile pour représenter une table ?', 'mcq', '["On accède aux colonnes par un numéro : tout se casse si une colonne se déplace","Elle prend trop de mémoire","Elle ne peut pas contenir de texte","Elle ne se trie pas"]'::jsonb, 0, 'Avec une liste de dictionnaires, on accède par un nom, et le code résiste au changement d’ordre.', 2),
    ('40e54f45-9e42-5494-ae64-d73abd0beca9'::uuid, 'nsi', '1re', 'Traitement de tables matricielles (tableur)', 'Que se passe-t-il si deux lignes portent la même clé lors d’une fusion ?', 'mcq', '["Python refuse la fusion","La seconde ligne est ignorée","Les deux tables sont triées","La fusion produit des doublons silencieux"]'::jsonb, 3, 'Une clé doit identifier un enregistrement de façon unique, sinon le résultat est faussé sans alerte.', 3),
    ('78b1a2f0-952c-56ef-9ea8-fa5ff8c3194d'::uuid, 'nsi', '1re', 'Traitement de tables matricielles (tableur)', 'Quel piège pose une virgule décimale dans un fichier CSV séparé par des virgules ?', 'mcq', '["Le fichier devient binaire","Les nombres sont arrondis","Elle peut être prise pour un séparateur de colonnes","Aucun"]'::jsonb, 2, '« 3,5 » risque d’être lu comme deux colonnes : 3 et 5. D’où l’usage du point-virgule comme séparateur en France.', 4),
    ('77973f5a-90dc-5ab1-9788-00a049a1729a'::uuid, 'nsi', '1re', 'Algorithmes gloutons', 'Dans le rendu de monnaie glouton, quelle pièce prend-on à chaque étape ?', 'mcq', '["La plus petite pièce","La plus grosse pièce qui n’excède pas ce qui reste à rendre","Une pièce au hasard","La pièce la plus fréquente"]'::jsonb, 1, 'Le glouton prend le meilleur choix immédiat, sans jamais revenir en arrière.', 1),
    ('324e5e69-394f-5453-b02d-fe7e09606d66'::uuid, 'nsi', '1re', 'Algorithmes gloutons', 'Quel critère glouton est prouvé optimal pour le choix d’activités ?', 'mcq', '["Choisir l’activité qui finit le plus tôt","Choisir la plus longue","Choisir celle qui commence le plus tôt","Choisir au hasard"]'::jsonb, 0, 'Finir le plus tôt laisse le plus de place aux activités suivantes : ce choix est démontré optimal.', 2),
    ('13adf467-0d33-5be8-9ef3-008934853899'::uuid, 'nsi', '1re', 'Algorithmes gloutons', 'Avec les pièces de 1, 2 et 5, combien de pièces le glouton rend-il pour 8 ?', 'mcq', '["Quatre","Deux","Huit","Trois"]'::jsonb, 3, '5, puis 2 (il reste 1), puis 1 : trois pièces, et c’est optimal avec ce système.', 3),
    ('2015e23a-911a-5d34-91bf-092bba955333'::uuid, 'nsi', '1re', 'Algorithmes gloutons', 'Quelle est l’étape que le glouton ne fait jamais ?', 'mcq', '["Trier les candidats","Ajouter un candidat à la solution","Revenir sur un choix déjà fait","Évaluer les candidats selon un critère"]'::jsonb, 2, 'Un choix glouton est définitif : c’est ce qui le rend rapide, et parfois non optimal.', 4),
    ('af951b93-defa-5503-bdcc-dbe10b2c72aa'::uuid, 'nsi', '1re', 'Algorithmes d’apprentissage', 'Prédire le prix d’un logement relève de…', 'mcq', '["la classification","la régression","le partitionnement","l’apprentissage non supervisé"]'::jsonb, 1, 'On prédit une valeur numérique : c’est une régression. Classer un courriel en indésirable ou non est une classification.', 1),
    ('30cc0139-02d6-51b3-bf62-0e229a204b1f'::uuid, 'nsi', '1re', 'Algorithmes d’apprentissage', 'Que se passe-t-il si k est choisi trop petit dans les k plus proches voisins ?', 'mcq', '["La prédiction suit le bruit","Les frontières s’effacent","Le calcul devient impossible","Le modèle refuse de prédire"]'::jsonb, 0, 'Avec un seul voisin, un exemple aberrant suffit à fausser la prédiction.', 2),
    ('e0273335-5d3f-5000-812c-02edd6409c59'::uuid, 'nsi', '1re', 'Algorithmes d’apprentissage', 'Que cherche l’apprentissage non supervisé ?', 'mcq', '["Une étiquette pour chaque donnée nouvelle","Le prix d’un bien","La vitesse de calcul","Une structure dans des données sans étiquette"]'::jsonb, 3, 'Le partitionnement, par exemple, regroupe les données semblables sans étiquette donnée d’avance.', 3),
    ('c2435fa2-0c9f-56e3-9f2e-5792754b9d00'::uuid, 'nsi', '1re', 'Algorithmes d’apprentissage', 'Un modèle constate qu’acheter des glaces et se noyer sont liés. Que peut-on en conclure ?', 'mcq', '["Que les glaces causent les noyades","Que les noyades causent l’achat de glaces","Rien sur la cause : une corrélation n’est pas une cause","Que le modèle est en surapprentissage"]'::jsonb, 2, 'Un modèle corrèle sans expliquer ; ici, l’été fait monter les deux à la fois.', 4),
    ('f822ed38-8c17-5c99-aa46-169590f88ae4'::uuid, 'si', '1re', 'Structure de la démarche de projet', 'Dans le triangle du projet, que se passe-t-il si l’on réduit le délai ?', 'mcq', '["Rien ne change pour le reste","Le coût monte ou la qualité se dégrade","La qualité s’améliore forcément","Le coût baisse automatiquement"]'::jsonb, 1, 'Les trois contraintes sont liées : en améliorer une pèse sur les deux autres.', 1),
    ('995321e0-ea91-5468-9189-50c1969c6a53'::uuid, 'si', '1re', 'Structure de la démarche de projet', 'Quelles trois questions structurent l’analyse du besoin ?', 'mcq', '["Combien, quand, où ?","Comment, avec quoi, pour combien ?","À qui rend-il service, sur quoi agit-il, dans quel but ?","Qui paie, qui fabrique, qui vend ?"]'::jsonb, 2, 'Le produit rend service à quelqu’un, agit sur quelque chose, dans un but précis : c’est le point de départ du cahier des charges.', 2),
    ('af4c53fd-3ba6-5dd9-babf-22962b1a5f40'::uuid, 'si', '1re', 'Structure de la démarche de projet', 'Pourquoi « utiliser un moteur pas à pas » n’a-t-il pas sa place dans un cahier des charges fonctionnel ?', 'mcq', '["C’est une solution, qui ferme d’avance les autres pistes","Ce moteur est trop cher","Il manque une tolérance","Un moteur n’est pas une contrainte normative"]'::jsonb, 0, 'Le cahier des charges dit ce qu’il faut faire, jamais comment le faire.', 3),
    ('9aa64a87-ccdd-53dd-9f7d-6702bb93e8a5'::uuid, 'si', '1re', 'Structure de la démarche de projet', 'L’écart entre le réel mesuré et le cahier des charges valide…', 'mcq', '["La pertinence du modèle","La justesse des hypothèses","Le planning du projet","La conformité du produit"]'::jsonb, 3, 'L’écart 3 compare le produit réel au besoin exprimé : il dit si le produit est conforme.', 4),
    ('fe01fd18-244f-51c7-a17b-ccdfec2f35c2'::uuid, 'si', '1re', 'Analyser un système', 'Dans « autonomie : 40 km ± 5 km », que représente « ± 5 km » ?', 'mcq', '["Le critère","Le niveau","La flexibilité","La fonction"]'::jsonb, 2, 'La flexibilité est la tolérance admise autour du niveau attendu (40 km), le critère étant l’autonomie.', 1),
    ('7f6e92fa-27ce-57f2-954a-3050ef0576a3'::uuid, 'si', '1re', 'Analyser un système', 'Quels sont les maillons de la chaîne d’information ?', 'mcq', '["Alimenter, distribuer, convertir","Acquérir, traiter, communiquer","Mesurer, stocker, afficher","Transmettre, agir, contrôler"]'::jsonb, 1, 'La chaîne d’information décide : elle acquiert par les capteurs, traite, puis communique.', 2),
    ('a8c71927-96bb-5ede-a227-69707fcdd27a'::uuid, 'si', '1re', 'Analyser un système', 'Une batterie appartient à quel maillon de la chaîne d’énergie ?', 'mcq', '["Transmettre","Convertir","Agir","Alimenter"]'::jsonb, 3, 'La batterie fournit l’énergie au système : elle alimente la chaîne.', 3),
    ('d9b959a8-4356-58b7-ac07-1e98e1f61511'::uuid, 'si', '1re', 'Analyser un système', 'Qu’est-ce qui fait d’un ensemble de composants un véritable système ?', 'mcq', '["La boucle où l’information commande l’énergie et les capteurs renvoient de l’information","La présence d’un moteur puissant","La juxtaposition d’une chaîne d’énergie et d’une chaîne d’information","Un cahier des charges signé"]'::jsonb, 0, 'Les deux chaînes se croisent : c’est cette boucle, et non leur simple juxtaposition, qui fait un système.', 4),
    ('f54c9fc0-2e5e-548a-a3a2-970865aa5a6d'::uuid, 'si', '1re', 'Le projet : la phase de conception', 'Qu’est-ce qui est interdit pendant la phase de convergence ?', 'mcq', '["Évaluer les idées","Rouvrir la liste des idées","Retenir une solution","Utiliser un tableau multicritère"]'::jsonb, 1, 'La divergence interdit de juger, la convergence interdit de rouvrir la liste : chaque temps a sa règle.', 1),
    ('caf4f28f-1826-5ac3-bba3-632f47ce62c0'::uuid, 'si', '1re', 'Le projet : la phase de conception', 'Dans un tableau multicritère, que se passe-t-il si l’on change les poids des critères ?', 'mcq', '["Rien, le classement est objectif","Le tableau devient invalide","Le classement des solutions peut changer","Seule la meilleure solution reste en tête"]'::jsonb, 2, 'Le tableau rend le choix explicite et discutable : changer les poids change le classement.', 2),
    ('ff69a753-8b2f-571c-a86d-e6b2848e00a1'::uuid, 'si', '1re', 'Le projet : la phase de conception', 'Qu’appelle-t-on solution constructive ?', 'mcq', '["La pièce, le composant ou le programme retenu","Ce que le produit doit rendre à l’utilisateur","Une contrainte du milieu extérieur","Un critère du cahier des charges"]'::jsonb, 0, 'On descend de la fonction de service à la fonction technique, puis à la solution constructive, le choix concret.', 3),
    ('638a03ed-4fee-512c-9cd9-2ff2f66af8c3'::uuid, 'si', '1re', 'Le projet : la phase de conception', 'Laquelle de ces hypothèses est une hypothèse simplificatrice courante en simulation ?', 'mcq', '["Le produit est déjà vendu","Le budget est illimité","Le client a validé le prototype","Les frottements sont négligés"]'::jsonb, 3, 'Solide indéformable, frottements négligés, régime permanent : ces hypothèses bornent la validité du résultat.', 4),
    ('d9ccc38d-5f6f-54c7-9282-1a533c5f06bc'::uuid, 'si', '1re', 'Énergie et mécanique', 'Quel est le rendement global de cinq éléments de rendement 0,9 en cascade ?', 'mcq', '["0,90","0,45","0,59","0,81"]'::jsonb, 2, '0,9 puissance 5 ≈ 0,59 : les rendements se multiplient, la chaîne longue perd beaucoup.', 1),
    ('7a8fb7c4-2404-54c6-bc1f-af046ddb14b0'::uuid, 'si', '1re', 'Énergie et mécanique', 'Quel système transforme une rotation en translation alternée ?', 'mcq', '["Bielle-manivelle","Poulies-courroie","Engrenages","Réducteur"]'::jsonb, 0, 'La bielle-manivelle donne un mouvement de va-et-vient, comme dans un moteur à piston.', 2),
    ('b70145bc-7ad8-5efa-8e80-9911c87bde39'::uuid, 'si', '1re', 'Énergie et mécanique', 'Pour un système poulies-courroie, de quoi dépend le rapport de transmission ?', 'mcq', '["Du nombre de dents","Des diamètres des poulies","Du pas de la vis","De la longueur de la courroie"]'::jsonb, 1, 'Le rapport d’un système poulies-courroie dépend des diamètres ; il transmet la rotation à distance.', 3),
    ('eec948c1-157e-552c-9eb1-c7401243d47d'::uuid, 'si', '1re', 'Énergie et mécanique', 'Que dit la relation fondamentale de la dynamique ?', 'mcq', '["Somme des forces = 0","P = C × ω","E = P × t","Somme des forces = m × a"]'::jsonb, 3, 'En dynamique, la somme des forces n’est plus nulle : elle donne l’accélération.', 4),
    ('f0ea086b-08bc-5e77-8fe9-1a751eced00d'::uuid, 'si', '1re', 'Information, capteurs et programmation', 'Combien de niveaux offre une conversion analogique-numérique sur 12 bits ?', 'mcq', '["1 024","4 096","256","2 048"]'::jsonb, 1, '2 puissance 12 = 4 096 niveaux.', 1),
    ('18e7d71a-5dba-5299-9ea1-e33d310c2e55'::uuid, 'si', '1re', 'Information, capteurs et programmation', 'Que font les deux opérations du CAN ?', 'mcq', '["Il amplifie puis filtre","Il chiffre puis compresse","Il échantillonne dans le temps et quantifie en amplitude","Il code en ASCII puis transmet"]'::jsonb, 2, 'L’échantillonnage découpe le temps, la quantification arrondit l’amplitude aux niveaux disponibles.', 2),
    ('2961b4fb-57e7-5d1b-a588-88627cc32251'::uuid, 'si', '1re', 'Information, capteurs et programmation', 'Quel type de capteur fournit une valeur codée sur un bus I2C ou SPI ?', 'mcq', '["Un capteur numérique","Un capteur TOR","Un capteur analogique","Un fin de course"]'::jsonb, 0, 'Le capteur numérique transmet directement une valeur codée sur un bus de communication.', 3),
    ('25ee6722-fe1a-54a7-b7fe-a13a63a0856d'::uuid, 'si', '1re', 'Information, capteurs et programmation', 'Dans quel ordre s’enchaînent les étapes de la boucle d’un système embarqué ?', 'mcq', '["Écrire les sorties, lire, calculer","Calculer, écrire, lire les entrées","Lire les sorties, écrire les entrées","Lire les entrées, calculer, écrire les sorties"]'::jsonb, 3, 'Le programme lit les capteurs, calcule l’action, commande les actionneurs, puis recommence.', 4),
    ('05622455-e284-5b90-9cdf-1ba9869082e8'::uuid, 'si', '1re', 'Le projet : la phase de planification', 'Comment obtient-on les dates au plus tôt dans un réseau PERT ?', 'mcq', '["En parcourant le réseau de la fin vers le début","En parcourant le réseau du début vers la fin","En lisant le diagramme de Gantt à l’envers","En divisant la durée totale par le nombre de tâches"]'::jsonb, 1, 'Les dates au plus tôt se calculent du début vers la fin, les dates au plus tard dans le sens inverse.', 1),
    ('ca53552d-9ae5-5efe-82c8-9369466f349f'::uuid, 'si', '1re', 'Le projet : la phase de planification', 'Que donne la longueur du chemin critique ?', 'mcq', '["La durée minimale du projet","Le coût total du projet","La marge totale disponible","Le nombre de ressources nécessaires"]'::jsonb, 0, 'Le chemin critique, suite des tâches de marge nulle, fixe la durée la plus courte possible du projet.', 2),
    ('c2a69f05-b2cb-5da9-bb11-6c8bfbe4de54'::uuid, 'si', '1re', 'Le projet : la phase de planification', 'Quel outil sert surtout à suivre l’avancement au quotidien ?', 'mcq', '["Le réseau PERT","Le tableau multicritère","Le diagramme de Gantt","Le cahier des charges"]'::jsonb, 2, 'Le Gantt montre les tâches simultanées sur une échelle de temps : c’est le tableau de bord.', 3),
    ('300eec97-1c80-52a6-9a3f-17752be5bdea'::uuid, 'si', '1re', 'Le projet : la phase de planification', 'Un retard sur une tâche disposant d’une marge suffisante retarde le projet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Tant que le retard reste inférieur à sa marge, il se résorbe sans toucher la date de fin.', 4),
    ('d4878e53-47f3-5b51-a386-69de5865eab5'::uuid, 'si', '1re', 'Le projet : les phases de réalisation et de terminaison', 'Que doit-on faire de toute évolution du besoin en cours de réalisation ?', 'mcq', '["L’appliquer directement","La refuser systématiquement","L’ignorer jusqu’à la livraison","La tracer, la chiffrer et la valider"]'::jsonb, 3, 'La gestion des modifications impose de tracer, chiffrer et valider chaque évolution.', 1),
    ('6fddb63c-a5e2-57f6-962f-13fc6d3d406d'::uuid, 'si', '1re', 'Le projet : les phases de réalisation et de terminaison', '« A-t-on construit le bon produit ? » : quelle démarche pose cette question ?', 'mcq', '["Valider","Vérifier","Planifier","Concevoir"]'::jsonb, 0, 'Valider confronte le produit au besoin réel ; vérifier le confronte aux spécifications.', 2),
    ('e8cec5dd-c93f-539a-8e20-0a193d226971'::uuid, 'si', '1re', 'Le projet : les phases de réalisation et de terminaison', 'Lors d’un essai, l’écart vient d’un instrument mal réglé. Quelle origine est en cause ?', 'mcq', '["Le produit","Une hypothèse du modèle","Le protocole de mesure","Le cahier des charges"]'::jsonb, 2, 'L’instrument et les conditions d’essai relèvent du protocole de mesure, à examiner avant d’accuser le produit.', 3),
    ('dc149853-e09a-56e0-a7b0-be1b5a3d24bf'::uuid, 'si', '1re', 'Le projet : les phases de réalisation et de terminaison', 'Que comprend la documentation livrée à la fin du projet ?', 'mcq', '["Le brainstorming initial","Notice, plan de maintenance et dossier technique","Le tableau multicritère uniquement","La liste des idées écartées"]'::jsonb, 1, 'La documentation permet d’utiliser et de maintenir le produit après la livraison.', 4),
    ('426ffa53-cc7a-5d22-b719-8f813e72d100'::uuid, 'si', '1re', 'Le SysML', 'Quel diagramme SysML montre la décomposition du système en blocs ?', 'mcq', '["Le diagramme de séquence","Le diagramme de définition de blocs","Le diagramme de cas d’utilisation","Le diagramme d’états"]'::jsonb, 1, 'Le diagramme de définition de blocs décrit la structure : de quoi le système est fait.', 1),
    ('e7d520ea-7e37-5214-900e-30688de85e9d'::uuid, 'si', '1re', 'Le SysML', 'Quel diagramme montre les échanges de messages dans le temps ?', 'mcq', '["Le diagramme de séquence","Le diagramme des exigences","Le diagramme de blocs internes","Le diagramme de définition de blocs"]'::jsonb, 0, 'Le diagramme de séquence décrit un comportement, en ordonnant les messages dans le temps.', 2),
    ('2cb94d9d-24a6-57e8-8941-cd80276f79e8'::uuid, 'si', '1re', 'Le SysML', 'Dans un diagramme d’états, qu’est-ce qu’une garde ?', 'mcq', '["Un acteur extérieur","Un flux d’énergie","Une condition à laquelle une transition est soumise","Un bloc de sécurité"]'::jsonb, 2, 'Une transition est déclenchée par un événement et peut être soumise à une condition : la garde.', 3),
    ('9ba3e885-bf93-514d-bc6b-9f1502bc8cbf'::uuid, 'si', '1re', 'Le SysML', 'Quel composant réalise la fonction « distribuer » de la chaîne d’énergie ?', 'mcq', '["L’actionneur","Le capteur","Le réducteur","Le préactionneur"]'::jsonb, 3, 'Le préactionneur distribue l’énergie à l’actionneur sur ordre de la chaîne d’information.', 4),
    ('d9be05d7-5b3c-5e38-9554-23631056128f'::uuid, 'si', '1re', 'Calcul vectoriel et repères', 'À quoi sert le produit scalaire en mécanique ?', 'mcq', '["Au calcul des moments","Au calcul du travail d’une force","Au calcul de la masse","Au changement de repère"]'::jsonb, 1, 'Le produit scalaire donne un nombre : c’est lui qui calcule le travail d’une force.', 1),
    ('54b53d07-b7d7-563c-a33f-eeae54ad0ac3'::uuid, 'si', '1re', 'Calcul vectoriel et repères', 'Quelle est la norme du vecteur de coordonnées (3 ; 4) ?', 'mcq', '["7","12","5","25"]'::jsonb, 2, '√(3² + 4²) = √25 = 5.', 2),
    ('0532b108-51eb-50ce-b796-a09b2f9adb2d'::uuid, 'si', '1re', 'Calcul vectoriel et repères', 'Une force de 10 N fait un angle de 60° avec un axe. Quelle est sa composante le long de cet axe ?', 'mcq', '["5 N","8,7 N","10 N","0 N"]'::jsonb, 0, 'Composante le long de l’axe = F × cos α = 10 × cos 60° = 10 × 0,5 = 5 N.', 3),
    ('e5921084-9d5c-528a-b087-b021d921285a'::uuid, 'si', '1re', 'Calcul vectoriel et repères', 'Quel est le résultat d’un produit vectoriel ?', 'mcq', '["Un nombre","Un angle","Une norme seule","Un vecteur perpendiculaire aux deux vecteurs"]'::jsonb, 3, 'Le produit vectoriel donne un vecteur perpendiculaire aux deux, de norme ‖u‖ × ‖v‖ × sin α.', 4),
    ('d55d0e93-1c5f-5555-8fb0-c8d747f8d5f5'::uuid, 'si', '1re', 'Modélisation des actions', 'Quel est le moment d’une force de 50 N appliquée perpendiculairement à 0,3 m du point considéré ?', 'mcq', '["150 N·m","15 N·m","166 N·m","1,5 N·m"]'::jsonb, 1, 'M = F × d = 50 × 0,3 = 15 N·m.', 1),
    ('ad00fb39-7de2-5503-b6f7-e7a4001a2a5e'::uuid, 'si', '1re', 'Modélisation des actions', 'Que transmet une liaison ponctuelle parfaite ?', 'mcq', '["Toutes les forces et tous les moments","Un moment seul","Une seule force, perpendiculaire au contact","Aucune action"]'::jsonb, 2, 'La liaison ponctuelle laisse 5 degrés de liberté et ne transmet qu’une force normale au contact.', 2),
    ('c761a225-13ce-51c4-a7d7-c7867255e9ce'::uuid, 'si', '1re', 'Modélisation des actions', 'Combien de degrés de liberté autorise une liaison glissière ?', 'mcq', '["Un, en translation","Un, en rotation","Zéro","Cinq"]'::jsonb, 0, 'La glissière n’autorise qu’une translation le long de son axe.', 3),
    ('e42944dc-542c-50b4-9c3b-e0cdeb06b5ba'::uuid, 'si', '1re', 'Modélisation des actions', 'Par quoi peut-on remplacer une action répartie sur une surface ?', 'mcq', '["Par un moment seul","Par plusieurs forces perpendiculaires","Par le poids du solide","Par une force unique équivalente"]'::jsonb, 3, 'Une action répartie se remplace par une force unique appliquée au point où la répartition s’équilibre.', 4),
    ('9e8ed26f-61b7-5e7b-9eec-d923debca700'::uuid, 'si', '1re', 'Représentation complète des actions', 'Combien de composantes compte une action mécanique dans l’espace ?', 'mcq', '["Trois","Six","Deux","Neuf"]'::jsonb, 1, 'Trois composantes de force et trois de moment, contre trois seulement dans un problème plan.', 1),
    ('ab7daf20-9252-5e78-b331-c2248a88f8ea'::uuid, 'si', '1re', 'Représentation complète des actions', 'Le calcul donne une valeur négative pour une inconnue tracée avec un sens supposé. Que conclure ?', 'mcq', '["Le calcul est faux","Il faut changer de repère","Le sens réel est l’inverse du sens supposé","L’action n’existe pas"]'::jsonb, 2, 'Le signe négatif indique simplement que le sens réel est opposé : la solution reste juste.', 2),
    ('9f814c0c-d3ce-5576-a8a6-25005508ecb2'::uuid, 'si', '1re', 'Représentation complète des actions', 'Que doit toujours porter une représentation graphique des actions ?', 'mcq', '["Une échelle indiquée","Le nom du fabricant","Les actions intérieures","La masse de chaque pièce"]'::jsonb, 0, 'La longueur de chaque flèche est proportionnelle à l’intensité : sans échelle, le tracé ne se lit pas.', 3),
    ('82f02f54-19d7-51a4-baa8-8fca158aae29'::uuid, 'si', '1re', 'Représentation complète des actions', 'Quand on transporte un torseur d’un point à un autre, qu’est-ce qui change ?', 'mcq', '["La résultante","Rien du tout","La direction de la résultante","Le moment"]'::jsonb, 3, 'La résultante ne change pas, mais le moment si, puisque le bras de levier change.', 4),
    ('058d3cd0-0f33-5d6d-96e0-a713a7387ff0'::uuid, 'si', '1re', 'Principe fondamental de la statique', 'Que désigne l’adhérence ?', 'mcq', '["Ce qui s’oppose au glissement en cours","Ce qui empêche le glissement","La composante normale du contact","Le poids du solide"]'::jsonb, 1, 'L’adhérence empêche le glissement ; le frottement s’oppose à un glissement déjà commencé.', 1),
    ('f3e80dec-4b1f-5230-95b3-6d312d22e316'::uuid, 'si', '1re', 'Principe fondamental de la statique', 'Sur un plan incliné, une pièce reste immobile tant que…', 'mcq', '["L’angle du plan reste inférieur à l’angle d’adhérence","Sa masse est faible","Le plan est horizontal","Son poids passe par le point de contact"]'::jsonb, 0, 'Au-delà de l’angle d’adhérence, la limite T ≤ f × N est dépassée et le glissement commence.', 2),
    ('71410ccb-bc82-5485-b114-9059f07e8216'::uuid, 'si', '1re', 'Principe fondamental de la statique', 'Quelle est la première étape de la méthode de résolution en statique ?', 'mcq', '["Écrire les équations","Choisir le point de calcul des moments","Isoler le solide","Vérifier l’homogénéité"]'::jsonb, 2, 'On isole, on fait le bilan des actions extérieures, puis on choisit repère et point avant d’écrire.', 3),
    ('c178d4fb-ec26-5598-a82e-5e3668e82055'::uuid, 'si', '1re', 'Principe fondamental de la statique', 'Un contact a une composante normale N = 200 N et un coefficient f = 0,3. Jusqu’à quelle valeur T peut-il monter sans glissement ?', 'mcq', '["200 N","600 N","0,3 N","60 N"]'::jsonb, 3, 'T ≤ f × N = 0,3 × 200 = 60 N.', 4),
    ('11b05906-a4ae-5325-810b-5db7d024d043'::uuid, 'si', '1re', 'Énergie et puissance', 'Combien de joules vaut un kilowattheure ?', 'mcq', '["1 000 J","3,6 × 10⁶ J","3 600 J","3,6 × 10³ J"]'::jsonb, 1, '1 kWh = 1 000 W × 3 600 s = 3,6 × 10⁶ J.', 1),
    ('9e4870e2-40ae-5248-9210-0dd7480c9791'::uuid, 'si', '1re', 'Énergie et puissance', 'Quelle est la puissance dissipée par une résistance de 10 Ω traversée par 2 A ?', 'mcq', '["20 W","5 W","40 W","200 W"]'::jsonb, 2, 'P = R × I² = 10 × 2² = 40 W.', 2),
    ('4287f2fa-48cc-52d2-9639-844a36560861'::uuid, 'si', '1re', 'Énergie et puissance', 'Quel est le rendement de trois maillons à 80 % chacun ?', 'mcq', '["Environ 51 %","80 %","240 %","Environ 64 %"]'::jsonb, 0, '0,8 × 0,8 × 0,8 = 0,512 : environ 51 %.', 3),
    ('502775dc-91d4-5f6b-8aec-8f8c1536a7d9'::uuid, 'si', '1re', 'Énergie et puissance', 'Pourquoi réduire le nombre de conversions améliore-t-il le rendement global ?', 'mcq', '["Parce que chaque conversion ajoute de l’énergie","Parce que les pertes s’annulent","Parce que les rendements s’additionnent","Parce que chaque conversion multiplie par un facteur inférieur à 1"]'::jsonb, 3, 'Chaque maillon supplémentaire multiplie le total par un rendement inférieur à 1.', 4),
    ('448061c2-d095-5bbb-b2ae-b4076e47038a'::uuid, 'si', '1re', 'Cinématique du point', 'Quelle est la valeur de l’accélération d’un point en mouvement circulaire uniforme ?', 'mcq', '["a = v × R","a = v² / R","a = 0","a = R / v"]'::jsonb, 1, 'L’accélération est centripète et vaut v² / R, même si la vitesse est constante en valeur.', 1),
    ('489161b0-1b71-5bba-8f47-ad47f84a7b89'::uuid, 'si', '1re', 'Cinématique du point', 'Un point est à 0,5 m de l’axe d’un solide tournant à 10 rad/s. Quelle est sa vitesse linéaire ?', 'mcq', '["5 m/s","20 m/s","0,05 m/s","10,5 m/s"]'::jsonb, 0, 'v = ω × R = 10 × 0,5 = 5 m/s.', 2),
    ('231e462e-8cb8-58c3-86bf-2bb4998b97f9'::uuid, 'si', '1re', 'Cinématique du point', 'Dans un mouvement rectiligne uniforme, l’accélération est…', 'mcq', '["Constante non nulle","Centripète","Nulle","Proportionnelle au temps"]'::jsonb, 2, 'La vitesse est constante en valeur et en direction : l’accélération est nulle.', 3),
    ('2744b3d8-2b08-5a63-ba5d-ee75499287fe'::uuid, 'si', '1re', 'Cinématique du point', 'Une roue d’entrée de rayon 2 cm entraîne une roue de sortie de rayon 6 cm. Que devient la vitesse angulaire ?', 'mcq', '["Elle est multipliée par 3","Elle reste la même","Elle est multipliée par 12","Elle est divisée par 3"]'::jsonb, 3, 'ω(sortie) / ω(entrée) = R(entrée) / R(sortie) = 2 / 6 = 1/3 : la vitesse est divisée par 3.', 4),
    ('04575437-a510-5976-8928-1d55d205ca59'::uuid, 'si', '1re', 'Les signaux', 'Un signal a une période de 20 ms. Quelle est sa fréquence ?', 'mcq', '["20 Hz","50 Hz","500 Hz","0,05 Hz"]'::jsonb, 1, 'f = 1 / T = 1 / 0,020 s = 50 Hz.', 1),
    ('7dffbf42-fa1e-5beb-9c47-258afdc78a6a'::uuid, 'si', '1re', 'Les signaux', 'Que fait l’étape de quantification ?', 'mcq', '["Elle prélève la valeur à intervalles réguliers","Elle écrit chaque niveau en binaire","Elle arrondit chaque échantillon au niveau disponible le plus proche","Elle supprime le bruit"]'::jsonb, 2, 'La quantification arrondit l’amplitude ; sa finesse dépend de la résolution en bits.', 2),
    ('061f6e20-6510-59cb-9001-7e18d008bfa2'::uuid, 'si', '1re', 'Les signaux', 'Quelle est la nature du signal délivré par un microphone ?', 'mcq', '["Analogique","Logique","Numérique","Binaire"]'::jsonb, 0, 'La tension d’un microphone varie continûment : elle peut prendre une infinité de valeurs.', 3),
    ('fde1f522-6e0a-5c86-94c3-1945f627f182'::uuid, 'si', '1re', 'Les signaux', 'Pourquoi un signal numérique se régénère-t-il exactement ?', 'mcq', '["Parce qu’il n’est jamais bruité","Parce qu’il est compressé","Parce qu’il est échantillonné très vite","Parce que le bruit reste sous le seuil de décision entre 0 et 1"]'::jsonb, 3, 'Tant que le bruit ne dépasse pas le seuil de décision, chaque bit est relu sans erreur.', 4),
    ('8eccaa2c-891c-563a-986a-c03685066b5c'::uuid, 'si', '1re', 'Codage de l’information', 'Que vaut le nombre binaire 1101 en décimal ?', 'mcq', '["11","13","15","9"]'::jsonb, 1, '1101 = 8 + 4 + 0 + 1 = 13.', 1),
    ('f7cc6a21-da81-5149-bc57-f3a62f788c20'::uuid, 'si', '1re', 'Codage de l’information', 'Que vaut le nombre hexadécimal F en décimal ?', 'mcq', '["16","10","15","14"]'::jsonb, 2, 'Les chiffres hexadécimaux vont de 0 à 9 puis de A (10) à F (15).', 2),
    ('2ee49267-194f-5e97-9354-9980c2fe845f'::uuid, 'si', '1re', 'Codage de l’information', 'Sur combien de bits l’ASCII code-t-il les caractères ?', 'mcq', '["7 bits","16 bits","4 bits","32 bits"]'::jsonb, 0, 'L’ASCII sur 7 bits ne suffit pas aux langues accentuées, d’où Unicode et UTF-8.', 3),
    ('bcdc7253-a566-5195-9a89-b5c6929cc994'::uuid, 'si', '1re', 'Codage de l’information', 'Le mot 01000001 représente-t-il forcément la lettre A ?', 'mcq', '["Oui, toujours","Oui, sauf dans une image","Non, il vaut toujours 65","Non, c’est la convention du programme qui l’interprète"]'::jsonb, 3, 'Ce mot vaut 65 en entier, A en ASCII, ou une nuance de gris : rien dans le mot ne dit ce qu’il représente.', 4),
    ('eeaac5a2-e0a3-59ad-8a02-c1cc4b033d18'::uuid, 'si', '1re', 'Les opérateurs logiques fondamentaux', 'Comment note-t-on l’opérateur ET dans une équation logique ?', 'mcq', '["Par un signe plus","Par un point","Par une barre","Par une flèche"]'::jsonb, 1, 'Le ET se note comme une multiplication, le OU comme une addition.', 1),
    ('4913c3c0-4ce3-5983-b072-dbf1b3cef249'::uuid, 'si', '1re', 'Les opérateurs logiques fondamentaux', 'Combien de lignes compte la table de vérité d’une fonction à quatre entrées ?', 'mcq', '["Huit","Douze","Seize","Quatre"]'::jsonb, 2, 'Une fonction à n entrées a 2 puissance n lignes : 2⁴ = 16.', 2),
    ('da5bf7ee-ff59-5c0d-a1ee-d4e9dd664bfd'::uuid, 'si', '1re', 'Les opérateurs logiques fondamentaux', 'Une alarme se déclenche dès que l’un des capteurs détecte une intrusion. Quel opérateur la décrit ?', 'mcq', '["OU","ET","NON","NON-ET"]'::jsonb, 0, 'Le OU vaut 1 dès qu’au moins une entrée vaut 1.', 3),
    ('041bf38b-712a-52c3-bf5d-25a77746a26d'::uuid, 'si', '1re', 'Les opérateurs logiques fondamentaux', 'Que vaut la sortie d’un NON-ET dont les deux entrées valent 1 ?', 'mcq', '["1","Indéterminée","Cela dépend du circuit","0"]'::jsonb, 3, 'Le ET de 1 et 1 vaut 1 ; inversé par le NON-ET, il donne 0.', 4),
    ('b35c8549-cb3a-550b-b0d8-8ea07a7d0490'::uuid, 'si', '1re', 'Association de portes logiques', 'Quel est l’intérêt de la table de vérité parmi les trois représentations ?', 'mcq', '["Elle se câble directement","Elle est exhaustive","Elle se simplifie","Elle occupe moins de place"]'::jsonb, 1, 'La table de vérité liste toutes les combinaisons : elle ne ment pas.', 1),
    ('baebf565-a279-5ec6-9221-37b5d52e2026'::uuid, 'si', '1re', 'Association de portes logiques', 'Sur quelles lignes de la table de vérité s’appuie la méthode du produit de sommes ?', 'mcq', '["Celles où la sortie vaut 1","Toutes les lignes","Celles où la sortie vaut 0","Seulement la dernière"]'::jsonb, 2, 'Le produit de sommes est la construction duale de la somme de produits : il part des 0.', 2),
    ('c9b104ea-3027-5e68-9ee1-204a631df8af'::uuid, 'si', '1re', 'Association de portes logiques', 'Quelle est la dernière étape de l’analyse d’un montage existant ?', 'mcq', '["Dresser la table de vérité pour vérifier","Nommer les sorties intermédiaires","Compter les portes","Remplacer les portes par des NON-ET"]'::jsonb, 0, 'On nomme, on écrit, on remonte jusqu’à la sortie, puis la table de vérité vérifie le tout.', 3),
    ('012509c8-5f45-54c9-a6f9-56b3d2864948'::uuid, 'si', '1re', 'Association de portes logiques', 'Quelle représentation d’une fonction logique se câble directement ?', 'mcq', '["L’équation logique","La table de vérité","Le tableau de Karnaugh","Le logigramme"]'::jsonb, 3, 'Le logigramme est le schéma du montage de portes : c’est lui qu’on câble.', 4),
    ('adb74017-c01f-554d-9aaf-7ef048530505'::uuid, 'si', '1re', 'Algèbre de Boole', 'Que vaut a . complément de a ?', 'mcq', '["1","0","a","Le complément de a"]'::jsonb, 1, 'Une variable et son complément ne valent jamais 1 en même temps : leur ET vaut 0.', 1),
    ('eafa204e-0ebd-5ec3-ad6d-f8a25e5edb82'::uuid, 'si', '1re', 'Algèbre de Boole', 'Que vaut a . 0 en algèbre de Boole ?', 'mcq', '["a","1","0","Le complément de a"]'::jsonb, 2, '0 est l’élément absorbant du ET.', 2),
    ('45478bde-2b56-5d76-84ce-234eb5d17b1e'::uuid, 'si', '1re', 'Algèbre de Boole', 'Que donne la loi de De Morgan appliquée au complément de (a + b) ?', 'mcq', '["Complément de a . complément de b","Complément de a + complément de b","a . b","a + b"]'::jsonb, 0, 'On complémente chaque terme et on échange les opérateurs : le OU devient un ET.', 3),
    ('3bd9e631-d64a-5149-901c-4bf9af4e7d61'::uuid, 'si', '1re', 'Algèbre de Boole', 'Que vaut a . (a + b) ?', 'mcq', '["a + b","b","a . b","a"]'::jsonb, 3, 'C’est le théorème d’absorption : a . (a + b) se réduit à a.', 4),
    ('33990149-01b7-5dd5-abdc-2a0f104b3bd4'::uuid, 'si', '1re', 'Simplification des expressions logiques', 'Combien de cases compte un tableau de Karnaugh à trois variables ?', 'mcq', '["Six","Huit","Neuf","Seize"]'::jsonb, 1, 'Le tableau a 2 puissance n cases, une par ligne de la table de vérité : 2³ = 8.', 1),
    ('ec0dec22-cb9d-531d-9437-7cd04284c23f'::uuid, 'si', '1re', 'Simplification des expressions logiques', 'Que se passe-t-il si l’on écrit les en-têtes d’un tableau de Karnaugh en binaire naturel ?', 'mcq', '["Rien, le résultat est identique","Le tableau devient plus petit","Les voisinages sont faux, donc la simplification aussi","Les groupes doublent de taille"]'::jsonb, 2, 'Il faut le code de Gray (00, 01, 11, 10) pour que deux cases voisines ne diffèrent que d’une variable.', 2),
    ('da6683fb-a447-54e7-9e41-132e3480c56a'::uuid, 'si', '1re', 'Simplification des expressions logiques', 'Qu’apporte un groupe deux fois plus grand dans un tableau de Karnaugh ?', 'mcq', '["Il élimine une variable de plus","Il ajoute un terme","Il rend le résultat faux","Il ne change rien"]'::jsonb, 0, 'Doubler la taille d’un groupe fait disparaître une variable supplémentaire du terme.', 3),
    ('8df3df46-c529-5180-809b-4d2ab57383a3'::uuid, 'si', '1re', 'Simplification des expressions logiques', 'Quelle est la principale difficulté de la simplification par l’algèbre ?', 'mcq', '["Elle change la fonction réalisée","Elle interdit les lois de De Morgan","Elle exige un tableau de Karnaugh","Rien ne garantit qu’on est arrivé au plus simple"]'::jsonb, 3, 'On peut toujours avoir manqué une factorisation : d’où l’intérêt de la méthode graphique de Karnaugh.', 4),
    ('a104f1fa-61f6-5ea0-b2f3-66185498a57f'::uuid, 'si', '1re', 'Sécurité du transfert d’information', 'Quelle exigence garantit que l’émetteur ne peut nier avoir envoyé le message ?', 'mcq', '["La confidentialité","La non-répudiation","La disponibilité","L’intégrité"]'::jsonb, 1, 'La non-répudiation, apportée par la signature numérique, empêche l’émetteur de renier son message.', 1),
    ('3d9f9d41-915c-5a2e-b199-1e2abe43bfbb'::uuid, 'si', '1re', 'Sécurité du transfert d’information', 'Comment HTTPS combine-t-il les deux chiffrements ?', 'mcq', '["Il n’utilise que le symétrique","Il chiffre deux fois chaque message en asymétrique","L’asymétrique transmet une clé de session symétrique, qui chiffre ensuite le trafic","Le symétrique transmet la clé privée"]'::jsonb, 2, 'L’asymétrique résout l’échange de clés, le symétrique chiffre vite le trafic.', 2),
    ('cda253a6-dc99-54fa-baa1-516f75117bad'::uuid, 'si', '1re', 'Sécurité du transfert d’information', 'Quelle est la difficulté propre au chiffrement symétrique ?', 'mcq', '["Il faut transmettre la clé au destinataire","Il est très lent","Il ne protège pas le contenu","Il nécessite deux clés différentes"]'::jsonb, 0, 'Émetteur et destinataire partagent la même clé : encore faut-il la leur faire parvenir.', 3),
    ('68b601e5-ec20-5b4d-8a71-f2b9cfc8c462'::uuid, 'si', '1re', 'Sécurité du transfert d’information', 'Avec quelle clé vérifie-t-on la signature numérique d’un émetteur ?', 'mcq', '["La clé privée de l’émetteur","La clé privée du destinataire","Une clé symétrique de session","La clé publique de l’émetteur"]'::jsonb, 3, 'L’émetteur signe avec sa clé privée ; chacun vérifie avec sa clé publique.', 4),
    ('64f688b5-ae3d-54f5-8b56-3ba60599351c'::uuid, 'si', '1re', 'Réseau de données', 'Quel type de réseau couvre quelques mètres autour d’une personne, comme le Bluetooth ?', 'mcq', '["LAN","PAN","WAN","MAN"]'::jsonb, 1, 'Le PAN est le réseau personnel ; le LAN couvre un bâtiment, le WAN une large étendue.', 1),
    ('38cd62fa-608b-5b81-8e50-735ef04b5d5a'::uuid, 'si', '1re', 'Réseau de données', 'D’après quelle adresse un commutateur distribue-t-il les trames ?', 'mcq', '["L’adresse IP","Le numéro de port","L’adresse MAC","Le masque de sous-réseau"]'::jsonb, 2, 'Le commutateur travaille dans le réseau local avec les adresses MAC ; le routeur, avec les adresses IP.', 2),
    ('28cdcff5-c2e7-5e65-b544-d9c432c25d1b'::uuid, 'si', '1re', 'Réseau de données', 'Quelle topologie offre plusieurs chemins et une grande robustesse, au prix d’un câblage coûteux ?', 'mcq', '["La topologie maillée","La topologie en bus","La topologie en étoile","La topologie en anneau"]'::jsonb, 0, 'Le réseau maillé survit à la coupure d’un lien car les données peuvent passer par un autre chemin.', 3),
    ('2c1cb9e4-eb81-571e-b775-c633f800edab'::uuid, 'si', '1re', 'Réseau de données', 'Quel protocole d’application, léger et fondé sur la publication-abonnement, est la référence des objets connectés ?', 'mcq', '["FTP","HTTP","TCP","MQTT"]'::jsonb, 3, 'MQTT est conçu pour des équipements modestes qui publient et s’abonnent à des sujets.', 4),
    ('63461c4b-cb09-5aad-866f-7fa607256667'::uuid, 'si', '1re', 'Le circuit électrique', 'Quelle conservation traduit la loi des nœuds ?', 'mcq', '["Celle de l’énergie","Celle de la charge","Celle de la puissance","Celle de la tension"]'::jsonb, 1, 'Rien ne s’accumule dans un fil : ce qui entre dans un nœud en ressort.', 1),
    ('fbeea08f-278e-5136-b0c0-41cce42ff9bd'::uuid, 'si', '1re', 'Le circuit électrique', 'Quelle est la résistance équivalente de deux résistances de 100 Ω en dérivation ?', 'mcq', '["200 Ω","100 Ω","50 Ω","10 000 Ω"]'::jsonb, 2, 'En dérivation, les inverses s’additionnent : 1/100 + 1/100 = 1/50, soit 50 Ω.', 2),
    ('9ae2ec97-5c88-53f8-85e0-5cf5ec4c874f'::uuid, 'si', '1re', 'Le circuit électrique', 'Que se passe-t-il si l’on branche un ampèremètre en dérivation ?', 'mcq', '["Il court-circuite le dipôle, car sa résistance est presque nulle","Il mesure la tension","Il ne se passe rien","Il mesure une intensité doublée"]'::jsonb, 0, 'Un ampèremètre se branche en série ; en dérivation, il crée un court-circuit qui peut détruire l’appareil ou le circuit.', 3),
    ('428a9f66-d764-5962-b7d6-9d334f416824'::uuid, 'si', '1re', 'Le circuit électrique', 'Deux résistances de 1 kΩ et 3 kΩ en série sont alimentées sous 8 V. Quelle tension aux bornes de celle de 3 kΩ ?', 'mcq', '["2 V","8 V","4 V","6 V"]'::jsonb, 3, 'Le pont diviseur partage la tension selon les valeurs : 8 × 3 / (1 + 3) = 6 V.', 4),
    ('f462d909-2b9a-58a5-aa37-f3b5c3ffe5bc'::uuid, 'si', '1re', 'Les composants électriques : générateur, résistance et condensateur', 'Un générateur de fém E = 12 V et de résistance interne r = 0,5 Ω débite 4 A. Quelle tension délivre-t-il ?', 'mcq', '["12 V","10 V","14 V","6 V"]'::jsonb, 1, 'U = E − r × I = 12 − 0,5 × 4 = 10 V.', 1),
    ('86215cf1-d009-559b-8264-6b3d2732360e'::uuid, 'si', '1re', 'Les composants électriques : générateur, résistance et condensateur', 'Au bout de combien de temps considère-t-on la charge d’un condensateur terminée à 99 % ?', 'mcq', '["τ","2 τ","5 τ","10 τ"]'::jsonb, 2, 'La charge suit une exponentielle : le régime établi est atteint à 99 % après 5 τ.', 2),
    ('496beea2-4815-5647-a41c-6a3620e2f508'::uuid, 'si', '1re', 'Les composants électriques : générateur, résistance et condensateur', 'Quelle relation lie la charge, la capacité et la tension d’un condensateur ?', 'mcq', '["Q = C × U","Q = C / U","Q = U / C","Q = ½ × C × U²"]'::jsonb, 0, 'Q = C × U, avec Q en coulombs, C en farads et U en volts.', 3),
    ('c16aac23-6fbb-5f40-a22a-738f2b3c2188'::uuid, 'si', '1re', 'Les composants électriques : générateur, résistance et condensateur', 'De quoi ne dépend pas la résistance d’un fil ?', 'mcq', '["De sa longueur","De sa section","De son matériau","De sa couleur"]'::jsonb, 3, 'La résistance d’un fil dépend de sa longueur, de sa section et du matériau conducteur.', 4),
    ('608ad0fc-da16-5241-90f7-565ab6f37d72'::uuid, 'si', '1re', 'Les composants électriques : inductance, diode et transistor', 'Quelle est l’unité de l’inductance ?', 'mcq', '["Le farad","Le henry","L’ohm","Le weber"]'::jsonb, 1, 'L’inductance d’une bobine s’exprime en henrys (H).', 1),
    ('0a3b13e7-c796-5968-b316-e05b5ededcb7'::uuid, 'si', '1re', 'Les composants électriques : inductance, diode et transistor', 'Comment se comporte une bobine en régime continu établi ?', 'mcq', '["Comme un interrupteur ouvert","Comme un générateur","Comme un simple fil","Comme une diode"]'::jsonb, 2, 'Son comportement est le symétrique du condensateur, qui se comporte, lui, en interrupteur ouvert.', 2),
    ('2bc2bfeb-0352-5a47-8782-266d7461a6fc'::uuid, 'si', '1re', 'Les composants électriques : inductance, diode et transistor', 'Quel régime du transistor est employé dans l’électronique analogique ?', 'mcq', '["L’amplification","La commutation","Le blocage permanent","La saturation permanente"]'::jsonb, 0, 'En régime linéaire, la sortie reproduit l’entrée en plus grand : c’est l’amplification.', 3),
    ('5e2d2f94-dfe8-5327-9d7e-4e8cda0aa608'::uuid, 'si', '1re', 'Les composants électriques : inductance, diode et transistor', 'Comment la diode de roue libre est-elle montée aux bornes de la bobine ?', 'mcq', '["En série avec la bobine, en direct","À la place du transistor","En parallèle avec l’alimentation","En inverse, à ses bornes"]'::jsonb, 3, 'Montée en inverse, elle ne conduit qu’à la coupure et offre au courant de la bobine un chemin pour s’éteindre.', 4),
    ('cce0ac10-0b04-5543-84a6-a948f9436565'::uuid, 'si', '1re', 'Les outils d’étude', 'Une amplitude occupe 3 divisions avec une sensibilité de 5 V/div. Quelle est sa valeur ?', 'mcq', '["8 V","15 V","1,7 V","35 V"]'::jsonb, 1, 'On compte les divisions et on multiplie par le calibre : 3 × 5 = 15 V.', 1),
    ('d025dae4-a702-5992-8953-e4adaf17e4c8'::uuid, 'si', '1re', 'Les outils d’étude', 'Quel appareil révèle un rebond de contact ou un temps de montée ?', 'mcq', '["Le multimètre","Le générateur de fonctions","L’oscilloscope","L’ampèremètre"]'::jsonb, 2, 'Seul l’oscilloscope montre l’allure du signal dans le temps.', 2),
    ('d2e10d73-299d-5a57-a8cd-114e1bc82e04'::uuid, 'si', '1re', 'Les outils d’étude', 'Que révèle un écart entre le calcul et la simulation ?', 'mcq', '["Une erreur de modèle ou d’hypothèse","Un composant hors tolérance","Un cahier des charges non respecté","Une panne de l’oscilloscope"]'::jsonb, 0, 'Calcul et simulation reposent tous deux sur des modèles : leur écart signale une erreur de modèle ou d’hypothèse.', 3),
    ('87c5df0d-6e5c-5f64-a49e-8e4d7e3dfbae'::uuid, 'si', '1re', 'Les outils d’étude', 'Laquelle de ces grandeurs un simulateur ignore-t-il, sauf si on la modélise ?', 'mcq', '["La loi d’Ohm","La loi des mailles","La valeur nominale des résistances","Les capacités parasites"]'::jsonb, 3, 'Le simulateur ne connaît que les phénomènes modélisés : capacités parasites, contacts, échauffement en sont exclus par défaut.', 4),
    ('b86538a5-21a1-5d30-9aa7-2af80dd75fe1'::uuid, 'enseignement-scientifique', '1re', 'Un niveau d’organisation : les éléments chimiques', 'Que sont deux isotopes d’un même élément ?', 'mcq', '["Des atomes de même nombre de neutrons mais de nombre de protons différent","Des atomes de même nombre de protons mais de nombre de neutrons différent","Des atomes de même masse mais de charge différente","Des atomes de même nombre d’électrons mais d’éléments différents"]'::jsonb, 1, 'Même Z, donc même élément ; seul le nombre de neutrons change, comme pour le carbone 12 et le carbone 14.', 1),
    ('e0daa6bd-7506-5f12-970a-796e6652c5ce'::uuid, 'enseignement-scientifique', '1re', 'Un niveau d’organisation : les éléments chimiques', 'Où se forment les éléments plus lourds que le fer, comme l’or ou l’uranium ?', 'mcq', '["Dans les trois premières minutes de l’Univers","Au cœur du Soleil actuel","Lors des explosions d’étoiles et des fusions d’astres compacts","Dans la croûte terrestre"]'::jsonb, 2, 'Au-delà du fer, la fusion consomme de l’énergie : il faut des événements violents, supernovae ou fusions d’astres compacts.', 2),
    ('82d99079-caa8-5a16-92f9-362e2712cb1b'::uuid, 'enseignement-scientifique', '1re', 'Un niveau d’organisation : les éléments chimiques', 'Il y a combien de temps a eu lieu le Big Bang ?', 'mcq', '["4,54 milliards d’années","4,6 milliards d’années","1,38 milliard d’années","13,8 milliards d’années"]'::jsonb, 3, '13,8 milliards d’années ; 4,6 milliards, c’est l’âge du Soleil, et 4,54 milliards celui de la Terre.', 3),
    ('66a6825c-ae42-504e-bc3d-9c2db3918661'::uuid, 'enseignement-scientifique', '1re', 'Un niveau d’organisation : les éléments chimiques', 'Que devient le carbone quand on brûle du charbon ?', 'mcq', '["Il se retrouve dans le dioxyde de carbone : l’élément se conserve","Il est détruit par la flamme","Il se transforme en oxygène","Il devient radioactif"]'::jsonb, 0, 'Une transformation chimique réarrange les atomes sans changer les éléments : le carbone passe dans le CO2.', 4),
    ('d9da34a6-62bd-5ee9-8cc3-c3657fa6167e'::uuid, 'enseignement-scientifique', '1re', 'Les édifices ordonnés : les cristaux', 'Le dioxyde de silicium peut donner du quartz ou du verre. Qu’est-ce qui en décide ?', 'mcq', '["La vitesse de refroidissement","La couleur du minéral","La pression atmosphérique","La masse de l’échantillon"]'::jsonb, 0, 'Un refroidissement lent laisse le temps de s’ordonner (quartz) ; un refroidissement brutal fige le désordre (verre).', 1),
    ('00b83a4b-225a-5e0c-8ce5-cc2515a809cf'::uuid, 'enseignement-scientifique', '1re', 'Les édifices ordonnés : les cristaux', 'Quelle est la compacité d’une maille cubique à faces centrées ?', 'mcq', '["Environ 0,52","Environ 1","Environ 0,74","Environ 0,34"]'::jsonb, 2, 'Environ 0,74 : c’est l’empilement le plus dense, contre 0,52 pour la maille cubique simple.', 2),
    ('c9ffd102-ea64-5e48-a5a9-8b5f2c422635'::uuid, 'enseignement-scientifique', '1re', 'Les édifices ordonnés : les cristaux', 'Comment calcule-t-on la masse volumique d’un cristal à partir de sa maille ?', 'mcq', '["En multipliant le nombre d’atomes par la compacité","En divisant le volume de la maille par sa masse","En additionnant les masses de tous les atomes des sommets","En divisant la masse des atomes de la maille par le volume de la maille"]'::jsonb, 3, 'ρ = masse des atomes de la maille / volume de la maille : la maille reproduit le cristal entier à petite échelle.', 3),
    ('0fc60cbe-1016-57ca-bd8e-69944cf899ac'::uuid, 'enseignement-scientifique', '1re', 'Les édifices ordonnés : les cristaux', 'De quel minéral sont faits l’os et l’émail dentaire ?', 'mcq', '["De carbonate de calcium","De phosphate de calcium","De silice","De chlorure de sodium"]'::jsonb, 1, 'Le phosphate de calcium forme l’os et l’émail ; le carbonate de calcium, les coquilles et les tests d’oursins.', 4),
    ('9c01c316-72a1-5457-979f-8f30a30f0e6a'::uuid, 'enseignement-scientifique', '1re', 'Une structure complexe : la cellule vivante', 'Quelle est la taille approximative d’une bactérie ?', 'mcq', '["1 mm","1 µm","1 nm","100 µm"]'::jsonb, 1, 'Environ 1 µm, soit dix à cent fois moins qu’une cellule animale (10 à 100 µm).', 1),
    ('aacc39e3-3e55-54f4-99ad-9c16d49b4a45'::uuid, 'enseignement-scientifique', '1re', 'Une structure complexe : la cellule vivante', 'Quel instrument a permis d’observer la membrane plasmique ?', 'mcq', '["La loupe binoculaire","Le microscope optique","Le microscope électronique","Le télescope"]'::jsonb, 2, 'La membrane mesure environ 7,5 nm, bien en dessous des 0,2 µm que distingue un microscope optique.', 2),
    ('48dc0a77-cbf3-502d-a358-bff1ffb37e81'::uuid, 'enseignement-scientifique', '1re', 'Une structure complexe : la cellule vivante', 'Qu’établissent Schleiden et Schwann vers 1838 ?', 'mcq', '["Que les cellules naissent de la matière inerte","Que la membrane est une bicouche de lipides","Que toute cellule provient d’une autre cellule","Que tous les êtres vivants sont constitués de cellules"]'::jsonb, 3, 'Virchow complétera en 1855 : toute cellule provient d’une cellule préexistante.', 3),
    ('4c1d59a0-5134-5793-9e55-e03b9671fbb6'::uuid, 'enseignement-scientifique', '1re', 'Une structure complexe : la cellule vivante', 'Qu’est-ce qu’une cellule hétérotrophe ?', 'mcq', '["Une cellule qui prélève sa matière organique dans le milieu","Une cellule qui fabrique sa matière organique à partir de minéral","Une cellule sans membrane","Une cellule qui ne réalise aucune réaction chimique"]'::jsonb, 0, 'Elle prélève sa matière organique, puis la dégrade par respiration (avec O2) ou fermentation (sans).', 4),
    ('356baa9e-a73e-5e1b-af24-8db04a08337b'::uuid, 'enseignement-scientifique', '1re', 'Le rayonnement solaire', 'Quelle masse le Soleil perd-il environ chaque seconde en rayonnant ?', 'mcq', '["4 tonnes","4 millions de tonnes","4 kilogrammes","La moitié de sa masse"]'::jsonb, 1, 'Environ 4 millions de tonnes par seconde, transformées en énergie selon E = m × c² : une paille pour un astre de 2 × 10³⁰ kg.', 1),
    ('e7809d87-c8ae-5c5a-b302-b32f4103d78c'::uuid, 'enseignement-scientifique', '1re', 'Le rayonnement solaire', 'Une étoile a une surface à 3 000 K. Où se situe son maximum d’émission ?', 'mcq', '["Dans le bleu","Dans l’ultraviolet","Dans le rouge et l’infrarouge","Dans le vert"]'::jsonb, 2, 'Loi de Wien : plus l’étoile est froide, plus son maximum est à grande longueur d’onde.', 2),
    ('451e9bdd-d5ac-56eb-9612-b9b625b88a12'::uuid, 'enseignement-scientifique', '1re', 'Le rayonnement solaire', 'Vers quelle longueur d’onde se situe le maximum d’émission du Soleil ?', 'mcq', '["Environ 500 nm","Environ 10 µm","Environ 100 nm","Environ 1 mm"]'::jsonb, 0, 'À 5 800 K, λmax ≈ 2,9 × 10⁻³ / 5 800 ≈ 500 nm : le vert-jaune, en plein visible.', 3),
    ('046d9f0a-afc6-5f86-8f55-a685737b2995'::uuid, 'enseignement-scientifique', '1re', 'Le rayonnement solaire', 'Pourquoi l’énergie du Soleil ne peut-elle pas venir d’une combustion ?', 'mcq', '["Parce qu’il n’y a pas de carbone dans le Soleil","Parce qu’une combustion ne produit pas de lumière","Parce que le Soleil est trop froid","Parce qu’aucune combustion ne tiendrait plus de quelques milliers d’années"]'::jsonb, 3, 'Le Soleil rayonne depuis 4,6 milliards d’années : seule la fusion nucléaire peut fournir une telle énergie.', 4),
    ('39bae509-9def-56e4-9ab6-e53359c35617'::uuid, 'enseignement-scientifique', '1re', 'Le bilan radiatif de la Terre', 'Quel est l’albédo approximatif de la neige fraîche ?', 'mcq', '["0,1","0,3","0,9","0,5"]'::jsonb, 2, 'La neige fraîche renvoie presque tout ; l’océan, sombre, n’en renvoie qu’environ 10 %.', 1),
    ('23ec7598-4135-5c8d-b790-dc46a0828a3d'::uuid, 'enseignement-scientifique', '1re', 'Le bilan radiatif de la Terre', 'Vers quelle longueur d’onde se situe le maximum du rayonnement émis par la Terre ?', 'mcq', '["Environ 500 nm","Environ 10 µm","Environ 1 mm","Environ 10 nm"]'::jsonb, 1, 'À 288 K, la loi de Wien place le maximum vers 10 µm, dans l’infrarouge.', 2),
    ('0d706853-d01e-544e-99ab-16ff7e3a7b62'::uuid, 'enseignement-scientifique', '1re', 'Le bilan radiatif de la Terre', 'De combien de degrés l’effet de serre naturel réchauffe-t-il la surface terrestre ?', 'mcq', '["18 °C","15 °C","1 °C","33 °C"]'::jsonb, 3, 'On passe de −18 °C sans effet de serre à +15 °C avec : 33 °C d’écart, qui permettent l’eau liquide.', 3),
    ('fa7bd068-d3e8-5295-9d0c-d55d535c4fc1'::uuid, 'enseignement-scientifique', '1re', 'Le bilan radiatif de la Terre', 'De quel ordre est l’excédent d’énergie qui provoque le réchauffement actuel ?', 'mcq', '["Environ 1 W/m²","Environ 100 W/m²","Environ 240 W/m²","Environ 340 W/m²"]'::jsonb, 0, 'Un écart minuscule, mais accumulé sur toute la surface et pendant des décennies : c’est le réchauffement climatique.', 4),
    ('5a0f23c0-7048-5eb3-956b-32d8e6d76126'::uuid, 'enseignement-scientifique', '1re', 'La photosynthèse : une conversion de l’énergie solaire', 'Quelle technique permet de séparer les pigments d’une feuille ?', 'mcq', '["La distillation","La filtration","La chromatographie","Le titrage"]'::jsonb, 2, 'La chromatographie sépare les chlorophylles a et b et les caroténoïdes.', 1),
    ('14366266-9a97-5354-9b4e-76b0092e36af'::uuid, 'enseignement-scientifique', '1re', 'La photosynthèse : une conversion de l’énergie solaire', 'Que montre la superposition du spectre d’action et du spectre d’absorption des pigments ?', 'mcq', '["Que la photosynthèse est maximale dans le vert","Que l’activité photosynthétique suit exactement les longueurs d’onde absorbées","Que la lumière n’a aucun rôle","Que seule la lumière ultraviolette est utilisée"]'::jsonb, 1, 'La plante fait la photosynthèse avec la lumière que ses pigments absorbent : surtout le bleu et le rouge.', 2),
    ('a249d8ad-7468-5fc8-b40e-a0b575ab308c'::uuid, 'enseignement-scientifique', '1re', 'La photosynthèse : une conversion de l’énergie solaire', 'D’où vient le pétrole ?', 'mcq', '["Des forêts du Carbonifère","Des roches volcaniques","Des cristaux de calcite","Du plancton marin enfoui"]'::jsonb, 3, 'Le pétrole vient du plancton marin ; le charbon, surtout des forêts du Carbonifère.', 3),
    ('f4bd42ad-08b1-5c8d-b54e-db73c0e77d29'::uuid, 'enseignement-scientifique', '1re', 'La photosynthèse : une conversion de l’énergie solaire', 'Quel est l’ordre de grandeur de la production primaire de la planète ?', 'mcq', '["100 milliards de tonnes de carbone par an","100 tonnes de carbone par an","100 millions de tonnes de carbone par jour","100 000 milliards de tonnes de carbone par an"]'::jsonb, 0, 'Environ 100 milliards de tonnes de carbone par an, partagées à peu près à égalité entre continents et océans.', 4),
    ('5fa1ab4d-72cb-559d-a088-ec465e758222'::uuid, 'enseignement-scientifique', '1re', 'Le bilan thermique du corps humain', 'À quoi servent les frissons quand on a froid ?', 'mcq', '["À faire transpirer","À dilater les vaisseaux de la peau","À produire de la chaleur par des contractions musculaires","À baisser la valeur de consigne"]'::jsonb, 2, 'Les frissons sont des contractions musculaires involontaires : l’énergie dépensée finit en chaleur.', 1),
    ('4be69e28-b3df-50f0-9d87-589bfc5d90a9'::uuid, 'enseignement-scientifique', '1re', 'Le bilan thermique du corps humain', 'À combien de kilojoules correspondent environ 2 000 kcal ?', 'mcq', '["478 kJ","8 400 kJ","2 000 kJ","20 000 kJ"]'::jsonb, 1, '1 kcal = 4,18 kJ, donc 2 000 kcal ≈ 8 400 kJ : l’ordre de grandeur d’une journée d’alimentation.', 2),
    ('e0b841eb-065f-5026-a2cc-07affc3e5908'::uuid, 'enseignement-scientifique', '1re', 'Le bilan thermique du corps humain', 'Qu’est-ce que la fièvre ?', 'mcq', '["Un relèvement délibéré de la valeur de consigne par l’organisme","Une panne de l’hypothalamus","Une évaporation insuffisante de la sueur","Un excès de vasoconstriction"]'::jsonb, 0, 'La fièvre n’est pas une panne : l’organisme règle volontairement sa température plus haut.', 3),
    ('d4d3c77e-afa6-5e98-b94a-7fe86fef843d'::uuid, 'enseignement-scientifique', '1re', 'Le bilan thermique du corps humain', 'Pourquoi se refroidit-on plus vite dans l’eau froide que dans l’air à la même température ?', 'mcq', '["Parce que l’eau empêche le rayonnement","Parce que l’eau froide bloque la sudation","Parce que l’eau augmente le métabolisme","Parce que l’eau conduit bien mieux la chaleur que l’air"]'::jsonb, 3, 'La conduction est bien plus efficace dans l’eau : d’où le danger d’hypothermie en cas de chute dans l’eau froide.', 4),
    ('2bdcfe82-eb41-52a0-b1b0-4e8c3c6184ae'::uuid, 'enseignement-scientifique', '1re', 'La forme de la Terre', 'L’angle de 7,2° mesuré par Ératosthène représente quelle fraction du tour complet ?', 'mcq', '["1/7","1/360","1/50","1/10"]'::jsonb, 2, '7,2 × 50 = 360 : la distance Syène-Alexandrie vaut donc un cinquantième du tour de la Terre.', 1),
    ('56a2af78-85f0-50dc-ac20-460c202d1118'::uuid, 'enseignement-scientifique', '1re', 'La forme de la Terre', 'Que vaut une minute d’arc le long d’un méridien ?', 'mcq', '["111 km","1 852 m, soit un mille marin","60 m","1,11 km"]'::jsonb, 1, 'Un degré vaut environ 111 km ; divisé en 60 minutes, cela donne environ 1 852 m, le mille marin.', 2),
    ('fc2598ab-fd5c-5ff3-817b-f4d2ae23b75d'::uuid, 'enseignement-scientifique', '1re', 'La forme de la Terre', 'Quel est l’écart entre le rayon équatorial et le rayon polaire de la Terre ?', 'mcq', '["Environ 21 km","Environ 210 km","Environ 2 km","Environ 6 400 km"]'::jsonb, 0, '6 378 km contre 6 357 km : moins de 0,4 % d’écart, dû à l’aplatissement par la rotation.', 3),
    ('29041844-3cf8-5805-9f08-4e3271c3c9a2'::uuid, 'enseignement-scientifique', '1re', 'La forme de la Terre', 'Qu’est-ce qu’une loxodromie ?', 'mcq', '["Le plus court chemin entre deux points","Un arc de grand cercle","La ligne de l’équateur","Un trajet à cap constant, plus simple à suivre mais plus long"]'::jsonb, 3, 'Le plus court chemin est l’orthodromie, un arc de grand cercle ; la loxodromie garde le même cap.', 4),
    ('8e4e87e5-d103-5d1a-8b36-cbd250d06674'::uuid, 'enseignement-scientifique', '1re', 'L’histoire de l’âge de la Terre', 'Sur quoi repose l’estimation d’Ussher en 1650 ?', 'mcq', '["Le refroidissement de boulets","L’addition des générations bibliques","L’épaisseur des sédiments","La datation de météorites"]'::jsonb, 1, 'Elle donnait quelques milliers d’années seulement.', 1),
    ('48b0a282-c63f-5dd2-8c18-885df1cf7e4d'::uuid, 'enseignement-scientifique', '1re', 'L’histoire de l’âge de la Terre', 'Quelle méthode Hutton et Lyell utilisent-ils au XIXe siècle ?', 'mcq', '["La thermodynamique du refroidissement","La radioactivité","L’épaisseur des séries sédimentaires et la lenteur de l’érosion","Le comptage des cernes des arbres"]'::jsonb, 2, 'Leur raisonnement conduisait à des centaines de millions d’années.', 2),
    ('65f96db2-8817-5089-8fba-94ddaf9d93b9'::uuid, 'enseignement-scientifique', '1re', 'L’histoire de l’âge de la Terre', 'Qui découvre la radioactivité, et en quelle année ?', 'mcq', '["Kelvin, en 1862","Patterson, en 1953","Buffon, en 1778","Becquerel, en 1896"]'::jsonb, 3, 'La découverte de Becquerel révèle une source de chaleur interne que le modèle de Kelvin ignorait.', 3),
    ('2a9db04a-5fd7-5ed1-9db8-fa52069238c7'::uuid, 'enseignement-scientifique', '1re', 'L’histoire de l’âge de la Terre', 'Quelle méthode Clair Patterson utilise-t-il en 1953 ?', 'mcq', '["La datation uranium-plomb de météorites","Le carbone 14 sur des roches terrestres","Le refroidissement d’une sphère de fer","Le comptage des couches de sédiments"]'::jsonb, 0, 'Il obtient 4,55 milliards d’années ; la valeur admise aujourd’hui est 4,54 Ga.', 4),
    ('1f95c4ef-0d29-50c3-a6bb-610c7e005e5e'::uuid, 'enseignement-scientifique', '1re', 'La Terre dans l’Univers', 'À quelle distance correspond environ une année-lumière ?', 'mcq', '["150 millions de km","9,5 × 10¹² km","3 × 10⁸ km","4,2 km"]'::jsonb, 1, 'C’est la distance parcourue par la lumière en un an : environ 9 500 milliards de kilomètres.', 1),
    ('0fc8f316-3378-5479-b9bf-6df3c7a7355c'::uuid, 'enseignement-scientifique', '1re', 'La Terre dans l’Univers', 'À quelle distance se trouve l’étoile la plus proche du Soleil ?', 'mcq', '["100 000 années-lumière","8 minutes-lumière","Environ 4,2 années-lumière","13,8 milliards d’années-lumière"]'::jsonb, 2, '4,2 années-lumière ; 100 000 années-lumière, c’est le diamètre de la Voie lactée.', 2),
    ('89364a98-75d6-582b-b03e-8c1420fbc8eb'::uuid, 'enseignement-scientifique', '1re', 'La Terre dans l’Univers', 'Outre les satellites de Jupiter, quelle observation de Galilée est incompatible avec le modèle de Ptolémée ?', 'mcq', '["Les phases de Vénus","Les éclipses de Lune","Les étoiles filantes","La rotation de la Terre sur elle-même"]'::jsonb, 0, 'Les phases complètes de Vénus ne s’expliquent que si Vénus tourne autour du Soleil.', 3),
    ('2ccbd2a9-da0d-522b-bae1-61a0109115bb'::uuid, 'enseignement-scientifique', '1re', 'La Terre dans l’Univers', 'Sur quoi repose la méthode des vitesses radiales pour détecter une exoplanète ?', 'mcq', '["Sur la baisse de luminosité de l’étoile","Sur la photographie directe de la planète","Sur la mesure de son champ magnétique","Sur le léger mouvement de l’étoile entraînée par la planète"]'::jsonb, 3, 'La planète fait légèrement osciller son étoile ; les transits, eux, reposent sur une baisse de luminosité.', 4),
    ('48a4b7b6-499e-5c1d-b50c-e50828a1610d'::uuid, 'enseignement-scientifique', '1re', 'Le son, phénomène vibratoire', 'Comment vibrent les particules d’air au passage d’un son ?', 'mcq', '["Perpendiculairement à la propagation","Dans la direction de propagation, en compressions et dilatations","Elles avancent avec le son jusqu’à l’oreille","Elles restent parfaitement immobiles"]'::jsonb, 1, 'Le son est une onde longitudinale : les particules oscillent autour de leur position, seule l’énergie se déplace.', 1),
    ('0ef42964-c5ab-589b-87d8-c03cb0e71254'::uuid, 'enseignement-scientifique', '1re', 'Le son, phénomène vibratoire', 'Quelle est la longueur d’onde dans l’air d’un la3 à 440 Hz ?', 'mcq', '["Environ 1,3 m","Environ 7,7 cm","Environ 0,77 m","Environ 150 km"]'::jsonb, 2, 'λ = v / f = 340 / 440 ≈ 0,77 m.', 2),
    ('3bd4b4c1-fff2-5baf-bf2c-1e11a236df38'::uuid, 'enseignement-scientifique', '1re', 'Le son, phénomène vibratoire', 'Qu’est-ce qui détermine la hauteur d’un son musical ?', 'mcq', '["Sa fréquence fondamentale","Ses harmoniques","Son amplitude","Sa célérité"]'::jsonb, 0, 'Plus la fréquence fondamentale est élevée, plus le son est aigu ; les harmoniques font le timbre.', 3),
    ('8e5e9129-5245-5e6f-aea1-ad8aa30ca61c'::uuid, 'enseignement-scientifique', '1re', 'Le son, phénomène vibratoire', 'Quels sons utilisent l’échographie et les sonars ?', 'mcq', '["Les infrasons","Les sons audibles graves","Les sons audibles aigus","Les ultrasons"]'::jsonb, 3, 'Les ultrasons, au-dessus de 20 kHz, sont inaudibles pour nous — mais pas pour les chauves-souris.', 4),
    ('13d869db-9e91-52d7-87fb-344f07bd646c'::uuid, 'enseignement-scientifique', '1re', 'La musique ou l’art de faire entendre les nombres', 'Quel rapport de fréquences correspond à une quarte ?', 'mcq', '["3/2","2","5/4","4/3"]'::jsonb, 3, 'Octave 2/1, quinte 3/2, quarte 4/3 : les intervalles consonants sont des rapports d’entiers simples.', 1),
    ('2d723764-2a6c-5481-a26f-446be55aa96a'::uuid, 'enseignement-scientifique', '1re', 'La musique ou l’art de faire entendre les nombres', 'Quelle est la fréquence de la note située une octave sous le la3 ?', 'mcq', '["880 Hz","220 Hz","440 Hz","110 Hz"]'::jsonb, 1, 'Descendre d’une octave divise la fréquence par deux : 440 / 2 = 220 Hz, le la2.', 2),
    ('62d9567b-f638-5688-a43d-eb9485848a1b'::uuid, 'enseignement-scientifique', '1re', 'La musique ou l’art de faire entendre les nombres', 'Que vaut la quinte dans la gamme tempérée ?', 'mcq', '["Exactement 1,5","Environ 1,059","Environ 1,498","Environ 1,333"]'::jsonb, 2, 'Sept demi-tons tempérés donnent environ 1,498 au lieu de 1,5 : aucun intervalle n’y est parfaitement juste.', 3),
    ('098f20b9-3914-56e9-a295-76a441697e8c'::uuid, 'enseignement-scientifique', '1re', 'La musique ou l’art de faire entendre les nombres', 'Comment construit-on la gamme de Pythagore ?', 'mcq', '["En empilant des quintes puis en ramenant chaque note dans l’octave en divisant par 2","En divisant l’octave en douze demi-tons égaux","En multipliant chaque note par 4/3","En additionnant 50 Hz à chaque note"]'::jsonb, 0, 'On multiplie par 3/2, puis on divise par 2 autant qu’il le faut : sept notes, puis douze.', 4),
    ('d88cfc4b-046e-55b8-ae3f-69ca93c387bc'::uuid, 'enseignement-scientifique', '1re', 'Le son, une information à coder', 'Que découpe la quantification ?', 'mcq', '["Le temps","L’amplitude du signal","Le nombre de voies","La durée du morceau"]'::jsonb, 1, 'L’échantillonnage découpe le temps, la quantification découpe l’amplitude en niveaux.', 1),
    ('9acccd5f-e789-5330-a88c-a639ca21e4f9'::uuid, 'enseignement-scientifique', '1re', 'Le son, une information à coder', 'Pour numériser un son qui monte jusqu’à 20 kHz, quelle fréquence d’échantillonnage minimale faut-il ?', 'mcq', '["20 kHz","10 kHz","40 kHz","80 kHz"]'::jsonb, 2, 'Shannon-Nyquist : fe ≥ 2 × fmax, soit 40 kHz. Le CD, à 44,1 kHz, respecte ce critère.', 2),
    ('c6606cee-5f58-5771-add4-acaef386a25a'::uuid, 'enseignement-scientifique', '1re', 'Le son, une information à coder', 'Combien pèse environ une chanson de trois minutes au format CD non compressé ?', 'mcq', '["Une trentaine de mégaoctets","Environ 3 Mo","Environ 300 Mo","Environ 3 Go"]'::jsonb, 0, 'Environ 176 ko par seconde × 180 s ≈ 32 Mo : d’où l’intérêt de compresser.', 3),
    ('c5597e7e-571a-5301-a468-9a7a23b1d7af'::uuid, 'enseignement-scientifique', '1re', 'Le son, une information à coder', 'Par combien environ une compression MP3 divise-t-elle la taille d’un fichier ?', 'mcq', '["Par 2","Par 100","Par 1 000","Par 10"]'::jsonb, 3, 'Environ dix fois, en supprimant les sons masqués et les fréquences extrêmes que l’oreille ne perçoit pas.', 4),
    ('d8e4efe3-2a53-54f6-a05f-4cafc861553a'::uuid, 'enseignement-scientifique', '1re', 'Entendre la musique', 'Quel est le plus petit os du corps humain ?', 'mcq', '["Le marteau","L’enclume","L’étrier","Le tympan"]'::jsonb, 2, 'L’étrier, dernier des trois osselets, transmet la vibration à la fenêtre ovale de l’oreille interne.', 1),
    ('01109c80-01f5-592c-8b92-5273239a18c0'::uuid, 'enseignement-scientifique', '1re', 'Entendre la musique', 'Comment appelle-t-on l’organisation où chaque fréquence résonne à un endroit précis de la cochlée ?', 'mcq', '["La tonotopie","L’acouphène","La tonalité","La résonance du tympan"]'::jsonb, 0, 'Aigus à l’entrée, graves au fond : la position des cellules stimulées code la hauteur.', 2),
    ('a3012583-0bc0-5017-9977-b635d96ae1e8'::uuid, 'enseignement-scientifique', '1re', 'Entendre la musique', 'Comment l’intensité d’un son est-elle codée dans le message nerveux ?', 'mcq', '["Par la position des cellules ciliées","Par la taille du tympan","Par la vitesse du son dans la cochlée","Par la fréquence des potentiels d’action et le nombre de fibres recrutées"]'::jsonb, 3, 'La hauteur est codée par la position ; l’intensité, par la fréquence des messages et le nombre de fibres.', 3),
    ('3f84faf0-abc2-5e26-81d8-5ab470c4eadc'::uuid, 'enseignement-scientifique', '1re', 'Entendre la musique', 'Au-delà de 85 dB, que fait chaque hausse de 3 dB sur la durée d’exposition tolérable ?', 'mcq', '["Elle la double","Elle la divise par deux","Elle ne la change pas","Elle la divise par dix"]'::jsonb, 1, '+3 dB, c’est une intensité doublée : la durée sans risque est divisée par deux.', 4),
    ('0f871899-eb95-5640-8ea9-af064bd22668'::uuid, 'enseignement-scientifique', '1re', 'Analyse de l’information chiffrée', 'Un prix passe de 50 € à 40 €. Quel est le taux d’évolution ?', 'mcq', '["−10 %","−20 %","−25 %","+20 %"]'::jsonb, 1, 't = (40 − 50) / 50 = −0,20, soit une baisse de 20 %.', 1),
    ('64bc5c53-3ef3-5e34-90ad-a944680935ac'::uuid, 'enseignement-scientifique', '1re', 'Analyse de l’information chiffrée', 'Quel est le taux global d’une hausse de 20 % suivie d’une hausse de 10 % ?', 'mcq', '["+30 %","+22 %","+32 %","+3,2 %"]'::jsonb, 2, 'On multiplie les coefficients : 1,20 × 1,10 = 1,32, soit +32 %, et non +30 %.', 2),
    ('f51526e4-fd44-53e1-9cfe-c6224031b297'::uuid, 'enseignement-scientifique', '1re', 'Analyse de l’information chiffrée', 'Un prix vaut 120 € l’année de référence, puis 150 €. Quel est son indice base 100 ?', 'mcq', '["150","30","80","125"]'::jsonb, 3, 'Indice = 100 × 150 / 120 = 125 : le prix a augmenté de 25 %.', 3),
    ('ea3b2d74-6363-5199-b016-024df9c1820b'::uuid, 'enseignement-scientifique', '1re', 'Analyse de l’information chiffrée', 'Dans une classe de 30 élèves, 12 sont des filles. Quelle est la proportion de filles ?', 'mcq', '["0,4","0,12","12 %","2,5"]'::jsonb, 0, '12 / 30 = 0,4, soit 40 % : une proportion est toujours comprise entre 0 et 1.', 4),
    ('3a460922-045a-59e4-b01b-b14fc1293b1a'::uuid, 'enseignement-scientifique', '1re', 'Phénomènes aléatoires', 'Comment appelle-t-on l’ensemble des issues d’une expérience aléatoire ?', 'mcq', '["L’univers","L’événement","La fréquence","L’échantillon"]'::jsonb, 0, 'Un événement est un ensemble d’issues ; l’univers les contient toutes.', 1),
    ('5c852149-13cf-5f28-8d1c-c5fdfb8745a5'::uuid, 'enseignement-scientifique', '1re', 'Phénomènes aléatoires', 'Pour p = 0,5 et un échantillon de taille n = 100, quel est l’intervalle de fluctuation au seuil de 95 % ?', 'mcq', '["[0,49 ; 0,51]","[0,4 ; 0,6]","[0,45 ; 0,55]","[0 ; 1]"]'::jsonb, 1, '1/√100 = 0,1 : l’intervalle est [0,5 − 0,1 ; 0,5 + 0,1] = [0,4 ; 0,6].', 2),
    ('9d46953b-c141-58a0-94ae-9d65e0d2496f'::uuid, 'enseignement-scientifique', '1re', 'Phénomènes aléatoires', 'Avec un dé équilibré, quelle est la probabilité d’obtenir 5 ou 6 ?', 'mcq', '["1/6","1/2","1/3","2/3"]'::jsonb, 2, 'Deux issues favorables sur six possibles : 2/6 = 1/3.', 3),
    ('ffb40e48-19b5-5745-9d8a-6f5541c7161b'::uuid, 'enseignement-scientifique', '1re', 'Phénomènes aléatoires', 'On lance 200 fois une pièce et on obtient 92 « pile ». Quelle est la fréquence de « pile » ?', 'mcq', '["0,92","0,5","92","0,46"]'::jsonb, 3, 'Fréquence = réalisations / essais = 92 / 200 = 0,46 ; la probabilité, elle, reste 0,5.', 4),
    ('81a23920-f89f-5d1e-bd19-03679ef0ce19'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et suites arithmétiques', 'Une suite arithmétique a pour premier terme u(1) = 5 et pour raison 3. Que vaut u(10) ?', 'mcq', '["35","32","30","38"]'::jsonb, 1, 'À partir du rang 1 : u(n) = u(1) + (n − 1) × r, donc u(10) = 5 + 9 × 3 = 32.', 1),
    ('5ed98fc4-5dc4-5bec-9333-3dc7a0a57243'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et suites arithmétiques', 'Quelle est la raison de la suite arithmétique 20 ; 17 ; 14 ; 11 ?', 'mcq', '["3","17","−1/3","−3"]'::jsonb, 3, 'On soustrait deux termes consécutifs : 17 − 20 = −3. Raison négative, suite décroissante.', 2),
    ('f487d812-2d08-5534-86a0-b25af0723dad'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et suites arithmétiques', 'Sur un tableur, comment obtient-on le terme suivant d’une suite arithmétique ?', 'mcq', '["En ajoutant r à la cellule précédente","En multipliant la cellule précédente par r","En divisant la cellule précédente par r","En recopiant le premier terme"]'::jsonb, 0, 'La formule d’une cellule reprend la précédente augmentée de la raison.', 3),
    ('56ab7f3d-cd5c-5af2-9c62-ad577e106666'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et suites arithmétiques', 'Quel type de croissance une suite arithmétique modélise-t-elle ?', 'mcq', '["Exponentielle","Quadratique","Linéaire","Logarithmique"]'::jsonb, 2, 'On ajoute toujours la même quantité : c’est une croissance linéaire, aux points alignés.', 4),
    ('35cc9409-2b78-5c0e-9ef8-dc943f737888'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et fonctions affines', 'La fonction f(x) = −2x + 5 est-elle croissante ou décroissante ?', 'mcq', '["Croissante, car 5 est positif","Décroissante, car a = −2 est négatif","Constante","Croissante puis décroissante"]'::jsonb, 1, 'Le sens de variation se lit sur le coefficient directeur a, pas sur b.', 1),
    ('7c723dc6-9d2f-545e-ad09-6adcf0ea48b4'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et fonctions affines', 'Quelle est l’ordonnée à l’origine de f(x) = 3x − 4 ?', 'mcq', '["3","4/3","−4","4"]'::jsonb, 2, 'C’est b = f(0) = −4 : la droite coupe l’axe des ordonnées en −4.', 2),
    ('b015accc-ce80-5631-bdd9-fc9786858b74'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et fonctions affines', 'Une droite passe par les points (1 ; 5) et (3 ; 11). Quel est son coefficient directeur ?', 'mcq', '["3","6","2","8"]'::jsonb, 0, 'a = (11 − 5) / (3 − 1) = 6 / 2 = 3.', 3),
    ('2d19ca45-decb-5a65-95e4-5e4df18d4dbe'::uuid, 'enseignement-scientifique', '1re', 'Croissance linéaire et fonctions affines', 'Que devient une fonction affine quand a = 0 ?', 'mcq', '["Une fonction linéaire","Une proportionnalité","Une fonction exponentielle","Une fonction constante"]'::jsonb, 3, 'f(x) = b pour tout x : la droite est horizontale.', 4),
    ('c8bc9675-f701-5bef-8b4e-f67c6544d45d'::uuid, 'enseignement-scientifique', '1re', 'Croissance exponentielle et suites géométriques', 'Quel est environ le temps de doublement d’une grandeur qui augmente de 7 % par an ?', 'mcq', '["7 ans","10 ans","70 ans","14 ans"]'::jsonb, 1, 'Règle des 70 : 70 / 7 = 10 ans environ.', 1),
    ('7531ab47-1939-5ca1-afdf-0ba00ba9005d'::uuid, 'enseignement-scientifique', '1re', 'Croissance exponentielle et suites géométriques', 'Quelle est la raison de la suite géométrique 5 ; 15 ; 45 ?', 'mcq', '["10","1/3","30","3"]'::jsonb, 3, 'On divise deux termes consécutifs : 15 / 5 = 45 / 15 = 3.', 2),
    ('dab978c7-2ba3-53d1-8dc0-d3993577d275'::uuid, 'enseignement-scientifique', '1re', 'Croissance exponentielle et suites géométriques', 'Que dire d’une suite géométrique de raison q = 1 ?', 'mcq', '["Elle est constante","Elle double à chaque pas","Elle décroît vers 0","Elle devient négative"]'::jsonb, 0, 'Multiplier par 1 ne change rien : tous les termes sont égaux au premier.', 3),
    ('7a0179b5-079c-55d2-ba15-7d61ffb0369b'::uuid, 'enseignement-scientifique', '1re', 'Croissance exponentielle et suites géométriques', 'Quelle grandeur reste constante lors d’une décroissance exponentielle ?', 'mcq', '["Le temps de doublement","La différence entre deux termes consécutifs","La demi-vie","La vitesse de décroissance"]'::jsonb, 2, 'La durée pour diviser par deux est la même au début qu’à la fin : c’est ce qui sert à dater les roches.', 4),
    ('765a988a-4427-5470-bfe0-01c2c26dd8fb'::uuid, 'enseignement-scientifique', '1re', 'Croissance et fonctions exponentielles', 'Pour f(x) = 500 × 1,2^x, que vaut f(0) ?', 'mcq', '["1,2","600","500","0"]'::jsonb, 2, 'q^0 = 1, donc f(0) = k = 500 : c’est la valeur initiale.', 1),
    ('74ba1b09-bca1-5b11-92f3-c88f87b15694'::uuid, 'enseignement-scientifique', '1re', 'Croissance et fonctions exponentielles', 'Une grandeur double tous les 5 ans. Par combien est-elle multipliée en 15 ans ?', 'mcq', '["Par 3","Par 8","Par 6","Par 15"]'::jsonb, 1, 'Trois doublements successifs : 2 × 2 × 2 = 8. Additionner les durées, c’est multiplier les facteurs.', 2),
    ('b94a555d-39f9-53cb-abc4-e291574d30a9'::uuid, 'enseignement-scientifique', '1re', 'Croissance et fonctions exponentielles', 'Que représente le nombre 1,04 dans le modèle C(t) = C0 × 1,04^t ?', 'mcq', '["Une hausse de 4 % par unité de temps","Le capital initial","La durée du placement","Une hausse de 104 % par an"]'::jsonb, 0, '1,04 est le coefficient multiplicateur d’une hausse de 4 %.', 3),
    ('5acfde4b-fe88-59a4-ba37-80e35579a74c'::uuid, 'enseignement-scientifique', '1re', 'Croissance et fonctions exponentielles', 'Avec des axes ordinaires, une évolution à pourcentage constant se représente par une droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un pourcentage constant donne une courbe exponentielle ; elle ne devient une droite qu’en échelle logarithmique.', 4),
    ('053ec7ad-fac3-5255-a840-e3b331b853cf'::uuid, 'enseignement-scientifique', '1re', 'Variation instantanée et nombre dérivé', 'Géométriquement, que représente le taux de variation moyen de f entre a et b ?', 'mcq', '["L’aire sous la courbe","La tangente en a","L’ordonnée du milieu","Le coefficient directeur de la sécante qui joint les points d’abscisses a et b"]'::jsonb, 3, 'Quand b se rapproche de a, cette sécante pivote et devient la tangente.', 1),
    ('f8784df8-f54b-58a5-a638-5c9453c3e33d'::uuid, 'enseignement-scientifique', '1re', 'Variation instantanée et nombre dérivé', 'Pour f(x) = x², quel est le taux de variation moyen entre 1 et 3 ?', 'mcq', '["4","8","2","6"]'::jsonb, 0, '(f(3) − f(1)) / (3 − 1) = (9 − 1) / 2 = 4.', 2),
    ('6441f32e-8196-577f-a2f4-adc9e25e5d2a'::uuid, 'enseignement-scientifique', '1re', 'Variation instantanée et nombre dérivé', 'Si v(t) est la vitesse d’un mobile, que représente v’(t) ?', 'mcq', '["Sa position","Son accélération","La distance parcourue","Sa vitesse moyenne"]'::jsonb, 1, 'La dérivée de la position est la vitesse ; celle de la vitesse est l’accélération.', 3),
    ('c9b86b69-c3f3-5a8a-968e-2c11698d5b7b'::uuid, 'enseignement-scientifique', '1re', 'Variation instantanée et nombre dérivé', 'Que peut-on dire de f en a si f’(a) est négatif ?', 'mcq', '["f est croissante en a","f s’annule en a","f décroît en a : la tangente descend","f admet un maximum en a"]'::jsonb, 2, 'Le signe du nombre dérivé donne le sens de la tangente : négatif, elle descend.', 4),
    ('5540a5b5-ffc7-5ff8-9222-e278769eca69'::uuid, 'enseignement-scientifique', '1re', 'Variation globale et fonction dérivée', 'Quelle est la dérivée de f(x) = x³ ?', 'mcq', '["x²","3x","3x²","x⁴ / 4"]'::jsonb, 2, 'La dérivée de x³ est 3x² ; x⁴ / 4 serait une primitive, pas une dérivée.', 1),
    ('e1c35f5f-e5cd-58f0-bdbc-04b3d29d029c'::uuid, 'enseignement-scientifique', '1re', 'Variation globale et fonction dérivée', 'Quelle est la dérivée de f(x) = 1/x ?', 'mcq', '["1/x²","−1/x²","−1/x","x"]'::jsonb, 1, '(1/x)’ = −1/x² : le signe moins traduit que 1/x décroît sur chaque intervalle.', 2),
    ('66a36462-5552-5dd0-b0b3-a1c46926aaa7'::uuid, 'enseignement-scientifique', '1re', 'Variation globale et fonction dérivée', 'Si f’ passe du négatif au positif en un point, qu’admet f en ce point ?', 'mcq', '["Un maximum","Aucun extremum","Un zéro","Un minimum"]'::jsonb, 3, 'f décroît puis croît : c’est un minimum. De + à −, ce serait un maximum.', 3),
    ('828077e7-8d45-5b44-a89f-fcdccf467da7'::uuid, 'enseignement-scientifique', '1re', 'Variation globale et fonction dérivée', 'Quelle est la valeur maximale de f(x) = −2x² + 8x + 3 ?', 'mcq', '["11","2","3","19"]'::jsonb, 0, 'Le maximum est atteint en x = 2 : f(2) = −8 + 16 + 3 = 11.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

-- 3. Sonde finale ---------------------------------------------------------
DO $$
DECLARE n integer;
BEGIN
